// update-mosp-modules.mjs — run from the analytix360 root:  node update-mosp-modules.mjs
// Opens MOSP Modules 3–8: 23 new lessons with hands-on labs, a practice lab of 4 exercises
// (beginner → expert) and an 8-question quiz per module, French for everything, and new
// spreadsheet functions (IFS, SUMIFS, COUNTIFS, AVERAGEIFS, XLOOKUP, INDEX, MATCH, PMT…).
// All-or-nothing: if any check fails, nothing is written.
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { dirname } from "path";
const fail = (m) => { console.error("STOPPED, nothing written: " + m); process.exit(1); };
if (!existsSync("client/src/data/courses/mosp.ts")) fail("client/src/data/courses/mosp.ts not found — run this from the analytix360 folder");
if (!existsSync("client/src/lms/labs/FormLab.tsx")) fail("run update-mosp-practice.mjs first (the Practice exercise lab type is needed)");
const FILES = {"client/src/data/courses/mosp/m3.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// MOSP Module 3: Microsoft Word — Advanced Document Production\n// Original Analytix Engineering material, aligned to Exam MO-110 (Word, Microsoft 365 Apps).\n\nconst MS = \"Microsoft Support\";\nconst LEARN = \"Microsoft Learn\";\nconst MO110 = { label: \"Exam MO-110: Microsoft Word (Microsoft 365 Apps)\", url: \"https://learn.microsoft.com/en-us/credentials/certifications/exams/mo-110/\", source: LEARN };\nconst SHORTCUTS = { label: \"Keyboard shortcuts in Word\", url: \"https://support.microsoft.com/en-us/accessibility/word/keyboard-shortcuts-in-word\", source: MS };\n\nexport const m3: CourseModule = {\n  id: \"mosp-m3\",\n  number: 3,\n  title: \"Microsoft Word — Advanced Document Production\",\n  summary: \"Tables, mail merge, Track Changes, tables of contents and templates.\",\n  hours: 10,\n  lessons: [\n    // ─────────────────────────── LESSON 1 ───────────────────────────\n    {\n      id: \"mosp-m3-l1\",\n      title: \"Tables that organise data\",\n      minutes: 25,\n      objectives: [\n        \"Create a table from scratch or by converting existing text\",\n        \"Format, sort and total a table, and repeat its header row on every page\",\n        \"Decide when a Word table is enough and when the data belongs in Excel\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Price lists, staff rosters, training schedules and budget summaries all read better in a table than in paragraphs separated by tabs and spaces. A Word table keeps columns aligned whatever the font, grows with its content and can be sorted and totalled without retyping anything.\" },\n        { type: \"h\", text: \"Three ways to create a table\" },\n        { type: \"table\", head: [\"Method\", \"How\", \"Best for\"], rows: [\n          [\"Quick grid\", \"Insert › Table, then drag over the grid\", \"Small tables up to 10 columns and 8 rows\"],\n          [\"Insert Table dialog\", \"Insert › Table › Insert Table, then type the number of columns and rows\", \"Larger tables, or when you want a fixed column width from the start\"],\n          [\"Convert Text to Table\", \"Select text separated by tabs, commas or paragraphs, then Insert › Table › Convert Text to Table\", \"Lists copied from an e-mail, a website or an old document\"],\n        ] },\n        { type: \"path\", items: [\"Insert\", \"Table\", \"Convert Text to Table\"], note: \"Word guesses the separator. Check the number of columns before clicking OK.\" },\n        { type: \"steps\", title: \"Convert a tabbed list into a table\", items: [\n          \"Turn on Show/Hide ¶ to check that each line uses the same separator, for example one tab between columns.\",\n          \"Select all the lines, including the header line.\",\n          \"Go to **Insert › Table › Convert Text to Table**.\",\n          \"Under Separate text at, choose **Tabs** (or Commas), check the number of columns and click OK.\",\n        ] },\n        { type: \"h\", text: \"Make it readable with Table Design\" },\n        { type: \"list\", items: [\n          \"**Table Styles** apply borders, shading and header formatting in one click. Choose a light style for documents that will be printed in black and white.\",\n          \"**Table Style Options** switch parts of the style on or off: Header Row, Total Row, Banded Rows, First Column.\",\n          \"**Borders** and **Shading** adjust individual cells when a style is not enough.\",\n        ] },\n        { type: \"h\", text: \"Headers that repeat on every page\" },\n        { type: \"p\", text: \"When a table runs over several pages, readers of page 3 no longer know what each column means. Word can repeat the header row automatically at the top of every page.\" },\n        { type: \"path\", items: [\"Table Layout\", \"Data\", \"Repeat Header Rows\"], note: \"Click in the first row (or select the first rows) before clicking. The same option is in Table Properties › Row.\" },\n        { type: \"callout\", tone: \"key\", title: \"Never retype the header\", text: \"A header typed again by hand at the top of page 2 moves to the middle of a page as soon as rows are added or deleted. Repeat Header Rows follows the page breaks for you.\" },\n        { type: \"h\", text: \"Merge, split, sort and total\" },\n        { type: \"table\", head: [\"Command\", \"Where\", \"Use it to\"], rows: [\n          [\"Merge Cells\", \"Table Layout › Merge\", \"Join cells into one, for example a title across the whole table\"],\n          [\"Split Cells\", \"Table Layout › Merge\", \"Divide one cell into several columns or rows\"],\n          [\"Sort\", \"Table Layout › Data\", \"Order rows by name, amount or date. Tick \\\"My list has a header row\\\" so the header stays on top\"],\n          [\"Formula\", \"Table Layout › Data\", \"Add a total with a formula field such as =SUM(ABOVE) or =SUM(LEFT)\"],\n          [\"Convert to Text\", \"Table Layout › Data\", \"Turn a table back into tabbed or comma-separated text\"],\n        ] },\n        { type: \"steps\", title: \"Total a column with a formula\", items: [\n          \"Click in the empty cell at the bottom of the amount column.\",\n          \"Go to **Table Layout › Data › Formula**.\",\n          \"Word proposes =SUM(ABOVE). Keep it, choose a number format if you want one, and click OK.\",\n          \"If you change an amount later, click the total and press F9 to update it.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Word formulas do not recalculate by themselves\", text: \"A Word formula is a field: it calculates once and then waits. After any change, select the table and press F9. If you need many formulas, percentages or frequent updates, keep the data in Excel.\" },\n        { type: \"h\", text: \"AutoFit and alignment\" },\n        { type: \"list\", items: [\n          \"**AutoFit Contents** makes each column as wide as its longest entry. **AutoFit Window** stretches the table to the margins. Both are under Table Layout › Cell Size › AutoFit.\",\n          \"**Distribute Columns** gives selected columns the same width, which looks tidy for dates or amounts.\",\n          \"Use the nine buttons in Table Layout › Alignment: left-align text, right-align amounts so the units line up, and centre short codes.\",\n        ] },\n        { type: \"h\", text: \"Word table or Excel?\" },\n        { type: \"table\", head: [\"Situation\", \"Best tool\"], rows: [\n          [\"A schedule, a contact list or a price list inside a letter or report\", \"Word table\"],\n          [\"One or two totals that rarely change\", \"Word table with =SUM(ABOVE)\"],\n          [\"Many calculations, percentages, filters or a chart\", \"Excel, then paste or link the result into Word (Module 8)\"],\n          [\"A list that will be reused for a mail merge\", \"Excel, one row per person (Lesson 2)\"],\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A hardware shop in Bafoussam sends its monthly price list to 40 building contractors. With the list in a Word table sorted by product, right-aligned prices and a header row that repeats on every page, the three-page document is easy to read on paper and on a phone.\" },\n        { type: \"form\", id: \"mosp-m3-l1-form\", title: \"Choose the right table command\",\n          task: \"A training centre in Yaoundé keeps its course timetable in a Word table. Choose the right command for each request, then type the formulas.\",\n          hint: \"Almost every table command is on the Table Layout tab. Formulas are fields: SUM with ABOVE adds the column above, SUM with LEFT adds the row to the left.\",\n          fields: [\n            { kind: \"select\", label: \"The timetable runs over three pages and the column titles must appear at the top of each page.\", options: [\"Insert › Header\", \"Table Layout › Data › Repeat Header Rows\", \"Table Design › Header Row\", \"Layout › Breaks › Page\"], answer: 1, explain: \"Repeat Header Rows follows the page breaks. The Header Row option in Table Design only changes the formatting of the first row.\" },\n            { kind: \"select\", label: \"The title \\\"Timetable, October 2026\\\" must run across all five columns of the first row.\", options: [\"Split Cells\", \"AutoFit Window\", \"Merge Cells\", \"Distribute Columns\"], answer: 2 },\n            { kind: \"select\", label: \"The courses must appear in alphabetical order, with the header row staying on top.\", options: [\"Table Layout › Data › Sort, with \\\"My list has a header row\\\" ticked\", \"Home › Paragraph › Sort, with no options\", \"Cut and paste the rows one by one\", \"Table Design › Banded Rows\"], answer: 0 },\n            { kind: \"text\", label: \"Type the formula that adds the fees in the cells above the last cell of the Fee column.\", accept: [\"=SUM(ABOVE)\"], placeholder: \"=…\", mono: true, explain: \"SUM(ABOVE) adds the numbers above the cell in the same column.\" },\n            { kind: \"text\", label: \"Type the formula that adds the numbers to the left of the last cell of a row.\", accept: [\"=SUM(LEFT)\"], placeholder: \"=…\", mono: true },\n            { kind: \"select\", label: \"You changed one fee, but the total did not change. What do you do?\", options: [\"Retype the formula\", \"Select the total and press F9\", \"Save and close the document\", \"Press Ctrl + Z\"], answer: 1, explain: \"F9 updates the selected fields. Word formulas never recalculate on their own.\" },\n          ] },\n        { type: \"check\", id: \"mosp-m3-l1-c1\", question: \"An NGO wants to analyse 600 survey answers by region, with percentages and a chart. Where should the data be kept?\", options: [\"In a Word table with =SUM formulas\", \"In Excel, with only the summary brought into the Word report\", \"In a Word table sorted by region\", \"In tabbed text in Word\"], answer: 1, explain: \"Word tables are for presenting data. Calculations, percentages and charts on hundreds of rows belong in Excel; the report then shows the summary.\" },\n        { type: \"task\", id: \"mosp-m3-l1-t1\", title: \"Practice\", items: [\n          \"Type a list of 10 staff members with name, department and phone number separated by tabs, then convert it to a table\",\n          \"Apply a light table style and turn on Banded Rows\",\n          \"Sort the table by department, then by name\",\n          \"Add enough rows to reach a second page and make the header row repeat\",\n          \"Add a Budget column and total it with =SUM(ABOVE), then change a number and update the total with F9\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Insert a table\", url: \"https://support.microsoft.com/en-us/office/insert-a-table-a138f745-73ef-4879-b99a-2f3d38be612a\", source: MS },\n          MO110,\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 2 ───────────────────────────\n    {\n      id: \"mosp-m3-l2\",\n      title: \"Mail merge for letters and labels\",\n      minutes: 30,\n      objectives: [\n        \"Prepare a clean Excel recipient list for a mail merge\",\n        \"Run the Mailings workflow from Start Mail Merge to Finish & Merge\",\n        \"Personalise letters with merge fields and rules, and print labels and envelopes\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Mail merge produces hundreds of personalised letters, labels, envelopes or e-mails from one document and one list. You write the letter once, Word fills in each person's name, address and amount, and you check the result before printing. It saves hours and avoids the copy-and-paste mistakes that send one member's amount to another.\" },\n        { type: \"h\", text: \"The three parts of a mail merge\" },\n        { type: \"table\", head: [\"Part\", \"What it is\", \"Example\"], rows: [\n          [\"Main document\", \"The letter, label or e-mail with the text that is the same for everyone, plus merge fields\", \"An invitation to the general assembly\"],\n          [\"Data source\", \"The list with one row per recipient and one column per piece of information\", \"An Excel workbook of 200 association members\"],\n          [\"Merged result\", \"One personalised copy per recipient\", \"200 letters in a new document, or sent straight to the printer\"],\n        ] },\n        { type: \"h\", text: \"Prepare a clean recipient list in Excel\" },\n        { type: \"list\", items: [\n          \"Put **one header row** in row 1, with short names without spaces such as Title, FirstName, LastName, City, Email, Amount.\",\n          \"No merged cells, no title above the headers and no empty rows inside the list.\",\n          \"One piece of information per column: split \\\"M. Paul NDZANA\\\" into Title, FirstName and LastName.\",\n          \"No totals or notes below the list: Word would treat them as recipients.\",\n          \"Save and close the workbook before you connect it to Word.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Numbers, phone numbers and dates\", text: \"Word reads the value stored in the cell, not the way Excel displays it. An amount may lose its thousands separator and a phone number may lose its leading zero or + sign. Store phone numbers as text, and for amounts add a column in Excel that already contains the amount written as text, such as 25 000.\" },\n        { type: \"h\", text: \"The Mailings workflow\" },\n        { type: \"path\", items: [\"Mailings\", \"Start Mail Merge\", \"Letters\"] },\n        { type: \"steps\", title: \"Merge letters from an Excel list\", items: [\n          \"Open or write the letter, then go to **Mailings › Start Mail Merge › Letters**.\",\n          \"Click **Select Recipients › Use an Existing List**, choose the workbook and the sheet, and keep \\\"First row of data contains column headers\\\" ticked.\",\n          \"Click **Edit Recipient List** to sort, filter or untick people who should not receive the letter.\",\n          \"Place the cursor where each detail belongs and use **Insert Merge Field** to add fields such as «Title», «FirstName» and «LastName».\",\n          \"Click **Preview Results** and use the arrows to check several recipients, especially long names and empty cells.\",\n          \"Click **Finish & Merge** and choose Edit Individual Documents, Print Documents or Send Email Messages.\",\n        ] },\n        { type: \"table\", head: [\"Button\", \"What it inserts or does\"], rows: [\n          [\"Address Block\", \"A complete address built from several columns, in a layout you choose\"],\n          [\"Greeting Line\", \"A salutation such as \\\"Dear Mr Ndzana,\\\" with a fallback for missing names\"],\n          [\"Insert Merge Field\", \"One column of the list, shown between « » chevrons\"],\n          [\"Rules\", \"Conditions such as If…Then…Else, or Skip Record If to leave some people out\"],\n          [\"Preview Results\", \"Replaces the fields with real data, one recipient at a time\"],\n          [\"Check for Errors\", \"Simulates the merge and reports problems before you print\"],\n        ] },\n        { type: \"h\", text: \"Personalise with a rule\" },\n        { type: \"p\", text: \"Rules let the text change from one recipient to another. With If…Then…Else you can write \\\"Madame\\\" when the Gender column contains F and \\\"Monsieur\\\" otherwise, or add a reminder paragraph only for members whose dues are unpaid.\" },\n        { type: \"path\", items: [\"Mailings\", \"Write & Insert Fields\", \"Rules\", \"If…Then…Else\"], note: \"Choose the field, the comparison and the value, then type the text to insert in each case.\" },\n        { type: \"h\", text: \"Finish the merge\" },\n        { type: \"table\", head: [\"Finish & Merge option\", \"Result\", \"Use it when\"], rows: [\n          [\"Edit Individual Documents\", \"A new document with one letter per recipient\", \"You want to check or save the letters before printing. This is the safest choice\"],\n          [\"Print Documents\", \"Sends all letters to the printer\", \"You have already checked the preview carefully\"],\n          [\"Send Email Messages\", \"One e-mail per recipient through Outlook, using the Email column\", \"The letter goes by e-mail. Outlook for Windows must be installed and set up\"],\n        ] },\n        { type: \"h\", text: \"Labels and envelopes\" },\n        { type: \"steps\", title: \"Print address labels\", items: [\n          \"Start a new blank document and go to **Mailings › Start Mail Merge › Labels**.\",\n          \"Choose the label vendor and product number printed on the box, for example an A4 sheet of 21 labels.\",\n          \"Select the same recipient list, then insert an **Address Block** or merge fields in the first label only.\",\n          \"Click **Update Labels** to copy the layout to every label on the sheet.\",\n          \"Preview, then print one test sheet on plain paper and hold it against a label sheet before using the real labels.\",\n        ] },\n        { type: \"p\", text: \"Envelopes work the same way: Mailings › Start Mail Merge › Envelopes, choose the size (DL is common for A4 letters folded in three), then place the address fields in the address box.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"The secretary of a teachers' association in Bafoussam must invite 200 members to the annual general meeting. With the member list cleaned in Excel, one letter written in Word and a rule that adds a reminder for unpaid dues, the 200 letters and the envelope labels are ready in under an hour.\" },\n        { type: \"form\", id: \"mosp-m3-l2-form\", title: \"Run a mail merge in the right order\",\n          task: \"You prepare invitation letters for the members of a savings cooperative in Douala. The Excel list has the columns Title, FirstName, LastName, City and Email. Answer each question.\",\n          hint: \"The workflow goes from left to right on the Mailings tab: Start Mail Merge, Select Recipients, insert fields, Preview Results, Finish & Merge. Merge fields appear between « » chevrons.\",\n          fields: [\n            { kind: \"select\", label: \"Step 1: what do you click first on the Mailings tab?\", options: [\"Finish & Merge\", \"Start Mail Merge › Letters\", \"Preview Results\", \"Insert Merge Field\"], answer: 1 },\n            { kind: \"select\", label: \"Step 2: how do you connect the Excel member list?\", options: [\"Select Recipients › Use an Existing List\", \"Insert › Object\", \"File › Open\", \"Select Recipients › Type a New List\"], answer: 0 },\n            { kind: \"text\", label: \"Type the merge field that inserts the member's first name, as Word shows it in the letter.\", accept: [\"«FirstName»\", \"<<FirstName>>\"], example: \"«FirstName»\", placeholder: \"«…»\", mono: true, explain: \"Word shows a merge field as the column name between chevrons.\" },\n            { kind: \"text\", label: \"Type the merge field for the family name column.\", accept: [\"«LastName»\", \"<<LastName>>\"], example: \"«LastName»\", placeholder: \"«…»\", mono: true },\n            { kind: \"select\", label: \"Only members from Douala should receive this letter. Where do you filter the list?\", options: [\"Delete the other rows in the merged letters\", \"Edit Recipient List › Filter\", \"Rules › Next Record\", \"Update Labels\"], answer: 1, explain: \"Edit Recipient List lets you filter, sort or untick recipients without changing the Excel file.\" },\n            { kind: \"select\", label: \"Which Finish & Merge option lets you check every letter before printing?\", options: [\"Print Documents\", \"Send Email Messages\", \"Edit Individual Documents\", \"Update Labels\"], answer: 2 },\n          ] },\n        { type: \"doc\", id: \"mosp-m3-l2-doc\", title: \"Format a merge letter\",\n          task: \"This payslip notice already contains merge fields. Format it: the first line in Heading 1 and centred, the place and date right-aligned, the words «NetPay» FCFA in bold, and the three deductions as a bulleted list.\",\n          hint: \"Formatting applied to a merge field is kept in every merged letter. Select «NetPay» FCFA together before clicking Bold, and select the three deduction lines before clicking Bullets.\",\n          html: \"<p>Salary payment notice</p><p>Douala, 30 September 2026</p><p>«Title» «FirstName» «LastName»</p><p>Staff number: «StaffNo»</p><p>Dear «Title» «LastName»,</p><p>Your salary for September 2026 was paid into your bank account today. Your net pay is «NetPay» FCFA.</p><p>The following amounts were deducted from your gross pay:</p><p>CNPS contribution</p><p>Income tax (IRPP)</p><p>Staff canteen</p><p>Human Resources Department</p>\",\n          checks: [\n            { kind: \"heading\", level: 1, text: \"Salary payment notice\" },\n            { kind: \"align\", text: \"Salary payment notice\", value: \"center\" },\n            { kind: \"align\", text: \"Douala, 30 September 2026\", value: \"right\" },\n            { kind: \"bold\", text: \"«NetPay» FCFA\" },\n            { kind: \"list\", ordered: false, min: 3 },\n          ] },\n        { type: \"check\", id: \"mosp-m3-l2-c1\", question: \"Your merged letters show some members twice and one letter addressed to \\\"TOTAL\\\". What is the most likely cause?\", options: [\"The letter uses the wrong font\", \"The Excel list has duplicate rows and a totals row below the data\", \"Preview Results was switched on\", \"The labels were not updated\"], answer: 1, explain: \"Word creates one letter for every row of the data source. Clean the list in Excel first: one header row, one row per person, nothing below the data.\" },\n        { type: \"task\", id: \"mosp-m3-l2-t1\", title: \"Practice\", items: [\n          \"Create an Excel list of 8 people with the columns Title, FirstName, LastName, City and Email\",\n          \"Write a short invitation letter and connect it to the list with Select Recipients\",\n          \"Insert a Greeting Line and the City field, and preview at least three recipients\",\n          \"Add an If…Then…Else rule that prints a different sentence for people in Yaoundé\",\n          \"Finish with Edit Individual Documents, then create a sheet of address labels from the same list\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Use mail merge for bulk email, letters, labels, and envelopes\", url: \"https://support.microsoft.com/en-us/office/use-mail-merge-for-bulk-email-letters-labels-and-envelopes-f488ed5b-b849-4c11-9cff-932c49474705\", source: MS },\n          MO110,\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 3 ───────────────────────────\n    {\n      id: \"mosp-m3-l3\",\n      title: \"Reviewing with comments and Track Changes\",\n      minutes: 25,\n      objectives: [\n        \"Add, answer and resolve comments during a review\",\n        \"Record, display, accept and reject changes with Track Changes\",\n        \"Compare two versions, restrict editing and proofread a bilingual document\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Reports, contracts and project proposals are rarely written by one person. Comments and Track Changes let several reviewers work on the same document while the author keeps full control: every suggestion is visible, attributed to its author and can be accepted or rejected one by one.\" },\n        { type: \"h\", text: \"Comments: discuss without changing the text\" },\n        { type: \"path\", items: [\"Review\", \"Comments\", \"New Comment\"], note: \"Shortcut: Ctrl + Alt + M.\" },\n        { type: \"steps\", title: \"Work with comments\", items: [\n          \"Select the words the comment is about, then press `Ctrl + Alt + M`.\",\n          \"Type your remark and post it. Type @ followed by a colleague's name to mention them: they receive an e-mail notification.\",\n          \"To answer, click **Reply** in the comment instead of starting a new one, so the whole discussion stays together.\",\n          \"When the point is settled, choose **Resolve** from the comment's menu. It stays in the document, greyed out, and can be reopened.\",\n          \"Before sending the final version, delete all comments: Review › Comments › Delete › Delete All Comments in Document.\",\n        ] },\n        { type: \"h\", text: \"Track Changes: every edit recorded\" },\n        { type: \"path\", items: [\"Review\", \"Tracking\", \"Track Changes\"], note: \"Shortcut: Ctrl + Shift + E. The button stays highlighted while tracking is on.\" },\n        { type: \"p\", text: \"While tracking is on, inserted text is underlined in colour, deleted text is struck through or moved to a balloon, and a line in the margin marks each changed line. Each reviewer gets a different colour.\" },\n        { type: \"table\", head: [\"Display for Review\", \"What you see\", \"Use it to\"], rows: [\n          [\"Simple Markup\", \"The edited text, with a red line in the margin where something changed\", \"Read the new version comfortably\"],\n          [\"All Markup\", \"Every insertion, deletion and formatting change, with the reviewer's name\", \"Check each change before accepting it\"],\n          [\"No Markup\", \"The document as it would look if all changes were accepted\", \"Proofread the final result\"],\n          [\"Original\", \"The document before any tracked change\", \"Compare with what you first wrote\"],\n        ] },\n        { type: \"steps\", title: \"Accept or reject changes\", items: [\n          \"Press `Ctrl + Home` and switch to **All Markup**.\",\n          \"Click **Review › Changes › Next** to jump to the first change.\",\n          \"Click **Accept** or **Reject**. Word moves to the next change automatically.\",\n          \"When you trust all the remaining changes, use the arrow under Accept and choose **Accept All Changes**.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Hiding changes is not removing them\", text: \"Switching to No Markup or turning Track Changes off does not delete the recorded changes. A client who opens the file can still see every deletion and comment. Accept or reject all changes, delete the comments, then run File › Info › Check for Issues › Inspect Document before sending.\" },\n        { type: \"shortcuts\", title: \"Review shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Alt\", \"M\"], action: \"Insert a comment\" },\n          { keys: [\"Ctrl\", \"Shift\", \"E\"], action: \"Turn Track Changes on or off\" },\n          { keys: [\"F7\"], action: \"Check spelling and grammar (opens the Editor pane)\" },\n          { keys: [\"Shift\", \"F7\"], action: \"Thesaurus\" },\n        ] },\n        { type: \"keys\", id: \"mosp-m3-l3-keys\", title: \"Practise the review shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Alt\", \"M\"], action: \"Insert a comment\" },\n          { keys: [\"Ctrl\", \"Shift\", \"E\"], action: \"Turn Track Changes on or off\" },\n          { keys: [\"F7\"], action: \"Check spelling and grammar\" },\n        ] },\n        { type: \"h\", text: \"Compare two versions\" },\n        { type: \"p\", text: \"A partner sometimes sends back an edited copy without Track Changes. Compare shows every difference between the two files as tracked changes in a new document, so you can review them normally.\" },\n        { type: \"path\", items: [\"Review\", \"Compare\", \"Compare\"], note: \"Choose the original document and the revised document. Combine merges the copies of several reviewers into one.\" },\n        { type: \"h\", text: \"Restrict Editing\" },\n        { type: \"steps\", title: \"Force reviewers to track their changes\", items: [\n          \"Go to **Review › Protect › Restrict Editing**.\",\n          \"Under Editing restrictions, tick the box and choose **Tracked changes** (or Comments, Filling in forms, No changes).\",\n          \"Click **Yes, Start Enforcing Protection** and enter a password if you want one.\",\n          \"Reviewers can now edit, but every change is recorded and they cannot switch tracking off.\",\n        ] },\n        { type: \"h\", text: \"Spelling, grammar and the proofing language\" },\n        { type: \"list\", items: [\n          \"Press F7 to open the **Editor** pane, which lists spelling, grammar and clarity suggestions one by one.\",\n          \"Word checks each passage in its proofing language. Select a French passage and choose Review › Language › Set Proofing Language › French.\",\n          \"Tick **Do not check spelling or grammar** for codes, product references or long lists of names.\",\n          \"Right-click a correct name such as Nkongsamba and choose **Add to Dictionary** so Word stops flagging it.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A consultancy in Yaoundé writes a bilingual project proposal for a ministry. The English team and the French team review with Track Changes on, the project manager accepts or rejects each change, and the French sections are set to the French proofing language so F7 checks both parts correctly.\" },\n        { type: \"form\", id: \"mosp-m3-l3-form\", title: \"Make the right review decision\",\n          task: \"You coordinate the review of a funding proposal for an NGO in Garoua. Choose the right feature for each situation.\",\n          hint: \"Think about what each person needs to see or be prevented from doing. Restrict Editing controls what reviewers may do; the display options only change what you see.\",\n          fields: [\n            { kind: \"select\", label: \"The director wants to read the edited text without coloured marks, but still see where something changed.\", options: [\"All Markup\", \"Simple Markup\", \"Original\", \"Turn Track Changes off\"], answer: 1 },\n            { kind: \"select\", label: \"A reviewer must be unable to make changes that are not tracked.\", options: [\"Review › Protect › Restrict Editing › Tracked changes\", \"Mark as Final\", \"Save as PDF\", \"Simple Markup\"], answer: 0, explain: \"Restrict Editing with Tracked changes keeps tracking on for everyone until the password is entered.\" },\n            { kind: \"select\", label: \"A partner returns an edited copy without Track Changes. How do you see what changed?\", options: [\"Read both files side by side\", \"Review › Compare › Compare\", \"Undo history\", \"Review › Track Changes\"], answer: 1 },\n            { kind: \"select\", label: \"A colleague answered your comment by creating a new comment further down. What should she have done?\", options: [\"Used Reply in the original comment\", \"Used Track Changes\", \"Deleted your comment\", \"Written her answer in the text\"], answer: 0 },\n            { kind: \"text\", label: \"Which key opens the Editor pane to check spelling and grammar?\", accept: [\"F7\"], placeholder: \"Key\", mono: true },\n            { kind: \"select\", label: \"The final version goes to the donor tomorrow. What must you do with the tracked changes and comments?\", options: [\"Switch to No Markup\", \"Turn Track Changes off\", \"Accept or reject all changes and delete all comments\", \"Nothing, the donor cannot see them\"], answer: 2, explain: \"Changes and comments stay in the file until they are accepted, rejected or deleted, whatever the display.\" },\n          ] },\n        { type: \"check\", id: \"mosp-m3-l3-c1\", question: \"You turned Track Changes off and chose No Markup. The coloured changes disappeared. What happens when the client opens the file?\", options: [\"Nothing: the changes are deleted\", \"The client can still display every tracked change and comment\", \"The document is locked\", \"The changes are accepted automatically\"], answer: 1, explain: \"Display options only change what you see on your screen. The changes remain in the file until they are accepted or rejected.\" },\n        { type: \"task\", id: \"mosp-m3-l3-t1\", title: \"Practice\", items: [\n          \"Turn on Track Changes with Ctrl + Shift + E and edit three sentences of an existing document\",\n          \"Add two comments with Ctrl + Alt + M, reply to one and resolve it\",\n          \"Switch between Simple Markup and All Markup, then accept one change and reject another\",\n          \"Compare your edited file with the original copy\",\n          \"Set one paragraph to French proofing and run F7\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Track changes in Word\", url: \"https://support.microsoft.com/en-us/office/track-changes-in-word-197ba630-0f5f-4a8e-9a77-3712475e806a\", source: MS },\n          SHORTCUTS,\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 4 ───────────────────────────\n    {\n      id: \"mosp-m3-l4\",\n      title: \"Tables of contents, captions and templates\",\n      minutes: 25,\n      objectives: [\n        \"Build and update an automatic table of contents from heading styles\",\n        \"Number figures and tables with captions, cross-references and footnotes\",\n        \"Save a company letterhead as a .dotx template and create documents from it\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Long documents such as annual reports, procedure manuals and theses need a table of contents, numbered figures and consistent layout. Word builds all of this automatically, as long as the document is structured with styles.\" },\n        { type: \"h\", text: \"Headings are the foundation\" },\n        { type: \"p\", text: \"The table of contents lists every paragraph formatted with Heading 1, Heading 2 or Heading 3. Titles made bold by hand are invisible to it. Before inserting a table of contents, open the Navigation Pane (View › Navigation Pane): what you see there is exactly what the table of contents will show.\" },\n        { type: \"shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Alt\", \"1\"], action: \"Apply Heading 1\" },\n          { keys: [\"Ctrl\", \"Alt\", \"2\"], action: \"Apply Heading 2\" },\n          { keys: [\"Ctrl\", \"Alt\", \"3\"], action: \"Apply Heading 3\" },\n        ] },\n        { type: \"keys\", id: \"mosp-m3-l4-keys\", title: \"Practise the heading shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Alt\", \"1\"], action: \"Apply Heading 1\" },\n          { keys: [\"Ctrl\", \"Alt\", \"2\"], action: \"Apply Heading 2\" },\n          { keys: [\"Ctrl\", \"Alt\", \"3\"], action: \"Apply Heading 3\" },\n        ] },\n        { type: \"doc\", id: \"mosp-m3-l4-doc\", title: \"Prepare a report for its table of contents\",\n          task: \"Apply Heading 1 to the three chapter titles (Introduction to the programme, Results of the year, Outlook for 2027) and Heading 2 to the two section titles (Vaccination campaigns, Community health training). Then justify the introduction paragraph.\",\n          hint: \"Click in each title and choose the style; you do not need to select the whole line. Chapters are Heading 1, the sections inside a chapter are Heading 2.\",\n          html: \"<p>Introduction to the programme</p><p>In 2026 our association ran a community health programme in twelve villages of the Far North region, with support from two international partners and the district health services.</p><p>Results of the year</p><p>Vaccination campaigns</p><p>Four campaigns reached 3 850 children under five, an increase of 18% on the previous year.</p><p>Community health training</p><p>Sixty community relays were trained in hygiene, nutrition and the early signs of malaria.</p><p>Outlook for 2027</p><p>The programme will extend to four new villages if the partners renew their funding.</p>\",\n          checks: [\n            { kind: \"heading\", level: 1, text: \"Introduction to the programme\" },\n            { kind: \"heading\", level: 1, text: \"Results of the year\" },\n            { kind: \"heading\", level: 1, text: \"Outlook for 2027\" },\n            { kind: \"heading\", level: 2, text: \"Vaccination campaigns\" },\n            { kind: \"heading\", level: 2, text: \"Community health training\" },\n            { kind: \"align\", text: \"twelve villages of the Far North\", value: \"justify\" },\n          ] },\n        { type: \"h\", text: \"Insert and update the table of contents\" },\n        { type: \"path\", items: [\"References\", \"Table of Contents\", \"Automatic Table 1\"], note: \"Custom Table of Contents lets you choose how many heading levels to show and the style of the dotted leaders.\" },\n        { type: \"steps\", title: \"Insert a table of contents\", items: [\n          \"Put the cursor on the blank page after the cover page.\",\n          \"Go to **References › Table of Contents** and choose an automatic table.\",\n          \"Hold Ctrl and click an entry to check that it jumps to the right heading.\",\n          \"After editing the report, click **References › Update Table**.\",\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Page numbers only, or entire table?\", text: \"Update Table asks what to update. Choose **Update page numbers only** when only the length of the text changed. Choose **Update entire table** when you added, deleted or renamed headings.\" },\n        { type: \"h\", text: \"Captions and cross-references\" },\n        { type: \"steps\", title: \"Number a figure or a table\", items: [\n          \"Select the picture, chart or table.\",\n          \"Go to **References › Captions › Insert Caption**.\",\n          \"Choose the label Figure or Table, type a short description after the number, and choose the position: usually above a table and below a figure.\",\n          \"Word numbers the captions in order and renumbers them when you insert a new one in between.\",\n        ] },\n        { type: \"path\", items: [\"References\", \"Captions\", \"Cross-reference\"], note: \"Choose the reference type (Figure, Table, Heading), then \\\"Only label and number\\\" to write \\\"see Figure 3\\\" in the text.\" },\n        { type: \"path\", items: [\"References\", \"Captions\", \"Insert Table of Figures\"], note: \"Lists every caption with its page number, like a table of contents for figures or tables.\" },\n        { type: \"p\", text: \"Cross-references, captions and tables of figures are fields, like the table of contents. Before printing, press Ctrl + A and then F9 to update all of them at once.\" },\n        { type: \"h\", text: \"Footnotes\" },\n        { type: \"p\", text: \"A footnote adds a source or an explanation at the bottom of the page without breaking the flow of the text. Use References › Footnotes › Insert Footnote (Ctrl + Alt + F). Word numbers the notes and keeps each one on the same page as its reference number.\" },\n        { type: \"h\", text: \"A letterhead template (.dotx)\" },\n        { type: \"steps\", title: \"Create and use a letterhead template\", items: [\n          \"In a new document, put the logo, company name, address, taxpayer number (NIU) and phone numbers in the header and footer.\",\n          \"Set A4, the margins and the styles your company uses, and leave the body empty.\",\n          \"Go to File › Save As and choose Word Template (*.dotx) as the file type. Word proposes the Custom Office Templates folder: keep it.\",\n          \"To write a letter, go to **File › New › Personal** and click the template. Word opens a new untitled document, so the template itself stays clean.\",\n          \"To change the template later, open the .dotx file itself (File › Open), edit it and save it.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A logistics SME in Douala found five different letterheads in use, some with an old phone number. The office manager built one .dotx template with the current details and shared it in the team's OneDrive. Every new letter now starts from the same, correct letterhead.\" },\n        { type: \"check\", id: \"mosp-m3-l4-c1\", question: \"You added two new chapters to a report, but they do not appear in the table of contents. What do you do?\", options: [\"Type them into the table of contents by hand\", \"References › Update Table › Update page numbers only\", \"Check that they use Heading 1, then References › Update Table › Update entire table\", \"Delete the table of contents and retype it\"], answer: 2, explain: \"New headings appear only if they use a Heading style, and only after an update of the entire table. Page numbers only would not add them.\" },\n        { type: \"task\", id: \"mosp-m3-l4-t1\", title: \"Practice\", items: [\n          \"Apply Heading 1 and Heading 2 to a report of at least five pages and check the Navigation Pane\",\n          \"Insert an automatic table of contents after the cover page\",\n          \"Add captions to two tables and one picture, then refer to the picture with a cross-reference\",\n          \"Insert a table of figures and a footnote that gives a source\",\n          \"Save your organisation's letterhead as a .dotx template and create a new letter from it\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Create a template\", url: \"https://support.microsoft.com/en-us/office/create-a-template-86a1d089-5ae2-4d53-9042-1191bce57deb\", source: MS },\n          MO110,\n        ] },\n      ],\n    },\n    // ─────────────────────────── PRACTICE LAB ───────────────────────────\n    {\n      id: \"mosp-m3-practice\",\n      title: \"Practice lab: advanced Word documents\",\n      minutes: 40,\n      objectives: [\n        \"Choose the right table command for a real document\",\n        \"Check a recipient list before a mail merge\",\n        \"Structure and format a long document for its table of contents\",\n        \"Plan a complete merge, review and publication workflow\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" },\n        { type: \"h\", text: \"Exercise 1: A price list table\" },\n        { type: \"form\", id: \"mosp-pr-m3-table\", level: \"beginner\", title: \"Build a supplier price list\",\n          task: \"A pharmacy in Garoua receives a supplier price list as plain text, with a tab between the product, the pack size and the price. Choose the right command for each step.\",\n          hint: \"Creating a table from existing text is on the Insert tab. Everything you do once the table exists is on Table Design (appearance) or Table Layout (structure, sorting and formulas).\",\n          fields: [\n            { kind: \"select\", label: \"Turn the tabbed lines into a table.\", options: [\"Insert › Table › Convert Text to Table\", \"Home › Paragraph › Tabs\", \"Insert › Table › Draw Table\", \"Table Layout › Convert to Text\"], answer: 0 },\n            { kind: \"select\", label: \"Give the table shaded header formatting and banded rows in one click.\", options: [\"Home › Styles › Heading 1\", \"Table Design › Table Styles\", \"Table Layout › Alignment\", \"Layout › Page Color\"], answer: 1 },\n            { kind: \"select\", label: \"The prices must line up on the units. How do you align the price column?\", options: [\"Centre\", \"Left\", \"Right\", \"Justify\"], answer: 2, explain: \"Right-aligned amounts put units under units and thousands under thousands, which makes them easy to compare.\" },\n            { kind: \"select\", label: \"Put the products in alphabetical order without moving the header.\", options: [\"Table Layout › Data › Sort, with a header row\", \"Table Design › First Column\", \"Cut and paste the rows\", \"Home › Find › Replace\"], answer: 0 },\n            { kind: \"select\", label: \"Make every column exactly as wide as its content.\", options: [\"AutoFit Window\", \"Fixed Column Width\", \"AutoFit Contents\", \"Split Cells\"], answer: 2 },\n          ] },\n        { type: \"h\", text: \"Exercise 2: Check a mailing list\" },\n        { type: \"sheet\", id: \"mosp-pr-m3-list\", level: \"intermediate\", title: \"Is the list ready for the merge?\",\n          task: \"A farmers' cooperative in Garoua will send its members a dues reminder by mail merge. Before merging, fill H2:H7: the number of members, the number of missing e-mail addresses, the number of members in Garoua, the dues collected, the Garoua members who paid at least 10 000 FCFA and the members with no payment recorded.\",\n          data: [\n            [\"Member ID\", \"Name\", \"City\", \"Email\", \"Dues paid\", null, \"Check\", \"Result\"],\n            [\"M01\", \"Aïcha Bello\", \"Garoua\", \"a.bello@mail.cm\", 15000, null, \"Members\", null],\n            [\"M02\", \"Paul Ndzana\", \"Yaoundé\", null, 10000, null, \"Missing e-mails\", null],\n            [\"M03\", \"Hadja Oumarou\", \"Garoua\", null, 5000, null, \"Members in Garoua\", null],\n            [\"M04\", \"Serge Tchoupo\", \"Bafoussam\", \"s.tchoupo@mail.cm\", 15000, null, \"Dues collected\", null],\n            [\"M05\", \"Mireille Ekané\", \"Douala\", \"m.ekane@mail.cm\", null, null, \"Garoua, paid ≥ 10 000\", null],\n            [\"M06\", \"Ibrahim Saïdou\", \"Garoua\", \"i.saidou@mail.cm\", 10000, null, \"No payment recorded\", null],\n            [\"M07\", \"Carine Fotso\", \"Bafoussam\", null, 15000],\n            [\"M08\", \"Abdou Hamadou\", \"Garoua\", \"a.hamadou@mail.cm\", 7500],\n          ],\n          editable: [\"H2\", \"H3\", \"H4\", \"H5\", \"H6\", \"H7\"],\n          checks: [{ cell: \"H2\", equals: 8 }, { cell: \"H3\", equals: 3 }, { cell: \"H4\", equals: 4 }, { cell: \"H5\", equals: 77500 }, { cell: \"H6\", equals: 2 }, { cell: \"H7\", equals: 1 }],\n          hint: \"COUNTA counts filled cells and COUNTBLANK counts empty ones. COUNTIF(C2:C9,\\\"Garoua\\\") counts one city. For two conditions use COUNTIFS(C2:C9,\\\"Garoua\\\",E2:E9,\\\">=10000\\\").\",\n          solution: { H2: \"=COUNTA(A2:A9)\", H3: \"=COUNTBLANK(D2:D9)\", H4: \"=COUNTIF(C2:C9,\\\"Garoua\\\")\", H5: \"=SUM(E2:E9)\", H6: \"=COUNTIFS(C2:C9,\\\"Garoua\\\",E2:E9,\\\">=10000\\\")\", H7: \"=COUNTBLANK(E2:E9)\" } },\n        { type: \"h\", text: \"Exercise 3: A procedures manual\" },\n        { type: \"doc\", id: \"mosp-pr-m3-manual\", level: \"advanced\", title: \"Structure a procedures manual\",\n          task: \"Prepare this extract of a ministry procedures manual for its table of contents and for printing: the two chapter titles in Heading 1, the two section titles in Heading 2, the purpose paragraph justified, the deadline in bold and the four steps as a numbered list.\",\n          hint: \"Chapters: \\\"Mission expenses\\\" and \\\"Supporting documents\\\". Sections: \\\"Before the mission\\\" and \\\"After the mission\\\". Select the four steps together before clicking Numbering. Bold only the words \\\"within 15 days\\\".\",\n          html: \"<p>Chapter 3: Mission expenses</p><p>This procedure explains how staff of the regional delegation prepare, approve and justify the costs of a mission outside their duty station, so that every payment can be checked during an audit.</p><p>Before the mission</p><p>Fill in the mission order form and attach the terms of reference</p><p>Have the form signed by your head of service</p><p>Send it to the finance unit for the advance</p><p>Collect the advance against a signed receipt</p><p>After the mission</p><p>Submit your mission report and the remaining receipts within 15 days of your return.</p><p>Chapter 4: Supporting documents</p><p>The finance unit keeps every receipt for ten years.</p>\",\n          checks: [\n            { kind: \"heading\", level: 1, text: \"Mission expenses\" },\n            { kind: \"heading\", level: 1, text: \"Supporting documents\" },\n            { kind: \"heading\", level: 2, text: \"Before the mission\" },\n            { kind: \"heading\", level: 2, text: \"After the mission\" },\n            { kind: \"align\", text: \"regional delegation prepare\", value: \"justify\" },\n            { kind: \"bold\", text: \"within 15 days\" },\n            { kind: \"list\", ordered: true, min: 4 },\n          ] },\n        { type: \"h\", text: \"Exercise 4: Payslip notices from start to finish\" },\n        { type: \"form\", id: \"mosp-pr-m3-workflow\", level: \"expert\", title: \"Plan the whole production\",\n          task: \"An SME in Yaoundé sends a monthly pay notice to 45 employees, on its letterhead, reviewed by the finance manager before it goes out. Answer each question about the complete workflow. Type shortcuts as keys joined with +, for example Ctrl + B.\",\n          hint: \"Think in order: the letterhead template, the Excel list, the merge fields and rules, the review with Track Changes, then the final merge. Each answer is in one of the four lessons of this module.\",\n          fields: [\n            { kind: \"select\", label: \"The letterhead must be reused every month without anyone overwriting it. How is it saved?\", options: [\"As a .docx in Documents\", \"As a Word Template (.dotx)\", \"As a PDF\", \"As a .txt file\"], answer: 1 },\n            { kind: \"select\", label: \"The Excel payroll list has a merged title in row 1 and the column names in row 3. What do you do before merging?\", options: [\"Nothing, Word skips the title\", \"Delete the title rows so the column names are in row 1, with no merged cells\", \"Merge the header cells too\", \"Save the list as a PDF\"], answer: 1, explain: \"Word reads the first row as the field names. A merged title in row 1 gives fields with meaningless names.\" },\n            { kind: \"text\", label: \"Type the merge field for the Excel column named NetPay.\", accept: [\"«NetPay»\", \"<<NetPay>>\"], example: \"«NetPay»\", placeholder: \"«…»\", mono: true },\n            { kind: \"select\", label: \"Employees with a salary advance must see an extra sentence about the repayment. Which rule do you use?\", options: [\"Skip Record If\", \"Next Record\", \"If…Then…Else\", \"Merge Record #\"], answer: 2, explain: \"If…Then…Else inserts one text when a condition is true (for example Advance greater than 0) and another text, or nothing, otherwise.\" },\n            { kind: \"text\", label: \"The finance manager reviews the letter template. Which shortcut turns Track Changes on?\", accept: [\"Ctrl+Shift+E\", \"Shift+Ctrl+E\"], placeholder: \"Ctrl + …\", mono: true },\n            { kind: \"text\", label: \"Which shortcut inserts a comment on the selected text?\", accept: [\"Ctrl+Alt+M\", \"Alt+Ctrl+M\"], placeholder: \"Ctrl + …\", mono: true },\n            { kind: \"select\", label: \"The finance manager must not be able to switch tracking off. Which setting do you apply?\", options: [\"Restrict Editing with Tracked changes\", \"Simple Markup\", \"Mark as Final\", \"Lock the Excel file\"], answer: 0 },\n            { kind: \"select\", label: \"All changes are accepted. What is the safest way to finish, so you can check the 45 notices before they are printed?\", options: [\"Print Documents\", \"Send Email Messages\", \"Edit Individual Documents\", \"Preview Results only\"], answer: 2 },\n          ] },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"mosp-m3-quiz\",\n    title: \"Module 3 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"A table runs over four pages. How do you make its column titles appear at the top of each page?\", options: [\"Copy the first row at the top of each page\", \"Insert a page break before each page\", \"Table Layout › Data › Repeat Header Rows\", \"Table Design › Header Row\"], answer: 2, explain: \"Repeat Header Rows follows the page breaks automatically. The Header Row option only changes formatting.\" },\n      { id: \"q2\", question: \"In a mail merge, what is the Excel list of recipients called?\", options: [\"The data source\", \"The main document\", \"The template\", \"The merged result\"], answer: 0, explain: \"The data source holds one row per recipient. The main document holds the text that is the same for everyone.\" },\n      { id: \"q3\", question: \"What does Ctrl + Shift + E do in Word?\", options: [\"Centres the paragraph\", \"Inserts a comment\", \"Opens the Editor pane\", \"Turns Track Changes on or off\"], answer: 3, explain: \"Ctrl + Shift + E switches tracking on or off. Ctrl + Alt + M inserts a comment and F7 opens the Editor.\" },\n      { id: \"q4\", question: \"Which Display for Review option shows the edited text with only a red line in the margin where changes were made?\", options: [\"All Markup\", \"Simple Markup\", \"No Markup\", \"Original\"], answer: 1, explain: \"Simple Markup is comfortable for reading. Switch to All Markup to see each change in detail.\" },\n      { id: \"q5\", question: \"You renamed several headings. What must you do so the table of contents shows the new names?\", options: [\"Update page numbers only\", \"Press Ctrl + S\", \"References › Update Table › Update entire table\", \"Insert a new table of contents below the old one\"], answer: 2, explain: \"Update page numbers only keeps the old text. Update entire table rebuilds the list from the current headings.\" },\n      { id: \"q6\", question: \"Which file type should you use for a company letterhead that everyone reuses?\", options: [\".dotx\", \".docx\", \".pdf\", \".xlsx\"], answer: 0, explain: \"A .dotx template opens as a new untitled document each time, so the original letterhead is never overwritten.\" },\n      { id: \"q7\", question: \"You changed a number in a Word table, but the =SUM(ABOVE) total did not change. What do you do?\", options: [\"Retype the total\", \"Save the document\", \"Convert the table to text\", \"Select the total and press F9\"], answer: 3, explain: \"Word formulas are fields that do not recalculate by themselves. F9 updates the selected fields.\" },\n      { id: \"q8\", question: \"Which recipient list will work best for a mail merge?\", options: [\"A list with a merged title in row 1 and totals at the bottom\", \"One header row in row 1, one row per person, no merged cells and no totals\", \"A Word table with one person per paragraph\", \"A list with names and addresses in one column\"], answer: 1, explain: \"Word reads the first row as field names and creates one letter per row, so the list must be clean and rectangular.\" },\n    ],\n  },\n};\n","client/src/data/courses/mosp/m4.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// Module 4 — Microsoft Excel: Spreadsheet Fundamentals\n// Original Analytix Engineering material, aligned to exam MO-210 (Excel, Microsoft 365 Apps).\n\nconst MS = \"Microsoft Support\";\nconst LEARN = \"Microsoft Learn\";\nconst EXAM = { label: \"Exam MO-210: Microsoft Excel (Microsoft 365 Apps)\", url: \"https://learn.microsoft.com/en-us/credentials/certifications/exams/mo-210/\", source: LEARN };\nconst SHORTCUTS = { label: \"Keyboard shortcuts in Excel\", url: \"https://support.microsoft.com/en-us/office/keyboard-shortcuts-in-excel-1798d9d5-842a-42b8-9c99-9b7213f0040f\", source: MS };\n\nexport const m4: CourseModule = {\n  id: \"mosp-m4\",\n  number: 4,\n  title: \"Microsoft Excel — Spreadsheet Fundamentals\",\n  summary: \"Workbooks, formulas, cell references, sorting, filtering and charts.\",\n  hours: 12,\n  lessons: [\n    // ─────────────────────────────── LESSON 1 ───────────────────────────────\n    {\n      id: \"mosp-m4-l1\",\n      title: \"Your first workbook: entering and organising data\",\n      minutes: 25,\n      objectives: [\n        \"Enter text, numbers and dates so that Excel recognises their type\",\n        \"Fill series and patterns quickly with AutoFill and Flash Fill\",\n        \"Organise sheets and save a workbook as .xlsx, .csv or PDF\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Excel is where most offices keep their numbers: daily sales, school fees, fuel purchases, staff hours, stock. A spreadsheet is only as reliable as the data typed into it, so this lesson is about entering data correctly and moving around a workbook quickly before we start calculating.\" },\n        { type: \"h\", text: \"Workbook, worksheet, cell and range\" },\n        { type: \"table\", head: [\"Term\", \"What it is\", \"Example\"], rows: [\n          [\"Workbook\", \"The Excel file itself\", \"2026_Ventes-Boutique.xlsx\"],\n          [\"Worksheet (sheet)\", \"One page of the workbook, shown as a tab at the bottom\", \"A sheet per month: Jan, Feb, Mar\"],\n          [\"Cell\", \"The box where a column and a row meet, named by its column letter and row number\", \"C4 is column C, row 4\"],\n          [\"Range\", \"A rectangle of cells, written as first cell:last cell\", \"B2:B31 holds one month of daily sales\"],\n        ] },\n        { type: \"h\", text: \"Text, numbers and dates\" },\n        { type: \"list\", items: [\n          \"**Text** (names, products, references) is aligned to the left by default.\",\n          \"**Numbers** are aligned to the right. Type them without units or spaces, for example 350000, and let the number format add the separator and FCFA later.\",\n          \"**Dates** are stored as numbers too, so Excel can sort them and count the days between two dates. Press `Ctrl + ;` to type today's date.\",\n          \"Press `Enter` to confirm and move down, `Tab` to confirm and move right, and `F2` to edit the active cell without retyping it.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Numbers stored as text break your totals\", text: \"An amount typed as 12 500 FCFA, or pasted from a bank or mobile money statement, is often stored as text. It sits on the left of the cell, shows a small green triangle, and SUM simply ignores it. Your total is wrong without any error message. Retype the number, or select the cells and choose **Convert to Number** from the warning icon.\" },\n        { type: \"sheet\", id: \"mosp-m4-l1-sheet\", title: \"Fix the amounts stored as text\",\n          task: \"The total in **D7** is too low because two amounts were typed with \\\"FCFA\\\" and are stored as text. Retype **D3** and **D5** as plain numbers. The total and the count below it will correct themselves.\",\n          data: [[\"Date\", \"Product\", \"Qty\", \"Amount (FCFA)\"],\n            [\"2026-03-02\", \"Rice 5 kg\", 4, 18000],\n            [\"2026-03-02\", \"Palm oil 1 L\", 6, \"7 200 FCFA\"],\n            [\"2026-03-03\", \"Sugar 1 kg\", 10, 9500],\n            [\"2026-03-03\", \"Soap (box)\", 2, \"13 000 FCFA\"],\n            [\"2026-03-04\", \"Tomato paste\", 12, 4800],\n            [null, null, \"Total\", \"=SUM(D2:D6)\"],\n            [null, null, \"Amounts counted\", \"=COUNT(D2:D6)\"]],\n          editable: [\"D3\", \"D5\"],\n          checks: [{ cell: \"D3\", equals: 7200 }, { cell: \"D5\", equals: 13000 }, { cell: \"D7\", equals: 52500 }, { cell: \"D8\", equals: 5 }],\n          hint: \"Type only the digits: 7200 in D3 and 13000 in D5, with no spaces or letters. COUNT counts only real numbers, so it shows 5 when every amount is a number.\",\n          solution: { D3: \"7200\", D5: \"13000\" } },\n        { type: \"callout\", tone: \"workplace\", title: \"Dates and regional settings\", text: \"On a computer set to French (Cameroon), Excel reads 03/04/2026 as 3 April; on one set to English (United States) it reads 4 March. When files travel between colleagues, type dates as 2026-04-03 (year-month-day): Excel understands this form on every computer, and it matches the file naming rule from Module 1.\" },\n        { type: \"h\", text: \"Fill handle, AutoFill and Flash Fill\" },\n        { type: \"steps\", title: \"Fill a series with the fill handle\", items: [\n          \"Type the first value, for example **Jan**, **Monday** or **2026-03-02**. For a number series, type the first two values (1 and 2) and select both.\",\n          \"Point at the small square in the bottom-right corner of the selection. The pointer becomes a thin black cross: this is the **fill handle**.\",\n          \"Drag down or right. Excel continues the series: Feb, Mar, Apr… or 3, 4, 5…\",\n          \"Double-click the fill handle instead of dragging to fill down to the last row of the neighbouring column.\",\n          \"Use the **Auto Fill Options** button that appears to switch between Copy Cells and Fill Series.\",\n        ] },\n        { type: \"p\", text: \"**Flash Fill** learns a pattern from an example. If column A holds invoice references such as DLA-2026-014, type DLA in the first cell of column B, then press `Ctrl + E`: Excel fills the city code for every row. It works just as well to join first names and surnames or to change their capitals.\" },\n        { type: \"path\", items: [\"Data\", \"Data Tools\", \"Flash Fill\"], note: \"Also on Home › Editing › Fill › Flash Fill. Check the result: Flash Fill guesses, and does not update when the source changes.\" },\n        { type: \"h\", text: \"Move around and organise sheets\" },\n        { type: \"shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Arrow\"], action: \"Jump to the edge of the data in that direction\" },\n          { keys: [\"Ctrl\", \"Home\"], action: \"Go to cell A1\" },\n          { keys: [\"Ctrl\", \"End\"], action: \"Go to the last used cell\" },\n          { keys: [\"Ctrl\", \"Page Down\"], action: \"Next sheet (Ctrl + Page Up for the previous one)\" },\n          { keys: [\"Shift\", \"F11\"], action: \"Insert a new sheet\" },\n          { keys: [\"Ctrl\", \";\"], action: \"Enter today's date\" },\n          { keys: [\"Ctrl\", \"Shift\", \";\"], action: \"Enter the current time\" },\n          { keys: [\"Ctrl\", \"E\"], action: \"Flash Fill\" },\n        ] },\n        { type: \"keys\", id: \"mosp-m4-l1-keys\", title: \"Practise the data-entry shortcuts\", items: [\n          { keys: [\"Ctrl\", \";\"], action: \"Enter today's date\" },\n          { keys: [\"Ctrl\", \"E\"], action: \"Flash Fill\" },\n          { keys: [\"F2\"], action: \"Edit the active cell\" },\n          { keys: [\"Ctrl\", \"S\"], action: \"Save\" },\n        ] },\n        { type: \"steps\", title: \"Name and colour sheet tabs\", items: [\n          \"Double-click a sheet tab (or right-click it and choose **Rename**) and type a short name such as **Jan-2026** or **Douala**.\",\n          \"Right-click the tab and choose **Tab Color** to group related sheets, for example green for sales and orange for expenses.\",\n          \"Drag a tab left or right to change the order. Hold `Ctrl` while dragging to make a copy of the sheet.\",\n        ] },\n        { type: \"h\", text: \"Save in the right format\" },\n        { type: \"table\", head: [\"Format\", \"What it keeps\", \"Use it when\"], rows: [\n          [\".xlsx\", \"Everything: all sheets, formulas, formatting and charts\", \"The normal working format\"],\n          [\".csv\", \"Only the values of the active sheet, as plain text\", \"Another system (accounting software, a database, a mobile money platform) must import the data\"],\n          [\".pdf\", \"A fixed picture of the printed pages\", \"The figures are final and must be read, not changed\"],\n        ] },\n        { type: \"path\", items: [\"File\", \"Save As\", \"Save as type\"], note: \"Choose Excel Workbook (*.xlsx), CSV UTF-8 (Comma delimited) (*.csv) or PDF (*.pdf).\" },\n        { type: \"check\", id: \"mosp-m4-l1-c1\", question: \"You paste a column of amounts from a mobile money statement. They sit on the left of the cells and SUM returns a total that is far too low. What is the most likely cause?\", options: [\"The column is too narrow\", \"The amounts are stored as text\", \"The sheet is protected\", \"SUM only works on the first ten rows\"], answer: 1, explain: \"Left alignment and a green triangle are the signs of numbers stored as text. SUM skips text, so those amounts are left out of the total without any error.\" },\n        { type: \"task\", id: \"mosp-m4-l1-t1\", title: \"Practice\", items: [\n          \"Create a workbook with three sheets named Jan, Feb and Mar, each with a different tab colour\",\n          \"On Jan, type a date in A2 as 2026-01-05 and fill the next 10 days with the fill handle\",\n          \"Type five invoice references like DLA-2026-014 and extract the city codes with Ctrl + E\",\n          \"Type one amount as \\\"5 000 FCFA\\\", watch SUM ignore it, then convert it to a number\",\n          \"Save the workbook as .xlsx, then save the Jan sheet as a CSV copy\",\n        ] },\n        { type: \"links\", items: [SHORTCUTS, EXAM] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 2 ───────────────────────────────\n    {\n      id: \"mosp-m4-l2\",\n      title: \"Formulas and cell references\",\n      minutes: 30,\n      objectives: [\n        \"Write formulas with operators and the everyday functions SUM, AVERAGE, MIN, MAX, COUNT and COUNTA\",\n        \"Choose between relative, absolute and mixed references and toggle them with F4\",\n        \"Calculate percentages and growth, and fix the most common formula errors\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A formula turns a sheet of numbers into a tool that answers questions: how much did we collect, what is the average, which branch sold most? Because formulas point to cells instead of fixed numbers, the answers update by themselves when the data changes.\" },\n        { type: \"h\", text: \"Anatomy of a formula\" },\n        { type: \"p\", text: \"Every formula starts with an equals sign. `=B2*C2` multiplies the value in B2 by the value in C2. Click a cell instead of typing its address to avoid typing mistakes, and press `Enter` to confirm.\" },\n        { type: \"table\", head: [\"Operator\", \"Meaning\", \"Example\"], rows: [\n          [\"+  −\", \"Add, subtract\", \"=B2+B3−B4\"],\n          [\"*  /\", \"Multiply, divide\", \"=C2*D2   =E2/E10\"],\n          [\"^\", \"Power\", \"=1.05^3 (three years of 5% growth)\"],\n          [\"%\", \"Per cent\", \"=B2*19.25%\"],\n          [\"&\", \"Join text\", \"=A2&\\\" \\\"&B2\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Order of operations\", text: \"Excel calculates brackets first, then powers, then multiplication and division, then addition and subtraction. So =10+20/2 gives 20, not 15. To average two cells write =(B2+C2)/2, with the brackets.\" },\n        { type: \"h\", text: \"The functions you will use every day\" },\n        { type: \"table\", head: [\"Function\", \"What it returns\", \"Example\"], rows: [\n          [\"SUM\", \"The total of the numbers\", \"=SUM(C2:C31)\"],\n          [\"AVERAGE\", \"The mean of the numbers (empty cells are ignored)\", \"=AVERAGE(C2:C31)\"],\n          [\"MIN / MAX\", \"The smallest / largest number\", \"=MAX(C2:C31)\"],\n          [\"COUNT\", \"How many cells contain numbers\", \"=COUNT(C2:C31)\"],\n          [\"COUNTA\", \"How many cells are not empty (text or numbers)\", \"=COUNTA(A2:A31)\"],\n        ] },\n        { type: \"path\", items: [\"Home\", \"Editing\", \"AutoSum\"], note: \"Or press Alt + =. Excel proposes a range: check it before pressing Enter. The arrow next to AutoSum offers Average, Count Numbers, Max and Min.\" },\n        { type: \"sheet\", id: \"mosp-m4-l2-fees\", title: \"School fees: the first instalment\",\n          task: \"Pupils with an empty cell in column C have not paid yet. Fill **F2:F8** with the total collected, the average payment, the smallest and largest payments, the number of pupils who paid, the number of pupils on the list and the number who have not paid.\",\n          data: [[\"Pupil\", \"Class\", \"Paid (FCFA)\", null, \"Measure\", \"Result\"],\n            [\"Ngo Biyong A.\", \"6e A\", 45000, null, \"Total collected\", null],\n            [\"Tchinda P.\", \"6e A\", 60000, null, \"Average payment\", null],\n            [\"Abena M.\", \"6e B\", null, null, \"Smallest payment\", null],\n            [\"Fouda J.\", \"6e B\", 30000, null, \"Largest payment\", null],\n            [\"Mbarga S.\", \"6e A\", 60000, null, \"Pupils who paid\", null],\n            [\"Nkeng L.\", \"6e B\", null, null, \"Pupils on the list\", null],\n            [\"Eyenga R.\", \"6e A\", 45000, null, \"Pupils not paid\", null]],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"F6\", \"F7\", \"F8\"],\n          checks: [{ cell: \"F2\", equals: 240000 }, { cell: \"F3\", equals: 48000 }, { cell: \"F4\", equals: 30000 }, { cell: \"F5\", equals: 60000 },\n            { cell: \"F6\", equals: 5 }, { cell: \"F7\", equals: 7 }, { cell: \"F8\", equals: 2 }],\n          hint: \"Use SUM, AVERAGE, MIN and MAX on C2:C8. COUNT(C2:C8) counts only the payments; COUNTA(A2:A8) counts every name. Pupils not paid is one count minus the other: =F7-F6.\",\n          solution: { F2: \"=SUM(C2:C8)\", F3: \"=AVERAGE(C2:C8)\", F4: \"=MIN(C2:C8)\", F5: \"=MAX(C2:C8)\", F6: \"=COUNT(C2:C8)\", F7: \"=COUNTA(A2:A8)\", F8: \"=F7-F6\" } },\n        { type: \"h\", text: \"Relative, absolute and mixed references\" },\n        { type: \"p\", text: \"When you copy a formula, Excel adjusts its cell references. `=C4*B1` copied one row down becomes `=C5*B2`. That is right for C, but wrong for B1 if B1 holds a single rate that every row needs. A dollar sign locks the part of the reference that must not move.\" },\n        { type: \"table\", head: [\"Reference\", \"Written\", \"When copied\"], rows: [\n          [\"Relative\", \"B1\", \"Column and row both change\"],\n          [\"Absolute\", \"$B$1\", \"Always points to B1\"],\n          [\"Mixed (row locked)\", \"B$1\", \"The column changes, the row stays 1\"],\n          [\"Mixed (column locked)\", \"$B1\", \"The column stays B, the row changes\"],\n        ] },\n        { type: \"steps\", title: \"Lock a reference with F4\", items: [\n          \"Type the formula, for example =C4*B1, and leave the cursor on or just after B1.\",\n          \"Press `F4` once to get $B$1. Press again for B$1, again for $B1, and once more to return to B1.\",\n          \"Press `Enter`, then copy the formula down with the fill handle.\",\n          \"Click a copied cell and check the formula bar: the locked reference has not moved.\",\n        ] },\n        { type: \"sheet\", id: \"mosp-m4-l2-fuel\", title: \"Fuel costs with one price cell\",\n          task: \"The fuel price is in **B1**. Fill **D4:D7** with each vehicle's cost (litres × price), **D8** with the total cost, and **E4:E7** with each vehicle's share of the total. Use absolute references so the formulas can be copied down.\",\n          data: [[\"Fuel price (FCFA/L)\", 840],\n            [null],\n            [\"Vehicle\", \"Driver\", \"Litres\", \"Cost (FCFA)\", \"Share of total\"],\n            [\"LT 214 AB\", \"Kamga\", 45, null, null],\n            [\"CE 887 KL\", \"Ndjock\", 62, null, null],\n            [\"OU 102 FG\", \"Aboubakar\", 38, null, null],\n            [\"NW 559 HP\", \"Tabi\", 55, null, null],\n            [\"Total\", null, \"=SUM(C4:C7)\", null]],\n          editable: [\"D4\", \"D5\", \"D6\", \"D7\", \"D8\", \"E4\", \"E5\", \"E6\", \"E7\"],\n          checks: [{ cell: \"D4\", equals: 37800 }, { cell: \"D5\", equals: 52080 }, { cell: \"D6\", equals: 31920 }, { cell: \"D7\", equals: 46200 }, { cell: \"D8\", equals: 168000 },\n            { cell: \"E4\", equals: 0.225, tol: 0.001 }, { cell: \"E5\", equals: 0.31, tol: 0.001 }, { cell: \"E6\", equals: 0.19, tol: 0.001 }, { cell: \"E7\", equals: 0.275, tol: 0.001 }],\n          hint: \"D4 is =C4*$B$1 and E4 is =D4/$D$8. Without the dollar signs, the copy in D5 would multiply by B2, which is empty, and give 0.\",\n          solution: { D4: \"=C4*$B$1\", D5: \"=C5*$B$1\", D6: \"=C6*$B$1\", D7: \"=C7*$B$1\", D8: \"=SUM(D4:D7)\", E4: \"=D4/$D$8\", E5: \"=D5/$D$8\", E6: \"=D6/$D$8\", E7: \"=D7/$D$8\" } },\n        { type: \"callout\", tone: \"workplace\", title: \"Put every rate in its own cell\", text: \"VAT at 19.25%, the pump price of fuel, a per diem or an exchange rate change during the year. Type each one once in a clearly labelled cell and refer to it with an absolute reference. When the rate changes, you update one cell instead of hunting through hundreds of formulas.\" },\n        { type: \"h\", text: \"Percentages and growth\" },\n        { type: \"list\", items: [\n          \"Share of a total: `=B2/$B$10`, then apply the Percent Style.\",\n          \"Growth from last year to this year: `=(C2-B2)/B2`, or `=C2/B2-1`. From 800 000 to 920 000 FCFA is 15% growth.\",\n          \"Add a percentage: `=B2*(1+$F$1)`. Remove a discount: `=B2*(1-$F$2)`.\",\n          \"A percentage is a share: 15% is stored as 0.15. Type 15% with the sign, or 0.15, never 15.\",\n        ] },\n        { type: \"h\", text: \"When a formula shows an error\" },\n        { type: \"table\", head: [\"Error\", \"Usual cause\", \"Fix\"], rows: [\n          [\"#DIV/0!\", \"Division by an empty cell or by zero\", \"Check the divisor; for a new branch with no sales last year, growth cannot be calculated\"],\n          [\"#VALUE!\", \"Arithmetic on text, for example a number stored as text with FCFA\", \"Convert the text to a number\"],\n          [\"#NAME?\", \"A misspelled function (=SUMM) or text typed without quotes\", \"Correct the spelling; use the function list that appears as you type\"],\n          [\"#REF!\", \"A cell the formula pointed to was deleted\", \"Undo the deletion or rewrite the reference\"],\n          [\"#####\", \"Not an error: the column is too narrow for the number\", \"Double-click the column's right border to widen it\"],\n        ] },\n        { type: \"keys\", id: \"mosp-m4-l2-keys\", title: \"Practise the formula shortcuts\", items: [\n          { keys: [\"Alt\", \"=\"], action: \"AutoSum\" },\n          { keys: [\"F4\"], action: \"Toggle absolute and relative references\" },\n          { keys: [\"Ctrl\", \"Enter\"], action: \"Enter the same formula in every selected cell\" },\n          { keys: [\"F2\"], action: \"Edit the active cell\" },\n        ] },\n        { type: \"check\", id: \"mosp-m4-l2-c1\", question: \"E4 contains =D4/D8, where D8 is the total. You copy it down to E5 and get #DIV/0!. How should E4 be written?\", options: [\"=D4/D9\", \"=$D$4/D8\", \"=D4/$D$8\", \"=SUM(D4/D8)\"], answer: 2, explain: \"Copying moves D8 to D9, which is empty, so Excel divides by zero. $D$8 keeps the total fixed while D4 moves down with each row.\" },\n        { type: \"check\", id: \"mosp-m4-l2-c2\", question: \"A shop sold 800 000 FCFA in March and 920 000 FCFA in April (B2 and C2). Which formula gives the growth?\", options: [\"=C2-B2\", \"=(C2-B2)/B2\", \"=C2-B2/B2\", \"=B2/C2\"], answer: 1, explain: \"Growth is the change divided by the starting value: 120 000 / 800 000 = 0.15, or 15%. Without brackets, Excel divides B2 by B2 first.\" },\n        { type: \"task\", id: \"mosp-m4-l2-t1\", title: \"Practice\", items: [\n          \"List ten expenses in column B and total them with Alt + =\",\n          \"Add the average, the smallest and the largest expense with AVERAGE, MIN and MAX\",\n          \"Put a VAT rate of 19.25% in one cell and calculate VAT for each expense with an absolute reference\",\n          \"Calculate each expense's share of the total and apply the Percent Style\",\n          \"Create a #DIV/0! and a #NAME? error on purpose, then fix them\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Switch between relative, absolute, and mixed references\", url: \"https://support.microsoft.com/en-us/office/switch-between-relative-absolute-and-mixed-references-dfec08cd-ae65-4f56-839e-5f0d8d0baca9\", source: MS },\n          { label: \"Overview of formulas in Excel\", url: \"https://support.microsoft.com/en-us/office/overview-of-formulas-in-excel-ecfdc708-9162-49e8-b993-c311f47ca173\", source: MS },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 3 ───────────────────────────────\n    {\n      id: \"mosp-m4-l3\",\n      title: \"Sort, filter and format data\",\n      minutes: 30,\n      objectives: [\n        \"Sort a list on one or several levels and filter it to show only the rows you need\",\n        \"Format a list as a table and apply number formats for FCFA, percentages and thousands\",\n        \"Highlight key values with conditional formatting and clean data with Freeze Panes, Remove Duplicates and Find & Replace\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A list of 500 transactions is hard to read. Sorting puts it in a useful order, filtering hides what you do not need, and formatting makes the important figures stand out. None of these tools changes your data: they change how you see it.\" },\n        { type: \"h\", text: \"Prepare the list first\" },\n        { type: \"list\", items: [\n          \"One header row with a clear, unique name in every column.\",\n          \"No completely blank rows or columns inside the list: Excel treats them as the end of the data.\",\n          \"One type of data per column: only dates in the date column, only numbers in the amount column.\",\n          \"No merged cells inside the list. Merged cells block sorting.\",\n        ] },\n        { type: \"h\", text: \"Sort on one or several levels\" },\n        { type: \"p\", text: \"To sort on one column, click any cell in it and use **Sort A to Z** or **Sort Z to A**. Excel sorts the whole list and keeps each row together. For more than one criterion, use the Sort dialog.\" },\n        { type: \"path\", items: [\"Data\", \"Sort & Filter\", \"Sort\"], note: \"Also Home › Editing › Sort & Filter › Custom Sort.\" },\n        { type: \"steps\", title: \"Sort by region, then by amount\", items: [\n          \"Click any cell inside the list, then open **Data › Sort**.\",\n          \"Check that **My data has headers** is ticked.\",\n          \"In **Sort by**, choose Region, order A to Z.\",\n          \"Click **Add Level**. In **Then by**, choose Amount, order Largest to Smallest.\",\n          \"Click OK. Rows are grouped by region and, inside each region, the largest amounts come first.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Never sort a single selected column\", text: \"If you select only one column and sort it, Excel warns you. Always choose **Expand the selection**. Otherwise that column moves on its own and every amount ends up next to the wrong name.\" },\n        { type: \"sheet\", id: \"mosp-m4-l3-sheet\", title: \"Subtotals after sorting\",\n          task: \"The deposits list has been sorted by region, then by amount. Because each region is now a block of rows, a simple SUM gives each regional total. Fill **F2:F4** with the three regional totals, **F5** with the total of all regions and **F6** with Littoral's share of that total.\",\n          data: [[\"Region\", \"Agent\", \"Deposits (FCFA)\", null, \"Region\", \"Total\"],\n            [\"Centre\", \"Owona\", 850000, null, \"Centre\", null],\n            [\"Centre\", \"Ateba\", 620000, null, \"Littoral\", null],\n            [\"Centre\", \"Mvondo\", 410000, null, \"Ouest\", null],\n            [\"Littoral\", \"Ekwalla\", 1200000, null, \"All regions\", null],\n            [\"Littoral\", \"Njoh\", 975000, null, \"Littoral share\", null],\n            [\"Littoral\", \"Din\", 540000],\n            [\"Littoral\", \"Kotto\", 305000],\n            [\"Ouest\", \"Fotso\", 730000],\n            [\"Ouest\", \"Kamdem\", 455000]],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"F6\"],\n          checks: [{ cell: \"F2\", equals: 1880000 }, { cell: \"F3\", equals: 3020000 }, { cell: \"F4\", equals: 1185000 }, { cell: \"F5\", equals: 6085000 }, { cell: \"F6\", equals: 0.4963, tol: 0.001 }],\n          hint: \"Centre is rows 2 to 4, Littoral rows 5 to 8, Ouest rows 9 and 10: =SUM(C2:C4), =SUM(C5:C8), =SUM(C9:C10). The share is =F3/F5.\",\n          solution: { F2: \"=SUM(C2:C4)\", F3: \"=SUM(C5:C8)\", F4: \"=SUM(C9:C10)\", F5: \"=SUM(F2:F4)\", F6: \"=F3/F5\" } },\n        { type: \"h\", text: \"Filter to show only what you need\" },\n        { type: \"path\", items: [\"Data\", \"Sort & Filter\", \"Filter\"], note: \"Or Ctrl + Shift + L. An arrow appears in every header cell.\" },\n        { type: \"list\", items: [\n          \"Click a header arrow and tick only the values to show, for example Littoral and Ouest.\",\n          \"Use **Number Filters › Greater Than** for amounts, **Text Filters › Contains** for part of a name, and **Date Filters** for a month or a quarter.\",\n          \"Filters on several columns combine: Region = Littoral AND Amount greater than 500 000.\",\n          \"Hidden rows are not deleted. The row numbers turn blue, and the status bar shows how many records were found.\",\n          \"Clear a filter with the header arrow › **Clear Filter From**, or remove all filters with `Ctrl + Shift + L`.\",\n        ] },\n        { type: \"h\", text: \"Format as Table and number formats\" },\n        { type: \"steps\", title: \"Turn a list into an Excel table\", items: [\n          \"Click inside the list and choose **Home › Format as Table** (or press `Ctrl + T`), then pick a style.\",\n          \"Confirm the range and that **My table has headers** is ticked.\",\n          \"Tick **Total Row** on the **Table Design** tab to add totals you can switch between Sum, Average and Count.\",\n          \"Type a new row under the table: the table grows and the formatting, filters and formulas follow.\",\n        ] },\n        { type: \"table\", head: [\"You want to show\", \"Number format\", \"Where\"], rows: [\n          [\"1 250 000\", \"Number with thousands separator, 0 decimals\", \"Home › Number › Comma Style, then Decrease Decimal\"],\n          [\"1 250 000 FCFA\", \"Custom: #,##0 \\\"FCFA\\\"\", \"Format Cells (Ctrl + 1) › Number › Custom\"],\n          [\"15%\", \"Percentage\", \"Home › Number › Percent Style (Ctrl + Shift + %)\"],\n          [\"2026-03-14\", \"Custom date: yyyy-mm-dd\", \"Format Cells › Number › Custom\"],\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"FCFA has no decimals\", text: \"The CFA franc is used without cents, so show amounts with 0 decimals and a thousands separator. The separator shown (a space or a comma) depends on the computer's regional settings; the number stored in the cell stays the same. Keep the custom format in one cell style so every report from the finance team looks alike.\" },\n        { type: \"h\", text: \"Conditional formatting, Freeze Panes and clean-up tools\" },\n        { type: \"path\", items: [\"Home\", \"Styles\", \"Conditional Formatting\", \"Highlight Cells Rules\", \"Greater Than\"], note: \"For example, fill in red every invoice above 500 000 FCFA. Data Bars, in the same menu, draw a bar in each cell proportional to its value.\" },\n        { type: \"path\", items: [\"View\", \"Window\", \"Freeze Panes\", \"Freeze Top Row\"], note: \"The header row stays visible while you scroll down a long list.\" },\n        { type: \"path\", items: [\"Data\", \"Data Tools\", \"Remove Duplicates\"], note: \"Tick only the columns that define a duplicate, such as the invoice number. Work on a copy: removed rows are deleted.\" },\n        { type: \"keys\", id: \"mosp-m4-l3-keys\", title: \"Practise the list shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Shift\", \"L\"], action: \"Turn filters on or off\" },\n          { keys: [\"Ctrl\", \"F\"], action: \"Find\" },\n          { keys: [\"Ctrl\", \"H\"], action: \"Find and Replace\" },\n          { keys: [\"Ctrl\", \"Z\"], action: \"Undo\" },\n        ] },\n        { type: \"form\", id: \"mosp-m4-l3-form\", title: \"Choose the right tool for the list\",\n          task: \"A logistics company in Douala keeps 600 deliveries in one sheet. Choose the tool or setting for each request. Type shortcuts as keys joined with +, for example Ctrl + B.\",\n          hint: \"Sort changes the order, Filter hides rows, conditional formatting colours cells by rule, Freeze Panes keeps headers visible, and Remove Duplicates deletes repeated rows.\",\n          fields: [\n            { kind: \"select\", label: \"Order the list by driver A to Z and, for each driver, by delivery fee from highest to lowest.\", options: [\"Sort A to Z on the Driver column\", \"Data › Sort with two levels: Driver A to Z, then Fee Largest to Smallest\", \"Filter on the Driver column\", \"Format as Table\"], answer: 1, explain: \"Two criteria need two levels in the Sort dialog, the main one first.\" },\n            { kind: \"text\", label: \"Which shortcut turns the filter arrows on and off?\", accept: [\"Ctrl+Shift+L\"], placeholder: \"Ctrl + …\", mono: true },\n            { kind: \"select\", label: \"You filter to show only Bonabéri deliveries. What happens to the other rows?\", options: [\"They are deleted\", \"They are hidden and come back when the filter is cleared\", \"They move to a new sheet\", \"They move to the bottom of the list\"], answer: 1, explain: \"A filter only hides rows. The blue row numbers show that some rows are hidden.\" },\n            { kind: \"select\", label: \"Every fee above 25 000 FCFA must turn red automatically, even when fees change.\", options: [\"Home › Font Color\", \"Home › Conditional Formatting › Highlight Cells Rules › Greater Than\", \"Data › Filter\", \"Review › New Comment\"], answer: 1, explain: \"Conditional formatting re-checks its rule every time the value changes. Manual colouring does not.\" },\n            { kind: \"select\", label: \"The column headings disappear when you scroll to row 400.\", options: [\"View › Freeze Panes › Freeze Top Row\", \"Page Layout › Print Titles\", \"Home › Wrap Text\", \"View › Zoom\"], answer: 0, explain: \"Print Titles repeats headings on printed pages; Freeze Panes keeps them visible on screen.\" },\n            { kind: \"select\", label: \"Some deliveries were imported twice with the same delivery number.\", options: [\"Data › Remove Duplicates, ticking only Delivery number\", \"Data › Sort\", \"Home › Clear › Clear Formats\", \"Data › Flash Fill\"], answer: 0, explain: \"Tick only the column that identifies a delivery. If you tick every column, rows that differ in one detail are kept.\" },\n            { kind: \"text\", label: \"The area \\\"Akwa Nord\\\" was renamed \\\"Akwa-Nord\\\". Which shortcut opens Find and Replace on the Replace tab?\", accept: [\"Ctrl+H\"], placeholder: \"Ctrl + …\", mono: true },\n          ] },\n        { type: \"check\", id: \"mosp-m4-l3-c1\", question: \"You select only the Amount column and sort it from largest to smallest, choosing \\\"Continue with the current selection\\\". What happens?\", options: [\"The whole list is sorted correctly\", \"Only the amounts move, so they no longer match their names\", \"Excel refuses to sort\", \"The amounts are converted to text\"], answer: 1, explain: \"Sorting a single column breaks the rows apart: the amounts are reordered but the names stay put. Choose Expand the selection, or click one cell and let Excel select the list.\" },\n        { type: \"task\", id: \"mosp-m4-l3-t1\", title: \"Practice\", items: [\n          \"Build a list of 20 sales with Date, Region, Salesperson and Amount columns\",\n          \"Sort it by Region A to Z, then by Amount Largest to Smallest\",\n          \"Filter it to show only one region with amounts above 100 000 FCFA, then clear the filter\",\n          \"Format it as a table, add a Total Row, and apply the custom format #,##0 \\\"FCFA\\\" to the amounts\",\n          \"Add Data Bars to the Amount column and freeze the top row\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Sort data in a range or table in Excel\", url: \"https://support.microsoft.com/en-us/office/sort-data-in-a-range-or-table-62d0b95d-2a90-4610-a6ae-2e545c4a4654\", source: MS },\n          { label: \"Filter data in a range or table in Excel\", url: \"https://support.microsoft.com/en-us/office/filter-data-in-a-range-or-table-01832226-31b5-4568-8806-38c37dcc180e\", source: MS },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 4 ───────────────────────────────\n    {\n      id: \"mosp-m4-l4\",\n      title: \"Charts and printing\",\n      minutes: 25,\n      objectives: [\n        \"Choose the chart type that fits the message: comparison, trend or share\",\n        \"Create a chart and give it a title that states the finding\",\n        \"Set up a sheet to print on A4 with titles, headers and footers, and export it to PDF\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A table gives the exact figures; a chart shows the pattern at a glance. Most managers will look at your chart for a few seconds, so choose the type that makes the point obvious and write that point in the title. Then make sure the sheet prints cleanly, because many reports still end up on paper or as PDF attachments.\" },\n        { type: \"h\", text: \"Choose the chart for the message\" },\n        { type: \"table\", head: [\"Your message\", \"Use\", \"Avoid\"], rows: [\n          [\"Compare categories: branches, products, regions\", \"Column chart, or bar chart when labels are long\", \"Pie with many slices\"],\n          [\"Show a trend over time: months, quarters, years\", \"Line chart\", \"Pie, which has no time axis\"],\n          [\"Show parts of one whole, with 2 to 4 parts\", \"Pie or doughnut chart\", \"Pie with 5 or more slices or with values that do not add up to a whole\"],\n        ] },\n        { type: \"chart\", id: \"mosp-m4-l4-chart1\", title: \"Fuel spending, January to June\", unit: \"FCFA\",\n          data: [{ label: \"Jan\", value: 410000 }, { label: \"Feb\", value: 395000 }, { label: \"Mar\", value: 450000 }, { label: \"Apr\", value: 520000 }, { label: \"May\", value: 560000 }, { label: \"Jun\", value: 610000 }],\n          kinds: [\"bar\", \"line\", \"pie\"], best: \"line\",\n          question: \"The logistics manager wants to show the director that fuel spending has been rising since March. Which chart makes it clearest?\",\n          explain: \"A line chart joins the months in order, so the rise from March to June is visible at once. A pie would hide the time order completely.\" },\n        { type: \"chart\", id: \"mosp-m4-l4-chart2\", title: \"Sales by branch, first quarter\", unit: \"FCFA\",\n          data: [{ label: \"Douala\", value: 18500000 }, { label: \"Yaoundé\", value: 15200000 }, { label: \"Bafoussam\", value: 7400000 }, { label: \"Garoua\", value: 6100000 }, { label: \"Bamenda\", value: 4300000 }, { label: \"Kribi\", value: 3900000 }, { label: \"Ngaoundéré\", value: 3600000 }],\n          kinds: [\"bar\", \"line\", \"pie\"], best: \"bar\",\n          question: \"You must compare the seven branches and show clearly which ones sell the least. Which chart is best?\",\n          explain: \"Bars share one baseline, so the eye compares their lengths precisely. Seven pie slices of similar size are hard to rank, and a line suggests a sequence that branches do not have.\" },\n        { type: \"callout\", tone: \"key\", title: \"A title that states the finding\", text: \"\\\"Fuel spending\\\" only names the data. \\\"Fuel spending up 54% since February\\\" tells the reader what to see. Write the conclusion in the title and keep the details, such as the unit and the period, in a subtitle or an axis title.\" },\n        { type: \"h\", text: \"Create and format a chart\" },\n        { type: \"steps\", title: \"From data to finished chart\", items: [\n          \"Select the labels and the values, including the header row, for example A1:B7.\",\n          \"Choose **Insert › Recommended Charts** and pick the type that fits your message, or press `Alt + F1` for a quick column chart.\",\n          \"Click the chart title and type the finding.\",\n          \"Use the **+** button beside the chart (Chart Elements) to add or remove axis titles, data labels and the legend.\",\n          \"Drag the chart next to the table and resize it from a corner so it does not stretch.\",\n        ] },\n        { type: \"path\", items: [\"Insert\", \"Charts\", \"Recommended Charts\"] },\n        { type: \"path\", items: [\"Chart Design\", \"Add Chart Element\"], note: \"Chart Design also has Switch Row/Column, Select Data, Change Chart Type and Move Chart.\" },\n        { type: \"list\", items: [\n          \"Remove what does not help: gridlines that are too heavy, a legend when there is only one series, 3-D effects.\",\n          \"Sort bars from largest to smallest so the ranking is easy to read.\",\n          \"Use one colour for all bars and a contrasting colour for the bar you want to discuss.\",\n          \"Start the value axis at zero for column and bar charts; otherwise small differences look huge.\",\n        ] },\n        { type: \"h\", text: \"Set up the page for printing\" },\n        { type: \"path\", items: [\"Page Layout\", \"Page Setup\", \"Orientation\", \"Landscape\"], note: \"Wide tables usually fit better in landscape. Check that Size is A4.\" },\n        { type: \"path\", items: [\"Page Layout\", \"Scale to Fit\", \"Width: 1 page\"], note: \"Leave Height on Automatic: all columns fit across the page and long lists continue on the next pages.\" },\n        { type: \"path\", items: [\"Page Layout\", \"Page Setup\", \"Print Titles\"], note: \"In Rows to repeat at top, select the header row (for example $1:$1) so it prints on every page.\" },\n        { type: \"steps\", title: \"Add a header and footer\", items: [\n          \"Choose **Insert › Header & Footer**. Excel switches to Page Layout view.\",\n          \"Click the left, centre or right box of the header and type, for example, the organisation name.\",\n          \"Scroll to the footer and use the **Header & Footer** tab to insert Page Number, Number of Pages and File Name.\",\n          \"Click any cell in the sheet, then return to **View › Normal**.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"Preview before you pay for printing\", text: \"Printing a 12-page report at a cyber café in Yaoundé because one column spilled onto extra pages wastes paper and money. Press `Ctrl + P` to see the print preview first, and when the report only needs to be read, send a PDF instead: it prints the same way on any computer.\" },\n        { type: \"h\", text: \"Preview and export to PDF\" },\n        { type: \"path\", items: [\"File\", \"Export\", \"Create PDF/XPS Document\"], note: \"Click Options to choose Active sheet(s), Entire workbook or only the Selection.\" },\n        { type: \"form\", id: \"mosp-m4-l4-form\", title: \"Print a staff hours report on A4\",\n          task: \"The staff hours report of a Garoua health district has 10 columns and 180 rows. Choose the right setting for each problem. Type shortcuts as keys joined with +.\",\n          hint: \"Orientation and Print Titles are on Page Layout › Page Setup, fitting is in Page Layout › Scale to Fit, and the preview opens with Ctrl + P.\",\n          fields: [\n            { kind: \"select\", label: \"The table is wider than it is tall. Which orientation?\", options: [\"Portrait\", \"Landscape\"], answer: 1 },\n            { kind: \"select\", label: \"The last two columns still print on separate pages.\", options: [\"Reduce the font to 6 pt\", \"Page Layout › Scale to Fit › Width: 1 page\", \"Delete the two columns\", \"Page Layout › Breaks › Insert Page Break\"], answer: 1, explain: \"Width: 1 page shrinks the sheet just enough to fit across, and leaves the height free.\" },\n            { kind: \"select\", label: \"Pages 2 to 5 have no column headings.\", options: [\"View › Freeze Panes\", \"Page Layout › Print Titles › Rows to repeat at top\", \"Insert › Header & Footer\", \"Home › Format as Table\"], answer: 1, explain: \"Freeze Panes only works on screen. Print Titles repeats the header row on every printed page.\" },\n            { kind: \"select\", label: \"Each page must show \\\"Page 3 of 5\\\" at the bottom.\", options: [\"Type it in the last row of the sheet\", \"Insert › Header & Footer, then Page Number and Number of Pages in the footer\", \"Page Layout › Margins\", \"File › Info › Properties\"], answer: 1 },\n            { kind: \"text\", label: \"Which shortcut opens the print preview?\", accept: [\"Ctrl+P\", \"Ctrl+F2\"], placeholder: \"Ctrl + …\", mono: true },\n            { kind: \"select\", label: \"Only the Summary sheet must be sent as a PDF.\", options: [\"File › Export › Create PDF/XPS Document, Options › Active sheet(s)\", \"File › Save As › CSV\", \"Take a screenshot\", \"Print the whole workbook and scan it\"], answer: 0, explain: \"The Options button lets you export only the active sheet instead of the whole workbook.\" },\n          ] },\n        { type: \"check\", id: \"mosp-m4-l4-c1\", question: \"Which chart title is best for a report to the management committee?\", options: [\"Chart 1\", \"Sales\", \"Sales by branch, Q1 2026 (FCFA)\", \"Douala and Yaoundé make 57% of first-quarter sales\"], answer: 3, explain: \"A title that states the finding tells busy readers what to notice. The period and unit can go in a subtitle or axis title.\" },\n        { type: \"task\", id: \"mosp-m4-l4-t1\", title: \"Practice\", items: [\n          \"Enter monthly sales for six months and create a line chart with a title that states the trend\",\n          \"Enter sales for five branches, create a bar chart and sort the bars from largest to smallest\",\n          \"Set a long list to landscape, Width: 1 page, with the header row repeated on every page\",\n          \"Add a footer with Page X of Y and the file name\",\n          \"Export only the active sheet to PDF and check it in the preview\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Create a chart from start to finish\", url: \"https://support.microsoft.com/en-us/excel/get-started/create-a-chart-from-start-to-finish\", source: MS },\n          { label: \"Print rows with column headers on top of every page\", url: \"https://support.microsoft.com/en-us/office/print-rows-with-column-headers-on-top-of-every-page-d3550133-f6a1-4c72-ad70-5309a2e8fe8c\", source: MS },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── PRACTICE LAB ───────────────────────────────\n    {\n      id: \"mosp-m4-practice\",\n      title: \"Practice lab: Excel from data entry to report\",\n      minutes: 40,\n      objectives: [\n        \"Total and average rows of data with the everyday functions\",\n        \"Build a two-way table with mixed references\",\n        \"Choose the right sort, filter, format, chart and formula for a report\",\n        \"Clean a report with missing values and numbers stored as text\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" },\n        { type: \"h\", text: \"Exercise 1: Weekly hours at a clinic\" },\n        { type: \"sheet\", id: \"mosp-pr-m4-hours\", level: \"beginner\", title: \"Total the staff hours\",\n          task: \"A clinic in Bafoussam records the hours each staff member worked this week. Fill **G2:G5** with each person's weekly total, **G6** with the total for the whole team and **G7** with the average per person.\",\n          data: [[\"Staff\", \"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Total\"],\n            [\"Nurse Fokou\", 8, 8, 10, 8, 6, null],\n            [\"Nurse Ewane\", 7, 9, 8, 8, 10, null],\n            [\"Lab tech Moussa\", 8, 9, 8, 12, 6, null],\n            [\"Receptionist Bih\", 6, 6, 6, 6, 6, null],\n            [\"Team total\", null, null, null, null, null, null],\n            [\"Average per person\", null, null, null, null, null, null]],\n          editable: [\"G2\", \"G3\", \"G4\", \"G5\", \"G6\", \"G7\"],\n          checks: [{ cell: \"G2\", equals: 40 }, { cell: \"G3\", equals: 42 }, { cell: \"G4\", equals: 43 }, { cell: \"G5\", equals: 30 }, { cell: \"G6\", equals: 155 }, { cell: \"G7\", equals: 38.75, tol: 0.01 }],\n          hint: \"G2 is =SUM(B2:F2); copy it down to G5. The team total adds G2:G5, and the average per person is =AVERAGE(G2:G5).\",\n          solution: { G2: \"=SUM(B2:F2)\", G3: \"=SUM(B3:F3)\", G4: \"=SUM(B4:F4)\", G5: \"=SUM(B5:F5)\", G6: \"=SUM(G2:G5)\", G7: \"=AVERAGE(G2:G5)\" } },\n        { type: \"h\", text: \"Exercise 2: Mission allowance table\" },\n        { type: \"sheet\", id: \"mosp-pr-m4-allowance\", level: \"intermediate\", title: \"One formula for a whole table\",\n          task: \"A ministry pays a daily mission allowance by staff category. Fill **C3:E5** with the allowance for 5, 10 and 22 days (daily rate × days) using **one formula with mixed references** copied across the table. Then fill **B8** with Category A's new daily rate after the increase in **B7**.\",\n          data: [[\"Mission allowance\", null, \"Number of days\"],\n            [\"Category\", \"Daily rate (FCFA)\", 5, 10, 22],\n            [\"Category A\", 25000, null, null, null],\n            [\"Category B\", 18000, null, null, null],\n            [\"Category C\", 12000, null, null, null],\n            [null],\n            [\"Increase (8%)\", 0.08],\n            [\"New rate, Category A\", null]],\n          editable: [\"C3\", \"D3\", \"E3\", \"C4\", \"D4\", \"E4\", \"C5\", \"D5\", \"E5\", \"B8\"],\n          checks: [{ cell: \"C3\", equals: 125000 }, { cell: \"D3\", equals: 250000 }, { cell: \"E3\", equals: 550000 },\n            { cell: \"C4\", equals: 90000 }, { cell: \"D4\", equals: 180000 }, { cell: \"E4\", equals: 396000 },\n            { cell: \"C5\", equals: 60000 }, { cell: \"D5\", equals: 120000 }, { cell: \"E5\", equals: 264000 }, { cell: \"B8\", equals: 27000 }],\n          hint: \"In C3 type =$B3*C$2: the rate is always in column B ($B) and the days are always in row 2 (row $2). Copy it to the other eight cells. B8 is =B3*(1+B7).\",\n          solution: { C3: \"=$B3*C$2\", D3: \"=$B3*D$2\", E3: \"=$B3*E$2\", C4: \"=$B4*C$2\", D4: \"=$B4*D$2\", E4: \"=$B4*E$2\", C5: \"=$B5*C$2\", D5: \"=$B5*D$2\", E5: \"=$B5*E$2\", B8: \"=B3*(1+B7)\" } },\n        { type: \"h\", text: \"Exercise 3: Preparing the regional sales report\" },\n        { type: \"form\", id: \"mosp-pr-m4-report\", level: \"advanced\", title: \"Formulas, formats and charts for a report\",\n          task: \"A distributor in Garoua lists its 2025 sales in column B and its 2026 sales in column C, one row per region, with the grand total in B10 and C10. Answer each question. Type formulas exactly as you would in Excel, starting with =.\",\n          hint: \"Growth is the change divided by the starting value. A reference that must not move when copied needs dollar signs. Think about what each tool does: sort orders, filter hides, conditional formatting colours by rule.\",\n          fields: [\n            { kind: \"text\", label: \"Type the formula for D2: the growth from 2025 (B2) to 2026 (C2), as a share.\", pattern: \"^=\\\\s*(\\\\(\\\\s*C2\\\\s*-\\\\s*B2\\\\s*\\\\)\\\\s*/\\\\s*B2|C2\\\\s*/\\\\s*B2\\\\s*-\\\\s*1)\\\\s*$\", example: \"=(C2-B2)/B2\", placeholder: \"=…\", mono: true, explain: \"=(C2-B2)/B2 and =C2/B2-1 give the same result. Without brackets, =C2-B2/B2 divides first and is wrong.\" },\n            { kind: \"text\", label: \"E2 shows each region's share of 2026 sales: =C2/C10. Rewrite it so that it can be copied down to E9.\", accept: [\"=C2/$C$10\", \"=C2/C$10\"], placeholder: \"=…\", mono: true, explain: \"The total must stay in C10, so lock it: $C$10 (or at least the row: C$10).\" },\n            { kind: \"select\", label: \"The growth for the new Kousséri region shows #DIV/0!. Why?\", options: [\"The 2026 figure is text\", \"Its 2025 cell is empty because the region opened in 2026\", \"The column is too narrow\", \"The function name is misspelled\"], answer: 1, explain: \"Dividing by an empty cell counts as dividing by zero. Growth cannot be calculated for a region with no sales last year.\" },\n            { kind: \"select\", label: \"Growth shows as 0.12 instead of 12%.\", options: [\"Multiply the formula by 100\", \"Apply the Percent Style (Ctrl + Shift + %)\", \"Type % after the formula\", \"Change the column width\"], answer: 1, explain: \"0.12 is correct; it only needs the Percent Style. Multiplying by 100 and adding % would show 1200%.\" },\n            { kind: \"select\", label: \"Rank the regions by 2026 sales, largest first, while each row stays together.\", options: [\"Select column C only and click Sort Largest to Smallest, Continue with the current selection\", \"Click one cell in column C and choose Sort Largest to Smallest\", \"Apply a filter and untick the small regions\", \"Cut and paste the rows by hand\"], answer: 1, explain: \"Clicking one cell lets Excel select the whole list and keep each row together.\" },\n            { kind: \"select\", label: \"Regions whose sales fell must stand out in red and update automatically.\", options: [\"Conditional Formatting › Highlight Cells Rules › Less Than 0 on the growth column\", \"Font Color red on today's falling regions\", \"Filter the growth column\", \"Freeze Panes\"], answer: 0, explain: \"A rule re-checks every time the figures change; a manual colour does not.\" },\n            { kind: \"select\", label: \"Which chart compares the nine regions' 2025 and 2026 sales side by side?\", options: [\"Pie chart\", \"Clustered bar or column chart\", \"Line chart with one line per region\", \"Doughnut chart\"], answer: 1, explain: \"Clustered bars put the two years side by side for each region on a common baseline.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 4: Mosquito net distribution report\" },\n        { type: \"sheet\", id: \"mosp-pr-m4-nets\", level: \"expert\", title: \"Clean up a report with gaps and text\",\n          task: \"An NGO's field report from the North region has problems: Pitoa has not reported households served yet, and some costs were typed with \\\"FCFA\\\". Fill **D2:D6** with coverage (served ÷ targeted), showing `Not reported` when Served is empty; **F2:F6** with every cost as a real number; then the summary in **B8:B12**.\",\n          data: [[\"District\", \"Targeted\", \"Served\", \"Coverage\", \"Cost reported\", \"Cost (FCFA)\"],\n            [\"Garoua I\", 420, 385, null, \"850000 FCFA\", null],\n            [\"Garoua II\", 380, 342, null, 760000, null],\n            [\"Pitoa\", 300, null, null, \"300000 FCFA\", null],\n            [\"Lagdo\", 260, 247, null, \"540000 FCFA\", null],\n            [\"Tchéboa\", 340, 289, null, 610000, null],\n            [null],\n            [\"Households served\", null],\n            [\"Districts reporting\", null],\n            [\"Coverage, reporting districts\", null],\n            [\"Total cost (FCFA)\", null],\n            [\"Cost per household served\", null]],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"D6\", \"F2\", \"F3\", \"F4\", \"F5\", \"F6\", \"B8\", \"B9\", \"B10\", \"B11\", \"B12\"],\n          checks: [{ cell: \"D2\", equals: 0.9167, tol: 0.001 }, { cell: \"D3\", equals: 0.9, tol: 0.001 }, { cell: \"D4\", equals: \"Not reported\" }, { cell: \"D5\", equals: 0.95, tol: 0.001 }, { cell: \"D6\", equals: 0.85, tol: 0.001 },\n            { cell: \"F2\", equals: 850000 }, { cell: \"F3\", equals: 760000 }, { cell: \"F4\", equals: 300000 }, { cell: \"F5\", equals: 540000 }, { cell: \"F6\", equals: 610000 },\n            { cell: \"B8\", equals: 1263 }, { cell: \"B9\", equals: 4 }, { cell: \"B10\", equals: 0.9021, tol: 0.001 }, { cell: \"B11\", equals: 3060000 }, { cell: \"B12\", equals: 2423, tol: 0.6 }],\n          hint: \"Coverage: =IF(C2=\\\"\\\",\\\"Not reported\\\",C2/B2). Cost: =VALUE(SUBSTITUTE(E2,\\\" FCFA\\\",\\\"\\\")) works for text and for real numbers alike; LEFT(E2,LEN(E2)-5) breaks on the rows that are already numbers. B9 is COUNT(C2:C6). For B10, divide households served by the targets of reporting districts only: =B8/SUMIF(C2:C6,\\\"<>\\\",B2:B6). B12 is =B11/B8.\",\n          solution: { D2: \"=IF(C2=\\\"\\\",\\\"Not reported\\\",C2/B2)\", D3: \"=IF(C3=\\\"\\\",\\\"Not reported\\\",C3/B3)\", D4: \"=IF(C4=\\\"\\\",\\\"Not reported\\\",C4/B4)\", D5: \"=IF(C5=\\\"\\\",\\\"Not reported\\\",C5/B5)\", D6: \"=IF(C6=\\\"\\\",\\\"Not reported\\\",C6/B6)\",\n            F2: \"=VALUE(SUBSTITUTE(E2,\\\" FCFA\\\",\\\"\\\"))\", F3: \"=VALUE(SUBSTITUTE(E3,\\\" FCFA\\\",\\\"\\\"))\", F4: \"=VALUE(SUBSTITUTE(E4,\\\" FCFA\\\",\\\"\\\"))\", F5: \"=VALUE(SUBSTITUTE(E5,\\\" FCFA\\\",\\\"\\\"))\", F6: \"=VALUE(SUBSTITUTE(E6,\\\" FCFA\\\",\\\"\\\"))\",\n            B8: \"=SUM(C2:C6)\", B9: \"=COUNT(C2:C6)\", B10: \"=B8/SUMIF(C2:C6,\\\"<>\\\",B2:B6)\", B11: \"=SUM(F2:F6)\", B12: \"=B11/B8\" } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"mosp-m4-quiz\",\n    title: \"Module 4 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"Which shortcut fills a column by following the pattern of the example you typed, for example extracting DLA from DLA-2026-014?\", options: [\"Ctrl + D\", \"Ctrl + E\", \"Ctrl + F\", \"Alt + =\"], answer: 1, explain: \"Ctrl + E runs Flash Fill, which copies the pattern of your example down the column. Ctrl + D copies the cell above.\" },\n      { id: \"q2\", question: \"One cell in C2:C20 contains \\\"45 000 FCFA\\\" typed by hand. What does =SUM(C2:C20) do with it?\", options: [\"Adds 45 000\", \"Shows #VALUE!\", \"Ignores it, because it is text\", \"Converts it automatically\"], answer: 2, explain: \"SUM skips text in a range, so the total is silently too low. Arithmetic with + on that cell would show #VALUE! instead.\" },\n      { id: \"q3\", question: \"What does =10+20/2 return?\", options: [\"20\", \"15\", \"25\", \"10\"], answer: 0, explain: \"Division comes before addition: 20/2 = 10, then 10 + 10 = 20. Write =(10+20)/2 to get 15.\" },\n      { id: \"q4\", question: \"You type =C4*B1 and press F4 once while the cursor is on B1. What does the reference become?\", options: [\"B$1\", \"$B1\", \"B1\", \"$B$1\"], answer: 3, explain: \"The first press of F4 locks both the column and the row. Further presses give B$1, then $B1, then back to B1.\" },\n      { id: \"q5\", question: \"Which function counts the cells that contain numbers only, ignoring names and empty cells?\", options: [\"COUNTA\", \"SUM\", \"COUNT\", \"MAX\"], answer: 2, explain: \"COUNT counts numbers only. COUNTA counts every cell that is not empty, text included.\" },\n      { id: \"q6\", question: \"Which shortcut turns the filter arrows on or off?\", options: [\"Ctrl + L\", \"Ctrl + Shift + L\", \"Ctrl + T\", \"Ctrl + H\"], answer: 1, explain: \"Ctrl + Shift + L toggles filters. Ctrl + T creates a table, which also has filter arrows.\" },\n      { id: \"q7\", question: \"Which chart best shows how monthly sales changed over a year?\", options: [\"Line chart\", \"Pie chart\", \"Doughnut chart\", \"A table of 12 numbers\"], answer: 0, explain: \"A line chart shows change over time in order. A pie shows parts of a whole and has no time axis.\" },\n      { id: \"q8\", question: \"A long list prints with the column headings only on page 1. Which setting fixes it?\", options: [\"View › Freeze Panes\", \"Page Layout › Orientation\", \"Home › Format as Table\", \"Page Layout › Print Titles\"], answer: 3, explain: \"Print Titles › Rows to repeat at top prints the header row on every page. Freeze Panes only affects the screen.\" },\n    ],\n  },\n};\n","client/src/data/courses/mosp/m5.ts":"import type { CourseModule, FormField } from \"../../../lms/types\";\n\n// Module 5 — Microsoft Excel: Advanced Data Analysis\n// Original Analytix Engineering material, aligned to the MO-210 Excel (Microsoft 365 Apps) objectives.\n\nconst MS = \"Microsoft Support\";\nconst LEARN = \"Microsoft Learn\";\nconst EXAM = { label: \"Microsoft Office Specialist: Excel Associate (Microsoft 365 Apps)\", url: \"https://learn.microsoft.com/en-us/credentials/certifications/mos-excel-associate-m365-apps/\", source: LEARN };\n\nconst R = (col: string, a: number, b: number) => `\\\\$?${col}\\\\$?${a}:\\\\$?${col}\\\\$?${b}`;\nconst SUMIFS_DSCHANG = `^=\\\\s*(SUMIFS\\\\(\\\\s*${R(\"C\", 2, 200)}\\\\s*,\\\\s*${R(\"A\", 2, 200)}\\\\s*,\\\\s*\"Dschang\"\\\\s*\\\\)|SUMIF\\\\(\\\\s*${R(\"A\", 2, 200)}\\\\s*,\\\\s*\"Dschang\"\\\\s*,\\\\s*${R(\"C\", 2, 200)}\\\\s*\\\\))$`;\n\nconst AREAS = [\"Rows\", \"Columns\", \"Values\", \"Filters\"];\nconst area = (label: string, answer: number, explain?: string): FormField => ({ kind: \"select\", label, options: AREAS, answer, explain });\n\nexport const m5: CourseModule = {\n  id: \"mosp-m5\",\n  number: 5,\n  title: \"Microsoft Excel — Advanced Data Analysis\",\n  summary: \"Logical and lookup functions, PivotTables, dashboards and What-If analysis.\",\n  hours: 12,\n  lessons: [\n    // ─────────────────────────── LESSON 1 ───────────────────────────\n    {\n      id: \"mosp-m5-l1\",\n      title: \"IF, AND, OR and IFS: formulas that make decisions\",\n      minutes: 28,\n      objectives: [\n        \"Write IF formulas that return different results depending on a logical test\",\n        \"Combine several conditions with AND, OR and IFS, and hide errors with IFERROR\",\n        \"Calculate conditional totals and counts with COUNTIF, SUMIF, COUNTIFS and SUMIFS\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Until now your formulas always did the same calculation. Logical functions let a formula decide: pay a bonus only if the target is met, show \\\"Reorder\\\" only when stock is low, give a grade that depends on the score. These decisions are the heart of most real workplace spreadsheets.\" },\n        { type: \"p\", text: \"A logical test is a comparison that is either TRUE or FALSE. Type `=C2>=D2` in a cell and Excel shows TRUE or FALSE. Every logical function is built on tests like this one.\" },\n        { type: \"table\", head: [\"Operator\", \"Meaning\", \"Example\", \"TRUE when…\"], rows: [\n          [\"=\", \"Equal to\", \"=B2=\\\"Douala\\\"\", \"The city is Douala (not case-sensitive)\"],\n          [\"<>\", \"Not equal to\", \"=E2<>\\\"Paid\\\"\", \"The status is anything except Paid\"],\n          [\">  <\", \"Greater than, less than\", \"=C2>500000\", \"The amount is above 500 000\"],\n          [\">=  <=\", \"Greater or equal, less or equal\", \"=E2<=2\", \"Two absences or fewer\"],\n        ] },\n        { type: \"h\", text: \"IF: one test, two possible results\" },\n        { type: \"code\", text: \"=IF(logical_test, value_if_true, value_if_false)\\n\\n=IF(C2>=D2, \\\"Yes\\\", \\\"No\\\")          target met?\\n=IF(C2>=D2, C2*5%, 0)              5% bonus, otherwise nothing\" },\n        { type: \"list\", items: [\n          \"Text results go in double quotes: \\\"Yes\\\". Numbers and cell references do not.\",\n          \"The result can be another formula, for example `C2*5%`.\",\n          \"In a French version of Excel, IF is SI and the separator is a semicolon: `=SI(C2>=D2;\\\"Oui\\\";\\\"Non\\\")`.\",\n        ] },\n        { type: \"h\", text: \"AND, OR and NOT: several conditions at once\" },\n        { type: \"table\", head: [\"Function\", \"Returns TRUE when…\", \"Example\"], rows: [\n          [\"AND\", \"Every condition is true\", \"=AND(C2>=D2, E2<=2): target met and two absences or fewer\"],\n          [\"OR\", \"At least one condition is true\", \"=OR(B2=\\\"Douala\\\", B2=\\\"Yaoundé\\\"): works in one of the two big cities\"],\n          [\"NOT\", \"The condition is false\", \"=NOT(F2=\\\"Paid\\\")\"],\n          [\"IF + AND\", \"AND and OR are usually placed inside IF as its test\", \"=IF(AND(C2>=D2,E2<=2),C2*5%,0): bonus only when both hold\"],\n        ] },\n        { type: \"sheet\", id: \"mosp-m5-l1-sheet\", title: \"Sales bonus eligibility\",\n          task: \"A distributor in Douala pays a 5% bonus on sales to agents who meet their target and have no more than 2 days of absence. Fill F2:F5 with \\\"Yes\\\" or \\\"No\\\" (target met?) and G2:G5 with the bonus in FCFA (0 if not eligible).\",\n          data: [\n            [\"Agent\", \"City\", \"Sales\", \"Target\", \"Days absent\", \"Target met\", \"Bonus\"],\n            [\"Ngo Bassa Carine\", \"Douala\", 4800000, 4500000, 1, null, null],\n            [\"Tchoumi Paul\", \"Yaoundé\", 3900000, 4000000, 0, null, null],\n            [\"Abena Marthe\", \"Douala\", 5200000, 5000000, 4, null, null],\n            [\"Fouda Eric\", \"Bafoussam\", 4100000, 3800000, 2, null, null],\n          ],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"G2\", \"G3\", \"G4\", \"G5\"],\n          checks: [\n            { cell: \"F2\", equals: \"Yes\" }, { cell: \"F3\", equals: \"No\" }, { cell: \"F4\", equals: \"Yes\" }, { cell: \"F5\", equals: \"Yes\" },\n            { cell: \"G2\", equals: 240000 }, { cell: \"G3\", equals: 0 }, { cell: \"G4\", equals: 0 }, { cell: \"G5\", equals: 205000 },\n          ],\n          hint: \"F2 is =IF(C2>=D2,\\\"Yes\\\",\\\"No\\\"). For G2 put AND inside IF: =IF(AND(C2>=D2,E2<=2),C2*5%,0). Abena met her target but was absent 4 days.\",\n          solution: {\n            F2: \"=IF(C2>=D2,\\\"Yes\\\",\\\"No\\\")\", F3: \"=IF(C3>=D3,\\\"Yes\\\",\\\"No\\\")\", F4: \"=IF(C4>=D4,\\\"Yes\\\",\\\"No\\\")\", F5: \"=IF(C5>=D5,\\\"Yes\\\",\\\"No\\\")\",\n            G2: \"=IF(AND(C2>=D2,E2<=2),C2*5%,0)\", G3: \"=IF(AND(C3>=D3,E3<=2),C3*5%,0)\", G4: \"=IF(AND(C4>=D4,E4<=2),C4*5%,0)\", G5: \"=IF(AND(C5>=D5,E5<=2),C5*5%,0)\",\n          } },\n        { type: \"h\", text: \"More than two results: nested IF or IFS\" },\n        { type: \"p\", text: \"To give a grade from a score you need more than two outcomes. The older way nests one IF inside another; IFS, available in Microsoft 365, lists test and result pairs and returns the result of the first test that is TRUE.\" },\n        { type: \"code\", text: \"Nested IF:  =IF(B2>=16,\\\"Excellent\\\",IF(B2>=12,\\\"Good\\\",IF(B2>=10,\\\"Pass\\\",\\\"Fail\\\")))\\nIFS:        =IFS(B2>=16,\\\"Excellent\\\", B2>=12,\\\"Good\\\", B2>=10,\\\"Pass\\\", TRUE,\\\"Fail\\\")\" },\n        { type: \"callout\", tone: \"key\", title: \"Order matters, and end with TRUE\", text: \"Excel stops at the first test that is TRUE, so test the highest band first. If B2>=10 came first, a score of 17 would get \\\"Pass\\\". The final pair TRUE,\\\"Fail\\\" catches everything else; without it IFS returns #N/A when no test is true.\" },\n        { type: \"h\", text: \"IFERROR: a clean result instead of an error\" },\n        { type: \"p\", text: \"`=IFERROR(formula, value_if_error)` returns the formula's result, or your chosen value if the formula produces an error such as #DIV/0! or #N/A. For example `=IFERROR(C2/D2,0)` shows 0 instead of #DIV/0! when the target is empty. Use it for expected errors only; hiding every error can hide real mistakes.\" },\n        { type: \"h\", text: \"Conditional totals: COUNTIF, SUMIF, COUNTIFS, SUMIFS\" },\n        { type: \"table\", head: [\"Function\", \"What it does\", \"Example\"], rows: [\n          [\"COUNTIF(range, criteria)\", \"Counts cells that meet one condition\", \"=COUNTIF(F2:F7,\\\"Reorder\\\")\"],\n          [\"SUMIF(range, criteria, sum_range)\", \"Adds values where one condition is met\", \"=SUMIF(B2:B7,\\\"Douala\\\",C2:C7)\"],\n          [\"COUNTIFS(range1, crit1, range2, crit2…)\", \"Counts rows that meet every condition\", \"=COUNTIFS(B2:B7,\\\"Medicine\\\",F2:F7,\\\"<>OK\\\")\"],\n          [\"SUMIFS(sum_range, range1, crit1…)\", \"Adds values where every condition is met. Note the sum range comes first\", \"=SUMIFS(C2:C7,B2:B7,\\\"Medicine\\\")\"],\n        ] },\n        { type: \"p\", text: \"Criteria with an operator go in quotes: \\\">100000\\\", \\\"<>OK\\\". To use a value from a cell, join the operator with &: `\\\">=\\\"&H2`.\" },\n        { type: \"sheet\", id: \"mosp-m5-l1-stock\", title: \"Stock alerts in a health centre pharmacy\",\n          task: \"Fill F2:F7 with an alert using IFS: \\\"Out\\\" when stock is 0, \\\"Reorder\\\" when stock is at or below the reorder level, otherwise \\\"OK\\\". Then fill F9 (number of Reorder alerts), F10 (Medicine items that are not OK) and F11 (total units in stock for Medicine).\",\n          data: [\n            [\"Item\", \"Category\", \"Stock\", \"Reorder level\", \"Unit price\", \"Alert\"],\n            [\"Paracetamol 500 mg\", \"Medicine\", 40, 50, 1200, null],\n            [\"Amoxicillin 250 mg\", \"Medicine\", 0, 30, 3500, null],\n            [\"ORS sachets\", \"Medicine\", 120, 80, 150, null],\n            [\"Soap bars\", \"Hygiene\", 15, 20, 400, null],\n            [\"Hand gel 500 ml\", \"Hygiene\", 60, 25, 2500, null],\n            [\"Gloves, box of 100\", \"Supplies\", 8, 10, 4500, null],\n            [null, null, null, null, null, null],\n            [null, null, null, null, \"Reorder alerts\", null],\n            [null, null, null, null, \"Medicine not OK\", null],\n            [null, null, null, null, \"Medicine units\", null],\n          ],\n          editable: [\"F2\", \"F3\", \"F4\", \"F5\", \"F6\", \"F7\", \"F9\", \"F10\", \"F11\"],\n          checks: [\n            { cell: \"F2\", equals: \"Reorder\" }, { cell: \"F3\", equals: \"Out\" }, { cell: \"F4\", equals: \"OK\" }, { cell: \"F5\", equals: \"Reorder\" }, { cell: \"F6\", equals: \"OK\" }, { cell: \"F7\", equals: \"Reorder\" },\n            { cell: \"F9\", equals: 3 }, { cell: \"F10\", equals: 2 }, { cell: \"F11\", equals: 160 },\n          ],\n          hint: \"Test for 0 first: =IFS(C2=0,\\\"Out\\\",C2<=D2,\\\"Reorder\\\",TRUE,\\\"OK\\\"). F9 is a COUNTIF on F2:F7. F10 needs two conditions: COUNTIFS(B2:B7,\\\"Medicine\\\",F2:F7,\\\"<>OK\\\"). F11 is SUMIFS(C2:C7,B2:B7,\\\"Medicine\\\").\",\n          solution: {\n            F2: \"=IFS(C2=0,\\\"Out\\\",C2<=D2,\\\"Reorder\\\",TRUE,\\\"OK\\\")\", F3: \"=IFS(C3=0,\\\"Out\\\",C3<=D3,\\\"Reorder\\\",TRUE,\\\"OK\\\")\", F4: \"=IFS(C4=0,\\\"Out\\\",C4<=D4,\\\"Reorder\\\",TRUE,\\\"OK\\\")\",\n            F5: \"=IFS(C5=0,\\\"Out\\\",C5<=D5,\\\"Reorder\\\",TRUE,\\\"OK\\\")\", F6: \"=IFS(C6=0,\\\"Out\\\",C6<=D6,\\\"Reorder\\\",TRUE,\\\"OK\\\")\", F7: \"=IFS(C7=0,\\\"Out\\\",C7<=D7,\\\"Reorder\\\",TRUE,\\\"OK\\\")\",\n            F9: \"=COUNTIF(F2:F7,\\\"Reorder\\\")\", F10: \"=COUNTIFS(B2:B7,\\\"Medicine\\\",F2:F7,\\\"<>OK\\\")\", F11: \"=SUMIFS(C2:C7,B2:B7,\\\"Medicine\\\")\",\n          } },\n        { type: \"path\", items: [\"Formulas\", \"Formula Auditing\", \"Evaluate Formula\"], note: \"Steps through a long formula one part at a time, so you can see which test is TRUE.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A district health service in the Far North tracks essential drugs in 12 health centres. One IFS column flags \\\"Out\\\" and \\\"Reorder\\\", and a COUNTIFS per centre gives the district pharmacist the list to order before the rainy season cuts the roads. The same pattern works for any stock: cement in a hardware store, airtime scratch cards, school supplies.\" },\n        { type: \"check\", id: \"mosp-m5-l1-c1\", question: \"Which formula gives \\\"Pass\\\" for scores of 10 and above and \\\"Fail\\\" otherwise, where the score is in B2?\", options: [\"=IF(B2>10,\\\"Pass\\\",\\\"Fail\\\")\", \"=IF(B2>=10,\\\"Pass\\\",\\\"Fail\\\")\", \"=IF(B2>=10,Pass,Fail)\", \"=IFS(B2>=10,\\\"Pass\\\")\"], answer: 1, explain: \"B2>=10 includes exactly 10. Text must be in quotes, and IFS without a final TRUE pair returns #N/A for scores below 10.\" },\n        { type: \"check\", id: \"mosp-m5-l1-c2\", question: \"You want the total sales of agent Tchoumi in the Centre region only. Which function fits best?\", options: [\"SUMIF\", \"COUNTIFS\", \"SUMIFS\", \"IFERROR\"], answer: 2, explain: \"Two conditions (agent and region) and a total: SUMIFS. SUMIF accepts only one condition, and COUNTIFS counts rows instead of adding amounts.\" },\n        { type: \"task\", id: \"mosp-m5-l1-t1\", title: \"Practice\", items: [\n          \"Build a list of 8 training participants with their final score out of 20\",\n          \"Add a Result column with IF: \\\"Certified\\\" from 12, otherwise \\\"Not certified\\\"\",\n          \"Add a Grade column with IFS: A from 16, B from 14, C from 12, otherwise D\",\n          \"Count the certified participants with COUNTIF and the average score of women with AVERAGEIFS\",\n          \"Divide one score by an empty cell, then wrap the formula in IFERROR\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"IFS function\", url: \"https://support.microsoft.com/en-us/excel/functions/ifs-function\", source: MS },\n          EXAM,\n        ] },\n      ],\n    },\n\n    // ─────────────────────────── LESSON 2 ───────────────────────────\n    {\n      id: \"mosp-m5-l2\",\n      title: \"XLOOKUP, VLOOKUP and INDEX-MATCH: finding data in tables\",\n      minutes: 28,\n      objectives: [\n        \"Look up prices, names and rates in a reference table with XLOOKUP and VLOOKUP\",\n        \"Explain the difference between exact and approximate match and use each correctly\",\n        \"Combine INDEX and MATCH, and handle missing codes without errors\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Most workbooks have a reference table somewhere: a price list, a staff list, a table of tax or commission bands. Lookup functions fetch the right line from that table, so you type a product code once and Excel fills in the name and the price. When the price list changes, every invoice updates.\" },\n        { type: \"h\", text: \"XLOOKUP: the modern lookup\" },\n        { type: \"code\", text: \"=XLOOKUP(lookup_value, lookup_array, return_array, [if_not_found], [match_mode])\\n\\n=XLOOKUP(E2, $A$2:$A$6, $C$2:$C$6, \\\"Not found\\\")\" },\n        { type: \"list\", items: [\n          \"lookup_value: what you are looking for, such as the product code in E2.\",\n          \"lookup_array: the column that contains the codes.\",\n          \"return_array: the column that contains the answer, such as the price. It can be to the left or the right of the codes.\",\n          \"if_not_found: what to show when the code is missing, instead of #N/A.\",\n          \"match_mode: leave it out for an exact match; -1 returns the next smaller value, which is what you need for bands.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Lock the table with F4\", text: \"When you copy a lookup down a column, the table must not move. Select the range in the formula and press F4 to add the dollar signs: $A$2:$A$6. The lookup value (E2) stays relative so it changes on each row.\" },\n        { type: \"sheet\", id: \"mosp-m5-l2-sheet\", title: \"Price a hardware order\",\n          task: \"A hardware store in Bafoussam prices orders from its list. Fill G2:G5 with the item name using XLOOKUP (show \\\"Not found\\\" for unknown codes), H2:H5 with quantity × unit price (0 for unknown codes), and H6 with the order total.\",\n          data: [\n            [\"Code\", \"Item\", \"Unit price\", null, \"Order code\", \"Qty\", \"Item\", \"Amount\"],\n            [\"CIM-50\", \"Cement bag 50 kg\", 5500, null, \"FER-10\", 30, null, null],\n            [\"FER-10\", \"Iron rod 10 mm\", 4200, null, \"CIM-50\", 40, null, null],\n            [\"TOL-2\", \"Roofing sheet 2 m\", 6800, null, \"TOL-3\", 12, null, null],\n            [\"PNT-20\", \"Paint 20 L\", 32000, null, \"CLO-1\", 5, null, null],\n            [\"CLO-1\", \"Nails 1 kg\", 1500, null, null, null, \"Total\", null],\n          ],\n          editable: [\"G2\", \"G3\", \"G4\", \"G5\", \"H2\", \"H3\", \"H4\", \"H5\", \"H6\"],\n          checks: [\n            { cell: \"G2\", equals: \"Iron rod 10 mm\" }, { cell: \"G3\", equals: \"Cement bag 50 kg\" }, { cell: \"G4\", equals: \"Not found\" }, { cell: \"G5\", equals: \"Nails 1 kg\" },\n            { cell: \"H2\", equals: 126000 }, { cell: \"H3\", equals: 220000 }, { cell: \"H4\", equals: 0 }, { cell: \"H5\", equals: 7500 }, { cell: \"H6\", equals: 353500 },\n          ],\n          hint: \"G2 is =XLOOKUP(E2,$A$2:$A$6,$B$2:$B$6,\\\"Not found\\\"). For H2 look up the price column with 0 as if_not_found and multiply by the quantity: =F2*XLOOKUP(E2,$A$2:$A$6,$C$2:$C$6,0). TOL-3 is not on the list.\",\n          solution: {\n            G2: \"=XLOOKUP(E2,$A$2:$A$6,$B$2:$B$6,\\\"Not found\\\")\", G3: \"=XLOOKUP(E3,$A$2:$A$6,$B$2:$B$6,\\\"Not found\\\")\", G4: \"=XLOOKUP(E4,$A$2:$A$6,$B$2:$B$6,\\\"Not found\\\")\", G5: \"=XLOOKUP(E5,$A$2:$A$6,$B$2:$B$6,\\\"Not found\\\")\",\n            H2: \"=F2*XLOOKUP(E2,$A$2:$A$6,$C$2:$C$6,0)\", H3: \"=F3*XLOOKUP(E3,$A$2:$A$6,$C$2:$C$6,0)\", H4: \"=F4*XLOOKUP(E4,$A$2:$A$6,$C$2:$C$6,0)\", H5: \"=F5*XLOOKUP(E5,$A$2:$A$6,$C$2:$C$6,0)\",\n            H6: \"=SUM(H2:H5)\",\n          } },\n        { type: \"h\", text: \"VLOOKUP: still everywhere\" },\n        { type: \"p\", text: \"VLOOKUP is older but you will find it in thousands of existing workbooks, so you must be able to read it. It searches the first column of a table and returns the value from the column number you give.\" },\n        { type: \"code\", text: \"=VLOOKUP(lookup_value, table_array, col_index_num, [range_lookup])\\n\\n=VLOOKUP(E2, $A$2:$C$6, 3, FALSE)     price = 3rd column, exact match\" },\n        { type: \"table\", head: [\"Weakness of VLOOKUP\", \"What happens\", \"XLOOKUP instead\"], rows: [\n          [\"Column number typed as a fixed number\", \"Insert a column inside the table and 3 now points at the wrong column: wrong prices, no error\", \"Points at the return column itself, so it follows the move\"],\n          [\"Looks only to the right\", \"Cannot return a value from a column to the left of the codes\", \"The return column can be anywhere\"],\n          [\"Approximate match by default\", \"Forget FALSE and a missing code can return a neighbour's price\", \"Exact match by default\"],\n          [\"No built-in missing-value text\", \"Shows #N/A, often wrapped in IFERROR\", \"if_not_found argument\"],\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Always type FALSE for codes\", text: \"The last argument of VLOOKUP is TRUE (approximate) when you leave it out. For product codes, staff IDs or invoice numbers, always end with FALSE (or 0). Approximate match on unsorted codes gives wrong answers without any warning.\" },\n        { type: \"h\", text: \"INDEX and MATCH\" },\n        { type: \"p\", text: \"Before XLOOKUP, professionals combined two functions. MATCH finds the position of a value in a column; INDEX returns the item at that position in another column. Together they do what XLOOKUP does, and they work in every version of Excel.\" },\n        { type: \"code\", text: \"=MATCH(\\\"TOL-2\\\", A2:A6, 0)                 → 3 (third row of the list)\\n=INDEX(C2:C6, 3)                          → 6800\\n=INDEX($C$2:$C$6, MATCH(E2, $A$2:$A$6, 0))  price of the code in E2\" },\n        { type: \"h\", text: \"Approximate match for bands\" },\n        { type: \"p\", text: \"Commission, tax and discount scales are written as bands: from 0, from 1 000 000, from 3 000 000… Put the lower limit of each band in the first column, sorted smallest to largest. An approximate match returns the last band whose limit is less than or equal to the value.\" },\n        { type: \"list\", items: [\n          \"VLOOKUP with TRUE: `=VLOOKUP(B2,$A$9:$C$12,3,TRUE)`\",\n          \"MATCH with 1: `=INDEX($B$9:$B$12,MATCH(B2,$A$9:$A$12,1))`\",\n          \"XLOOKUP with match_mode -1: `=XLOOKUP(B2,$A$9:$A$12,$C$9:$C$12,,-1)`\",\n        ] },\n        { type: \"sheet\", id: \"mosp-m5-l2-bands\", title: \"Commission bands\",\n          task: \"Agents are paid a commission that depends on their sales band (table in A8:C12). Fill C2:C5 with the band name using INDEX and MATCH, D2:D5 with the rate using VLOOKUP with approximate match, and E2:E5 with the commission (sales × rate).\",\n          data: [\n            [\"Agent\", \"Sales\", \"Band\", \"Rate\", \"Commission\"],\n            [\"Mbarga Luc\", 850000, null, null, null],\n            [\"Ewane Sylvie\", 3000000, null, null, null],\n            [\"Hamadou Ali\", 4750000, null, null, null],\n            [\"Nkeng Grace\", 6200000, null, null, null],\n            [null, null, null, null, null],\n            [null, null, null, null, null],\n            [\"From\", \"Band\", \"Rate\", null, null],\n            [0, \"Starter\", 0, null, null],\n            [1000000, \"Bronze\", 0.02, null, null],\n            [3000000, \"Silver\", 0.035, null, null],\n            [5000000, \"Gold\", 0.05, null, null],\n          ],\n          editable: [\"C2\", \"C3\", \"C4\", \"C5\", \"D2\", \"D3\", \"D4\", \"D5\", \"E2\", \"E3\", \"E4\", \"E5\"],\n          checks: [\n            { cell: \"C2\", equals: \"Starter\" }, { cell: \"C3\", equals: \"Silver\" }, { cell: \"C4\", equals: \"Silver\" }, { cell: \"C5\", equals: \"Gold\" },\n            { cell: \"D2\", equals: 0, tol: 0.0001 }, { cell: \"D3\", equals: 0.035, tol: 0.0001 }, { cell: \"D4\", equals: 0.035, tol: 0.0001 }, { cell: \"D5\", equals: 0.05, tol: 0.0001 },\n            { cell: \"E2\", equals: 0 }, { cell: \"E3\", equals: 105000 }, { cell: \"E4\", equals: 166250 }, { cell: \"E5\", equals: 310000 },\n          ],\n          hint: \"C2: =INDEX($B$9:$B$12,MATCH(B2,$A$9:$A$12,1)). D2: =VLOOKUP(B2,$A$9:$C$12,3,TRUE). E2: =B2*D2. Ewane's sales are exactly 3 000 000, so she is already in the Silver band.\",\n          solution: {\n            C2: \"=INDEX($B$9:$B$12,MATCH(B2,$A$9:$A$12,1))\", C3: \"=INDEX($B$9:$B$12,MATCH(B3,$A$9:$A$12,1))\", C4: \"=INDEX($B$9:$B$12,MATCH(B4,$A$9:$A$12,1))\", C5: \"=INDEX($B$9:$B$12,MATCH(B5,$A$9:$A$12,1))\",\n            D2: \"=VLOOKUP(B2,$A$9:$C$12,3,TRUE)\", D3: \"=VLOOKUP(B3,$A$9:$C$12,3,TRUE)\", D4: \"=VLOOKUP(B4,$A$9:$C$12,3,TRUE)\", D5: \"=VLOOKUP(B5,$A$9:$C$12,3,TRUE)\",\n            E2: \"=B2*D2\", E3: \"=B3*D3\", E4: \"=B4*D4\", E5: \"=B5*D5\",\n          } },\n        { type: \"path\", items: [\"Formulas\", \"Function Library\", \"Lookup & Reference\"], note: \"Lists XLOOKUP, VLOOKUP, INDEX and MATCH with a dialog box that explains each argument.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"An NGO in Yaoundé pays mission allowances by staff grade. HR keeps one staff table (ID, name, grade) and one allowance table (grade, daily rate). Finance types only the staff ID and the number of nights; XLOOKUP fills in the name and rate. When the board raises the rates, HR changes one table and every claim sheet is correct.\" },\n        { type: \"check\", id: \"mosp-m5-l2-c1\", question: \"A colleague's formula is =VLOOKUP(A2,Prices!A:D,4,FALSE). Someone inserts a new column B in the Prices sheet. What happens?\", options: [\"Excel adjusts the 4 automatically\", \"The formula now returns values from the wrong column\", \"The formula shows #REF!\", \"Nothing, because FALSE protects it\"], answer: 1, explain: \"The table range grows to A:E, but the column number stays 4, which now points at a different column. XLOOKUP or INDEX-MATCH avoid this because they reference the return column directly.\" },\n        { type: \"check\", id: \"mosp-m5-l2-c2\", question: \"Which lookup should use an approximate match?\", options: [\"Finding a price from a product code\", \"Finding a staff name from an employee ID\", \"Finding a tax rate from an income, using a table of lower band limits\", \"Finding a phone number from a customer name\"], answer: 2, explain: \"Bands need approximate match: the income falls between two limits and Excel returns the band below. Codes, IDs and names must always match exactly.\" },\n        { type: \"task\", id: \"mosp-m5-l2-t1\", title: \"Practice\", items: [\n          \"Create a price list of 8 products with codes, names and prices on a sheet named Prices\",\n          \"On another sheet, build an order form where typing a code fills in the name and price with XLOOKUP\",\n          \"Rewrite one of the lookups with VLOOKUP and one with INDEX and MATCH\",\n          \"Insert a column in the price list and see which formula breaks\",\n          \"Add a discount table by order amount and look up the discount with approximate match\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"XLOOKUP function\", url: \"https://support.microsoft.com/en-us/excel/functions/xlookup-function\", source: MS },\n          EXAM,\n        ] },\n      ],\n    },\n\n    // ─────────────────────────── LESSON 3 ───────────────────────────\n    {\n      id: \"mosp-m5-l3\",\n      title: \"PivotTables and PivotCharts: summarise thousands of rows\",\n      minutes: 30,\n      objectives: [\n        \"Prepare a data list so a PivotTable can use it\",\n        \"Build a PivotTable with the Rows, Columns, Values and Filters areas and change how values are summarised\",\n        \"Add slicers and a PivotChart, refresh after changes, and rebuild a pivot summary with SUMIFS\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A PivotTable turns a long list of transactions into a summary table in a few clicks: sales by region and product, expenses by month and budget line, beneficiaries by district and gender. You drag fields around instead of writing formulas, and you can change the question in seconds.\" },\n        { type: \"h\", text: \"Step 1: prepare the data\" },\n        { type: \"list\", items: [\n          \"One header row, with a short, unique name in every column.\",\n          \"One record per row: one sale, one payment, one beneficiary.\",\n          \"No blank rows or columns inside the data, and no subtotal rows.\",\n          \"One type of data per column: amounts are numbers, not \\\"250 000 FCFA\\\" typed as text.\",\n          \"Turn the list into a table so new rows are included automatically.\",\n        ] },\n        { type: \"path\", items: [\"Home\", \"Format as Table\"], note: \"Or press Ctrl + T. Give the table a name in Table Design › Table Name, for example tblSales.\" },\n        { type: \"h\", text: \"Step 2: insert the PivotTable\" },\n        { type: \"path\", items: [\"Insert\", \"PivotTable\", \"From Table/Range\"] },\n        { type: \"steps\", title: \"Create your first PivotTable\", items: [\n          \"Click any cell inside the table.\",\n          \"Go to Insert › PivotTable › From Table/Range. Excel suggests the table name as the range.\",\n          \"Keep New Worksheet and click OK.\",\n          \"In the PivotTable Fields pane, drag Region to Rows, Product to Columns and Amount to Values.\",\n          \"Rename the new sheet, for example Summary.\",\n        ] },\n        { type: \"table\", head: [\"Area\", \"What it does\", \"Typical fields\"], rows: [\n          [\"Rows\", \"One row in the summary for each distinct value\", \"Region, agent, budget line, month\"],\n          [\"Columns\", \"One column for each distinct value; keep it to a few\", \"Product, year, gender\"],\n          [\"Values\", \"The numbers that are calculated: Sum, Count, Average…\", \"Amount, quantity, number of beneficiaries\"],\n          [\"Filters\", \"A drop-down above the table that limits the whole report\", \"Year, project, donor\"],\n        ] },\n        { type: \"h\", text: \"Change how values are summarised\" },\n        { type: \"list\", items: [\n          \"Numbers are added (Sum) by default; text fields dropped in Values are counted (Count).\",\n          \"To switch to Average or Count, right-click a value › Summarize Values By.\",\n          \"To show shares, right-click › Show Values As › % of Grand Total (or % of Column Total).\",\n          \"Format numbers once for the whole field: right-click › Number Format, instead of formatting cells.\",\n          \"Group dates by month or quarter, or amounts by ranges: right-click an item › Group.\",\n        ] },\n        { type: \"form\", id: \"mosp-m5-l3-areas\", title: \"Which field goes where?\",\n          task: \"The finance officer of a micro-credit network wants a report on loans disbursed. For each need, choose the PivotTable area, then answer the two questions about summarising.\",\n          hint: \"Rows and Columns create the headings of the summary, Values holds the numbers that are calculated, and Filters limits the whole report to one choice.\",\n          fields: [\n            area(\"One line per branch (Douala, Yaoundé, Garoua…)\", 0),\n            area(\"One column per loan type (Agriculture, Trade, School fees)\", 1, \"Loan type has only three values, so it fits across the columns.\"),\n            area(\"The total amount disbursed\", 2),\n            area(\"A drop-down to show only the year 2026\", 3, \"A filter limits the whole report without adding rows or columns.\"),\n            { kind: \"select\", label: \"The manager wants the number of loans, not the amount. What do you change?\", options: [\"Summarize Values By › Count\", \"Show Values As › % of Grand Total\", \"Group\", \"Refresh\"], answer: 0, explain: \"Count counts the loans in each cell. You can also drag the Loan ID field to Values, where text is counted automatically.\" },\n            { kind: \"select\", label: \"She also wants each branch's share of the total. Which option gives it?\", options: [\"Summarize Values By › Average\", \"Show Values As › % of Grand Total\", \"Number Format › Percentage\", \"Insert Slicer\"], answer: 1, explain: \"Show Values As recalculates each cell as a share. Number Format would only display the amounts with a % sign.\" },\n          ] },\n        { type: \"h\", text: \"Slicers, refresh and PivotCharts\" },\n        { type: \"path\", items: [\"PivotTable Analyze\", \"Insert Slicer\"], note: \"Buttons that filter the PivotTable with one click. Ideal for dashboards shown to managers.\" },\n        { type: \"callout\", tone: \"warning\", title: \"A PivotTable does not update itself\", text: \"When the source data changes, the PivotTable keeps the old figures until you refresh it. If you add rows to a plain range instead of a table, you must also change the source range.\" },\n        { type: \"shortcuts\", items: [\n          { keys: [\"Ctrl\", \"T\"], action: \"Format the list as a table\" },\n          { keys: [\"Alt\", \"F5\"], action: \"Refresh the selected PivotTable\" },\n          { keys: [\"Ctrl\", \"Alt\", \"F5\"], action: \"Refresh all PivotTables and data connections in the workbook\" },\n        ] },\n        { type: \"path\", items: [\"PivotTable Analyze\", \"PivotChart\"], note: \"A chart linked to the PivotTable: filtering or pivoting one changes the other.\" },\n        { type: \"h\", text: \"The same summary with SUMIFS\" },\n        { type: \"p\", text: \"Each cell of a PivotTable is a SUMIFS (or COUNTIFS) with the row and column headings as criteria. Writing it yourself is useful when the layout of a report is fixed, when you need to mix sources, or to check a pivot. Mixed references let one formula fill the whole grid: $E2 keeps column E for the region, F$1 keeps row 1 for the product.\" },\n        { type: \"code\", text: \"=SUMIFS($C$2:$C$10, $A$2:$A$10, $E2, $B$2:$B$10, F$1)\" },\n        { type: \"sheet\", id: \"mosp-m5-l3-sheet\", title: \"Build a pivot summary with SUMIFS\",\n          task: \"A food wholesaler lists its sales in A1:C10. Fill the summary: F2:G4 with total sales by region and product, H2:H4 with the number of sales per region, and F5:H5 with the grand totals.\",\n          data: [\n            [\"Region\", \"Product\", \"Amount\", null, \"Region\", \"Rice\", \"Oil\", \"Sales count\"],\n            [\"Littoral\", \"Rice\", 450000, null, \"Littoral\", null, null, null],\n            [\"Centre\", \"Oil\", 280000, null, \"Centre\", null, null, null],\n            [\"Littoral\", \"Oil\", 190000, null, \"West\", null, null, null],\n            [\"West\", \"Rice\", 320000, null, \"Grand total\", null, null, null],\n            [\"Centre\", \"Rice\", 510000],\n            [\"Littoral\", \"Rice\", 275000],\n            [\"West\", \"Oil\", 145000],\n            [\"Centre\", \"Oil\", 230000],\n            [\"Littoral\", \"Oil\", 160000],\n          ],\n          editable: [\"F2\", \"G2\", \"F3\", \"G3\", \"F4\", \"G4\", \"H2\", \"H3\", \"H4\", \"F5\", \"G5\", \"H5\"],\n          checks: [\n            { cell: \"F2\", equals: 725000 }, { cell: \"G2\", equals: 350000 }, { cell: \"F3\", equals: 510000 }, { cell: \"G3\", equals: 510000 },\n            { cell: \"F4\", equals: 320000 }, { cell: \"G4\", equals: 145000 },\n            { cell: \"H2\", equals: 4 }, { cell: \"H3\", equals: 3 }, { cell: \"H4\", equals: 2 },\n            { cell: \"F5\", equals: 1555000 }, { cell: \"G5\", equals: 1005000 }, { cell: \"H5\", equals: 9 },\n          ],\n          hint: \"Type =SUMIFS($C$2:$C$10,$A$2:$A$10,$E2,$B$2:$B$10,F$1) in F2, then copy it to G2 and down to row 4. H2 is =COUNTIF($A$2:$A$10,E2). Row 5 is SUM of each column.\",\n          solution: {\n            F2: \"=SUMIFS($C$2:$C$10,$A$2:$A$10,$E2,$B$2:$B$10,F$1)\", G2: \"=SUMIFS($C$2:$C$10,$A$2:$A$10,$E2,$B$2:$B$10,G$1)\",\n            F3: \"=SUMIFS($C$2:$C$10,$A$2:$A$10,$E3,$B$2:$B$10,F$1)\", G3: \"=SUMIFS($C$2:$C$10,$A$2:$A$10,$E3,$B$2:$B$10,G$1)\",\n            F4: \"=SUMIFS($C$2:$C$10,$A$2:$A$10,$E4,$B$2:$B$10,F$1)\", G4: \"=SUMIFS($C$2:$C$10,$A$2:$A$10,$E4,$B$2:$B$10,G$1)\",\n            H2: \"=COUNTIF($A$2:$A$10,E2)\", H3: \"=COUNTIF($A$2:$A$10,E3)\", H4: \"=COUNTIF($A$2:$A$10,E4)\",\n            F5: \"=SUM(F2:F4)\", G5: \"=SUM(G2:G4)\", H5: \"=SUM(H2:H4)\",\n          } },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"The M&E officer of an NGO in Bamenda receives a monthly export of 3 000 beneficiary records. One PivotTable with District in Rows, Gender in Columns and a count of Beneficiary ID in Values answers the donor's standard table. A slicer for the month and a PivotChart turn it into a one-page dashboard for the coordination meeting.\" },\n        { type: \"check\", id: \"mosp-m5-l3-c1\", question: \"You added 40 new sales to the source table, but the PivotTable totals have not changed. What should you do?\", options: [\"Delete the PivotTable and build it again\", \"Refresh the PivotTable\", \"Press F9 to recalculate\", \"Sort the source data\"], answer: 1, explain: \"A PivotTable reads its source only when it is refreshed: PivotTable Analyze › Refresh, or Alt + F5. Because the source is a table, the new rows are included.\" },\n        { type: \"check\", id: \"mosp-m5-l3-c2\", question: \"Which data list is ready for a PivotTable?\", options: [\"A list with a subtotal row after each region\", \"A list with two header rows merged across columns\", \"A list with one header row, one record per row and no blank rows\", \"A list where amounts are typed as \\\"250 000 FCFA\\\"\"], answer: 2, explain: \"Subtotal rows would be counted twice, merged headers give fields no clear name, and amounts typed as text cannot be added.\" },\n        { type: \"task\", id: \"mosp-m5-l3-t1\", title: \"Practice\", items: [\n          \"Format a sales or expense list of at least 30 rows as a table and name it\",\n          \"Insert a PivotTable with a category in Rows, a period in Columns and an amount in Values\",\n          \"Show the values as % of Grand Total, then switch back to Sum\",\n          \"Add a slicer and a PivotChart, and place them next to the PivotTable\",\n          \"Add five rows to the table, refresh, and check that the totals change\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Overview of PivotTables and PivotCharts\", url: \"https://support.microsoft.com/en-us/office/overview-of-pivottables-and-pivotcharts-527c8fa3-02c0-445a-a2db-7794676bce96\", source: MS },\n          EXAM,\n        ] },\n      ],\n    },\n\n    // ─────────────────────────── LESSON 4 ───────────────────────────\n    {\n      id: \"mosp-m5-l4\",\n      title: \"What-If analysis, data validation and protection\",\n      minutes: 30,\n      objectives: [\n        \"Calculate loan repayments with PMT and test options with Goal Seek, Scenario Manager and data tables\",\n        \"Control what users can type with Data Validation lists, number limits and input messages\",\n        \"Lock formulas and protect sheets and workbooks before sharing a model\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"What-If analysis answers questions such as \\\"What will I repay each month?\\\", \\\"How much can I borrow if I can pay 100 000 FCFA a month?\\\" or \\\"What happens to profit if prices rise by 10%?\\\". Once your model is right, validation and protection stop other people from breaking it.\" },\n        { type: \"h\", text: \"PMT: the monthly repayment of a loan\" },\n        { type: \"code\", text: \"=PMT(rate, nper, pv, [fv], [type])\\n\\n=PMT(18%/12, 24, -2000000)      2 000 000 FCFA over 24 months at 18% a year\" },\n        { type: \"table\", head: [\"Argument\", \"Meaning\", \"Watch out\"], rows: [\n          [\"rate\", \"Interest rate per period\", \"Monthly payments: divide the annual rate by 12\"],\n          [\"nper\", \"Number of payments\", \"Months, not years: 2 years = 24\"],\n          [\"pv\", \"Amount borrowed today\", \"Excel treats money you receive as positive and money you pay as negative\"],\n          [\"fv, type\", \"Optional: balance left at the end, and 1 for payments at the start of each period\", \"Leave them out for an ordinary loan\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Why PMT is negative\", text: \"PMT shows the payment as money going out, so the result is negative when the loan amount is positive. Put a minus sign before the loan amount (-B2) or before PMT to show a positive repayment.\" },\n        { type: \"sheet\", id: \"mosp-m5-l4-sheet\", title: \"Compare three loan offers\",\n          task: \"A tailor in Yaoundé needs 1 500 000 FCFA to buy machines and compares three offers. Fill E2:E4 with the monthly repayment as a positive number, F2:F4 with the total repaid and G2:G4 with the total interest.\",\n          data: [\n            [\"Lender\", \"Amount\", \"Annual rate\", \"Months\", \"Monthly payment\", \"Total repaid\", \"Total interest\"],\n            [\"Microfinance A\", 1500000, 0.24, 12, null, null, null],\n            [\"Bank B\", 1500000, 0.15, 24, null, null, null],\n            [\"Cooperative C\", 1500000, 0.18, 18, null, null, null],\n          ],\n          editable: [\"E2\", \"E3\", \"E4\", \"F2\", \"F3\", \"F4\", \"G2\", \"G3\", \"G4\"],\n          checks: [\n            { cell: \"E2\", equals: 141839.39, tol: 1 }, { cell: \"E3\", equals: 72729.97, tol: 1 }, { cell: \"E4\", equals: 95708.67, tol: 1 },\n            { cell: \"F2\", equals: 1702072.74, tol: 5 }, { cell: \"F3\", equals: 1745519.33, tol: 5 }, { cell: \"F4\", equals: 1722756.11, tol: 5 },\n            { cell: \"G2\", equals: 202072.74, tol: 5 }, { cell: \"G3\", equals: 245519.33, tol: 5 }, { cell: \"G4\", equals: 222756.11, tol: 5 },\n          ],\n          hint: \"E2 is =PMT(C2/12,D2,-B2): monthly rate, number of months, and the amount with a minus sign. Total repaid is E2*D2, and interest is the total repaid minus the amount borrowed.\",\n          solution: {\n            E2: \"=PMT(C2/12,D2,-B2)\", E3: \"=PMT(C3/12,D3,-B3)\", E4: \"=PMT(C4/12,D4,-B4)\",\n            F2: \"=E2*D2\", F3: \"=E3*D3\", F4: \"=E4*D4\",\n            G2: \"=F2-B2\", G3: \"=F3-B3\", G4: \"=F4-B4\",\n          } },\n        { type: \"p\", text: \"Bank B has the lowest monthly payment but costs the most in interest, because you pay for twice as long. Always compare the total cost, not only the monthly amount.\" },\n        { type: \"h\", text: \"Goal Seek: work backwards from the result\" },\n        { type: \"path\", items: [\"Data\", \"What-If Analysis\", \"Goal Seek\"] },\n        { type: \"steps\", title: \"How much can I borrow for 100 000 FCFA a month?\", items: [\n          \"Click the cell with the PMT formula, for example E3.\",\n          \"Open Data › What-If Analysis › Goal Seek. Set cell already shows E3.\",\n          \"In To value, type 100000.\",\n          \"In By changing cell, select the loan amount, B3. It must contain a number, not a formula.\",\n          \"Click OK. Excel tries values until the payment is 100 000, then click OK to keep the result or Cancel to undo it.\",\n        ] },\n        { type: \"h\", text: \"Scenario Manager and data tables\" },\n        { type: \"list\", items: [\n          \"Scenario Manager (Data › What-If Analysis › Scenario Manager) saves named sets of input values, for example Pessimistic, Expected and Optimistic prices and volumes. Show each one in turn, or click Summary for a comparison report on a new sheet.\",\n          \"A data table (Data › What-If Analysis › Data Table) calculates one formula for a whole list of inputs, such as the repayment for 12, 18, 24 and 36 months. You give the row or column input cell, and Excel fills the grid.\",\n          \"Use Goal Seek for one target, Scenario Manager for a few named cases with several inputs, and a data table for one or two inputs across many values.\",\n        ] },\n        { type: \"h\", text: \"Data Validation: control what people type\" },\n        { type: \"path\", items: [\"Data\", \"Data Tools\", \"Data Validation\"] },\n        { type: \"table\", head: [\"Tab or setting\", \"Use it for\", \"Example\"], rows: [\n          [\"Settings › Allow: List\", \"A drop-down of allowed values\", \"Source: Douala,Yaoundé,Garoua, or a range such as =$H$2:$H$10\"],\n          [\"Settings › Allow: Whole number\", \"Numbers between limits\", \"Quantity between 1 and 500; number of months between 6 and 36\"],\n          [\"Settings › Allow: Decimal or Date\", \"Amounts, rates or dates within limits\", \"Interest rate between 0 and 0.4\"],\n          [\"Input Message\", \"A tip that appears when the cell is selected\", \"\\\"Type the amount in FCFA, without spaces\\\"\"],\n          [\"Error Alert\", \"What happens with a wrong entry: Stop blocks it, Warning and Information allow it after a message\", \"Stop: \\\"Choose a city from the list\\\"\"],\n        ] },\n        { type: \"h\", text: \"Lock cells and protect the sheet\" },\n        { type: \"p\", text: \"Every cell is locked by default, but locking only works once the sheet is protected. So the method is: unlock the input cells, then protect the sheet. Users can type in the inputs, and the formulas are safe.\" },\n        { type: \"steps\", title: \"Protect a loan calculator\", items: [\n          \"Select the input cells (amount, rate, months).\",\n          \"Press Ctrl + 1 to open Format Cells, go to the Protection tab and untick Locked.\",\n          \"Go to Review › Protect Sheet, choose what users may do, type a password if needed and click OK.\",\n          \"To stop people adding, deleting or renaming sheets, use Review › Protect Workbook (structure).\",\n          \"To stop people opening the file at all, use File › Info › Protect Workbook › Encrypt with Password.\",\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Sheet protection is not security\", text: \"Protect Sheet prevents accidental changes; it does not hide confidential data from a determined person. For salaries or client data, encrypt the file with a password and control who can open it in OneDrive. Keep passwords somewhere safe: Microsoft cannot recover them.\" },\n        { type: \"form\", id: \"mosp-m5-l4-form\", title: \"Goal Seek, validation and protection\",\n          task: \"Your loan calculator has the amount in B2, the annual rate in C2, the months in D2 and the PMT formula in E2. Answer each question; type cell references like B2.\",\n          hint: \"Goal Seek sets the formula cell to a value by changing an input cell. Protection needs two steps: unlock the inputs, then protect the sheet.\",\n          fields: [\n            { kind: \"text\", label: \"Goal Seek: what do you type in Set cell?\", accept: [\"E2\", \"$E$2\"], placeholder: \"Cell\", mono: true, explain: \"Set cell is always the cell that contains the formula whose result you want to fix.\" },\n            { kind: \"text\", label: \"Goal Seek: what do you type in To value, for a payment of 100 000 FCFA a month?\", accept: [\"100000\", \"100 000\"], placeholder: \"Value\", mono: true },\n            { kind: \"text\", label: \"Goal Seek: what do you type in By changing cell, to find the amount you can borrow?\", accept: [\"B2\", \"$B$2\"], placeholder: \"Cell\", mono: true, explain: \"By changing cell must be an input that the formula depends on, and it must contain a value, not a formula.\" },\n            { kind: \"select\", label: \"The months in D2 must be a whole number from 6 to 36. Which setting do you use?\", options: [\"Data Validation › Allow: Whole number, between 6 and 36\", \"Data Validation › Allow: List\", \"Conditional Formatting › Highlight Cells Rules\", \"Review › Protect Sheet\"], answer: 0 },\n            { kind: \"select\", label: \"You want a note to appear when someone selects B2, before they type. Which Data Validation tab do you use?\", options: [\"Settings\", \"Input Message\", \"Error Alert\", \"Protection\"], answer: 1 },\n            { kind: \"select\", label: \"Colleagues must be able to change B2:D2 but never the formula in E2. What do you do?\", options: [\"Protect the sheet only\", \"Unlock B2:D2 in Format Cells › Protection, then protect the sheet\", \"Lock E2, then protect the workbook structure\", \"Hide column E\"], answer: 1, explain: \"All cells are locked by default, so protecting the sheet alone would block the inputs too.\" },\n            { kind: \"select\", label: \"You want to compare an Expected case and a Crisis case, each changing the amount, the rate and the months. Which tool fits?\", options: [\"Goal Seek\", \"Scenario Manager\", \"Data Validation\", \"Protect Workbook\"], answer: 1, explain: \"Scenario Manager stores named sets of several inputs and can produce a summary report.\" },\n          ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A credit officer at a microfinance institution in Bafoussam visits clients with a laptop. Her loan simulator has drop-down lists for the loan product, whole-number limits for the duration, and a protected sheet so the PMT formulas and rates set by head office cannot be changed. The client sees the repayment immediately, and every officer uses the same rules.\" },\n        { type: \"check\", id: \"mosp-m5-l4-c1\", question: \"A loan of 3 000 000 FCFA at 12% a year is repaid monthly over 3 years. Which formula gives the monthly payment as a positive number?\", options: [\"=PMT(12%,3,3000000)\", \"=PMT(12%/12,36,-3000000)\", \"=PMT(12%,36,-3000000)\", \"=PMT(1%,3,3000000)\"], answer: 1, explain: \"Monthly payments need a monthly rate (12%/12) and the number of months (36). The minus sign before the amount makes the result positive.\" },\n        { type: \"check\", id: \"mosp-m5-l4-c2\", question: \"You protected a sheet, and now nobody can type in the input cells either. What did you forget?\", options: [\"To protect the workbook structure\", \"To unlock the input cells before protecting the sheet\", \"To add Data Validation\", \"To save the file as .xlsm\"], answer: 1, explain: \"Cells are locked by default. Untick Locked in Format Cells › Protection for the inputs, then protect the sheet again.\" },\n        { type: \"task\", id: \"mosp-m5-l4-t1\", title: \"Practice\", items: [\n          \"Build a loan calculator with amount, annual rate and months as inputs and a PMT formula\",\n          \"Use Goal Seek to find the amount you can borrow for 75 000 FCFA a month\",\n          \"Create three scenarios in Scenario Manager and produce a Summary report\",\n          \"Add Data Validation: a list of loan products and whole numbers from 6 to 36 for the months, with an input message\",\n          \"Unlock the input cells, protect the sheet, and test that the formula cannot be changed\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Use Goal Seek to find the result you want by adjusting an input value\", url: \"https://support.microsoft.com/en-us/excel/use-goal-seek-to-find-the-result-you-want-by-adjusting-an-input-value\", source: MS },\n          { label: \"Protect a worksheet\", url: \"https://support.microsoft.com/en-us/excel/protect-a-worksheet\", source: MS },\n        ] },\n      ],\n    },\n\n    // ─────────────────────────── PRACTICE LAB ───────────────────────────\n    {\n      id: \"mosp-m5-practice\",\n      title: \"Practice lab: decisions, lookups and analysis in Excel\",\n      minutes: 40,\n      objectives: [\n        \"Apply IF and COUNTIF to a simple follow-up list\",\n        \"Combine lookups with IFERROR to handle missing codes\",\n        \"Choose the right analysis tool and write PMT and SUMIFS formulas\",\n        \"Build a complete invoice summary that combines XLOOKUP, SUMIFS and IF\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" },\n        { type: \"h\", text: \"Exercise 1: School fees follow-up\" },\n        { type: \"sheet\", id: \"mosp-pr-m5-fees\", level: \"beginner\", title: \"Who still owes school fees?\",\n          task: \"The bursar of a secondary school in Bamenda follows up fees. Fill E2:E5 with the balance (fees due minus paid), F2:F5 with \\\"Cleared\\\" when the balance is 0 or \\\"Owing\\\" otherwise, then F7 with the number of students owing and F8 with the total still to collect.\",\n          data: [\n            [\"Student\", \"Class\", \"Fees due\", \"Paid\", \"Balance\", \"Status\"],\n            [\"Nji Ernest\", \"Form 3\", 185000, 185000, null, null],\n            [\"Mouafo Diane\", \"Form 5\", 210000, 150000, null, null],\n            [\"Bello Aminatou\", \"Form 3\", 185000, 100000, null, null],\n            [\"Etoundi Serge\", \"Lower Sixth\", 240000, 240000, null, null],\n            [null, null, null, null, null, null],\n            [null, null, null, null, \"Students owing\", null],\n            [null, null, null, null, \"To collect\", null],\n          ],\n          editable: [\"E2\", \"E3\", \"E4\", \"E5\", \"F2\", \"F3\", \"F4\", \"F5\", \"F7\", \"F8\"],\n          checks: [\n            { cell: \"E2\", equals: 0 }, { cell: \"E3\", equals: 60000 }, { cell: \"E4\", equals: 85000 }, { cell: \"E5\", equals: 0 },\n            { cell: \"F2\", equals: \"Cleared\" }, { cell: \"F3\", equals: \"Owing\" }, { cell: \"F4\", equals: \"Owing\" }, { cell: \"F5\", equals: \"Cleared\" },\n            { cell: \"F7\", equals: 2 }, { cell: \"F8\", equals: 145000 },\n          ],\n          hint: \"E2 is =C2-D2. F2 is =IF(E2=0,\\\"Cleared\\\",\\\"Owing\\\"). F7 counts \\\"Owing\\\" with COUNTIF, and F8 is the SUM of the balances.\",\n          solution: {\n            E2: \"=C2-D2\", E3: \"=C3-D3\", E4: \"=C4-D4\", E5: \"=C5-D5\",\n            F2: \"=IF(E2=0,\\\"Cleared\\\",\\\"Owing\\\")\", F3: \"=IF(E3=0,\\\"Cleared\\\",\\\"Owing\\\")\", F4: \"=IF(E4=0,\\\"Cleared\\\",\\\"Owing\\\")\", F5: \"=IF(E5=0,\\\"Cleared\\\",\\\"Owing\\\")\",\n            F7: \"=COUNTIF(F2:F5,\\\"Owing\\\")\", F8: \"=SUM(E2:E5)\",\n          } },\n        { type: \"h\", text: \"Exercise 2: Mission allowances\" },\n        { type: \"sheet\", id: \"mosp-pr-m5-perdiem\", level: \"intermediate\", title: \"Look up staff and daily rates\",\n          task: \"An NGO pays mission allowances by grade. For each mission in rows 9 to 12, fill C with the staff name (\\\"Unknown ID\\\" if the ID is not in the staff list), D with the grade (\\\"None\\\" if unknown) and E with nights × daily rate, showing 0 when the grade cannot be found.\",\n          data: [\n            [\"Staff ID\", \"Name\", \"Grade\", null, \"Grade\", \"Daily rate\"],\n            [\"NG-101\", \"Ayuk Brenda\", \"A\", null, \"A\", 45000],\n            [\"NG-102\", \"Kamga Rodrigue\", \"B\", null, \"B\", 35000],\n            [\"NG-103\", \"Oumarou Fadimatou\", \"C\", null, \"C\", 25000],\n            [\"NG-104\", \"Manga Clarisse\", \"B\"],\n            [\"NG-105\", \"Tabi Joseph\", \"C\"],\n            [null, null, null],\n            [\"Staff ID\", \"Nights\", \"Name\", \"Grade\", \"Allowance\"],\n            [\"NG-103\", 3, null, null, null],\n            [\"NG-101\", 2, null, null, null],\n            [\"NG-110\", 4, null, null, null],\n            [\"NG-104\", 5, null, null, null],\n          ],\n          editable: [\"C9\", \"C10\", \"C11\", \"C12\", \"D9\", \"D10\", \"D11\", \"D12\", \"E9\", \"E10\", \"E11\", \"E12\"],\n          checks: [\n            { cell: \"C9\", equals: \"Oumarou Fadimatou\" }, { cell: \"C10\", equals: \"Ayuk Brenda\" }, { cell: \"C11\", equals: \"Unknown ID\" }, { cell: \"C12\", equals: \"Manga Clarisse\" },\n            { cell: \"D9\", equals: \"C\" }, { cell: \"D10\", equals: \"A\" }, { cell: \"D11\", equals: \"None\" }, { cell: \"D12\", equals: \"B\" },\n            { cell: \"E9\", equals: 75000 }, { cell: \"E10\", equals: 90000 }, { cell: \"E11\", equals: 0 }, { cell: \"E12\", equals: 175000 },\n          ],\n          hint: \"C9: =XLOOKUP(A9,$A$2:$A$6,$B$2:$B$6,\\\"Unknown ID\\\"). D9 is the same with the grade column and \\\"None\\\". For E9, find the rate with INDEX($F$2:$F$4,MATCH(D9,$E$2:$E$4,0)), multiply by B9, and wrap everything in IFERROR(…,0).\",\n          solution: {\n            C9: \"=XLOOKUP(A9,$A$2:$A$6,$B$2:$B$6,\\\"Unknown ID\\\")\", C10: \"=XLOOKUP(A10,$A$2:$A$6,$B$2:$B$6,\\\"Unknown ID\\\")\", C11: \"=XLOOKUP(A11,$A$2:$A$6,$B$2:$B$6,\\\"Unknown ID\\\")\", C12: \"=XLOOKUP(A12,$A$2:$A$6,$B$2:$B$6,\\\"Unknown ID\\\")\",\n            D9: \"=XLOOKUP(A9,$A$2:$A$6,$C$2:$C$6,\\\"None\\\")\", D10: \"=XLOOKUP(A10,$A$2:$A$6,$C$2:$C$6,\\\"None\\\")\", D11: \"=XLOOKUP(A11,$A$2:$A$6,$C$2:$C$6,\\\"None\\\")\", D12: \"=XLOOKUP(A12,$A$2:$A$6,$C$2:$C$6,\\\"None\\\")\",\n            E9: \"=IFERROR(B9*INDEX($F$2:$F$4,MATCH(D9,$E$2:$E$4,0)),0)\", E10: \"=IFERROR(B10*INDEX($F$2:$F$4,MATCH(D10,$E$2:$E$4,0)),0)\",\n            E11: \"=IFERROR(B11*INDEX($F$2:$F$4,MATCH(D11,$E$2:$E$4,0)),0)\", E12: \"=IFERROR(B12*INDEX($F$2:$F$4,MATCH(D12,$E$2:$E$4,0)),0)\",\n          } },\n        { type: \"h\", text: \"Exercise 3: The right analysis tool\" },\n        { type: \"form\", id: \"mosp-pr-m5-tools\", level: \"advanced\", title: \"Choose the tool and write the formula\",\n          task: \"A cooperative of coffee farmers in the West region asks you for help with its workbook. Answer each question. Type formulas in English with commas, starting with =.\",\n          hint: \"Goal Seek finds one input for a target result, Scenario Manager compares named cases, a PivotTable summarises long lists, and Data Validation controls entries. For PMT, the rate and the number of periods must both be monthly.\",\n          fields: [\n            { kind: \"text\", label: \"The cooperative borrows the amount in B2 at the annual rate in B3 over the number of months in B4. Write the formula for the monthly payment as a positive number.\", pattern: \"^=PMT\\\\(\\\\s*\\\\$?B\\\\$?3\\\\s*/\\\\s*12\\\\s*,\\\\s*\\\\$?B\\\\$?4\\\\s*,\\\\s*-\\\\s*\\\\$?B\\\\$?2\\\\s*\\\\)$|^=-PMT\\\\(\\\\s*\\\\$?B\\\\$?3\\\\s*/\\\\s*12\\\\s*,\\\\s*\\\\$?B\\\\$?4\\\\s*,\\\\s*\\\\$?B\\\\$?2\\\\s*\\\\)$\", example: \"=PMT(B3/12,B4,-B2)\", placeholder: \"=PMT(…)\", mono: true, explain: \"Divide the annual rate by 12, use the number of months, and put a minus sign before the amount (or before PMT).\" },\n            { kind: \"text\", label: \"Deliveries are listed with the farmer's village in A2:A200 and the kilograms in C2:C200. Write a formula for the total kilograms delivered from Dschang.\", pattern: SUMIFS_DSCHANG, accept: [\"=SUMIFS(C2:C200,A2:A200,\\\"Dschang\\\")\", \"=SUMIF(A2:A200,\\\"Dschang\\\",C2:C200)\"], example: \"=SUMIFS(C2:C200,A2:A200,\\\"Dschang\\\")\", placeholder: \"=SUMIFS(…)\", mono: true, explain: \"SUMIFS puts the range to add first; SUMIF puts it last. Both work for one condition.\" },\n            { kind: \"select\", label: \"The board wants to know the price per kilogram that brings total income to exactly 45 000 000 FCFA. Which tool?\", options: [\"Goal Seek\", \"Scenario Manager\", \"PivotTable\", \"Data Validation\"], answer: 0, explain: \"One target result and one input to change: Goal Seek.\" },\n            { kind: \"select\", label: \"It also wants to compare a Good harvest, a Normal harvest and a Drought case, each with a different volume, price and transport cost.\", options: [\"Goal Seek\", \"Scenario Manager\", \"Data Validation\", \"IFERROR\"], answer: 1 },\n            { kind: \"select\", label: \"A list of 4 000 deliveries must be summarised by village and by month, with a count of farmers.\", options: [\"A nested IF\", \"Scenario Manager\", \"A PivotTable\", \"Goal Seek\"], answer: 2 },\n            { kind: \"select\", label: \"Collectors keep typing the village name differently (Dschang, dschang, Dshang). How do you prevent this?\", options: [\"Protect the workbook\", \"Data Validation with a List of villages\", \"Format as Table\", \"Conditional Formatting\"], answer: 1, explain: \"A drop-down list only accepts the approved spellings, so SUMIFS and PivotTables group the data correctly.\" },\n            { kind: \"select\", label: \"In a PivotTable of deliveries, where do you put the Month field to get one column per month?\", options: AREAS, answer: 1 },\n          ] },\n        { type: \"h\", text: \"Exercise 4: Customer invoices and volume discount\" },\n        { type: \"sheet\", id: \"mosp-pr-m5-orders\", level: \"expert\", title: \"Invoice lines, customer totals and discount\",\n          task: \"A wholesaler in Douala prices orders from the list in A1:C5. Fill D8:D12 with quantity × unit price: a discontinued code or a cancelled line (no quantity) must give 0, not an error. Then fill G2:G3 with each customer's total, and H2:H3 with the amount to invoice after a 10% discount for customers whose total is at least 500 000 FCFA.\",\n          data: [\n            [\"Code\", \"Product\", \"Unit price\", null, null, \"Customer\", \"Total\", \"To invoice\"],\n            [\"SAV-12\", \"Soap, carton of 12\", 7500, null, null, \"Épicerie Mbopi\", null, null],\n            [\"HUI-5\", \"Palm oil 5 L\", 6250, null, null, \"Boutique Ngaba\", null, null],\n            [\"RIZ-25\", \"Rice 25 kg\", 16000],\n            [\"SUC-5\", \"Sugar 5 kg\", 4800],\n            [null, null, null],\n            [\"Customer\", \"Code\", \"Qty\", \"Amount\"],\n            [\"Épicerie Mbopi\", \"RIZ-25\", 20, null],\n            [\"Épicerie Mbopi\", \"SAV-12\", 24, null],\n            [\"Boutique Ngaba\", \"HUI-5\", 30, null],\n            [\"Boutique Ngaba\", \"SUC-10\", 10, null],\n            [\"Boutique Ngaba\", \"RIZ-25\", null, null],\n          ],\n          editable: [\"D8\", \"D9\", \"D10\", \"D11\", \"D12\", \"G2\", \"G3\", \"H2\", \"H3\"],\n          checks: [\n            { cell: \"D8\", equals: 320000 }, { cell: \"D9\", equals: 180000 }, { cell: \"D10\", equals: 187500 }, { cell: \"D11\", equals: 0 }, { cell: \"D12\", equals: 0 },\n            { cell: \"G2\", equals: 500000 }, { cell: \"G3\", equals: 187500 },\n            { cell: \"H2\", equals: 450000 }, { cell: \"H3\", equals: 187500 },\n          ],\n          hint: \"D8: =C8*XLOOKUP(B8,$A$2:$A$5,$C$2:$C$5,0). SUC-10 is not on the list, so if_not_found must be 0. G2: =SUMIFS($D$8:$D$12,$A$8:$A$12,F2). H2: =IF(G2>=500000,G2*0.9,G2). Mbopi's total is exactly 500 000, so > instead of >= gives the wrong answer.\",\n          solution: {\n            D8: \"=C8*XLOOKUP(B8,$A$2:$A$5,$C$2:$C$5,0)\", D9: \"=C9*XLOOKUP(B9,$A$2:$A$5,$C$2:$C$5,0)\", D10: \"=C10*XLOOKUP(B10,$A$2:$A$5,$C$2:$C$5,0)\",\n            D11: \"=C11*XLOOKUP(B11,$A$2:$A$5,$C$2:$C$5,0)\", D12: \"=C12*XLOOKUP(B12,$A$2:$A$5,$C$2:$C$5,0)\",\n            G2: \"=SUMIFS($D$8:$D$12,$A$8:$A$12,F2)\", G3: \"=SUMIFS($D$8:$D$12,$A$8:$A$12,F3)\",\n            H2: \"=IF(G2>=500000,G2*0.9,G2)\", H3: \"=IF(G3>=500000,G3*0.9,G3)\",\n          } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"mosp-m5-quiz\",\n    title: \"Module 5 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"What does =IF(AND(B2>=12,C2=\\\"Yes\\\"),\\\"Certified\\\",\\\"Not certified\\\") return when B2 is 14 and C2 is \\\"No\\\"?\", options: [\"Certified\", \"Not certified\", \"TRUE\", \"#N/A\"], answer: 1, explain: \"AND needs every condition to be true. The score is enough, but C2 is not \\\"Yes\\\", so IF returns the value_if_false.\" },\n      { id: \"q2\", question: \"Why do you end an IFS formula with TRUE,\\\"…\\\"?\", options: [\"To make it faster\", \"To give a result when none of the other tests is true\", \"To make the tests case-sensitive\", \"To convert text to numbers\"], answer: 1, explain: \"TRUE is always true, so it catches every remaining case. Without it, IFS returns #N/A when no test matches.\" },\n      { id: \"q3\", question: \"Which formula adds the amounts in C2:C100 for the Littoral region (A2:A100) and the product Rice (B2:B100)?\", options: [\"=SUMIF(A2:A100,\\\"Littoral\\\",C2:C100)\", \"=COUNTIFS(A2:A100,\\\"Littoral\\\",B2:B100,\\\"Rice\\\")\", \"=SUMIFS(A2:A100,\\\"Littoral\\\",B2:B100,\\\"Rice\\\")\", \"=SUMIFS(C2:C100,A2:A100,\\\"Littoral\\\",B2:B100,\\\"Rice\\\")\"], answer: 3, explain: \"SUMIFS starts with the range to add, followed by pairs of criteria range and criteria.\" },\n      { id: \"q4\", question: \"What does the fourth argument of =XLOOKUP(E2,A2:A50,C2:C50,\\\"Not found\\\") do?\", options: [\"Sets approximate match\", \"Returns \\\"Not found\\\" instead of #N/A when the code is missing\", \"Searches from the bottom\", \"Makes the lookup case-sensitive\"], answer: 1, explain: \"The optional if_not_found argument replaces the #N/A error with your own value.\" },\n      { id: \"q5\", question: \"Which lookup is correct for finding a tax rate from a table of lower income limits sorted in ascending order?\", options: [\"=VLOOKUP(B2,$A$2:$B$6,2,TRUE)\", \"=VLOOKUP(B2,$A$2:$B$6,2,FALSE)\", \"=MATCH(B2,$A$2:$A$6,0)\", \"=XLOOKUP(B2,$A$2:$A$6,$B$2:$B$6)\"], answer: 0, explain: \"Bands need approximate match. VLOOKUP with TRUE returns the band whose lower limit is the largest one not above the income.\" },\n      { id: \"q6\", question: \"In a PivotTable, which area creates a drop-down that limits the whole report, for example to one year?\", options: [\"Rows\", \"Columns\", \"Values\", \"Filters\"], answer: 3, explain: \"Filters sit above the PivotTable and apply to all of it. Slicers do the same job with buttons.\" },\n      { id: \"q7\", question: \"What does =PMT(15%/12,24,-1000000) calculate?\", options: [\"The total interest on the loan\", \"The monthly repayment of 1 000 000 FCFA over 24 months at 15% a year\", \"The amount you can borrow\", \"The yearly repayment over 24 years\"], answer: 1, explain: \"The rate is divided by 12 and nper is 24 months, so the result is the monthly payment. The minus sign makes it positive.\" },\n      { id: \"q8\", question: \"Which tool finds the loan amount that gives a monthly payment of exactly 80 000 FCFA?\", options: [\"Scenario Manager\", \"Data Validation\", \"Goal Seek\", \"Protect Sheet\"], answer: 2, explain: \"Goal Seek changes one input cell until a formula reaches the value you set.\" },\n    ],\n  },\n};\n","client/src/data/courses/mosp/m6.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// Module 6 — Microsoft PowerPoint: professional presentations.\n// Original Analytix Engineering material, aligned to exam MO-300 (Microsoft PowerPoint).\n\nconst MS = \"Microsoft Support\";\nconst LEARN = \"Microsoft Learn\";\n\nconst EXAM = { label: \"Exam MO-300: Microsoft PowerPoint\", url: \"https://learn.microsoft.com/en-us/credentials/certifications/exams/mo-300/\", source: LEARN };\nconst KEYS_CREATE = { label: \"Use keyboard shortcuts to create PowerPoint presentations\", url: \"https://support.microsoft.com/en-us/office/use-keyboard-shortcuts-to-create-powerpoint-presentations-ebb3d20e-dcd4-444f-a38e-bb5c5ed180f4\", source: MS };\nconst KEYS_DELIVER = { label: \"Use keyboard shortcuts to deliver PowerPoint presentations\", url: \"https://support.microsoft.com/en-us/accessibility/powerpoint/use-keyboard-shortcuts-to-deliver-powerpoint-presentations\", source: MS };\nconst ACCESSIBLE = { label: \"Make your PowerPoint presentations accessible to people with disabilities\", url: \"https://support.microsoft.com/en-us/office/make-your-powerpoint-presentations-accessible-to-people-with-disabilities-6f7772b2-2f33-4bd2-8ca7-dae3b2b3ef25\", source: MS };\nconst MASTER = { label: \"What is a slide master?\", url: \"https://support.microsoft.com/en-us/office/what-is-a-slide-master-b9abb2a0-7aef-4257-a14e-4329c904da54\", source: MS };\nconst COMPRESS = { label: \"Reduce the file size of a picture in Microsoft Office\", url: \"https://support.microsoft.com/en-us/office/reduce-the-file-size-of-your-images-in-microsoft-office-8db7211c-d958-457c-babd-194109eb9535\", source: MS };\n\nconst INTRO = { type: \"p\" as const, text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" };\n\nexport const m6: CourseModule = {\n  id: \"mosp-m6\",\n  number: 6,\n  title: \"Microsoft PowerPoint — Professional Presentations\",\n  summary: \"Design, Slide Master, visuals, animation and delivery.\",\n  hours: 10,\n  lessons: [\n    // ─────────────────────────────── LESSON 1 ───────────────────────────────\n    {\n      id: \"mosp-m6-l1\",\n      title: \"Designing clear slides\",\n      minutes: 25,\n      objectives: [\n        \"Build each slide around one message with a title that states the point\",\n        \"Use layouts, placeholders, Designer and the alignment tools to keep slides tidy\",\n        \"Make slides readable and accessible with contrast, font sizes and alt text\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"A slide is not a document. Your audience reads it in a few seconds while listening to you, often from the back of a hot meeting room with a tired projector. Clear slides carry one idea each, use few words and large text, and leave the details to you and to a handout.\" },\n        { type: \"h\", text: \"One slide, one message\" },\n        { type: \"list\", items: [\n          \"Decide the single point of the slide before you open PowerPoint. If you need two points, make two slides.\",\n          \"Write the title as a short sentence that states that point. The audience should get the message from the title alone.\",\n          \"Keep bullets short: three to five bullets, and no more than about ten words each. Write key words, not full paragraphs.\",\n          \"Say the detail out loud and put it in the speaker notes or in a handout, not on the slide.\",\n          \"Use a picture, a chart or a diagram when it shows the point faster than words.\",\n        ] },\n        { type: \"table\", head: [\"Topic title (weak)\", \"Message title (strong)\"], rows: [\n          [\"Sales Q1 2026\", \"Q1 sales rose 12% thanks to the Bafoussam branch\"],\n          [\"Training results\", \"85% of staff passed the Excel test after two weeks\"],\n          [\"Budget\", \"Fuel costs take a third of the 2026 transport budget\"],\n          [\"Survey\", \"Most clients want to pay by mobile money\"],\n        ] },\n        { type: \"callout\", tone: \"key\", title: \"Readable from the back of the room\", text: \"Use at least 32 pt for titles and 24 pt for body text; never go below 18 pt. Choose dark text on a light background, or light text on a dark background, and avoid red on green or text over busy photos. A plain sans-serif font such as Calibri, Aptos or Arial reads best on a projector.\" },\n        { type: \"h\", text: \"Layouts and placeholders\" },\n        { type: \"p\", text: \"Each new slide uses a **layout**, such as Title and Content, Two Content or Section Header. A layout contains **placeholders**, the dotted boxes that say \\\"Click to add title\\\" or \\\"Click to add text\\\". Typing in placeholders instead of drawing your own text boxes keeps fonts and positions consistent, lets the Outline view and screen readers find your titles, and allows the Slide Master to update every slide at once (Lesson 2).\" },\n        { type: \"path\", items: [\"Home\", \"Slides\", \"Layout\"], note: \"Changes the layout of the selected slides without losing their content.\" },\n        { type: \"path\", items: [\"Home\", \"Slides\", \"New Slide\"], note: \"Click the arrow under New Slide to choose the layout of the new slide.\" },\n        { type: \"h\", text: \"Designer and the alignment tools\" },\n        { type: \"path\", items: [\"Design\", \"Designer\", \"Designer\"], note: \"In recent versions Designer is also on the right end of the Home tab. It needs an internet connection.\" },\n        { type: \"p\", text: \"Designer suggests layouts for the pictures, icons and lists on the current slide. Pick a suggestion as a starting point, then check that the text is still large enough and that your title still states the point.\" },\n        { type: \"steps\", title: \"Line objects up exactly\", items: [\n          \"Select the objects to line up: click the first, then hold `Shift` and click the others.\",\n          \"Go to **Shape Format › Arrange › Align** (or **Picture Format** for pictures).\",\n          \"Choose an edge, for example **Align Top**, or **Align Middle** for a row of icons.\",\n          \"With three or more objects selected, choose **Distribute Horizontally** to make the gaps equal.\",\n          \"Press `Ctrl + G` to group them so they move together.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Smart guides\", text: \"When you drag an object, red dotted lines appear when it lines up with another object or with the centre of the slide. Release the mouse on the guide for a perfect alignment.\" },\n        { type: \"h\", text: \"Pictures, alt text and accessibility\" },\n        { type: \"steps\", title: \"Make the deck accessible\", items: [\n          \"Right-click each picture, chart or icon and choose **View Alt Text**. Describe what it shows in one sentence, or tick **Mark as decorative** for pure decoration.\",\n          \"Give every slide a title, even if you hide it on a picture slide. Screen readers use titles to navigate.\",\n          \"Go to **Review › Check Accessibility** and fix each error and warning listed in the pane.\",\n          \"Check the reading order of objects in the pane under **Reading Order** so a screen reader follows the logical order.\",\n        ] },\n        { type: \"path\", items: [\"Review\", \"Accessibility\", \"Check Accessibility\"] },\n        { type: \"slide\", id: \"mosp-m6-l1-slide\", title: \"Rewrite a crowded health briefing slide\", task: \"This slide will be projected at the regional health delegation in Bafoussam. Rewrite it with a title that **states the point** in 10 words or fewer, and **no more than 4 bullets** of 10 words or fewer.\",\n          slide: { title: \"Presentation of the situation concerning the results of the vaccination campaign carried out in the health district during the month of March 2026\", bullets: [\n            \"The campaign team visited a total of 42 villages in the district, including several villages that are very difficult to reach during the rainy season\",\n            \"A total of 18 450 children under five years old received the vaccine, which represents 92% of the target that was set by the delegation\",\n            \"In some areas the refrigerators for the vaccines stopped working because of power cuts that lasted several days\",\n            \"The teams think that the participation of community leaders and churches helped a lot to convince the parents\",\n            \"Two villages could not be reached because the bridge was damaged\",\n            \"We would like to request funding for solar refrigerators before the next campaign in September\",\n          ] },\n          rules: { maxBullets: 4, maxWords: 10, titleMaxWords: 10 },\n          hint: \"Try a title such as \\\"March campaign reached 92% of children under five\\\", then keep only coverage, the cold-chain problem and the funding request.\" },\n        { type: \"h\", text: \"Editing shortcuts that save time\" },\n        { type: \"shortcuts\", items: [\n          { keys: [\"Ctrl\", \"M\"], action: \"Insert a new slide\" },\n          { keys: [\"Ctrl\", \"D\"], action: \"Duplicate the selected object or slide\" },\n          { keys: [\"Ctrl\", \"G\"], action: \"Group the selected objects\" },\n          { keys: [\"Ctrl\", \"Shift\", \"G\"], action: \"Ungroup the selected group\" },\n          { keys: [\"Ctrl\", \"Shift\", \">\"], action: \"Increase the font size\" },\n          { keys: [\"Ctrl\", \"Shift\", \"<\"], action: \"Decrease the font size\" },\n          { keys: [\"Ctrl\", \"E\"], action: \"Centre the paragraph\" },\n          { keys: [\"Ctrl\", \"K\"], action: \"Insert a hyperlink\" },\n        ] },\n        { type: \"keys\", id: \"mosp-m6-l1-keys\", title: \"Practise the PowerPoint editing shortcuts\", items: [\n          { keys: [\"Ctrl\", \"M\"], action: \"Insert a new slide\" },\n          { keys: [\"Ctrl\", \"D\"], action: \"Duplicate the selected object or slide\" },\n          { keys: [\"Ctrl\", \"G\"], action: \"Group the selected objects\" },\n          { keys: [\"Ctrl\", \"Shift\", \"G\"], action: \"Ungroup the selected group\" },\n          { keys: [\"Ctrl\", \"Shift\", \">\"], action: \"Increase the font size\" },\n          { keys: [\"Ctrl\", \"Shift\", \"<\"], action: \"Decrease the font size\" },\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"Many meeting rooms in Yaoundé and Douala have bright windows and an old projector. Light grey text on white, or thin fonts, disappear on the wall. Before an important meeting, project one slide in the real room and read it from the last row.\" },\n        { type: \"check\", id: \"mosp-m6-l1-c1\", question: \"Which title works best for a slide showing that complaints fell after a new call centre opened in Douala?\", options: [\"Customer complaints\", \"Complaints fell by 40% after the Douala call centre opened\", \"Analysis of complaints data from January to June 2026 by region and type\", \"Slide 7\"], answer: 1, explain: \"A message title states the finding in a short sentence, so the audience knows what to look for before they read the chart. Topic titles and long descriptive titles leave the reader to guess.\" },\n        { type: \"task\", id: \"mosp-m6-l1-t1\", title: \"Practice\", items: [\n          \"Take a presentation you gave recently and rewrite every title as a sentence that states the point\",\n          \"Split any slide that has more than five bullets into two slides\",\n          \"Set titles to at least 32 pt and body text to at least 24 pt\",\n          \"Align and group one row of icons with the Align and Distribute commands\",\n          \"Add alt text to every picture and run Check Accessibility until it reports no errors\",\n        ] },\n        { type: \"links\", items: [ACCESSIBLE, KEYS_CREATE] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 2 ───────────────────────────────\n    {\n      id: \"mosp-m6-l2\",\n      title: \"Slide Master and branding\",\n      minutes: 25,\n      objectives: [\n        \"Edit the Slide Master and its layouts to change every slide at once\",\n        \"Add a logo, footer and slide numbers once and apply theme colours and fonts\",\n        \"Save and apply a corporate template (.potx) and reset slides that ignore the master\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"If you add your logo to 30 slides one by one, you will have 30 logos in slightly different places, and changing them later takes an afternoon. The **Slide Master** holds the design of the whole presentation: fonts, colours, background, logo, footer and the position of every placeholder. Change it once and every slide follows.\" },\n        { type: \"h\", text: \"What the Slide Master controls\" },\n        { type: \"table\", head: [\"Level\", \"Where you see it\", \"What a change affects\"], rows: [\n          [\"Slide Master\", \"The large thumbnail at the top of the left pane in Slide Master view\", \"Every layout and every slide: fonts, colours, background, logo\"],\n          [\"Layout\", \"The smaller thumbnails under the master\", \"Only the slides that use that layout, for example Title Slide or Two Content\"],\n          [\"Slide\", \"Normal view\", \"That slide only. Use it for content, not for design\"],\n        ] },\n        { type: \"path\", items: [\"View\", \"Master Views\", \"Slide Master\"], note: \"Click Close Master View on the Slide Master tab to return to Normal view.\" },\n        { type: \"h\", text: \"Add the logo and footer once\" },\n        { type: \"steps\", title: \"Put the logo on every slide\", items: [\n          \"Open **View › Slide Master** and click the large master thumbnail at the top.\",\n          \"Go to **Insert › Pictures › This Device** and choose the logo file, ideally a PNG with a transparent background.\",\n          \"Resize it and move it to a corner, for example top right. It now appears on every layout.\",\n          \"If the logo must not appear on the title slide, click the **Title Slide** layout and tick **Hide Background Graphics** on the Slide Master tab. (This also hides any other graphics from the master on that layout.)\",\n          \"Click **Close Master View**.\",\n        ] },\n        { type: \"path\", items: [\"Insert\", \"Text\", \"Header & Footer\"], note: \"Tick Slide number and Footer, type the footer text, tick Don't show on title slide, then click Apply to All.\" },\n        { type: \"callout\", tone: \"tip\", title: \"Footer text lives on the master\", text: \"The Header & Footer box switches the footer on; the Slide Master decides where it sits and how it looks. To change the footer font or position, edit the footer placeholder on the master, not on individual slides.\" },\n        { type: \"h\", text: \"Themes: colours and fonts\" },\n        { type: \"p\", text: \"A **theme** is a set of colours, fonts and effects. When you use theme colours (the top rows of any colour menu) instead of \\\"More Colors\\\", a change of theme recolours the whole deck, including charts and SmartArt.\" },\n        { type: \"path\", items: [\"Design\", \"Variants\", \"More\", \"Colors\", \"Customize Colors\"], note: \"Enter your organisation's brand colours, for example from the logo, and give the set a name.\" },\n        { type: \"path\", items: [\"Design\", \"Variants\", \"More\", \"Fonts\", \"Customize Fonts\"], note: \"Choose one heading font and one body font.\" },\n        { type: \"h\", text: \"Use a corporate template (.potx)\" },\n        { type: \"steps\", title: \"Create the template once\", items: [\n          \"Build the master: logo, colours, fonts, footer and the layouts your organisation needs.\",\n          \"Delete the example slides, or keep one example slide per layout as a guide.\",\n          \"Go to **File › Save As** and choose PowerPoint Template (*.potx) as the file type.\",\n          \"Share the .potx file with colleagues, for example in a shared OneDrive or SharePoint folder.\",\n        ] },\n        { type: \"path\", items: [\"Design\", \"Themes\", \"More\", \"Browse for Themes\"], note: \"Choose the .potx file to apply its master to an existing presentation.\" },\n        { type: \"h\", text: \"Fix slides that ignore the master\" },\n        { type: \"p\", text: \"Old slides often keep manual formatting: a title moved by hand, a different font typed over, or text in a text box instead of a placeholder. These slides do not follow the master.\" },\n        { type: \"steps\", title: \"Bring a slide back in line\", items: [\n          \"Select the slides in the thumbnail pane (`Ctrl + A` in the pane selects them all).\",\n          \"Go to **Home › Slides › Reset**. Placeholders return to the position and formatting of their layout; your text stays.\",\n          \"If a title is in a separate text box, cut the text, delete the box and paste the text into the title placeholder.\",\n          \"Check the layout with **Home › Slides › Layout** and choose the right one if needed.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"An NGO in Yaoundé receives slides from five project officers for its annual review with donors. The communications officer builds one .potx template with the NGO logo, colours and a bilingual footer (\\\"Rapport annuel 2026 / Annual Report 2026\\\"), applies it to every file with Browse for Themes, then runs Reset on the old slides. The final deck looks like one team made it.\" },\n        { type: \"form\", id: \"mosp-m6-l2-form\", title: \"Slide Master decisions\", task: \"A cooperative in Bafoussam is preparing a template for all its presentations. Choose the right action for each request.\",\n          hint: \"Design that must be the same on every slide belongs on the Slide Master; things that affect one kind of slide belong on a layout; old slides are brought back with Reset.\",\n          fields: [\n            { kind: \"select\", label: \"The logo must appear in the top-right corner of every slide.\", options: [\"Insert it on each slide\", \"Insert it on the Slide Master (top thumbnail)\", \"Insert it in the speaker notes\", \"Paste it in the footer text\"], answer: 1, explain: \"Objects on the master appear on every layout, and therefore on every slide.\" },\n            { kind: \"select\", label: \"Only section header slides need a dark green background.\", options: [\"Change the Slide Master background\", \"Change the background of the Section Header layout\", \"Apply a new theme\", \"Change each slide in Normal view\"], answer: 1, explain: \"A change on one layout affects only the slides that use that layout.\" },\n            { kind: \"select\", label: \"Slide numbers must appear on every slide except the title slide.\", options: [\"Insert › Header & Footer, tick Slide number and Don't show on title slide, Apply to All\", \"Type the number in a text box on each slide\", \"Home › Numbering\", \"View › Notes Page\"], answer: 0 },\n            { kind: \"select\", label: \"Colleagues must start every new presentation with this design.\", options: [\"Save as .pptx and ask them to copy slides\", \"Save as PowerPoint Template (.potx) and share it\", \"Export as PDF\", \"Save as PowerPoint Show (.ppsx)\"], answer: 1, explain: \"A .potx template opens as a new, untitled presentation, so nobody overwrites the original.\" },\n            { kind: \"select\", label: \"Three old slides have titles in the wrong place and the wrong font.\", options: [\"Delete and retype them\", \"Select them and use Home › Slides › Reset\", \"Change the theme\", \"Use Format Painter on each letter\"], answer: 1, explain: \"Reset returns placeholders to the layout's position and formatting without deleting the text.\" },\n            { kind: \"text\", label: \"What is the file extension of a PowerPoint template?\", accept: [\".potx\", \"potx\"], example: \".potx\", placeholder: \".…\", mono: true },\n          ] },\n        { type: \"check\", id: \"mosp-m6-l2-c1\", question: \"You changed the title font on the Slide Master, but slide 4 still shows the old font. What is the most likely cause?\", options: [\"The Slide Master only works after you save\", \"Slide 4 has manual formatting that overrides the master\", \"The font is not installed on the projector\", \"Slide Master changes apply only to new slides\"], answer: 1, explain: \"Manual formatting on a slide wins over the master. Select the slide and use Home › Slides › Reset to remove it.\" },\n        { type: \"task\", id: \"mosp-m6-l2-t1\", title: \"Practice\", items: [\n          \"Open View › Slide Master and add a logo to the master\",\n          \"Hide the logo on the Title Slide layout with Hide Background Graphics\",\n          \"Create a custom colour set from your organisation's brand colours\",\n          \"Add a footer and slide numbers that do not show on the title slide\",\n          \"Save the result as a .potx template and apply it to an older presentation, then Reset the slides\",\n        ] },\n        { type: \"links\", items: [MASTER, EXAM] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 3 ───────────────────────────────\n    {\n      id: \"mosp-m6-l3\",\n      title: \"Charts, SmartArt and media\",\n      minutes: 30,\n      objectives: [\n        \"Choose, insert and edit the chart that matches the message\",\n        \"Turn bullet lists into SmartArt and add icons, video and audio\",\n        \"Compress media and use animations and transitions sparingly\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Numbers and processes are easier to understand as pictures. A good chart shows one comparison; a SmartArt diagram shows steps or structure; a short video can replace a long explanation. Used badly, the same tools produce cluttered slides and heavy files that will not open on a colleague's laptop.\" },\n        { type: \"h\", text: \"Choose the chart from the message\" },\n        { type: \"table\", head: [\"Your message\", \"Chart to use\", \"Example\"], rows: [\n          [\"Compare items\", \"Bar or column chart\", \"Sales by branch: Douala, Yaoundé, Garoua\"],\n          [\"Show change over time\", \"Line chart\", \"Monthly cocoa deliveries over 12 months\"],\n          [\"Show parts of a whole (few parts)\", \"Pie or doughnut chart\", \"Share of the budget by item, 3 to 5 items\"],\n          [\"Show a relationship between two numbers\", \"Scatter chart\", \"Training hours and test scores\"],\n        ] },\n        { type: \"chart\", id: \"mosp-m6-l3-chart\", title: \"Cocoa delivered to the cooperative, January to June 2026\", unit: \"t\", kinds: [\"bar\", \"line\", \"pie\"], best: \"line\",\n          question: \"The manager wants to show whether deliveries are growing month after month. Which chart shows that best?\",\n          explain: \"A line joins the months in order, so the rise and the dip in April are visible at once. A pie treats the months as parts of a whole and hides the order of time.\",\n          data: [{ label: \"Jan\", value: 38 }, { label: \"Feb\", value: 42 }, { label: \"Mar\", value: 47 }, { label: \"Apr\", value: 41 }, { label: \"May\", value: 53 }, { label: \"Jun\", value: 58 }] },\n        { type: \"h\", text: \"Insert and edit a chart\" },\n        { type: \"path\", items: [\"Insert\", \"Illustrations\", \"Chart\"], note: \"Or click the chart icon in a content placeholder.\" },\n        { type: \"steps\", title: \"From data to a clean chart\", items: [\n          \"Choose the chart type and click OK. A small Excel sheet opens with example data.\",\n          \"Type or paste your data over the example. Drag the blue border so it covers only your rows and columns.\",\n          \"Close the sheet. To change the numbers later, select the chart and go to **Chart Design › Data › Edit Data**.\",\n          \"Use **Chart Elements** (the + button next to the chart) to add data labels and remove what you do not need, such as gridlines.\",\n          \"Write the finding in the slide title, for example \\\"Deliveries rose 50% since January\\\".\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Charts from Excel\", text: \"If the chart already exists in Excel, copy it and paste it into PowerPoint. Use the paste options to choose whether it takes the presentation's theme and whether it stays linked to the workbook. Module 8 covers linking in detail.\" },\n        { type: \"h\", text: \"Turn bullets into SmartArt\" },\n        { type: \"path\", items: [\"Home\", \"Paragraph\", \"Convert to SmartArt\"], note: \"Select the text placeholder first. More SmartArt Graphics shows every type.\" },\n        { type: \"table\", head: [\"SmartArt type\", \"Use it for\", \"Example\"], rows: [\n          [\"Process\", \"Steps in order\", \"Loan application: request, visit, committee, payment\"],\n          [\"Cycle\", \"Steps that repeat\", \"Plan, do, check, act\"],\n          [\"Hierarchy\", \"Reporting lines\", \"Organisation chart of a directorate\"],\n          [\"List\", \"Items of equal weight\", \"Three services of an SME\"],\n          [\"Relationship\", \"Overlap or balance\", \"Where two programmes share beneficiaries\"],\n        ] },\n        { type: \"h\", text: \"Icons, video and audio\" },\n        { type: \"path\", items: [\"Insert\", \"Illustrations\", \"Icons\"], note: \"Icons are vector images: they stay sharp at any size and you can recolour them with theme colours.\" },\n        { type: \"path\", items: [\"Insert\", \"Media\", \"Video\", \"This Device\"], note: \"Audio is on the same Media group: Insert › Media › Audio.\" },\n        { type: \"steps\", title: \"Keep the file light\", items: [\n          \"For pictures: select one, go to **Picture Format › Adjust › Compress Pictures**, untick \\\"Apply only to this picture\\\" and choose a lower resolution, for example 150 ppi.\",\n          \"For video and audio: go to **File › Info › Compress Media** and choose **Standard (480p)** for sharing or **HD (720p)** for projecting.\",\n          \"Save, then check the new file size in File Explorer.\",\n          \"Keep the original video files in a folder next to the presentation in case you need the full quality later.\",\n        ] },\n        { type: \"h\", text: \"Animations and transitions, used sparingly\" },\n        { type: \"table\", head: [\"Effect\", \"Where to find it\", \"Good use\"], rows: [\n          [\"Appear or Fade (entrance)\", \"Animations › Animation\", \"Show bullets or chart parts one at a time as you talk about them\"],\n          [\"Fade (transition)\", \"Transitions › Transition to This Slide\", \"A calm, consistent change between slides\"],\n          [\"Morph (transition)\", \"Transitions › Transition to This Slide\", \"Move or zoom an object smoothly from one slide to the next\"],\n          [\"Spin, Bounce, Flip\", \"Animations and Transitions\", \"Rarely at work: they distract from the message\"],\n        ] },\n        { type: \"steps\", title: \"Create a Morph effect\", items: [\n          \"Build the first slide, for example a map of Cameroon with a small label.\",\n          \"Duplicate the slide with `Ctrl + D` in the thumbnail pane.\",\n          \"On the second slide, move, resize or recolour the same objects, for example enlarge the Littoral region.\",\n          \"Select the second slide and choose **Transitions › Morph**. Play it with `Shift + F5`.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"In the workplace\", text: \"A 40 MB deck full of phone videos will not go through a ministry e-mail server and will stall on a slow connection in Garoua. Compress media before you send, share a OneDrive link instead of an attachment, and keep animations to Appear or Fade so the deck runs smoothly on an older laptop.\" },\n        { type: \"form\", id: \"mosp-m6-l3-form\", title: \"Choose the right visual and effect\", task: \"You are preparing a presentation for a microfinance institution in Douala. Choose the best option for each slide.\",\n          hint: \"Match the visual to the message: comparison, time, parts of a whole, or steps. For effects, prefer the simplest one that helps the audience follow.\",\n          fields: [\n            { kind: \"select\", label: \"Number of new accounts in each of four branches in 2026\", options: [\"Pie chart\", \"Bar chart\", \"Line chart\", \"SmartArt Cycle\"], answer: 1, explain: \"Comparing separate items is a job for bars: they share one baseline.\" },\n            { kind: \"select\", label: \"The five steps of a loan application, from request to payment\", options: [\"SmartArt Process\", \"SmartArt Hierarchy\", \"Scatter chart\", \"A table of 5 columns\"], answer: 0, explain: \"A Process diagram shows steps in order with arrows.\" },\n            { kind: \"select\", label: \"You want the three bullet points to show one at a time as you speak.\", options: [\"Bounce entrance animation\", \"Appear or Fade entrance animation, On Click\", \"Vortex transition\", \"Rehearse Timings\"], answer: 1, explain: \"Appear or Fade reveals each point without distracting from it.\" },\n            { kind: \"select\", label: \"The file is 65 MB because of two phone videos and must be e-mailed.\", options: [\"File › Info › Compress Media\", \"Save as .potx\", \"Delete the Slide Master\", \"Home › Reset\"], answer: 0, explain: \"Compress Media re-encodes the videos at a lower quality and makes the file much smaller.\" },\n            { kind: \"select\", label: \"A map should zoom smoothly into the Littoral region on the next slide.\", options: [\"Morph transition\", \"Fly In animation on every region\", \"Push transition\", \"Insert a video of a map\"], answer: 0, explain: \"Morph animates the difference between two slides that share the same objects.\" },\n            { kind: \"select\", label: \"The share of a 12 000 000 FCFA budget spent on salaries, rent and equipment\", options: [\"Line chart\", \"Pie chart\", \"Scatter chart\", \"SmartArt Hierarchy\"], answer: 1, explain: \"Three parts of one whole is a good use of a pie or doughnut chart.\" },\n          ] },\n        { type: \"check\", id: \"mosp-m6-l3-c1\", question: \"What must you do for the Morph transition to move a logo from the left of slide 5 to the right of slide 6?\", options: [\"Apply Morph to slide 5 and draw a motion path\", \"Have the same logo on both slides, placed differently, and apply Morph to slide 6\", \"Insert the logo as a video\", \"Apply the Fly In animation to both slides\"], answer: 1, explain: \"Morph works on the slide you arrive on. It finds the objects shared by the two slides and animates their change of position, size or colour.\" },\n        { type: \"task\", id: \"mosp-m6-l3-t1\", title: \"Practice\", items: [\n          \"Insert a column chart, replace the example data with sales for three branches and edit it with Edit Data\",\n          \"Change the slide title so it states what the chart shows\",\n          \"Convert a four-step bullet list into a SmartArt Process\",\n          \"Insert an icon, recolour it with a theme colour and add alt text\",\n          \"Insert a short video, compress the media and compare the file size before and after\",\n        ] },\n        { type: \"links\", items: [COMPRESS, EXAM] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 4 ───────────────────────────────\n    {\n      id: \"mosp-m6-l4\",\n      title: \"Rehearsing and delivering\",\n      minutes: 30,\n      objectives: [\n        \"Prepare speaker notes and rehearse with Presenter View and Rehearse Timings\",\n        \"Control a slide show with the keyboard and set up a projector correctly\",\n        \"Export the presentation as PDF, video or handouts and share it for co-authoring\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Good slides do not save an unprepared speaker. Rehearsing with your notes, knowing the slide show keys, and arriving with a backup copy make the difference between a calm presentation and ten minutes lost to a cable, a frozen laptop or a power cut.\" },\n        { type: \"h\", text: \"Speaker notes\" },\n        { type: \"path\", items: [\"View\", \"Show\", \"Notes\"], note: \"Or click Notes in the status bar. The notes pane opens under the slide.\" },\n        { type: \"p\", text: \"Write the details, figures and transitions you will say in the notes, not on the slide. Keep them short enough to read at a glance: key words and numbers, not a full speech.\" },\n        { type: \"h\", text: \"Presenter View and the projector\" },\n        { type: \"p\", text: \"Presenter View shows you the current slide, the next slide, your notes and a timer on the laptop screen, while the audience sees only the slide on the projector. It needs two screens set to **Extend**, not Duplicate.\" },\n        { type: \"steps\", title: \"Connect a laptop to a projector\", items: [\n          \"Connect the HDMI or VGA cable and switch on the projector before you start the slide show.\",\n          \"Press `Win + P` and choose **Extend**.\",\n          \"In PowerPoint, go to **Slide Show › Monitors**, tick **Use Presenter View** and set the Monitor to the projector (or leave Automatic).\",\n          \"Start the show with `F5`. If the screens are swapped, click **Display Settings › Swap Presenter View and Slide Show** at the top of Presenter View.\",\n        ] },\n        { type: \"path\", items: [\"Slide Show\", \"Monitors\", \"Use Presenter View\"] },\n        { type: \"h\", text: \"Rehearse Timings\" },\n        { type: \"path\", items: [\"Slide Show\", \"Set Up\", \"Rehearse Timings\"], note: \"A Recording toolbar shows the time on the current slide and the total.\" },\n        { type: \"p\", text: \"Go through the presentation as if the audience were there. At the end, PowerPoint shows the total time and asks whether to keep the timings. Keep them if the slides must advance on their own, for example on a stand at a trade fair; otherwise note the times and untick **Use Timings** in the Set Up group so you advance slides yourself.\" },\n        { type: \"h\", text: \"Slide Show keys\" },\n        { type: \"p\", text: \"The slide show keys are single keys or work only during a show, so the browser trainer cannot capture them. Learn them from this table and try them in PowerPoint.\" },\n        { type: \"table\", head: [\"Key\", \"What it does during a slide show\"], rows: [\n          [\"F5\", \"Start from the first slide\"],\n          [\"Shift + F5\", \"Start from the current slide\"],\n          [\"Alt + F5\", \"Start in Presenter View\"],\n          [\"N, Space, Right arrow or Page Down\", \"Next slide or next animation\"],\n          [\"P, Backspace, Left arrow or Page Up\", \"Previous slide or animation\"],\n          [\"Slide number + Enter\", \"Jump to that slide, for example 12 + Enter\"],\n          [\"B or full stop (.)\", \"Black screen; press again to return\"],\n          [\"W or comma (,)\", \"White screen; press again to return\"],\n          [\"Ctrl + S\", \"Show the list of all slides\"],\n          [\"Ctrl + L\", \"Laser pointer\"],\n          [\"Ctrl + P / E\", \"Pen for drawing on the slide / erase the drawings\"],\n          [\"Esc\", \"End the slide show\"],\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Use the black screen\", text: \"When the discussion moves away from the slides, press `B`. The audience looks at you instead of an old slide. Press `B` again to continue exactly where you were.\" },\n        { type: \"h\", text: \"Export, handouts and sharing\" },\n        { type: \"table\", head: [\"Output\", \"Where\", \"Use it when\"], rows: [\n          [\"PDF\", \"File › Export › Create PDF/XPS Document\", \"Sending the final deck to participants, or as a backup to project from any computer\"],\n          [\"Video (.mp4)\", \"File › Export › Create a Video\", \"Playing on a screen at a stand, or sharing on WhatsApp or a website\"],\n          [\"Printed handouts\", \"File › Print › Full Page Slides › Handouts\", \"Participants take notes; 3 slides per page leaves lines for writing\"],\n          [\"Shared link\", \"Share (top right)\", \"Colleagues edit the same deck at the same time (co-authoring)\"],\n        ] },\n        { type: \"path\", items: [\"File\", \"Export\", \"Create PDF/XPS Document\"] },\n        { type: \"path\", items: [\"File\", \"Print\", \"Full Page Slides\", \"3 Slides\"], note: \"Choose Handouts, 3 Slides to print lines for notes beside each slide.\" },\n        { type: \"p\", text: \"To co-author, save the presentation to OneDrive or SharePoint, click **Share** and invite colleagues with edit rights. Each person can work on different slides at the same time, and their initials appear on the slide they are editing.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"Plan for a power cut\", text: \"Power cuts and unfamiliar computers are part of presenting in Cameroon. Charge the laptop fully, bring your own HDMI adapter, and keep a PDF copy of the deck on a USB drive and in your e-mail. If the laptop fails, the PDF opens on any computer, and printed handouts let you continue even without a projector.\" },\n        { type: \"slide\", id: \"mosp-m6-l4-slide\", title: \"Tighten a closing slide\", task: \"This is the last slide of a budget presentation to the municipal council in Garoua. Rewrite it with a title of 8 words or fewer that **states the decision you ask for**, and **no more than 3 bullets** of 8 words or fewer.\",\n          slide: { title: \"Conclusion and summary of everything that was said during this presentation of the draft 2027 budget\", bullets: [\n            \"The draft budget for 2027 amounts to a total of 1 250 000 000 FCFA which is 6% more than 2026\",\n            \"Most of the increase is for road maintenance in the northern districts after the rainy season\",\n            \"Revenue from market fees is expected to grow if the new collection system with mobile money works\",\n            \"Salaries remain stable because there is no recruitment planned\",\n            \"We therefore ask the council to vote on the draft budget at the next session in December\",\n          ] },\n          rules: { maxBullets: 3, maxWords: 8, titleMaxWords: 8 },\n          hint: \"Start from the request: for example \\\"Please approve the 2027 budget in December\\\". Then keep the total, the main increase and the new revenue.\" },\n        { type: \"form\", id: \"mosp-m6-l4-form\", title: \"Delivery decisions\", task: \"You present a training report at a hotel in Yaoundé. Answer each question. Type keys as they appear on the keyboard, for example F5 or Shift + F5.\",\n          hint: \"Look again at the slide show keys table and at the export options.\",\n          fields: [\n            { kind: \"text\", label: \"Which key starts the slide show from the current slide?\", accept: [\"Shift+F5\", \"Maj+F5\"], example: \"Shift + F5\", placeholder: \"Key\", mono: true },\n            { kind: \"text\", label: \"A participant asks a question and you want the screen to go black. Which key do you press?\", accept: [\"B\", \".\"], example: \"B\", placeholder: \"Key\", mono: true },\n            { kind: \"text\", label: \"You want to jump straight to slide 14. What do you type?\", accept: [\"14+Enter\", \"14Enter\", \"14+Entrée\"], example: \"14 + Enter\", placeholder: \"…\", mono: true },\n            { kind: \"select\", label: \"The projector shows exactly what is on your laptop, including your notes. What must you change?\", options: [\"Win + P › Extend\", \"Win + P › Duplicate\", \"Turn off Presenter View\", \"Lower the screen resolution\"], answer: 0, explain: \"With Duplicate, both screens show the same image. Extend gives the projector its own screen, so Presenter View stays on the laptop.\" },\n            { kind: \"select\", label: \"The organisers want a copy that anyone can open without PowerPoint and that will not change.\", options: [\"Send the .pptx\", \"File › Export › Create PDF/XPS Document\", \"Save as .potx\", \"Share an editing link\"], answer: 1 },\n            { kind: \"select\", label: \"You want to know how long each slide takes before the real session.\", options: [\"Slide Show › Set Up › Rehearse Timings\", \"Transitions › Duration\", \"View › Notes Page\", \"Review › Check Accessibility\"], answer: 0, explain: \"Rehearse Timings records the time on each slide and the total.\" },\n          ] },\n        { type: \"check\", id: \"mosp-m6-l4-c1\", question: \"The electricity goes off ten minutes before your presentation and the venue computer restarts without PowerPoint. What prepared backup lets you continue fastest?\", options: [\"The .potx template on your laptop\", \"A PDF copy of the deck on a USB drive\", \"The speaker notes in your head\", \"A link to the presentation on OneDrive with no internet\"], answer: 1, explain: \"A PDF opens on almost any computer, even without PowerPoint or an internet connection, and keeps the layout exactly.\" },\n        { type: \"task\", id: \"mosp-m6-l4-t1\", title: \"Practice\", items: [\n          \"Write speaker notes of key words for every slide of a five-slide presentation\",\n          \"Run Rehearse Timings and note the total time\",\n          \"Connect to a second screen or projector, choose Extend and present in Presenter View\",\n          \"During the show, use B, a slide number + Enter and Esc\",\n          \"Export a PDF copy to a USB drive and print handouts with 3 slides per page\",\n        ] },\n        { type: \"links\", items: [KEYS_DELIVER, EXAM] },\n      ],\n    },\n    // ─────────────────────────────── PRACTICE ───────────────────────────────\n    {\n      id: \"mosp-m6-practice\",\n      title: \"Practice lab: professional presentations\",\n      minutes: 35,\n      objectives: [\n        \"Apply the rules of clear, accessible slides\",\n        \"Choose charts, SmartArt and media for a donor report\",\n        \"Fix branding and effects with the Slide Master, Reset and transitions\",\n        \"Plan a conference talk from rehearsal timings\",\n      ],\n      blocks: [\n        INTRO,\n        { type: \"h\", text: \"Exercise 1: A ministry briefing\" },\n        { type: \"form\", id: \"mosp-pr-m6-briefing\", level: \"beginner\", title: \"Check the slides of a ministry briefing\",\n          task: \"A directorate of a ministry in Yaoundé prepares a 10-minute briefing for the Minister's cabinet. Choose the best answer for each question about slide design.\",\n          hint: \"One message per slide, a title that states the point, short bullets, large text, strong contrast and alt text on every picture.\",\n          fields: [\n            { kind: \"select\", label: \"Which title is best for the slide on school enrolment?\", options: [\"Enrolment\", \"Enrolment statistics 2021–2026 by region, gender and level\", \"Girls' enrolment rose 9% in the Far North since 2021\", \"Slide 3: data\"], answer: 2, explain: \"A message title states the finding in one short sentence.\" },\n            { kind: \"select\", label: \"A slide has nine bullets of about twenty words each. What do you do?\", options: [\"Reduce the font to 14 pt so it fits\", \"Keep key words, move details to the notes and split it into two slides\", \"Add an animation to each bullet\", \"Change the background to black\"], answer: 1 },\n            { kind: \"select\", label: \"What is the smallest body text size you should use on a projected slide?\", options: [\"10 pt\", \"14 pt\", \"18 pt\", \"40 pt\"], answer: 2, explain: \"Aim for 24 pt or more; 18 pt is the minimum for text read from the back of the room.\" },\n            { kind: \"select\", label: \"Which colour combination reads best on an old projector?\", options: [\"Light grey text on white\", \"Dark blue text on white\", \"Red text on green\", \"Yellow text on a photo\"], answer: 1 },\n            { kind: \"select\", label: \"A colleague who uses a screen reader will receive the deck. What must every photo have?\", options: [\"A border\", \"Alt text\", \"An animation\", \"A caption in bold\"], answer: 1, explain: \"Alt text lets the screen reader describe the picture. Use Review › Check Accessibility to find pictures without it.\" },\n            { kind: \"select\", label: \"Four logos of partner institutions are placed unevenly across the slide. Which tool fixes the gaps?\", options: [\"Arrange › Align › Distribute Horizontally\", \"Designer only\", \"Crop\", \"Reset\"], answer: 0 },\n          ] },\n        { type: \"h\", text: \"Exercise 2: An NGO donor report\" },\n        { type: \"form\", id: \"mosp-pr-m6-donor\", level: \"intermediate\", title: \"Visuals for a donor report\",\n          task: \"An NGO working on clean water in the Adamaoua region reports to its donor. Choose the right visual or command for each slide, and type the menu paths where asked, with › or > between the parts.\",\n          hint: \"Comparison: bars. Time: line. Parts of one whole: pie. Steps: SmartArt Process. Reporting lines: SmartArt Hierarchy. Heavy files: Compress Media.\",\n          fields: [\n            { kind: \"select\", label: \"Boreholes drilled in each of five villages\", options: [\"Bar chart\", \"Line chart\", \"Pie chart\", \"SmartArt Cycle\"], answer: 0 },\n            { kind: \"select\", label: \"Litres of water distributed per month over two years\", options: [\"Pie chart\", \"Line chart\", \"SmartArt List\", \"Doughnut chart\"], answer: 1 },\n            { kind: \"select\", label: \"How the 45 000 000 FCFA grant was split between drilling, training and monitoring\", options: [\"Scatter chart\", \"Pie chart\", \"Line chart\", \"SmartArt Process\"], answer: 1, explain: \"Three parts that add up to one grant: a pie or doughnut works well.\" },\n            { kind: \"select\", label: \"The project team: coordinator, two engineers, four community officers\", options: [\"SmartArt Hierarchy\", \"SmartArt Cycle\", \"Bar chart\", \"A bulleted list of 7 items\"], answer: 0 },\n            { kind: \"text\", label: \"Which menu path turns a selected bullet list into a SmartArt diagram? (tab › group › command)\", pattern: \"^(home\\\\s*(›|>|/)\\\\s*paragraph\\\\s*(›|>|/)\\\\s*convert\\\\s+to\\\\s+smartart|accueil\\\\s*(›|>|/)\\\\s*paragraphe\\\\s*(›|>|/)\\\\s*convertir\\\\s+en\\\\s+(graphique\\\\s+)?smartart)$\", example: \"Home › Paragraph › Convert to SmartArt\", placeholder: \"Home › …\", explain: \"Select the text placeholder first; the gallery previews each layout.\" },\n            { kind: \"text\", label: \"The deck with three field videos is 80 MB. Which menu path makes the videos smaller? (tab › section › command)\", pattern: \"^(file\\\\s*(›|>|/)\\\\s*info\\\\s*(›|>|/)\\\\s*compress\\\\s+media|fichier\\\\s*(›|>|/)\\\\s*informations\\\\s*(›|>|/)\\\\s*compresser\\\\s+(le\\\\s+)?m[ée]dia)$\", example: \"File › Info › Compress Media\", placeholder: \"File › …\", explain: \"Choose Standard (480p) for sharing by e-mail, HD (720p) for projecting.\" },\n            { kind: \"select\", label: \"After inserting a chart, the donor's figures change. Where do you update them?\", options: [\"Delete and redraw the chart\", \"Chart Design › Data › Edit Data\", \"Insert › Table\", \"Home › Reset\"], answer: 1 },\n          ] },\n        { type: \"h\", text: \"Exercise 3: A sales pitch that must look on-brand\" },\n        { type: \"form\", id: \"mosp-pr-m6-pitch\", level: \"advanced\", title: \"Fix the branding and effects of a sales pitch\",\n          task: \"Kemba Solar SARL, an SME in Bafoussam that sells solar backup kits, merged slides from three salespeople into one pitch. Solve each problem with the most efficient method. Type shortcuts as keys joined with +.\",\n          hint: \"Think at the right level: master for every slide, layout for one kind of slide, Reset for slides with manual formatting. Keep effects simple, and remember that Morph goes on the second slide.\",\n          fields: [\n            { kind: \"select\", label: \"The logo is on some slides only and in different positions.\", options: [\"Copy it to each slide and align it by eye\", \"Delete the copies and put one logo on the Slide Master\", \"Put it in the footer text\", \"Add it with Designer\"], answer: 1, explain: \"One logo on the master appears in the same place on every slide.\" },\n            { kind: \"select\", label: \"After you apply the company template, six slides still show Times New Roman titles.\", options: [\"Select those slides and click Home › Slides › Reset\", \"Change the theme again\", \"Retype the titles\", \"Save as PDF\"], answer: 0, explain: \"The titles carry manual formatting. Reset brings them back to the layout's font and position.\" },\n            { kind: \"select\", label: \"One salesperson typed the titles in text boxes instead of title placeholders. What problem does that cause?\", options: [\"None\", \"The titles do not follow the master and are missing for screen readers and the Outline view\", \"The file cannot be saved\", \"The slides cannot be printed\"], answer: 1 },\n            { kind: \"select\", label: \"Every slide flies in with a different transition: Vortex, Curtains, Origami.\", options: [\"Keep them, they impress clients\", \"Select all slides and apply Fade, then Apply To All\", \"Remove the slides\", \"Add sounds to them\"], answer: 1, explain: \"One calm transition used everywhere looks professional and does not distract from the offer.\" },\n            { kind: \"select\", label: \"You want the kit photo to grow and slide to the right between slides 4 and 5. Which slide gets the Morph transition?\", options: [\"Slide 4\", \"Slide 5\", \"Both\", \"Neither: use a motion path\"], answer: 1, explain: \"A transition belongs to the slide you arrive on.\" },\n            { kind: \"text\", label: \"Which shortcut duplicates the selected slide in the thumbnail pane, so you can build the Morph pair?\", accept: [\"Ctrl+D\", \"Ctrl+Shift+D\"], example: \"Ctrl + D\", placeholder: \"Ctrl + …\", mono: true },\n            { kind: \"text\", label: \"Which shortcut groups the selected kit icons so they move together?\", accept: [\"Ctrl+G\"], example: \"Ctrl + G\", placeholder: \"Ctrl + …\", mono: true },\n            { kind: \"select\", label: \"Management wants every future pitch to start from this corrected design. How do you save it?\", options: [\"PowerPoint Presentation (.pptx)\", \"PowerPoint Template (.potx)\", \"PDF\", \"PowerPoint Show (.ppsx)\"], answer: 1 },\n          ] },\n        { type: \"h\", text: \"Exercise 4: Timing a conference talk\" },\n        { type: \"sheet\", id: \"mosp-pr-m6-timing\", level: \"expert\", title: \"Plan a 25-minute conference talk from rehearsal timings\",\n          task: \"You rehearsed a 25-minute talk for a business conference in Douala with Rehearse Timings. Column D holds the seconds recorded for each section; one section was not rehearsed yet. In **E2:E7**, convert seconds to minutes rounded to 1 decimal, but show the text `Not rehearsed` when D is empty. In **G2:G7**, show `Rehearse` if D is empty, `Cut` if the rehearsed minutes are more than the planned minutes (column C), otherwise `OK`. In **E8**, total the rehearsed minutes. In **B10**, count the sections marked `Cut`. In **B11**, estimate the length of the talk: rehearsed minutes plus the planned minutes of sections marked `Rehearse`. In **B12**, show `Over the slot` if B11 is greater than the slot in B9, otherwise `Within the slot`.\",\n          hint: \"E2: =IF(D2=\\\"\\\",\\\"Not rehearsed\\\",ROUND(D2/60,1)). G2 tests the empty cell first, then compares E2 with C2. SUM ignores text, so E8 is a plain SUM. B11 adds a SUMIF on column G.\",\n          data: [\n            [\"Section\", \"Slides\", \"Planned (min)\", \"Rehearsed (s)\", \"Rehearsed (min)\", \"Notes\", \"Status\"],\n            [\"Opening\", 2, 2, 110, null, \"Story of a power cut\", null],\n            [\"The problem\", 3, 4, 290, null, \"Cost of generators\", null],\n            [\"Our survey in Douala and Garoua\", 4, 5, 372, null, \"200 SMEs\", null],\n            [\"Results\", 5, 6, null, null, \"Not rehearsed yet\", null],\n            [\"Our solution\", 3, 4, 230, null, \"Solar backup kits\", null],\n            [\"Questions\", 1, 4, 180, null, \"\", null],\n            [\"Total\", null, null, null, null, null, null],\n            [\"Slot (min)\", 25, null, null, null, null, null],\n            [\"Sections to cut\", null, null, null, null, null, null],\n            [\"Estimated length (min)\", null, null, null, null, null, null],\n            [\"Verdict\", null, null, null, null, null, null],\n          ],\n          editable: [\"E2\", \"E3\", \"E4\", \"E5\", \"E6\", \"E7\", \"G2\", \"G3\", \"G4\", \"G5\", \"G6\", \"G7\", \"E8\", \"B10\", \"B11\", \"B12\"],\n          checks: [\n            { cell: \"E2\", equals: 1.8, tol: 0.001 },\n            { cell: \"E3\", equals: 4.8, tol: 0.001 },\n            { cell: \"E4\", equals: 6.2, tol: 0.001 },\n            { cell: \"E5\", equals: \"Not rehearsed\" },\n            { cell: \"E6\", equals: 3.8, tol: 0.001 },\n            { cell: \"E7\", equals: 3, tol: 0.001 },\n            { cell: \"G2\", equals: \"OK\" },\n            { cell: \"G3\", equals: \"Cut\" },\n            { cell: \"G4\", equals: \"Cut\" },\n            { cell: \"G5\", equals: \"Rehearse\" },\n            { cell: \"G6\", equals: \"OK\" },\n            { cell: \"G7\", equals: \"OK\" },\n            { cell: \"E8\", equals: 19.6, tol: 0.001 },\n            { cell: \"B10\", equals: 2 },\n            { cell: \"B11\", equals: 25.6, tol: 0.001 },\n            { cell: \"B12\", equals: \"Over the slot\" },\n          ],\n          solution: {\n            E2: \"=IF(D2=\\\"\\\",\\\"Not rehearsed\\\",ROUND(D2/60,1))\",\n            E3: \"=IF(D3=\\\"\\\",\\\"Not rehearsed\\\",ROUND(D3/60,1))\",\n            E4: \"=IF(D4=\\\"\\\",\\\"Not rehearsed\\\",ROUND(D4/60,1))\",\n            E5: \"=IF(D5=\\\"\\\",\\\"Not rehearsed\\\",ROUND(D5/60,1))\",\n            E6: \"=IF(D6=\\\"\\\",\\\"Not rehearsed\\\",ROUND(D6/60,1))\",\n            E7: \"=IF(D7=\\\"\\\",\\\"Not rehearsed\\\",ROUND(D7/60,1))\",\n            G2: \"=IF(D2=\\\"\\\",\\\"Rehearse\\\",IF(E2>C2,\\\"Cut\\\",\\\"OK\\\"))\",\n            G3: \"=IF(D3=\\\"\\\",\\\"Rehearse\\\",IF(E3>C3,\\\"Cut\\\",\\\"OK\\\"))\",\n            G4: \"=IF(D4=\\\"\\\",\\\"Rehearse\\\",IF(E4>C4,\\\"Cut\\\",\\\"OK\\\"))\",\n            G5: \"=IF(D5=\\\"\\\",\\\"Rehearse\\\",IF(E5>C5,\\\"Cut\\\",\\\"OK\\\"))\",\n            G6: \"=IF(D6=\\\"\\\",\\\"Rehearse\\\",IF(E6>C6,\\\"Cut\\\",\\\"OK\\\"))\",\n            G7: \"=IF(D7=\\\"\\\",\\\"Rehearse\\\",IF(E7>C7,\\\"Cut\\\",\\\"OK\\\"))\",\n            E8: \"=SUM(E2:E7)\",\n            B10: \"=COUNTIF(G2:G7,\\\"Cut\\\")\",\n            B11: \"=E8+SUMIF(G2:G7,\\\"Rehearse\\\",C2:C7)\",\n            B12: \"=IF(B11>B9,\\\"Over the slot\\\",\\\"Within the slot\\\")\",\n          } },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"mosp-m6-quiz\",\n    title: \"Module 6 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"Which slide title follows the \\\"one message\\\" rule?\", options: [\"Quarterly results\", \"Q3 revenue beat the target by 8%\", \"Results, analysis, comments and next steps\", \"Data\"], answer: 1, explain: \"A message title states the point in a short sentence. The others only name a topic.\" },\n      { id: \"q2\", question: \"Where do you add a logo so that it appears on every slide?\", options: [\"Insert › Header & Footer\", \"Design › Designer\", \"On each slide in Normal view\", \"On the Slide Master in View › Slide Master\"], answer: 3, explain: \"Objects placed on the master appear on every layout, so on every slide.\" },\n      { id: \"q3\", question: \"Which command brings a slide's placeholders back to the position and formatting of its layout?\", options: [\"Home › Slides › Reset\", \"Design › Format Background\", \"Review › Compare\", \"File › Info › Compress Media\"], answer: 0, explain: \"Reset removes manual formatting from placeholders but keeps your text.\" },\n      { id: \"q4\", question: \"Which file type is a PowerPoint template?\", options: [\".pptx\", \".ppsx\", \".potx\", \".pdf\"], answer: 2, explain: \"A .potx opens as a new untitled presentation built on the template's master.\" },\n      { id: \"q5\", question: \"Which chart best shows monthly sales over a year?\", options: [\"Pie chart\", \"Line chart\", \"SmartArt Hierarchy\", \"Doughnut chart\"], answer: 1, explain: \"A line shows the order of time and the trend between months.\" },\n      { id: \"q6\", question: \"During a slide show, what does pressing B do?\", options: [\"Shows a black screen until you press B again\", \"Goes back one slide\", \"Makes the text bold\", \"Opens the list of slides\"], answer: 0, explain: \"B (or the full stop) blacks out the screen so the audience focuses on you; press it again to return.\" },\n      { id: \"q7\", question: \"Presenter View is not showing on your laptop: the projector shows the same image. What is the fix?\", options: [\"Press Ctrl + M\", \"Choose Duplicate with Win + P\", \"Choose Extend with Win + P\", \"Save as PDF\"], answer: 2, explain: \"Presenter View needs two separate screens, which is what Extend provides.\" },\n      { id: \"q8\", question: \"Which is the best backup against a power cut or a venue computer without PowerPoint?\", options: [\"A .potx template\", \"A PDF copy on a USB drive\", \"The Rehearse Timings file\", \"A higher-resolution video\"], answer: 1, explain: \"A PDF opens on almost any computer and keeps the exact layout of your slides.\" },\n    ],\n  },\n};\n","client/src/data/courses/mosp/m7.ts":"import type { CourseModule } from \"../../../lms/types\";\n\n// Module 7 — Microsoft Outlook: professional communication and organisation.\n// Menu paths follow classic Outlook for Windows (Microsoft 365); differences in new Outlook are noted.\n\nconst MS = \"Microsoft Support\";\nconst LEARN = \"Microsoft Learn\";\n\nconst MO400 = { label: \"Exam MO-400: Microsoft Outlook (Office 2019)\", url: \"https://learn.microsoft.com/en-us/credentials/certifications/exams/mo-400/\", source: LEARN };\nconst SHORTCUTS = { label: \"Keyboard shortcuts for Outlook\", url: \"https://support.microsoft.com/en-us/accessibility/outlook/keyboard-shortcuts-for-outlook\", source: MS };\n\nconst RECIP = [\"To\", \"Cc\", \"Bcc\", \"Do not include\"];\nconst FOURD = [\"Delete\", \"Do it now\", \"Delegate (forward)\", \"Defer (flag with a date)\", \"File (move to a folder)\"];\n\nexport const m7: CourseModule = {\n  id: \"mosp-m7\",\n  number: 7,\n  title: \"Microsoft Outlook — Professional Communication & Organization\",\n  summary: \"E-mail, calendar, contacts, tasks and inbox management.\",\n  hours: 8,\n  lessons: [\n    // ─────────────────────────── LESSON 1 ───────────────────────────\n    {\n      id: \"mosp-m7-l1\",\n      title: \"Professional e-mail: write, address and send with care\",\n      minutes: 28,\n      objectives: [\n        \"Address messages correctly with To, Cc and Bcc, and protect recipients' privacy\",\n        \"Structure an e-mail so the reader sees the purpose, the action and the deadline at once\",\n        \"Use replies, forwarding, signatures, delayed delivery and recall with their limits in mind\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"E-mail is still the official channel of most offices: requests, approvals, invoices and invitations travel through it, and messages are kept as records. A clear, well-addressed e-mail gets a faster answer and protects you if a decision is questioned later.\" },\n        { type: \"callout\", tone: \"key\", title: \"Classic Outlook and new Outlook\", text: \"Microsoft is moving Windows users from classic Outlook to new Outlook, which looks like Outlook on the web. The features in this module exist in both, but some menu names and positions differ. The paths shown here are for classic Outlook; if you see a Settings gear instead of a File tab, you are in new Outlook.\" },\n        { type: \"h\", text: \"To, Cc and Bcc\" },\n        { type: \"table\", head: [\"Field\", \"Who goes there\", \"What it tells the reader\"], rows: [\n          [\"To\", \"The people who must act or answer\", \"\\\"This is for you, I am waiting for your reply.\\\"\"],\n          [\"Cc\", \"People who need to be informed, such as your manager\", \"\\\"For information, no action expected.\\\"\"],\n          [\"Bcc\", \"Recipients who must not see each other's addresses\", \"Nobody sees the Bcc list. Use it for group mailings to people outside your organisation\"],\n        ] },\n        { type: \"path\", items: [\"Options\", \"Show Fields\", \"Bcc\"], note: \"In a new message window. The Bcc line then stays visible for future messages.\" },\n        { type: \"callout\", tone: \"warning\", title: \"Group mails and privacy\", text: \"Sending one message to 150 clients with all addresses in To or Cc exposes everyone's address to everyone, and invites endless Reply All chains. Put your own address in To and the recipients in Bcc, or use a mail merge. Bcc recipients are never included when someone clicks Reply All.\" },\n        { type: \"h\", text: \"A structure the reader can scan\" },\n        { type: \"list\", ordered: true, items: [\n          \"**Subject line**: topic, action and date, for example \\\"Q3 report Garoua branch: figures needed by Fri 16 Oct\\\".\",\n          \"**Greeting**: \\\"Dear Mrs Mballa,\\\" for a first contact; \\\"Hello Paul,\\\" with colleagues you know.\",\n          \"**Purpose first**: one sentence saying why you write.\",\n          \"**Action and deadline**: what you need, from whom, by when. Bold the deadline.\",\n          \"**Details**: short paragraphs or a bulleted list. Attach or link the files you mention.\",\n          \"**Closing and signature**: name, title, organisation, phone number.\",\n        ] },\n        { type: \"table\", head: [\"Weak subject\", \"Clear subject\"], rows: [\n          [\"Urgent!!!\", \"Mission order Kribi: signature needed today before 15:00\"],\n          [\"Document\", \"Draft MoU with CAMWATER, v2 for your comments by 20 Oct\"],\n          [\"RE: RE: RE: question\", \"Training room booking 5 Nov: confirmed\"],\n          [\"(no subject)\", \"Invoice AE-2026-118, 350 000 FCFA: payment reminder\"],\n        ] },\n        { type: \"doc\", id: \"mosp-m7-l1-doc\", title: \"Format an e-mail body\", task: \"This e-mail asks four branch heads for their monthly figures. Make the deadline sentence **bold**, turn the three items to send into a **bulleted list**, and make the name of the shared folder **bold**.\",\n          hint: \"Select the whole deadline sentence and click Bold. Select the three item lines together before clicking Bullets.\",\n          html: \"<p>Dear branch heads,</p><p>To prepare the regional report for the Director General, please send me your October figures.</p><p>Deadline: Wednesday 4 November 2026 at 12:00.</p><p>Please send:</p><p>the sales table for October</p><p>the list of unpaid invoices</p><p>the fuel and generator expenses</p><p>Save the files in the shared folder Rapports-Octobre-2026 on OneDrive rather than attaching them.</p><p>Thank you,</p><p>Nadine Ekambi, Regional Coordinator</p>\",\n          checks: [\n            { kind: \"bold\", text: \"Deadline: Wednesday 4 November 2026\" },\n            { kind: \"list\", ordered: false, min: 3 },\n            { kind: \"bold\", text: \"Rapports-Octobre-2026\" },\n          ] },\n        { type: \"h\", text: \"Attachments or OneDrive links?\" },\n        { type: \"table\", head: [\"Send an attachment when…\", \"Share a OneDrive link when…\"], rows: [\n          [\"The file is final, such as a signed PDF or an invoice\", \"Several people must edit the same file\"],\n          [\"The recipient is outside your organisation and may not open links\", \"The file is large: mail servers often reject messages over 20–25 MB\"],\n          [\"You need a record of exactly what was sent\", \"You want to update the file after sending, or remove access later\"],\n        ] },\n        { type: \"h\", text: \"Reply, Reply All and Forward\" },\n        { type: \"shortcuts\", items: [\n          { keys: [\"Ctrl\", \"R\"], action: \"Reply to the sender only\" },\n          { keys: [\"Ctrl\", \"Shift\", \"R\"], action: \"Reply All\" },\n          { keys: [\"Ctrl\", \"F\"], action: \"Forward (in Outlook, not Find)\" },\n          { keys: [\"Ctrl\", \"Enter\"], action: \"Send the message (classic Outlook asks to confirm the first time)\" },\n          { keys: [\"Ctrl\", \"K\"], action: \"Check names against the address book\" },\n        ] },\n        { type: \"keys\", id: \"mosp-m7-l1-keys\", title: \"Practise the message shortcuts\", items: [\n          { keys: [\"Ctrl\", \"R\"], action: \"Reply to the sender only\" },\n          { keys: [\"Ctrl\", \"F\"], action: \"Forward the message\" },\n          { keys: [\"Ctrl\", \"Enter\"], action: \"Send the message\" },\n          { keys: [\"Ctrl\", \"K\"], action: \"Check names\" },\n        ] },\n        { type: \"p\", text: \"Use Reply All only when every person on the list needs your answer. \\\"Thank you\\\" to 40 people is noise. When you forward a long thread, add two lines on top explaining what you want from the new reader.\" },\n        { type: \"h\", text: \"Signatures, delayed delivery and recall\" },\n        { type: \"path\", items: [\"File\", \"Options\", \"Mail\", \"Signatures\"], note: \"In new Outlook: Settings › Accounts › Signatures. Create one full signature for new messages and a short one for replies.\" },\n        { type: \"path\", items: [\"Options\", \"Delay Delivery\"], note: \"In a message window. Set \\\"Do not deliver before\\\" a date and time. In new Outlook, use the arrow next to Send › Schedule send.\" },\n        { type: \"list\", items: [\n          \"**Recall** works only between Microsoft 365 work accounts in the same organisation, and only if the recipient has not opened the message. Never count on it.\",\n          \"A better safety net: in new Outlook, turn on **Undo send** (Settings › Mail › Compose and reply) to get a few seconds to cancel.\",\n          \"Read the message aloud before sending anything sensitive, and add the recipients last so it cannot leave by accident.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"Bilingual e-mails\", text: \"When writing to a ministry or partner that works in both official languages, put the French and English versions one after the other, separated by a line, rather than mixing sentences. Start with the language of the recipient. A subject line such as \\\"Invitation atelier / Workshop invitation: Bafoussam, 12 Nov\\\" shows both at once.\" },\n        { type: \"form\", id: \"mosp-m7-l1-form\", title: \"Address and title the message\", task: \"The Human Resources office of a Yaoundé SME is organising a first-aid training. Decide where each person goes, then choose and write clear subject lines.\",\n          hint: \"To = must act; Cc = informed; Bcc = must not see the other addresses. A good subject names the topic, the action and the date.\",\n          fields: [\n            { kind: \"select\", label: \"The 12 staff members who must confirm attendance\", options: RECIP, answer: 0 },\n            { kind: \"select\", label: \"Your manager, who approved the budget and only needs to follow\", options: RECIP, answer: 1 },\n            { kind: \"select\", label: \"The external trainer, who should not receive the staff members' addresses in a later reminder sent to the whole list\", options: RECIP, answer: 2, explain: \"Bcc hides the addresses from each other. The trainer can still receive the reminder.\" },\n            { kind: \"select\", label: \"A colleague on leave who has nothing to do with the training\", options: RECIP, answer: 3 },\n            { kind: \"select\", label: \"Which subject line is best?\", options: [\"Training\", \"URGENT PLEASE READ\", \"First-aid training 12 Nov: confirm attendance by 5 Nov\", \"Hello everyone\"], answer: 2, explain: \"It gives the topic, the action expected and the deadline.\" },\n            { kind: \"text\", label: \"Rewrite the subject \\\"Urgent!!!\\\" for this e-mail: you need the Q3 activity report of the Bafoussam branch by Friday 16 October.\", pattern: \"^(?!.*!!)(?=.*(report|rapport))(?=.*(q3|t3|third quarter|3rd quarter))(?=.*(16|friday|fri)).{15,100}$\", example: \"Q3 activity report Bafoussam: needed by Fri 16 Oct\", placeholder: \"Subject\", explain: \"Name the document, the branch and the deadline. Exclamation marks do not make a message more urgent.\" },\n          ] },\n        { type: \"check\", id: \"mosp-m7-l1-c1\", question: \"You send an invitation to 80 members of an association who do not know each other. Where do you put their addresses?\", options: [\"In To, so everyone feels invited\", \"In Cc\", \"In Bcc, with your own address in To\", \"Half in To and half in Cc\"], answer: 2, explain: \"Bcc keeps each member's address private and prevents Reply All chains to 80 people. Your own address in To gives the message a visible recipient.\" },\n        { type: \"task\", id: \"mosp-m7-l1-t1\", title: \"Practice\", items: [\n          \"Create a full signature and a short reply signature in Outlook\",\n          \"Show the Bcc field in a new message window\",\n          \"Rewrite the subject lines of three e-mails you sent last week using topic, action and date\",\n          \"Schedule a test message to yourself with Delay Delivery for 10 minutes later\",\n          \"Send a large file as a OneDrive link instead of an attachment\",\n        ] },\n        { type: \"links\", items: [\n          SHORTCUTS,\n          { label: \"How to recall an email in Outlook\", url: \"https://support.microsoft.com/en-us/office/recall-or-replace-an-email-message-that-you-sent-35027f88-d655-4554-b4f8-6c0729a723a0\", source: MS },\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 2 ───────────────────────────\n    {\n      id: \"mosp-m7-l2\",\n      title: \"Inbox rules and folders: keep 100+ e-mails a day under control\",\n      minutes: 28,\n      objectives: [\n        \"Organise the mailbox with a simple folder structure, categories and flags\",\n        \"Automate sorting with rules, Quick Steps and Focused Inbox\",\n        \"Find any message in seconds with search operators\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"When 100 or more messages arrive every day, reading them in order no longer works. Professionals decide once what happens to each message, let Outlook sort the routine ones automatically, and use search instead of scrolling.\" },\n        { type: \"h\", text: \"Decide once: the four Ds\" },\n        { type: \"table\", head: [\"Decision\", \"When\", \"In Outlook\"], rows: [\n          [\"Delete\", \"No value, or already stored elsewhere\", \"Delete, or Archive if you may need it\"],\n          [\"Do\", \"Takes less than two minutes\", \"Answer now, then file\"],\n          [\"Delegate\", \"Someone else should handle it\", \"Forward with a clear request\"],\n          [\"Defer\", \"Takes longer and has a deadline\", \"Flag with a date, or turn it into a task or calendar slot\"],\n        ] },\n        { type: \"h\", text: \"A folder structure that stays small\" },\n        { type: \"p\", text: \"Create a few broad folders, not one per person. Outlook search is fast, so deep folder trees waste more time than they save. A good start: Inbox, Action, Waiting for, Reference, and one folder per major project or client.\" },\n        { type: \"shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Shift\", \"E\"], action: \"Create a new folder\" },\n          { keys: [\"Ctrl\", \"Shift\", \"V\"], action: \"Move the selected message to a folder\" },\n          { keys: [\"Ctrl\", \"Shift\", \"G\"], action: \"Flag for follow-up with a custom date\" },\n          { keys: [\"Ctrl\", \"U\"], action: \"Mark as unread\" },\n          { keys: [\"Ctrl\", \"E\"], action: \"Go to the search box\" },\n          { keys: [\"Ctrl\", \"D\"], action: \"Delete the selected message\" },\n        ] },\n        { type: \"h\", text: \"Focused Inbox, categories and flags\" },\n        { type: \"path\", items: [\"View\", \"Show Focused Inbox\"], note: \"Outlook splits the Inbox into Focused and Other. Move a message to Focused once and future messages from that sender follow.\" },\n        { type: \"list\", items: [\n          \"**Categories** are coloured labels. A message can have several, for example \\\"Budget 2027\\\" and \\\"Waiting for\\\". Rename them in Home › Tags › Categorize › All Categories.\",\n          \"**Flags** add a due date: Today, Tomorrow, This Week, Next Week or Custom. Flagged messages appear in your task list (Lesson 4).\",\n          \"**Archive** moves a message out of the Inbox without deleting it. Use it for everything finished that you might need later.\",\n        ] },\n        { type: \"h\", text: \"Rules: let Outlook sort for you\" },\n        { type: \"p\", text: \"A rule has three parts: **conditions** (which messages), **actions** (what to do with them) and optional **exceptions** (which messages to leave alone). Most rules on messages you receive run on the server, so they work even when Outlook is closed on a Microsoft 365 account.\" },\n        { type: \"path\", items: [\"Home\", \"Rules\", \"Manage Rules & Alerts\", \"New Rule\"], note: \"Faster: right-click a message › Rules › Create Rule. In new Outlook: Settings › Mail › Rules.\" },\n        { type: \"steps\", title: \"Create a rule with the Rules Wizard\", items: [\n          \"Start from a blank rule: **Apply rule on messages I receive**.\",\n          \"Tick the conditions, for example **from people or public group** and **with specific words in the subject**. Click each underlined value to fill it.\",\n          \"Tick the actions, for example **move it to the specified folder** and **assign it to the category**.\",\n          \"Add exceptions if needed, for example **except if it is marked as importance** High.\",\n          \"Name the rule, tick **Run this rule now on messages already in Inbox**, and click Finish.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Quick Steps for one-click routines\", text: \"A Quick Step groups several actions into one button, for example \\\"mark as read, categorise Finance and move to Invoices\\\". Create them in Home › Quick Steps › Create New. Rules act on arrival; Quick Steps act when you click.\" },\n        { type: \"h\", text: \"Clean up and search\" },\n        { type: \"path\", items: [\"Home\", \"Clean Up\", \"Clean Up Conversation\"], note: \"Removes messages whose full text is already quoted in a later reply. New Outlook and Outlook on the web offer Sweep to delete or move everything from one sender.\" },\n        { type: \"table\", head: [\"Type in the search box\", \"Finds\"], rows: [\n          [\"`from:Ngono`\", \"Messages sent by anyone called Ngono\"],\n          [\"`subject:budget`\", \"Messages with \\\"budget\\\" in the subject\"],\n          [\"`hasattachments:yes`\", \"Messages with attachments\"],\n          [\"`received:yesterday`\", \"Messages received yesterday (also: this week, last month)\"],\n          [\"`\\\"mission order\\\"`\", \"The exact phrase, not the two words separately\"],\n          [\"`from:Ngono subject:budget`\", \"Both conditions at once; use OR in capitals for either\"],\n        ] },\n        { type: \"p\", text: \"The Search tab that opens when you click the search box builds these operators for you, in the language of your Outlook. If your Outlook is in French, use its buttons once to see the exact words it expects.\" },\n        { type: \"form\", id: \"mosp-m7-l2-form\", title: \"Build a rule and search the mailbox\", task: \"Aïcha works at the Ministry of Trade in Yaoundé. Tax notices from the Direction Générale des Impôts (address avis@dgi.example.cm) arrive every day and bury her other mail. Build the rule, then write the searches she needs.\",\n          hint: \"Conditions select the messages, actions do something to them, exceptions protect some of them. Search operators are written as name, colon, value, with no space after the colon.\",\n          fields: [\n            { kind: \"select\", label: \"Condition that selects the tax notices\", options: [\"from people or public group: avis@dgi.example.cm\", \"sent only to me\", \"marked as importance Low\", \"with specific words in the body: Dear\"], answer: 0 },\n            { kind: \"select\", label: \"Action that gets them out of the Inbox without losing them\", options: [\"delete it\", \"move it to the specified folder: Impôts\", \"forward it to all staff\", \"print it\"], answer: 1 },\n            { kind: \"select\", label: \"She still wants to see urgent notices in the Inbox. Which exception?\", options: [\"except if it has an attachment\", \"except if it is marked as importance High\", \"except if sent only to me\", \"No exception is possible\"], answer: 1, explain: \"Messages marked High importance stay in the Inbox; all the others go to the folder.\" },\n            { kind: \"select\", label: \"The Inbox already holds 300 old notices. What should she tick on the last page of the wizard?\", options: [\"Turn on this rule\", \"Run this rule now on messages already in Inbox\", \"Create this rule on all accounts\", \"Stop processing more rules\"], answer: 1 },\n            { kind: \"text\", label: \"Search: every message sent by Mr Fouda\", pattern: \"^from:\\\\s*\\\"?[a-z.@ ]*fouda[a-z.@ ]*\\\"?$\", example: \"from:Fouda\", placeholder: \"Search\", mono: true },\n            { kind: \"text\", label: \"Search: messages with \\\"tender\\\" in the subject\", pattern: \"^subject:\\\\s*\\\"?tender\\\"?$\", example: \"subject:tender\", placeholder: \"Search\", mono: true },\n            { kind: \"text\", label: \"Search: messages from Fouda that have an attachment\", pattern: \"^(?=.*from:\\\\s*\\\"?[a-z.@]*fouda)(?=.*hasattachments?:\\\\s*(yes|true)).*$\", example: \"from:Fouda hasattachments:yes\", placeholder: \"Search\", mono: true, explain: \"Two operators separated by a space must both be true.\" },\n          ] },\n        { type: \"keys\", id: \"mosp-m7-l2-keys\", title: \"Practise the triage shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Shift\", \"V\"], action: \"Move the message to a folder\" },\n          { keys: [\"Ctrl\", \"Shift\", \"G\"], action: \"Flag for follow-up\" },\n          { keys: [\"Ctrl\", \"U\"], action: \"Mark as unread\" },\n          { keys: [\"Ctrl\", \"E\"], action: \"Go to the search box\" },\n          { keys: [\"Ctrl\", \"Shift\", \"E\"], action: \"Create a new folder\" },\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"Mobile money and bank notifications\", text: \"Automatic notifications from your bank, mobile money platform or ERP can reach hundreds a week. One rule that moves them to a \\\"Notifications\\\" folder, with an exception for messages containing \\\"failed\\\" or \\\"échec\\\", keeps the Inbox for people while still showing the alerts that matter.\" },\n        { type: \"check\", id: \"mosp-m7-l2-c1\", question: \"You want every message from the finance team to be marked as read, categorised \\\"Finance\\\" and moved to a folder, but only when you decide. What should you create?\", options: [\"A rule\", \"A Quick Step\", \"A search folder\", \"A contact group\"], answer: 1, explain: \"A Quick Step runs several actions when you click it. A rule would act automatically on every message as it arrives.\" },\n        { type: \"task\", id: \"mosp-m7-l2-t1\", title: \"Practice\", items: [\n          \"Create four folders: Action, Waiting for, Reference and one project folder\",\n          \"Rename three colour categories to match your work, such as Budget, Clients and Waiting for\",\n          \"Create one rule for a newsletter or notification sender and run it on existing messages\",\n          \"Create a Quick Step that marks a message as read and moves it to Reference\",\n          \"Find last month's messages with attachments from one colleague using operators\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Manage email messages by using rules in Outlook\", url: \"https://support.microsoft.com/en-us/outlook/mail/manage-email-messages-by-using-rules-in-outlook\", source: MS },\n          MO400,\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 3 ───────────────────────────\n    {\n      id: \"mosp-m7-l3\",\n      title: \"Calendar and meetings across sites and time zones\",\n      minutes: 28,\n      objectives: [\n        \"Create appointments and meetings, including recurring and Teams meetings\",\n        \"Find a time that suits every attendee with the Scheduling Assistant and time zones\",\n        \"Track responses, share your calendar and book rooms\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"The calendar is where your time is negotiated. A clear invitation, sent at a time that works for everyone and with an agenda, saves a round of e-mails and makes the meeting itself shorter.\" },\n        { type: \"h\", text: \"Appointment, meeting or event?\" },\n        { type: \"table\", head: [\"Item\", \"What it is\", \"Example\"], rows: [\n          [\"Appointment\", \"Time blocked in your calendar only; nobody is invited\", \"Two hours to write the quarterly report\"],\n          [\"Meeting\", \"An invitation sent to others, who accept or decline\", \"Weekly team meeting, client visit\"],\n          [\"All-day event\", \"A day marked without blocking hours\", \"Public holiday, colleague's leave\"],\n        ] },\n        { type: \"path\", items: [\"Home\", \"New Appointment\"], note: \"Or Ctrl + Shift + A from anywhere in Outlook.\" },\n        { type: \"path\", items: [\"Home\", \"New Meeting\"], note: \"In the Calendar. Adding attendees to an appointment also turns it into a meeting.\" },\n        { type: \"h\", text: \"Build a good invitation\" },\n        { type: \"steps\", title: \"Schedule a meeting\", items: [\n          \"Add required attendees in **Required** and people who may come in **Optional**.\",\n          \"Write a subject that says what will be decided, for example \\\"Validate the 2027 training plan\\\".\",\n          \"Open the **Scheduling Assistant** to see everyone's free and busy times, and pick a slot where nobody is busy.\",\n          \"Use **Room Finder** or add a room from the list to book a meeting room at the same time.\",\n          \"Click **Teams Meeting** to add an online link for people at other sites.\",\n          \"Write the **agenda** in the body: items, who presents, what decision is expected.\",\n          \"Click **Recurrence** if the meeting repeats, then **Send**.\",\n        ] },\n        { type: \"callout\", tone: \"tip\", title: \"Response options\", text: \"In the meeting window, **Response Options** lets you turn off Request Responses for large information sessions, or stop attendees proposing new times. After sending, open the meeting and click **Tracking** to see who accepted, declined or has not answered.\" },\n        { type: \"h\", text: \"Time zones\" },\n        { type: \"p\", text: \"Cameroon uses **West Africa Time (WAT), UTC+1**, all year, with no summer time. Many partners change their clocks, so the difference with Douala changes during the year.\" },\n        { type: \"table\", head: [\"City\", \"Offset\", \"Difference with Douala\"], rows: [\n          [\"Abidjan, Dakar\", \"UTC+0\", \"1 hour behind all year\"],\n          [\"Paris, Brussels\", \"UTC+1 in winter, UTC+2 from late March to late October\", \"Same time in winter, 1 hour ahead in summer\"],\n          [\"Nairobi\", \"UTC+3\", \"2 hours ahead all year\"],\n          [\"Washington, Montréal\", \"UTC−5 in winter, UTC−4 from March to early November\", \"6 hours behind in winter, 5 hours behind in summer\"],\n        ] },\n        { type: \"path\", items: [\"File\", \"Options\", \"Calendar\", \"Time zones\"], note: \"Tick Show a second time zone, for example Paris, to see both columns in the calendar.\" },\n        { type: \"p\", text: \"In a meeting window, the **Time Zones** button lets you set the start time in the time zone of the organiser. Outlook converts the time automatically for each attendee, so write the time zone in the body too: \\\"14:00 Douala (WAT) / 15:00 Paris\\\".\" },\n        { type: \"shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Shift\", \"A\"], action: \"New appointment\" },\n          { keys: [\"Ctrl\", \"Shift\", \"Q\"], action: \"New meeting request\" },\n          { keys: [\"Ctrl\", \"G\"], action: \"Go to a date in the Calendar\" },\n        ] },\n        { type: \"keys\", id: \"mosp-m7-l3-keys\", title: \"Practise the calendar shortcut\", items: [\n          { keys: [\"Ctrl\", \"Shift\", \"A\"], action: \"New appointment\" },\n        ] },\n        { type: \"h\", text: \"Share your calendar\" },\n        { type: \"path\", items: [\"Home\", \"Share Calendar\"], note: \"In the Calendar. Choose what the person sees.\" },\n        { type: \"list\", items: [\n          \"**Can view when I'm busy**: colleagues see free and busy blocks only.\",\n          \"**Can view titles and locations**: enough for an assistant planning your week.\",\n          \"**Can view all details** or **Can edit**: only for people you trust with your agenda.\",\n          \"Mark personal appointments **Private** so their details stay hidden even when the calendar is shared.\",\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"Meetings across Cameroonian sites\", text: \"A regional NGO with offices in Douala, Garoua and Bertoua schedules its monthly meeting at 10:00 so the Garoua team, who may travel by road, can join. The invitation includes a Teams link and a phone dial-in for colleagues with weak connections, and the agenda is attached so people can read it offline during a power cut.\" },\n        { type: \"form\", id: \"mosp-m7-l3-form\", title: \"Set up the meeting\", task: \"Émile, a project officer in Yaoundé, organises a quarterly review with two colleagues in Douala, the partner's accountant in Abidjan and the country director. Choose the right settings.\",\n          hint: \"Meetings invite people, appointments do not. Abidjan is one hour behind Cameroon all year.\",\n          fields: [\n            { kind: \"select\", label: \"What should he create?\", options: [\"An appointment\", \"A meeting\", \"An all-day event\", \"A task\"], answer: 1 },\n            { kind: \"select\", label: \"The country director may join if her schedule allows. Where does she go?\", options: [\"Required\", \"Optional\", \"Bcc\", \"Resources\"], answer: 1 },\n            { kind: \"select\", label: \"Which tool shows everyone's free and busy times side by side?\", options: [\"Tracking\", \"Scheduling Assistant\", \"Response Options\", \"Categorize\"], answer: 1 },\n            { kind: \"select\", label: \"Colleagues in Douala and Abidjan will join online. What does he add?\", options: [\"A OneDrive link\", \"A Teams meeting link\", \"A read receipt\", \"A second time zone\"], answer: 1 },\n            { kind: \"text\", label: \"The meeting starts at 10:00 in Yaoundé. What time is it in Abidjan? (hh:mm)\", pattern: \"^0?9[:h.]00$\", example: \"09:00\", placeholder: \"hh:mm\", mono: true, explain: \"Abidjan is UTC+0 and Cameroon UTC+1, so Abidjan is one hour behind.\" },\n            { kind: \"select\", label: \"The review repeats on the first Monday of every third month. Which button?\", options: [\"Recurrence\", \"Forward\", \"Tracking\", \"Private\"], answer: 0 },\n            { kind: \"select\", label: \"Two weeks later, where does he see who has not answered?\", options: [\"The Sent Items folder\", \"Tracking in the open meeting\", \"The Scheduling Assistant\", \"Focused Inbox\"], answer: 1 },\n          ] },\n        { type: \"check\", id: \"mosp-m7-l3-c1\", question: \"On 20 October, a Douala manager sends an invitation for 15:00 Douala time to a partner in Paris. What time will the partner see in Outlook?\", options: [\"14:00\", \"15:00\", \"16:00\", \"17:00\"], answer: 2, explain: \"In October, Paris is still on summer time (UTC+2), one hour ahead of Cameroon (UTC+1). Outlook converts the time automatically.\" },\n        { type: \"task\", id: \"mosp-m7-l3-t1\", title: \"Practice\", items: [\n          \"Block two hours of focused work as an appointment in your calendar\",\n          \"Add a second time zone for a city where you have partners\",\n          \"Send a test meeting with a Teams link and an agenda to a colleague\",\n          \"Share your calendar with a colleague as \\\"Can view titles and locations\\\"\",\n          \"Open a meeting you organised and check the Tracking list\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Use the Scheduling Assistant and Room Finder for meetings in Outlook\", url: \"https://support.microsoft.com/en-us/office/use-the-scheduling-assistant-and-room-finder-for-meetings-in-outlook-2e00ac07-cef1-47c8-9b99-77372434d3fa\", source: MS },\n          MO400,\n        ] },\n      ],\n    },\n    // ─────────────────────────── LESSON 4 ───────────────────────────\n    {\n      id: \"mosp-m7-l4\",\n      title: \"Tasks, contacts and automatic replies\",\n      minutes: 25,\n      objectives: [\n        \"Turn e-mails into tasks with due dates and reminders\",\n        \"Build contacts and contact groups, and import them from Excel or CSV\",\n        \"Set up Automatic Replies for internal and external senders\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"An inbox is a poor to-do list: important requests sink under new mail. Outlook can turn a message into a task with a date, keep your contacts in one place, and answer for you when you are away.\" },\n        { type: \"h\", text: \"From e-mail to task\" },\n        { type: \"list\", items: [\n          \"**Flag** a message (Home › Follow Up) and choose a date. It appears in your task list with a link back to the message.\",\n          \"Choose **Follow Up › Add Reminder** to get a pop-up at a set time, for example the day before the deadline.\",\n          \"Create a task that is not linked to any e-mail with **Ctrl + Shift + K**: subject, start date, due date, reminder.\",\n          \"Your flagged messages and tasks also appear in **Microsoft To Do** on the web and on your phone, so you can tick them off anywhere.\",\n        ] },\n        { type: \"path\", items: [\"Home\", \"Follow Up\", \"Custom\"], note: \"Set a start date, due date and reminder. In new Outlook, you can also drag a message to My Day.\" },\n        { type: \"shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Shift\", \"K\"], action: \"New task\" },\n          { keys: [\"Ctrl\", \"Shift\", \"G\"], action: \"Flag for follow-up with a custom date\" },\n          { keys: [\"Ctrl\", \"Shift\", \"C\"], action: \"New contact\" },\n          { keys: [\"Ctrl\", \"Shift\", \"L\"], action: \"New contact group\" },\n        ] },\n        { type: \"keys\", id: \"mosp-m7-l4-keys\", title: \"Practise the task and contact shortcuts\", items: [\n          { keys: [\"Ctrl\", \"Shift\", \"K\"], action: \"New task\" },\n          { keys: [\"Ctrl\", \"Shift\", \"L\"], action: \"New contact group\" },\n          { keys: [\"Ctrl\", \"Shift\", \"G\"], action: \"Flag for follow-up\" },\n        ] },\n        { type: \"h\", text: \"Contacts and contact groups\" },\n        { type: \"p\", text: \"A complete contact card saves time later: full name, organisation, job title, e-mail, mobile number and city. A **contact group** (called a contact list in new Outlook) puts several contacts behind one name, such as \\\"Branch heads\\\", so you type one name instead of twelve addresses.\" },\n        { type: \"path\", items: [\"People\", \"Home\", \"New Contact Group\"], note: \"Give it a name, click Add Members, choose From Outlook Contacts or From Address Book, then Save & Close.\" },\n        { type: \"callout\", tone: \"warning\", title: \"Contact groups and Bcc\", text: \"When you put a contact group in To or Cc, recipients see all its members' addresses. For external groups, put the contact group in Bcc.\" },\n        { type: \"h\", text: \"Import contacts from Excel\" },\n        { type: \"steps\", title: \"Import a list of partners\", items: [\n          \"In Excel, keep one row per person with clear headings such as First Name, Last Name, Company, E-mail, Mobile.\",\n          \"Save as **CSV UTF-8 (Comma delimited)** so accented names such as Nkoué or Émilie import correctly.\",\n          \"In Outlook: **File › Open & Export › Import/Export**, then **Import from another program or file** › **Comma Separated Values**.\",\n          \"Choose the file and whether to replace or allow duplicates, then select the Contacts folder.\",\n          \"Click **Map Custom Fields** and check that each Excel column is matched to the right Outlook field, then Finish.\",\n        ] },\n        { type: \"h\", text: \"Automatic Replies (Out of Office)\" },\n        { type: \"path\", items: [\"File\", \"Automatic Replies\"], note: \"Work or school accounts. In new Outlook: Settings › Accounts › Automatic replies.\" },\n        { type: \"list\", items: [\n          \"Tick **Only send during this time range** so the reply stops by itself when you return.\",\n          \"Write a separate message for **Outside My Organization**: shorter, without internal details, and only to your contacts if you want to limit spam.\",\n          \"Give the date of return and a colleague's name and address for urgent matters, but no personal details such as \\\"I am travelling abroad\\\".\",\n        ] },\n        { type: \"form\", id: \"mosp-m7-l4-form\", title: \"Organise tasks, contacts and leave\", task: \"Serge, logistics officer of an SME in Douala, goes on leave from 2 to 13 November. Choose the right Outlook feature for each situation.\",\n          hint: \"Flags and tasks carry dates; contact groups replace long lists of addresses; Automatic Replies handle absence.\",\n          fields: [\n            { kind: \"select\", label: \"A supplier asks for a quotation by Friday. Serge wants a reminder on Thursday morning.\", options: [\"Mark it as unread\", \"Flag it with a custom date and add a reminder\", \"Move it to Archive\", \"Forward it to himself\"], answer: 1 },\n            { kind: \"select\", label: \"He e-mails the same nine drivers every week.\", options: [\"Create a contact group\", \"Create a rule\", \"Share his calendar\", \"Create a category\"], answer: 0 },\n            { kind: \"select\", label: \"His 240 transport partners are in an Excel file. Which format should he save it in before importing?\", options: [\"PDF\", \"CSV UTF-8 (Comma delimited)\", \"Excel Macro-Enabled Workbook\", \"Plain text with tabs\"], answer: 1, explain: \"CSV UTF-8 keeps accented characters such as é and è.\" },\n            { kind: \"select\", label: \"During the import, the \\\"Mobile\\\" column lands in the \\\"Business Fax\\\" field. Where does he fix this?\", options: [\"Map Custom Fields\", \"Clean Up\", \"Response Options\", \"Categorize\"], answer: 0 },\n            { kind: \"select\", label: \"Which setting stops the out-of-office message automatically when he returns?\", options: [\"Only send during this time range\", \"Delay Delivery\", \"Request Responses\", \"Recurrence\"], answer: 0 },\n            { kind: \"select\", label: \"Which is the best external reply?\", options: [\"\\\"I am in Dubai with my family until the 13th.\\\"\", \"\\\"I am away until 13 November. For urgent logistics matters, please contact Mrs Ngo Biyong at logistique@example.cm.\\\"\", \"\\\"Out.\\\"\", \"\\\"Call me on my personal number.\\\"\"], answer: 1, explain: \"Give the return date and an alternative contact, without personal details.\" },\n          ] },\n        { type: \"callout\", tone: \"workplace\", title: \"Before your leave\", text: \"Before a mission to the regions or annual leave, set Automatic Replies, delegate your open tasks by forwarding them with a short note, and share your calendar with the colleague covering for you. Your partners are not left waiting, and nobody has to call you in Kribi to ask where a file is.\" },\n        { type: \"check\", id: \"mosp-m7-l4-c1\", question: \"You flag an e-mail with the date \\\"Next Week\\\". Where can you see it besides the Inbox?\", options: [\"Only in the Sent Items folder\", \"In your task list and in Microsoft To Do\", \"In the Calendar as a meeting\", \"Nowhere else\"], answer: 1, explain: \"Flagged messages appear in the To-Do List in Outlook and in the Flagged email list of Microsoft To Do.\" },\n        { type: \"task\", id: \"mosp-m7-l4-t1\", title: \"Practice\", items: [\n          \"Flag three e-mails that need action with realistic dates, and add a reminder to one\",\n          \"Create two tasks with Ctrl + Shift + K that are not linked to e-mails\",\n          \"Create a contact group for your team\",\n          \"Prepare a five-row contact list in Excel, save it as CSV UTF-8 and import it\",\n          \"Write internal and external Automatic Replies for your next leave (do not turn them on yet)\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Set up out of office automatic replies in Outlook\", url: \"https://support.microsoft.com/en-us/office/send-automatic-out-of-office-replies-from-outlook-9742f476-5348-4f9f-997f-5e208513bd67\", source: MS },\n          { label: \"Import or export contacts in Outlook using a .csv file\", url: \"https://support.microsoft.com/en-us/outlook/people/import-or-export-contacts-in-outlook-using-a-csv-file\", source: MS },\n        ] },\n      ],\n    },\n    // ─────────────────────────── PRACTICE ───────────────────────────\n    {\n      id: \"mosp-m7-practice\",\n      title: \"Practice lab: e-mail, rules and meetings\",\n      minutes: 35,\n      objectives: [\n        \"Triage a busy inbox with clear decisions\",\n        \"Design rules and searches for a real mailbox\",\n        \"Plan a meeting across several time zones\",\n        \"Send a sensitive group mailing without exposing anyone\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" },\n        { type: \"h\", text: \"Exercise 1: Monday morning in Bafoussam\" },\n        { type: \"form\", id: \"mosp-pr-m7-triage\", level: \"beginner\", title: \"Triage the inbox\",\n          task: \"Clarisse manages the Bafoussam branch of a microfinance institution. It is Monday 8:00 and she has 64 unread messages. Decide what to do with each one: delete, do it now, delegate, defer or file.\",\n          hint: \"Two minutes or less: do it now. Someone else's job: delegate. Longer with a deadline: defer with a flag. Finished but worth keeping: file. No value: delete.\",\n          fields: [\n            { kind: \"select\", label: \"A promotional newsletter from a printer she has never used\", options: FOURD, answer: 0 },\n            { kind: \"select\", label: \"A colleague asks for the phone number of the Dschang agent. She knows it by heart.\", options: FOURD, answer: 1, explain: \"Answering takes less than two minutes.\" },\n            { kind: \"select\", label: \"A client complains about a loan repayment schedule. The credit officer handles schedules.\", options: FOURD, answer: 2 },\n            { kind: \"select\", label: \"Head office asks for the branch budget proposal by Friday. It will take three hours.\", options: FOURD, answer: 3 },\n            { kind: \"select\", label: \"The signed minutes of last month's credit committee, for her records\", options: FOURD, answer: 4 },\n            { kind: \"select\", label: \"After triage, which shortcut moves a selected message to a folder?\", options: [\"Ctrl + Shift + V\", \"Ctrl + F\", \"Ctrl + R\", \"Ctrl + Shift + A\"], answer: 0 },\n          ] },\n        { type: \"h\", text: \"Exercise 2: Rules for an NGO programme officer\" },\n        { type: \"form\", id: \"mosp-pr-m7-rules\", level: \"intermediate\", title: \"Design rules and searches\",\n          task: \"Olivier coordinates a health programme for an NGO in Garoua. He receives daily reports from 14 health centres (all from addresses ending in @centres.example.org, subject starting with \\\"Rapport journalier\\\"), plus alerts from the stock system (stock@example.org). Answer the questions to build his rules and searches.\",\n          hint: \"Pick the condition that matches all the messages you want and nothing else. Exceptions keep important messages in the Inbox. Operators: from:, subject:, hasattachments:, received:.\",\n          fields: [\n            { kind: \"select\", label: \"Best condition for the daily reports\", options: [\"with specific words in the subject: Rapport journalier\", \"sent only to me\", \"with an attachment\", \"from people or public group: Olivier\"], answer: 0, explain: \"The subject words match all 14 centres with one condition.\" },\n            { kind: \"select\", label: \"Best action for the daily reports\", options: [\"delete it\", \"move it to the specified folder: Rapports centres\", \"forward it to the director\", \"mark it as High importance\"], answer: 1 },\n            { kind: \"select\", label: \"Stock alerts must stay visible only when they mention a stock-out (\\\"rupture\\\"). How?\", options: [\"Rule moving stock@example.org to a folder, except if the subject contains \\\"rupture\\\"\", \"Rule deleting all stock alerts\", \"Flag every stock alert\", \"No rule: read them all\"], answer: 0, explain: \"The exception keeps the dangerous alerts in the Inbox while the routine ones are filed.\" },\n            { kind: \"select\", label: \"He wants one button to mark a report as read, categorise it \\\"Validé\\\" and move it to Archive. What does he create?\", options: [\"A rule\", \"A Quick Step\", \"A contact group\", \"An appointment\"], answer: 1 },\n            { kind: \"text\", label: \"Search: daily reports that have an attachment\", pattern: \"^(?=.*subject:\\\\s*\\\"?rapport)(?=.*hasattachments?:\\\\s*(yes|true)).*$\", example: \"subject:\\\"Rapport journalier\\\" hasattachments:yes\", placeholder: \"Search\", mono: true },\n            { kind: \"text\", label: \"Search: messages from the stock system received last week\", pattern: \"^(?=.*from:\\\\s*\\\"?stock)(?=.*received:\\\\s*\\\"?last ?week\\\"?).*$\", example: \"from:stock@example.org received:\\\"last week\\\"\", placeholder: \"Search\", mono: true, explain: \"Combine from: with received: and a date word such as yesterday, this week or last week.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 3: A four-site meeting\" },\n        { type: \"form\", id: \"mosp-pr-m7-timezones\", level: \"advanced\", title: \"Plan across time zones\",\n          task: \"A Douala logistics company holds a one-hour steering meeting on Tuesday 13 October 2026 with its partners in Paris (UTC+2 on that date), Nairobi (UTC+3) and Washington (UTC−4 on that date). Douala is UTC+1. Everyone works from 8:00 to 17:00 local time. Answer in hh:mm.\",\n          hint: \"Work out each difference with Douala first: Paris +1 h, Nairobi +2 h, Washington −5 h in October. Watch out: Paris and Washington change their clocks, Douala and Nairobi do not.\",\n          fields: [\n            { kind: \"text\", label: \"If the meeting starts at 14:00 in Douala, what time is it in Paris?\", pattern: \"^15[:h.]00$\", example: \"15:00\", placeholder: \"hh:mm\", mono: true },\n            { kind: \"text\", label: \"At 14:00 in Douala, what time is it in Nairobi?\", pattern: \"^16[:h.]00$\", example: \"16:00\", placeholder: \"hh:mm\", mono: true },\n            { kind: \"text\", label: \"At 14:00 in Douala, what time is it in Washington?\", pattern: \"^0?9[:h.]00$\", example: \"09:00\", placeholder: \"hh:mm\", mono: true },\n            { kind: \"select\", label: \"Which Douala start time keeps the whole hour inside everyone's working day?\", options: [\"09:00\", \"11:00\", \"14:00\", \"16:00\"], answer: 2, explain: \"At 9:00 and 11:00 it is still night or early morning in Washington (3:00 and 5:00). At 16:00 the meeting ends at 19:00 in Nairobi. At 14:00 it runs 9:00–10:00 in Washington and 16:00–17:00 in Nairobi.\" },\n            { kind: \"text\", label: \"The same meeting is held on Tuesday 8 December 2026, when Paris is back to UTC+1. What time is it in Paris at 14:00 in Douala?\", pattern: \"^14[:h.]00$\", example: \"14:00\", placeholder: \"hh:mm\", mono: true, explain: \"In winter Paris and Douala show the same time.\" },\n            { kind: \"text\", label: \"On 8 December Washington is UTC−5. What time is it there at 14:00 in Douala?\", pattern: \"^0?8[:h.]00$\", example: \"08:00\", placeholder: \"hh:mm\", mono: true },\n            { kind: \"select\", label: \"What is the safest way to avoid confusion for the series?\", options: [\"Write only \\\"14:00\\\" in the invitation\", \"Set the time zone in the meeting and state the time for each city in the body\", \"Send four separate invitations\", \"Ask everyone to convert the time themselves\"], answer: 1, explain: \"Outlook converts the time for each attendee, and the body confirms it for anyone reading on another device.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 4: A sensitive group mailing\" },\n        { type: \"form\", id: \"mosp-pr-m7-bcc\", level: \"expert\", title: \"Send confidential results to 60 candidates\",\n          task: \"A training centre in Yaoundé must tell 60 external candidates that the results of a recruitment test are available, and send the results file to the jury. Candidates must not see each other's addresses or scores. Answer each question.\",\n          hint: \"Think of privacy first: who can see which addresses, who may use Reply All, and whether a file should travel as an attachment or a link with limited access.\",\n          fields: [\n            { kind: \"select\", label: \"Where do the 60 candidates' addresses go?\", options: [\"To\", \"Cc\", \"Bcc\", \"In the body of the message\"], answer: 2 },\n            { kind: \"select\", label: \"What goes in the To field of that message?\", options: [\"Nothing, it can stay empty\", \"The centre's own address\", \"The first candidate\", \"The whole jury\"], answer: 1, explain: \"Your own address gives the message a visible recipient; some mail servers treat messages with an empty To field as spam.\" },\n            { kind: \"select\", label: \"The candidates are in a contact group called \\\"Candidats 2026\\\". Where do you put the group?\", options: [\"To\", \"Cc\", \"Bcc\", \"It cannot be used\"], answer: 2, explain: \"A contact group in To or Cc reveals every member's address.\" },\n            { kind: \"select\", label: \"A candidate clicks Reply All to protest. Who receives the reply?\", options: [\"All 60 candidates\", \"Only the sender and the To and Cc recipients\", \"The jury\", \"Nobody\"], answer: 1, explain: \"Bcc recipients are never included in Reply All.\" },\n            { kind: \"select\", label: \"How should the jury receive the results file with scores?\", options: [\"As an attachment to the candidates' message\", \"As a OneDrive link shared with the jury members only, in a separate message\", \"Pasted in the body for all\", \"Printed and scanned\"], answer: 1 },\n            { kind: \"select\", label: \"You notice a spelling mistake in a candidate's name one minute after sending the jury message. What is realistic?\", options: [\"Recall always removes it\", \"Recall may work only if the jury are in your organisation and have not opened it; otherwise send a short correction\", \"Delete it from Sent Items\", \"Ask everyone to ignore Outlook\"], answer: 1 },\n            { kind: \"text\", label: \"Write the subject line for the candidates: it must name the test and say the results are available (French or English).\", pattern: \"^(?!.*!!)(?=.*(result|résultat|resultat))(?=.*(test|recruit|recrut|concours|exam)).{15,100}$\", example: \"Recruitment test 2026: results available\", placeholder: \"Subject\", explain: \"Name the test and the news. Avoid \\\"Urgent\\\" and exclamation marks.\" },\n            { kind: \"select\", label: \"To avoid sending too early by mistake, which classic Outlook setting holds the message until 8:00 the next day?\", options: [\"Delay Delivery\", \"Request a Read Receipt\", \"Automatic Replies\", \"Clean Up\"], answer: 0 },\n          ] },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"mosp-m7-quiz\",\n    title: \"Module 7 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"Which field hides the recipients' addresses from each other?\", options: [\"Bcc\", \"Cc\", \"To\", \"Subject\"], answer: 0, explain: \"Nobody sees the Bcc list, and Bcc recipients are not included when someone clicks Reply All.\" },\n      { id: \"q2\", question: \"In Outlook, what does Ctrl + F do when a message is selected?\", options: [\"Opens the search box\", \"Flags the message\", \"Forwards the message\", \"Opens the font settings\"], answer: 2, explain: \"In Outlook, Ctrl + F forwards. Use Ctrl + E to search.\" },\n      { id: \"q3\", question: \"A rule has conditions, actions and…\", options: [\"categories\", \"folders\", \"signatures\", \"exceptions\"], answer: 3, explain: \"Exceptions exclude some messages that match the conditions, for example those marked High importance.\" },\n      { id: \"q4\", question: \"Which search finds messages with attachments sent by Ngono?\", options: [\"Ngono + attachment\", \"from:Ngono hasattachments:yes\", \"subject:Ngono\", \"to:Ngono attach\"], answer: 1, explain: \"from: filters the sender and hasattachments:yes keeps only messages with files.\" },\n      { id: \"q5\", question: \"What is the time zone of Cameroon?\", options: [\"UTC+0 all year\", \"UTC+1 in winter and UTC+2 in summer\", \"UTC+1 all year (WAT)\", \"UTC+3 all year\"], answer: 2, explain: \"Cameroon uses West Africa Time, UTC+1, with no summer time.\" },\n      { id: \"q6\", question: \"Where do you see who has accepted or declined a meeting you organised?\", options: [\"Tracking in the open meeting\", \"Sent Items\", \"Focused Inbox\", \"Automatic Replies\"], answer: 0, explain: \"The Tracking view lists each attendee's response.\" },\n      { id: \"q7\", question: \"Which shortcut creates a new task?\", options: [\"Ctrl + Shift + A\", \"Ctrl + Shift + L\", \"Ctrl + Shift + K\", \"Ctrl + R\"], answer: 2, explain: \"Ctrl + Shift + K creates a task. Ctrl + Shift + A is a new appointment and Ctrl + Shift + L a new contact group.\" },\n      { id: \"q8\", question: \"When does message recall have a chance to work?\", options: [\"Always, within one hour\", \"Only for Gmail recipients\", \"Only between work accounts in the same organisation, if the message is still unopened\", \"Only for messages with attachments\"], answer: 2, explain: \"Recall needs Microsoft 365 work accounts in the same organisation and an unopened message. Otherwise send a correction.\" },\n    ],\n  },\n};\n","client/src/data/courses/mosp/m8.ts":"import type { Block, CourseModule } from \"../../../lms/types\";\n\n// Module 8 of MOSP: Integrated Office skills and the capstone deliverable package.\n\nconst MS = \"Microsoft Support\";\nconst LEARN = \"Microsoft Learn\";\n\nconst INTRO: Block = { type: \"p\", text: \"Four exercises of increasing difficulty, from beginner to expert. Each one uses a different workplace situation. Take your time: every answer is checked, and the explanations appear after you check.\" };\n\nconst PASTE = [\"Keep Source Formatting\", \"Use Destination Styles\", \"Link & Keep Source Formatting\", \"Link & Use Destination Styles\", \"Picture\", \"Keep Text Only\"];\nconst SHARE = [\"Specific people, Can edit\", \"Specific people, Can view\", \"People in your organisation, Can view\", \"Anyone with the link, Can view\"];\n\nexport const m8: CourseModule = {\n  id: \"mosp-m8\",\n  number: 8,\n  title: \"Integrated Office Skills & Capstone Project\",\n  summary: \"Combine Word, Excel, PowerPoint and Outlook in one professional deliverable.\",\n  hours: 10,\n  lessons: [\n    // ─────────────────────────────── LESSON 1 ───────────────────────────────\n    {\n      id: \"mosp-m8-l1\",\n      title: \"Linking Excel data into Word and PowerPoint\",\n      minutes: 25,\n      objectives: [\n        \"Choose the right paste option when moving Excel tables and charts into Word or PowerPoint\",\n        \"Decide between linking, embedding and pasting a picture\",\n        \"Update, repair and break links before a document is shared\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"Most professional reports repeat figures that already live in Excel. Typing them again wastes time and creates errors: the report says 45 million while the workbook says 45.15 million. When you link the data instead, Word and PowerPoint show the figures from the workbook and can be refreshed when the workbook changes.\" },\n        { type: \"h\", text: \"The paste options for an Excel table\" },\n        { type: \"p\", text: \"Copy a range in Excel with `Ctrl + C`, click in Word or PowerPoint, then open Home › Paste (or the small Paste Options button that appears after pasting). Each icon gives a different result:\" },\n        { type: \"table\", head: [\"Paste option\", \"What you get\", \"Use it when\"], rows: [\n          [\"Keep Source Formatting\", \"A Word or PowerPoint table that looks like the Excel range\", \"A one-off copy that must look exactly as in Excel\"],\n          [\"Use Destination Styles\", \"A table that takes the fonts and colours of the report\", \"A one-off copy that should match the report\"],\n          [\"Link & Keep Source Formatting\", \"A linked table with the Excel look\", \"Figures that change and must stay in the Excel look\"],\n          [\"Link & Use Destination Styles\", \"A linked table with the report's look\", \"Monthly or quarterly reports where the figures are refreshed\"],\n          [\"Picture\", \"An image of the range\", \"Final documents and PDFs: nobody can change the figures\"],\n          [\"Keep Text Only\", \"Plain text, cells separated by tabs\", \"You only need the numbers or words, without a table\"],\n        ] },\n        { type: \"path\", items: [\"Home\", \"Paste\", \"Paste Special\"], note: \"In Word and PowerPoint, also Ctrl + Alt + V. Choose Paste link and Microsoft Excel Worksheet Object to create a link.\" },\n        { type: \"h\", text: \"Link, embed or picture?\" },\n        { type: \"table\", head: [\"Method\", \"Where the data lives\", \"Advantage\", \"Risk\"], rows: [\n          [\"Link (Paste link)\", \"In the Excel workbook; the document shows it\", \"One update in Excel refreshes every report\", \"Breaks if the workbook is moved or renamed\"],\n          [\"Embed\", \"A full copy of the workbook inside the document\", \"Works without the original file\", \"The whole workbook travels with the file, including hidden sheets; the file grows\"],\n          [\"Picture\", \"Only an image in the document\", \"Small, safe, looks the same everywhere\", \"Cannot be edited or updated\"],\n        ] },\n        { type: \"callout\", tone: \"warning\", title: \"Embedding shares more than you think\", text: \"An embedded table or chart carries the entire workbook, not just the cells you copied. A slide sent to a partner can therefore contain the salaries sheet or the supplier prices. For files that leave your organisation, paste a picture or export a PDF.\" },\n        { type: \"h\", text: \"Link a table step by step\" },\n        { type: \"steps\", title: \"Paste Link into a Word report\", items: [\n          \"Save the Excel workbook first, in its final folder (ideally OneDrive or SharePoint), with its final name.\",\n          \"Select the range, for example A1:F6, and press `Ctrl + C`.\",\n          \"In Word, click where the table should go and open **Home › Paste › Paste Special**.\",\n          \"Choose **Paste link**, then **Microsoft Excel Worksheet Object** (or HTML Format to get a Word table), and click OK.\",\n          \"Change a figure in Excel, save, then right-click the table in Word and choose **Update Link**.\",\n        ] },\n        { type: \"h\", text: \"Linked charts in PowerPoint\" },\n        { type: \"p\", text: \"Copy an Excel chart and paste it on a slide with **Use Destination Theme & Link Data**: the chart takes the colours of the presentation but its data stays in Excel. To refresh it, select the chart and use Chart Design › Refresh Data. Chart Design › Edit Data opens the source workbook.\" },\n        { type: \"h\", text: \"Manage every link from one place\" },\n        { type: \"path\", items: [\"File\", \"Info\", \"Edit Links to Files\"], note: \"Appears at the bottom right under Related Documents only when the file contains links. Works the same in Word and PowerPoint.\" },\n        { type: \"list\", items: [\n          \"**Update Now** refreshes the selected links.\",\n          \"**Change Source** points a broken link to the workbook's new location or name.\",\n          \"**Break Link** turns the linked object into a fixed copy that no longer updates.\",\n          \"**Automatic update** refreshes links when the file opens; **Manual update** waits until you ask.\",\n        ] },\n        { type: \"shortcuts\", title: \"Links in Word\", items: [\n          { keys: [\"Ctrl\", \"Alt\", \"V\"], action: \"Open Paste Special (Word and PowerPoint)\" },\n          { keys: [\"F9\"], action: \"Update the selected linked table or field\" },\n          { keys: [\"Ctrl\", \"A\"], action: \"Select the whole document, then F9 updates every link\" },\n          { keys: [\"Ctrl\", \"Shift\", \"F9\"], action: \"Unlink: turn the selected linked table into fixed content\" },\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"Why links break in real offices\", text: \"An accountant in Douala links the monthly report to C:\\\\Users\\\\Nadine\\\\Desktop\\\\Ventes.xlsx, then moves the workbook to the team's SharePoint folder. The next month the report still shows March figures. Agree on the final folder and file name before you link, and never link to a file on a USB drive or the desktop.\" },\n        { type: \"form\", id: \"mosp-m8-l1-paste\", title: \"Choose the paste option\", task: \"For each situation, choose the paste option you would use when copying an Excel range into Word or PowerPoint.\",\n          hint: \"Ask two questions: must the figures update later (link or not)? Must they look like Excel or like the report (source or destination)? Final PDFs and files for outsiders are usually a picture.\",\n          fields: [\n            { kind: \"select\", label: \"The monthly sales table in the management report must use the report's fonts and be refreshed every month from the same workbook.\", options: PASTE, answer: 3, explain: \"Link keeps the connection to the workbook; Destination Styles gives the report's look.\" },\n            { kind: \"select\", label: \"A final report will be exported to PDF for a donor. The figures must never change.\", options: PASTE, answer: 4, explain: \"A picture cannot be edited or refreshed by mistake, and it shows the same way everywhere.\" },\n            { kind: \"select\", label: \"You only need the three product names from a column to write them in a sentence.\", options: PASTE, answer: 5, explain: \"Keep Text Only drops the table and keeps the words.\" },\n            { kind: \"select\", label: \"A one-off price list must look exactly as the finance team formatted it in Excel, and you may adjust it in Word.\", options: PASTE, answer: 0, explain: \"No update needed, and the Excel look must be kept.\" },\n            { kind: \"select\", label: \"The quarterly dashboard table must stay in the corporate Excel colours and be refreshed every quarter.\", options: PASTE, answer: 2, explain: \"Linked, with the source formatting.\" },\n          ] },\n        { type: \"form\", id: \"mosp-m8-l1-links\", title: \"Link, embed or fix?\", task: \"Answer each question about linked and embedded data. Type keys joined with +, for example Ctrl + C.\",\n          hint: \"Edit Links to Files is on File › Info. F9 updates a selected field in Word. Embedded objects carry the whole workbook.\",\n          fields: [\n            { kind: \"select\", label: \"The workbook was renamed from Ventes.xlsx to 2026-04_Ventes.xlsx. The Word report now shows an error when you update the link. What do you do?\", options: [\"Delete the table and retype the figures\", \"File › Info › Edit Links to Files › Change Source\", \"Save the report as PDF\", \"Rename the Word document\"], answer: 1, explain: \"Change Source points the link to the file's new name or location.\" },\n            { kind: \"text\", label: \"In Word, which key updates the linked table you have selected?\", accept: [\"F9\"], placeholder: \"Key\", mono: true, explain: \"F9 updates the selected field. Select everything with Ctrl + A first to update all links.\" },\n            { kind: \"select\", label: \"A slide sent to an external partner contains an embedded chart. The workbook also has a salaries sheet. What is the risk?\", options: [\"None: only the chart is sent\", \"The chart colours may change\", \"The partner can open the whole embedded workbook, including the salaries sheet\", \"The file cannot be opened without the workbook\"], answer: 2, explain: \"Embedding places a full copy of the workbook in the presentation. Paste a picture instead.\" },\n            { kind: \"select\", label: \"Which method keeps the file smallest and safe from changes?\", options: [\"Embed\", \"Link\", \"Picture\", \"Keep Source Formatting\"], answer: 2 },\n            { kind: \"text\", label: \"Which shortcut turns a selected linked table in Word into fixed content that no longer updates?\", accept: [\"Ctrl+Shift+F9\", \"Shift+Ctrl+F9\"], placeholder: \"Ctrl + …\", mono: true, explain: \"Ctrl + Shift + F9 unlinks the field. You can also use Break Link in the Edit Links dialog.\" },\n          ] },\n        { type: \"check\", id: \"mosp-m8-l1-c1\", question: \"You pasted a table with Paste link last month. This month the Excel file was moved to a new SharePoint folder. What happens when you update the link?\", options: [\"Word finds the file automatically\", \"The link cannot find the source until you use Change Source\", \"The table is deleted\", \"Word converts the table to a picture\"], answer: 1, explain: \"A link stores the path to the workbook. When the file moves or is renamed, the path no longer works and you must point it to the new location with Change Source.\" },\n        { type: \"task\", id: \"mosp-m8-l1-t1\", title: \"Practice\", items: [\n          \"Create a small Excel table of monthly sales for four towns and save it to OneDrive\",\n          \"Paste it into Word three times: Use Destination Styles, Link & Use Destination Styles, and Picture\",\n          \"Change one figure in Excel, save, and update the linked table with a right-click › Update Link\",\n          \"Paste an Excel chart into PowerPoint with Use Destination Theme & Link Data and refresh it\",\n          \"Open File › Info › Edit Links to Files and look at the source path of each link\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Copy from Excel to another Office program\", url: \"https://support.microsoft.com/en-us/word/copy-from-excel-to-another-office-program\", source: MS },\n          { label: \"Insert and update Excel data in PowerPoint\", url: \"https://support.microsoft.com/en-us/office/insert-and-update-excel-data-in-powerpoint-0690708a-5ce6-41b4-923f-11d57554138d\", source: MS },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 2 ───────────────────────────────\n    {\n      id: \"mosp-m8-l2\",\n      title: \"Collaboration in OneDrive and SharePoint\",\n      minutes: 25,\n      objectives: [\n        \"Share files with the right people and the right permissions\",\n        \"Co-author documents, mention colleagues in comments and restore earlier versions\",\n        \"Keep working during internet cuts with Files On-Demand and clear team naming rules\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"When a report is written by four people who e-mail attachments to each other, nobody knows which copy is the right one. Storing the file once in the cloud and sharing a link means everyone works on the same file, Office saves every version, and you control exactly who can see or change it.\" },\n        { type: \"h\", text: \"OneDrive or SharePoint?\" },\n        { type: \"table\", head: [\"\", \"OneDrive for work or school\", \"SharePoint (and Teams files)\"], rows: [\n          [\"Belongs to\", \"You\", \"The team or department\"],\n          [\"Use it for\", \"Your drafts and files you share now and then\", \"Team files that must stay after someone leaves\"],\n          [\"When someone leaves\", \"Their OneDrive is removed after a delay\", \"Files stay with the team site\"],\n          [\"Typical example\", \"Your draft of the monthly report\", \"The shared Finance folder with all quarterly packages\"],\n        ] },\n        { type: \"path\", items: [\"File\", \"Save As\", \"OneDrive or Sites\"], note: \"Sites lists the SharePoint sites and Teams you belong to.\" },\n        { type: \"h\", text: \"Share with the right people\" },\n        { type: \"p\", text: \"Select **Share** at the top right of Word, Excel or PowerPoint (or right-click a file on onedrive.com). Open the link settings to choose who can use the link, then choose what they can do: **Can edit** lets the person change the file, **Can view** lets them read and download it only. To stop sharing later, open Manage access and remove the person or the link.\" },\n        { type: \"table\", head: [\"Link setting\", \"Who can open it\", \"Typical use\"], rows: [\n          [\"Specific people\", \"Only the people you name, signed in with that address\", \"Most work files, auditors, partners\"],\n          [\"People in your organisation\", \"Any colleague who has the link\", \"Internal procedures, staff notices\"],\n          [\"People with existing access\", \"Only people who already have access\", \"Sending a reminder link without changing permissions\"],\n          [\"Anyone with the link\", \"Anyone, even if the link is forwarded\", \"Public flyers or forms; avoid for confidential files\"],\n        ] },\n        { type: \"form\", id: \"mosp-m8-l2-share\", title: \"Set the right sharing permissions\", task: \"Choose the link setting and permission for each situation.\",\n          hint: \"Start with the narrowest option that still works. Anyone with the link is only for truly public content.\",\n          fields: [\n            { kind: \"select\", label: \"Your colleague Brice writes half of the NGO's annual report with you.\", options: SHARE, answer: 0, explain: \"He needs to change the document, and only he should get the access.\" },\n            { kind: \"select\", label: \"An external auditor from a Yaoundé firm must read the final accounts.\", options: SHARE, answer: 1, explain: \"The auditor reads but must not change the accounts. Naming the person stops the link working for anyone else.\" },\n            { kind: \"select\", label: \"The HR procedures manual must be readable by every staff member.\", options: SHARE, answer: 2, explain: \"All colleagues can read it, nobody outside the organisation can.\" },\n            { kind: \"select\", label: \"A job advertisement will be posted on the company's Facebook page.\", options: SHARE, answer: 3, explain: \"The content is public anyway, so a view-only Anyone link is acceptable.\" },\n            { kind: \"select\", label: \"The Director General must approve the budget but should not modify the workbook.\", options: SHARE, answer: 1, explain: \"View access for one named person.\" },\n          ] },\n        { type: \"h\", text: \"Co-authoring in real time\" },\n        { type: \"p\", text: \"When a Word, Excel or PowerPoint file is saved in OneDrive or SharePoint, several people can edit it at the same time. Their pictures or initials appear at the top of the window and coloured flags show where each person is working. AutoSave must be on, and the file must be in a modern format (.docx, .xlsx, .pptx), not an old .doc or .xls.\" },\n        { type: \"steps\", title: \"Mention a colleague in a comment\", items: [\n          \"Select the text or cell concerned and choose **Review › New Comment**.\",\n          \"Type `@` followed by the first letters of your colleague's name and pick them from the list.\",\n          \"Write the request, for example \\\"please confirm the Garoua figure\\\", and post the comment.\",\n          \"Your colleague receives an e-mail with a link that opens the file at your comment.\",\n        ] },\n        { type: \"h\", text: \"Version History\" },\n        { type: \"path\", items: [\"File\", \"Info\", \"Version History\"], note: \"Or click the file name in the title bar. On onedrive.com, right-click the file › Version history.\" },\n        { type: \"steps\", title: \"Restore an earlier version\", items: [\n          \"Open Version History and select a version by its date, time and author.\",\n          \"It opens as a read-only copy. Check that it contains what you need.\",\n          \"Select **Restore**. The old version becomes the current one and the replaced version stays in the history.\",\n          \"If you only need a paragraph, copy it from the old version instead of restoring the whole file.\",\n        ] },\n        { type: \"h\", text: \"Check out and check in\" },\n        { type: \"p\", text: \"Some SharePoint libraries ask you to **check out** a file before editing. While it is checked out, only you can change it; the others can only read. When you finish, **check in** with a short comment describing your change. Check-out and co-authoring do not mix: use check-out only for files such as signed procedures that one person at a time should edit. In the library, select the file, then … › More › Check out; in the desktop apps, File › Info › Check Out appears when the library supports it.\" },\n        { type: \"h\", text: \"Working with an unstable connection\" },\n        { type: \"table\", head: [\"OneDrive icon\", \"Meaning\"], rows: [\n          [\"Blue cloud\", \"Online-only: the file needs the internet to open\"],\n          [\"Green tick in a white circle\", \"Available on this device since you last opened it\"],\n          [\"White tick in a green circle\", \"Always kept on this device, even offline\"],\n          [\"Two blue arrows\", \"Syncing in progress\"],\n        ] },\n        { type: \"callout\", tone: \"workplace\", title: \"Before a field mission or a long power cut\", text: \"A programme officer leaving Yaoundé for three days of field visits around Garoua right-clicks the project folder in File Explorer and chooses **Always keep on this device**. She keeps working offline, and OneDrive uploads her changes as soon as the connection returns. On a mobile data bundle, pause syncing from the OneDrive icon to save credit.\" },\n        { type: \"h\", text: \"Naming and folder conventions for teams\" },\n        { type: \"list\", items: [\n          \"Folders: number them by stage, for example `01_Data`, `02_Drafts`, `03_Final`, `04_Sent`.\",\n          \"Files: `date_subject` without _v1, _v2 inside the cloud, because Version History keeps the versions for you.\",\n          \"Add a version number only to copies that leave the team, such as a PDF sent to a donor.\",\n          \"Never keep a personal copy named \\\"Rapport_final_Awa\\\": comment in the shared file instead.\",\n        ] },\n        { type: \"form\", id: \"mosp-m8-l2-versions\", title: \"Recover and co-author\", task: \"Answer each question about version history, comments, check-out and offline work.\",\n          hint: \"Version History is on File › Info. Mentions start with a special character. Co-authoring needs a modern file format.\",\n          fields: [\n            { kind: \"select\", label: \"Yesterday a colleague deleted the whole Recommendations section of a shared report. How do you get it back?\", options: [\"Ctrl + Z\", \"File › Info › Version History, then open an earlier version\", \"Ask IT to restore last month's backup\", \"Rewrite the section\"], answer: 1, explain: \"Undo only works in your own session. Version History keeps the earlier versions saved in the cloud.\" },\n            { kind: \"text\", label: \"Which character do you type in a comment to mention a colleague?\", accept: [\"@\"], placeholder: \"Character\", mono: true },\n            { kind: \"select\", label: \"Two colleagues cannot edit Budget.xls at the same time, although it is on SharePoint. Why?\", options: [\"The file is too large\", \"The file uses the old .xls format; save it as .xlsx\", \"SharePoint does not support Excel\", \"AutoSave only works on Fridays\"], answer: 1, explain: \"Real-time co-authoring needs the modern formats: .docx, .xlsx and .pptx.\" },\n            { kind: \"select\", label: \"You travel to Garoua tomorrow with no reliable internet. What do you do with the project folder?\", options: [\"Free up space\", \"Always keep on this device\", \"Share it with Anyone\", \"Compress it to ZIP and e-mail it to yourself\"], answer: 1, explain: \"The files are downloaded now and stay available offline. Changes sync when you are back online.\" },\n            { kind: \"select\", label: \"A procedure in a SharePoint library is checked out to a colleague who is on leave. What is the right action?\", options: [\"Save a copy with another name and edit that\", \"Ask the library owner to check it in or discard the check-out\", \"Delete the file\", \"Wait until the colleague returns next month\"], answer: 1, explain: \"A site owner can release the check-out. Copies create two versions of the truth.\" },\n          ] },\n        { type: \"check\", id: \"mosp-m8-l2-c1\", question: \"You want an external partner to read a confidential report without the link working for anyone else. Which link setting do you choose?\", options: [\"Anyone with the link, Can edit\", \"People in your organisation\", \"Specific people, Can view\", \"Anyone with the link, Can view\"], answer: 2, explain: \"Specific people only works for the addresses you enter, so a forwarded link is useless to others. Can view prevents changes.\" },\n        { type: \"task\", id: \"mosp-m8-l2-t1\", title: \"Practice\", items: [\n          \"Save a Word document to OneDrive and share it with one colleague as Can view\",\n          \"Ask a colleague to open the same file and edit it with you at the same time\",\n          \"Add a comment with an @mention and check that the e-mail notification arrives\",\n          \"Open Version History and restore a version from earlier in the day\",\n          \"Set one folder to Always keep on this device and check the icon changes\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Share files and folders in Microsoft OneDrive\", url: \"https://support.microsoft.com/en-us/onedrive/share-files-and-folders-in-microsoft-onedrive\", source: MS },\n          { label: \"Restore a previous version of a file stored in OneDrive\", url: \"https://support.microsoft.com/en-us/onedrive/restore-a-previous-version-of-a-file-stored-in-onedrive\", source: MS },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── LESSON 3 ───────────────────────────────\n    {\n      id: \"mosp-m8-l3\",\n      title: \"Capstone: the business deliverable package\",\n      minutes: 30,\n      objectives: [\n        \"Compute quarterly results in Excel and link them into a structured Word report\",\n        \"Summarise the results on clear PowerPoint slides\",\n        \"Send the package by Outlook to the right people with a secure OneDrive link and a final quality check\",\n      ],\n      blocks: [\n        { type: \"p\", text: \"This capstone brings the whole programme together. You play the role of a business analyst who must deliver the quarterly performance package to the Director General: one Excel workbook, one Word report, one short presentation and one e-mail. The labs below follow the same scenario from start to finish.\" },\n        { type: \"callout\", tone: \"workplace\", title: \"The brief\", text: \"AgroNova Distribution SARL sells seeds, fertiliser and small equipment to retailers from its head office in Bafoussam and three branches in Douala, Yaoundé and Garoua. The Director General, Mrs Chantal Ebongue, wants the Q3 2026 performance package on her desk by Friday 9 October, before the board meeting. The Finance Manager, Mr Paul Nkeng, must be kept informed.\" },\n        { type: \"h\", text: \"What the package contains\" },\n        { type: \"table\", head: [\"File\", \"Content\", \"Key skills\"], rows: [\n          [\"2026-Q3_Results.xlsx\", \"Targets, actual sales, achievement rate and status per region\", \"Formulas, absolute references, IF\"],\n          [\"2026-Q3_Performance-report.docx\", \"Heading styles, a table of contents, a linked results table, recommendations\", \"Styles, TOC, Paste link, captions\"],\n          [\"2026-Q3_Board-summary.pptx\", \"Five slides that tell the story in one minute each\", \"Clear titles, few bullets, linked chart\"],\n          [\"E-mail in Outlook\", \"A short message with one OneDrive link to the folder\", \"Recipients, subject, sharing permissions\"],\n        ] },\n        { type: \"h\", text: \"Step 1: compute the results in Excel\" },\n        { type: \"sheet\", id: \"mosp-m8-l3-sheet\", title: \"Q3 results by region\", task: \"Fill **D2:D5** with each region's achievement rate (actual divided by target), **E2:E5** with the variance (actual minus target), **F2:F5** with the status \\\"Achieved\\\" when the rate is 100% or more and \\\"Below target\\\" otherwise, then **B6:D6** with the totals and the overall rate.\",\n          data: [\n            [\"Region\", \"Target (FCFA)\", \"Actual (FCFA)\", \"Achievement\", \"Variance (FCFA)\", \"Status\"],\n            [\"Douala\", 42000000, 45150000, null, null, null],\n            [\"Yaoundé\", 38000000, 34960000, null, null, null],\n            [\"Bafoussam\", 25000000, 26250000, null, null, null],\n            [\"Garoua\", 18000000, 15300000, null, null, null],\n            [\"Total\", null, null, null],\n          ],\n          editable: [\"D2\", \"D3\", \"D4\", \"D5\", \"E2\", \"E3\", \"E4\", \"E5\", \"F2\", \"F3\", \"F4\", \"F5\", \"B6\", \"C6\", \"D6\"],\n          checks: [\n            { cell: \"D2\", equals: 1.075, tol: 0.0005 }, { cell: \"D3\", equals: 0.92, tol: 0.0005 }, { cell: \"D4\", equals: 1.05, tol: 0.0005 }, { cell: \"D5\", equals: 0.85, tol: 0.0005 },\n            { cell: \"E2\", equals: 3150000 }, { cell: \"E3\", equals: -3040000 }, { cell: \"E4\", equals: 1250000 }, { cell: \"E5\", equals: -2700000 },\n            { cell: \"F2\", equals: \"Achieved\" }, { cell: \"F3\", equals: \"Below target\" }, { cell: \"F4\", equals: \"Achieved\" }, { cell: \"F5\", equals: \"Below target\" },\n            { cell: \"B6\", equals: 123000000 }, { cell: \"C6\", equals: 121660000 }, { cell: \"D6\", equals: 0.9891, tol: 0.0005 },\n          ],\n          hint: \"D2 is =C2/B2 and E2 is =C2-B2. The status uses IF: =IF(D2>=1,\\\"Achieved\\\",\\\"Below target\\\"). The overall rate is the total actual divided by the total target, not the average of the four rates.\",\n          solution: {\n            D2: \"=C2/B2\", D3: \"=C3/B3\", D4: \"=C4/B4\", D5: \"=C5/B5\",\n            E2: \"=C2-B2\", E3: \"=C3-B3\", E4: \"=C4-B4\", E5: \"=C5-B5\",\n            F2: \"=IF(D2>=1,\\\"Achieved\\\",\\\"Below target\\\")\", F3: \"=IF(D3>=1,\\\"Achieved\\\",\\\"Below target\\\")\", F4: \"=IF(D4>=1,\\\"Achieved\\\",\\\"Below target\\\")\", F5: \"=IF(D5>=1,\\\"Achieved\\\",\\\"Below target\\\")\",\n            B6: \"=SUM(B2:B5)\", C6: \"=SUM(C2:C5)\", D6: \"=C6/B6\",\n          } },\n        { type: \"h\", text: \"Step 2: build the Word report\" },\n        { type: \"steps\", title: \"Report structure\", items: [\n          \"Apply **Heading 1** to the report title and chapter titles, and **Heading 2** to the sections inside them.\",\n          \"Insert a table of contents on page 2 with **References › Table of Contents** and choose an automatic style.\",\n          \"In Excel, copy A1:F6 and paste it into the Results section with **Link & Use Destination Styles**.\",\n          \"Add a caption under the table with **References › Insert Caption**, for example \\\"Table 1: Q3 2026 sales by region\\\".\",\n          \"When the figures change, update the links, then right-click the table of contents and choose **Update Field › Update entire table**.\",\n        ] },\n        { type: \"path\", items: [\"References\", \"Table of Contents\", \"Automatic Table 1\"] },\n        { type: \"doc\", id: \"mosp-m8-l3-doc\", title: \"Format the report section\", task: \"Make the title a **Heading 1**, make \\\"Results by region\\\" and \\\"Recommendations\\\" **Heading 2**, **justify** the results paragraph, make the total **121 660 000 FCFA bold**, and turn the three recommendations into a **numbered list**.\",\n          hint: \"Use the Styles menu for headings. Click inside the results paragraph before choosing Justify. Select the three recommendation lines together before clicking Numbering.\",\n          html: \"<p>Quarterly performance report: Q3 2026</p><p>AgroNova Distribution SARL, Bafoussam. Prepared by the sales analysis unit for the Director General.</p><p>Results by region</p><p>Total sales for the quarter reached 121 660 000 FCFA against a target of 123 000 000 FCFA, an achievement rate of 98.9%. Douala and Bafoussam exceeded their targets, while Yaoundé and Garoua fell short because of late deliveries and the rainy season.</p><p>Recommendations</p><p>Recruit a second sales representative for Garoua before the planting season</p><p>Review delivery schedules in Yaoundé with the transport contractor</p><p>Extend the Douala loyalty discount to retailers in Bafoussam</p><p>The results table is linked to the workbook 2026-Q3_Results.xlsx.</p>\",\n          checks: [\n            { kind: \"heading\", level: 1, text: \"Quarterly performance report\" },\n            { kind: \"heading\", level: 2, text: \"Results by region\" },\n            { kind: \"heading\", level: 2, text: \"Recommendations\" },\n            { kind: \"align\", text: \"Total sales for the quarter\", value: \"justify\" },\n            { kind: \"bold\", text: \"121 660 000 FCFA\" },\n            { kind: \"list\", ordered: true, min: 3 },\n          ] },\n        { type: \"h\", text: \"Step 3: a five-slide summary\" },\n        { type: \"table\", head: [\"Slide\", \"Title that states the message\", \"Content\"], rows: [\n          [\"1\", \"Q3 2026 performance package\", \"Company name, date, presenter\"],\n          [\"2\", \"Sales reached 98.9% of target\", \"Linked chart: target and actual by region\"],\n          [\"3\", \"Douala and Bafoussam beat their targets\", \"Two or three short bullets\"],\n          [\"4\", \"Garoua and Yaoundé need action\", \"Causes in a few words\"],\n          [\"5\", \"Three decisions for the board\", \"The recommendations from the report\"],\n        ] },\n        { type: \"slide\", id: \"mosp-m8-l3-slide\", title: \"Rewrite the key results slide\", task: \"Rewrite slide 2 for the board: a title of **8 words or fewer** that states the result, and **no more than 4 bullets** of **10 words or fewer**.\",\n          hint: \"Put the conclusion in the title, for example \\\"Q3 sales reached 98.9% of target\\\". Keep one idea per bullet and move details to the report.\",\n          slide: { title: \"Presentation of the sales results obtained by all the regions of the company during the third quarter of 2026\", bullets: [\n            \"The total sales of the company for the quarter were 121 660 000 FCFA compared with a target of 123 000 000 FCFA\",\n            \"Douala exceeded its target with an achievement rate of 107.5%, which is the best result of all the regions\",\n            \"Bafoussam also exceeded its target with an achievement rate of 105%\",\n            \"Yaoundé did not reach its target and achieved only 92% because of several late deliveries\",\n            \"Garoua was the weakest region with 85% of its target, mainly because of the rainy season and roads\",\n            \"The details of every region are available in the Word report and in the Excel workbook\",\n          ] },\n          rules: { maxBullets: 4, maxWords: 10, titleMaxWords: 8 } },\n        { type: \"h\", text: \"Step 4: send the package from Outlook\" },\n        { type: \"list\", items: [\n          \"**To**: the person who must act, here the Director General. **Cc**: people who only need to know, here the Finance Manager.\",\n          \"**Subject**: specific and searchable, for example \\\"Q3 2026 performance package for approval\\\".\",\n          \"**Body**: three to five lines: what is attached, the key result, what you expect and by when.\",\n          \"**Files**: one OneDrive or SharePoint link to the folder instead of three heavy attachments; check the link permissions before sending.\",\n          \"Use **Bcc** only for large external lists, never to hide a recipient from a colleague.\",\n        ] },\n        { type: \"form\", id: \"mosp-m8-l3-mail\", title: \"Prepare the e-mail to the Director General\", task: \"Complete the e-mail that sends the Q3 package to Mrs Ebongue, with Mr Nkeng informed.\",\n          hint: \"The person who must approve goes in To, the person who only needs to know goes in Cc. The link should work only for the people who need it.\",\n          fields: [\n            { kind: \"select\", label: \"Who goes in the To line?\", options: [\"Paul Nkeng, Finance Manager\", \"Chantal Ebongue, Director General\", \"All staff\", \"Nobody: use Bcc only\"], answer: 1, explain: \"She is the person who must read and approve the package.\" },\n            { kind: \"select\", label: \"Who goes in the Cc line?\", options: [\"Paul Nkeng, Finance Manager\", \"The transport contractor\", \"Chantal Ebongue, Director General\", \"The board members' personal addresses\"], answer: 0, explain: \"The Finance Manager is kept informed but is not asked to act.\" },\n            { kind: \"text\", label: \"Type a clear subject line that mentions the quarter and the year.\", pattern: \"(q3|third quarter|t3).*2026|2026.*(q3|third quarter|t3)\", example: \"Q3 2026 performance package for approval\", placeholder: \"Subject\", explain: \"A specific subject with the period makes the e-mail easy to find before the board meeting.\" },\n            { kind: \"select\", label: \"How do you give her the three files?\", options: [\"Attach the three files (about 18 MB)\", \"A link to the OneDrive folder shared with Specific people, Can view\", \"An Anyone link with Can edit\", \"Copy them on a USB drive\"], answer: 1, explain: \"One link keeps the package in one place, stays light on slow connections, and only she can open it.\" },\n            { kind: \"select\", label: \"The report's table is linked to the workbook. What must you do before exporting the report to PDF?\", options: [\"Nothing, PDFs update themselves\", \"Update the links and the table of contents, then export\", \"Delete the table\", \"Change the paste option to Keep Text Only\"], answer: 1, explain: \"A PDF freezes whatever the report shows at export time, so refresh the links and the table of contents first.\" },\n          ] },\n        { type: \"h\", text: \"Quality checklist before you press Send\" },\n        { type: \"list\", items: [\n          \"The totals in Word and PowerPoint match the workbook exactly after updating the links.\",\n          \"The table of contents is updated and all headings use Heading styles.\",\n          \"Every slide title states a message; no slide has more than four or five bullets.\",\n          \"Spelling is checked in the right language for each passage (French and English).\",\n          \"File names follow the team convention and the files sit in the shared folder.\",\n          \"The link permissions are Specific people and Can view for the Director General.\",\n          \"Nothing confidential is embedded: no hidden sheets, comments or personal notes remain (File › Info › Check for Issues › Inspect Document).\",\n        ] },\n        { type: \"path\", items: [\"File\", \"Info\", \"Check for Issues\", \"Inspect Document\"], note: \"Finds comments, hidden text, document properties and embedded content before you share.\" },\n        { type: \"check\", id: \"mosp-m8-l3-c1\", question: \"The workbook shows a total of 121 660 000 FCFA but the Word report still shows 119 800 000 FCFA. What is the most likely cause?\", options: [\"The report was pasted as a picture or the linked table has not been updated\", \"Word rounds large numbers\", \"Excel has a formula error\", \"The PDF was exported too early\"], answer: 0, explain: \"A picture never changes, and a link shows new figures only after it is updated (right-click › Update Link, or F9). Always compare the totals before sending.\" },\n        { type: \"task\", id: \"mosp-m8-l3-t1\", title: \"Practice\", items: [\n          \"Build the AgroNova results workbook and save it to a OneDrive folder named 2026-Q3_Package\",\n          \"Write a two-page Word report with a table of contents, a linked results table and a caption\",\n          \"Create the five-slide summary with a linked chart on slide 2\",\n          \"Draft the Outlook e-mail with the right To and Cc recipients and a view-only folder link\",\n          \"Go through the quality checklist and run Inspect Document on the report\",\n        ] },\n        { type: \"links\", items: [\n          { label: \"Exam MO-110: Microsoft Word (Microsoft 365 Apps)\", url: \"https://learn.microsoft.com/en-us/credentials/certifications/exams/mo-110/\", source: LEARN },\n          { label: \"Exam MO-400: Microsoft Outlook\", url: \"https://learn.microsoft.com/en-us/credentials/certifications/exams/mo-400/\", source: LEARN },\n        ] },\n      ],\n    },\n    // ─────────────────────────────── PRACTICE ───────────────────────────────\n    {\n      id: \"mosp-m8-practice\",\n      title: \"Practice lab: integrated Office deliverables\",\n      minutes: 40,\n      objectives: [\n        \"Choose paste options for tables and charts moved between Office apps\",\n        \"Format a report section that presents linked figures\",\n        \"Clean and summarise exported data with Excel formulas\",\n        \"Combine Excel, Word, PowerPoint, OneDrive and Outlook decisions in one deliverable\",\n      ],\n      blocks: [\n        INTRO,\n        { type: \"h\", text: \"Exercise 1: The school enrolment brief\" },\n        { type: \"form\", id: \"mosp-pr-m8-paste\", level: \"beginner\", title: \"Paste the enrolment figures\",\n          task: \"A regional education delegation in Bertoua keeps its school enrolment figures in Excel. Choose the paste option for each document.\",\n          hint: \"Link when the figures will change and must be refreshed. Picture for final documents. Destination styles to match the document, source formatting to keep the Excel look.\",\n          fields: [\n            { kind: \"select\", label: \"A weekly Word bulletin must show the latest enrolment table in the bulletin's own style.\", options: PASTE, answer: 3, explain: \"The figures change every week and the table should look like the bulletin.\" },\n            { kind: \"select\", label: \"The signed annual report sent to the ministry as a PDF.\", options: PASTE, answer: 4, explain: \"A picture keeps the figures exactly as approved.\" },\n            { kind: \"select\", label: \"You need only the list of school names to paste into an e-mail.\", options: PASTE, answer: 5 },\n            { kind: \"select\", label: \"A one-time copy of the table for a Word memo, matching the memo's fonts.\", options: PASTE, answer: 1, explain: \"No link is needed for a one-off copy, and the memo's style should win.\" },\n          ] },\n        { type: \"h\", text: \"Exercise 2: The cooperative's monthly note\" },\n        { type: \"doc\", id: \"mosp-pr-m8-note\", level: \"intermediate\", title: \"Format a note with linked figures\",\n          task: \"Make the title a **Heading 1**, \\\"Deliveries in May\\\" and \\\"Next steps\\\" **Heading 2**, **justify** the paragraph about deliveries, make **4 850 kg** bold, and turn the three next steps into a **bulleted list**.\",\n          hint: \"Headings come from the Styles menu. Select only 4 850 kg before clicking Bold. Select the three step lines together before clicking Bullets.\",\n          html: \"<p>Foumbot market gardeners' cooperative: monthly note</p><p>Prepared for the management committee, June 2026.</p><p>Deliveries in May</p><p>Members delivered 4 850 kg of tomatoes and peppers to the Douala wholesalers in May, an increase of 12% on April. The figures below are linked to the cooperative's delivery workbook and are refreshed before each committee meeting.</p><p>Next steps</p><p>Renew the transport contract before the end of June</p><p>Train ten new members in grading and packing</p><p>Share this note in the cooperative's OneDrive folder</p>\",\n          checks: [\n            { kind: \"heading\", level: 1, text: \"Foumbot market gardeners\" },\n            { kind: \"heading\", level: 2, text: \"Deliveries in May\" },\n            { kind: \"heading\", level: 2, text: \"Next steps\" },\n            { kind: \"align\", text: \"Members delivered\", value: \"justify\" },\n            { kind: \"bold\", text: \"4 850 kg\" },\n            { kind: \"list\", ordered: false, min: 3 },\n          ] },\n        { type: \"h\", text: \"Exercise 3: A messy mobile money export\" },\n        { type: \"sheet\", id: \"mosp-pr-m8-momo\", level: \"advanced\", title: \"Clean the collections before linking them\",\n          task: \"A microfinance branch exported its collections with amounts stored as text, and one receipt is still pending. Fill **E2:E8** with each amount as a real number (0 for the pending receipt), then **H2:H5**: the Douala MoMo total, the number of non-cash receipts of 100 000 FCFA or more, the number of pending receipts and the average confirmed amount.\",\n          data: [\n            [\"Receipt\", \"Town\", \"Channel\", \"Amount (text)\", \"Amount\", null, \"Measure\", \"Result\"],\n            [\"R-101\", \"Douala\", \"MoMo\", \"125 000 FCFA\", null, null, \"Douala MoMo total\", null],\n            [\"R-102\", \"Yaoundé\", \"Cash\", \"80 000 FCFA\", null, null, \"Non-cash ≥ 100 000\", null],\n            [\"R-103\", \"Douala\", \"Orange Money\", \"210 000 FCFA\", null, null, \"Pending receipts\", null],\n            [\"R-104\", \"Douala\", \"MoMo\", \"pending\", null, null, \"Average confirmed\", null],\n            [\"R-105\", \"Bafoussam\", \"MoMo\", \"95 500 FCFA\"],\n            [\"R-106\", \"Douala\", \"MoMo\", \"150 000 FCFA\"],\n            [\"R-107\", \"Yaoundé\", \"Orange Money\", \"60 000 FCFA\"],\n          ],\n          editable: [\"E2\", \"E3\", \"E4\", \"E5\", \"E6\", \"E7\", \"E8\", \"H2\", \"H3\", \"H4\", \"H5\"],\n          checks: [\n            { cell: \"E2\", equals: 125000 }, { cell: \"E3\", equals: 80000 }, { cell: \"E4\", equals: 210000 }, { cell: \"E5\", equals: 0 },\n            { cell: \"E6\", equals: 95500 }, { cell: \"E7\", equals: 150000 }, { cell: \"E8\", equals: 60000 },\n            { cell: \"H2\", equals: 275000 }, { cell: \"H3\", equals: 3 }, { cell: \"H4\", equals: 1 }, { cell: \"H5\", equals: 120083.33, tol: 0.01 },\n          ],\n          hint: \"Remove \\\" FCFA\\\" and the spaces with SUBSTITUTE, convert with VALUE, and wrap everything in IFERROR(…,0) for the pending receipt. Then use SUMIFS with two criteria, COUNTIFS with \\\"<>Cash\\\" and \\\">=100000\\\", COUNTIF on the text column, and AVERAGEIF with \\\">0\\\".\",\n          solution: {\n            E2: \"=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(D2,\\\" FCFA\\\",\\\"\\\"),\\\" \\\",\\\"\\\")),0)\",\n            E3: \"=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(D3,\\\" FCFA\\\",\\\"\\\"),\\\" \\\",\\\"\\\")),0)\",\n            E4: \"=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(D4,\\\" FCFA\\\",\\\"\\\"),\\\" \\\",\\\"\\\")),0)\",\n            E5: \"=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(D5,\\\" FCFA\\\",\\\"\\\"),\\\" \\\",\\\"\\\")),0)\",\n            E6: \"=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(D6,\\\" FCFA\\\",\\\"\\\"),\\\" \\\",\\\"\\\")),0)\",\n            E7: \"=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(D7,\\\" FCFA\\\",\\\"\\\"),\\\" \\\",\\\"\\\")),0)\",\n            E8: \"=IFERROR(VALUE(SUBSTITUTE(SUBSTITUTE(D8,\\\" FCFA\\\",\\\"\\\"),\\\" \\\",\\\"\\\")),0)\",\n            H2: \"=SUMIFS(E2:E8,B2:B8,\\\"Douala\\\",C2:C8,\\\"MoMo\\\")\",\n            H3: \"=COUNTIFS(C2:C8,\\\"<>Cash\\\",E2:E8,\\\">=100000\\\")\",\n            H4: \"=COUNTIF(D2:D8,\\\"pending\\\")\",\n            H5: \"=AVERAGEIF(E2:E8,\\\">0\\\")\",\n          } },\n        { type: \"h\", text: \"Exercise 4: The donor report package\" },\n        { type: \"form\", id: \"mosp-pr-m8-donor\", level: \"expert\", title: \"Deliver the half-year donor package\",\n          task: \"The NGO Femmes Actives du Nord in Garoua must send its half-year report to a donor. Targets are in B2:B6 and women reached in C2:C6 of the Excel workbook. Answer each question across Excel, Word, PowerPoint, OneDrive and Outlook. Type formulas starting with =.\",\n          hint: \"Overall rate = total reached divided by total target. Words in the report should update from Excel; anything leaving the NGO should be fixed and view-only. The donor contact acts, the country director is informed.\",\n          fields: [\n            { kind: \"text\", label: \"Excel: type the formula for the overall reach rate of the five activities.\", accept: [\"=SUM(C2:C6)/SUM(B2:B6)\"], pattern: \"^=SUM\\\\(\\\\$?C\\\\$?2:\\\\$?C\\\\$?6\\\\)/SUM\\\\(\\\\$?B\\\\$?2:\\\\$?B\\\\$?6\\\\)$\", example: \"=SUM(C2:C6)/SUM(B2:B6)\", placeholder: \"=…\", mono: true, explain: \"Divide the totals. An average of the five rates would give small activities the same weight as large ones.\" },\n            { kind: \"select\", label: \"Word draft: the results table must match the report's styles and follow corrections made in Excel.\", options: PASTE, answer: 3 },\n            { kind: \"select\", label: \"Word draft: the field team corrected two figures in Excel. How do you refresh every link in the report at once?\", options: [\"Ctrl + A, then F9\", \"Ctrl + S\", \"Ctrl + Shift + F9\", \"Close and reopen Excel\"], answer: 0, explain: \"Select everything and press F9. Ctrl + Shift + F9 would unlink the tables instead.\" },\n            { kind: \"select\", label: \"PowerPoint: the chart for the donor's slide deck, sent as a file outside the NGO.\", options: [\"Use Destination Theme & Embed Workbook\", \"Use Destination Theme & Link Data\", \"Picture\", \"Keep Source Formatting & Embed Workbook\"], answer: 2, explain: \"The workbook holds beneficiaries' names. A picture shares only the chart.\" },\n            { kind: \"select\", label: \"OneDrive: how do you share the final folder with the donor's programme officer?\", options: SHARE, answer: 1, explain: \"Only the named person can open it, and nobody outside the NGO can change the final files.\" },\n            { kind: \"select\", label: \"Outlook: the donor's programme officer must acknowledge the report; the NGO's country director should see the message. Where does the country director go?\", options: [\"To\", \"Cc\", \"Bcc\", \"Nowhere: forward it later\"], answer: 1, explain: \"Cc is for people kept informed who are not asked to act.\" },\n            { kind: \"text\", label: \"Name the PDF sent on 15 July 2026 with the date_subject_version pattern, first version.\", pattern: \"^2026-07-15_[A-Za-z0-9À-ÿ][A-Za-z0-9À-ÿ-]*_v1\\\\.pdf$\", example: \"2026-07-15_Rapport-semestriel-bailleur_v1.pdf\", placeholder: \"2026-…\", mono: true, explain: \"Copies that leave the team carry a version number; files inside the shared folder rely on Version History.\" },\n            { kind: \"select\", label: \"Before sending, which command finds hidden comments and personal information in the Word report?\", options: [\"File › Info › Check for Issues › Inspect Document\", \"Review › Spelling & Grammar\", \"View › Navigation Pane\", \"Home › Styles\"], answer: 0 },\n          ] },\n      ],\n    },\n  ],\n  quiz: {\n    id: \"mosp-m8-quiz\",\n    title: \"Module 8 Quiz\",\n    passPct: 70,\n    questions: [\n      { id: \"q1\", question: \"What does Paste Special › Paste link create in Word?\", options: [\"A picture of the Excel range\", \"A full copy of the workbook inside the document\", \"A table that shows the workbook's data and can be updated\", \"A hyperlink that opens a website\"], answer: 2, explain: \"A linked object displays data stored in the Excel file and is refreshed with Update Link or F9.\" },\n      { id: \"q2\", question: \"Which action most often breaks a link between Word and Excel?\", options: [\"Moving or renaming the Excel workbook\", \"Changing a figure in Excel\", \"Printing the Word report\", \"Opening the report on another day\"], answer: 0, explain: \"The link stores the workbook's path. When the path changes, use Change Source to repair it.\" },\n      { id: \"q3\", question: \"Where can you see, update and break all the links in a Word or PowerPoint file?\", options: [\"Home › Paste\", \"Review › Compare\", \"Insert › Link\", \"File › Info › Edit Links to Files\"], answer: 3, explain: \"The Edit Links dialog lists each link with Update Now, Change Source and Break Link.\" },\n      { id: \"q4\", question: \"Why can embedding an Excel chart in a presentation be risky?\", options: [\"The chart cannot be resized\", \"The entire workbook, including other sheets, is stored in the presentation\", \"The chart updates every time Excel opens\", \"Embedded charts cannot be printed\"], answer: 1, explain: \"An embedded object carries a full copy of the workbook, which anyone who receives the file can open.\" },\n      { id: \"q5\", question: \"An external auditor must read your final accounts. Which sharing option fits best?\", options: [\"Anyone with the link, Can edit\", \"People in your organisation, Can view\", \"Specific people, Can view\", \"Anyone with the link, Can view\"], answer: 2, explain: \"Only the named auditor can open the file, and view access prevents changes.\" },\n      { id: \"q6\", question: \"A colleague overwrote your section of a shared report this morning. What is the quickest way to recover it?\", options: [\"Version History\", \"Ctrl + Z\", \"Recycle Bin\", \"Inspect Document\"], answer: 0, explain: \"Version History keeps earlier versions of cloud files; open the version from before the change and restore it or copy the section.\" },\n      { id: \"q7\", question: \"In File Explorer, a OneDrive file shows a blue cloud icon. What does it mean?\", options: [\"The file is syncing\", \"The file has an error\", \"The file is shared with Anyone\", \"The file is online-only and needs the internet to open\"], answer: 3, explain: \"Choose Always keep on this device before travelling so the file stays available offline.\" },\n      { id: \"q8\", question: \"You send an 18 MB package of three files to the Director General. What is the best practice?\", options: [\"Attach the three files and Cc everyone\", \"Send one link to the shared folder with view permission for her\", \"Send each file in a separate e-mail\", \"Put the files on a USB drive\"], answer: 1, explain: \"One link is light on the network, keeps a single copy of each file, and lets you control access.\" },\n    ],\n  },\n};\n"};
