const PATCHES = [["client/src/lms/labs/formula.ts","SUBSTITUE: \"SUBSTITUTE\",","SUBSTITUE: \"SUBSTITUTE\",\n  \"SI.CONDITIONS\": \"IFS\", \"SOMME.SI.ENS\": \"SUMIFS\", \"NB.SI.ENS\": \"COUNTIFS\", \"MOYENNE.SI.ENS\": \"AVERAGEIFS\", RECHERCHEX: \"XLOOKUP\", EQUIV: \"MATCH\",\n  VPM: \"PMT\", \"ARRONDI.SUP\": \"ROUNDUP\", \"ARRONDI.INF\": \"ROUNDDOWN\", NOMPROPRE: \"PROPER\", \"NB.VIDE\": \"COUNTBLANK\", ENT: \"INT\", PRODUIT: \"PRODUCT\","],["client/src/lms/labs/formula.ts","          case \"VLOOKUP\": {","          case \"IFS\": {\n            for (let i = 0; i + 1 < n.args.length; i += 2) { const c = toBool(arg(i)); if (isErr(c)) return c; if (c) return arg(i + 1); }\n            return err(ERR.na);\n          }\n          case \"SUMIFS\": case \"COUNTIFS\": case \"AVERAGEIFS\": {\n            const first = name === \"COUNTIFS\" ? 0 : 1;\n            if ((n.args.length - first) < 2 || (n.args.length - first) % 2) return err(ERR.value);\n            const ranges: Value[][] = [];\n            for (let i = first; i < n.args.length; i += 2) { const r = n.args[i]; if (r?.k !== \"range\") return err(ERR.value); ranges.push(rangeCells(r.a, r.b).flat()); }\n            const size = ranges[0]?.length ?? 0;\n            if (ranges.some((r) => r.length !== size)) return err(ERR.value);\n            const crits: Value[] = []; for (let i = first + 1; i < n.args.length; i += 2) crits.push(arg(i));\n            const keep = [...Array(size).keys()].filter((k) => ranges.every((r, j) => matchCriteria(r[k] as Value, crits[j] as Value)));\n            if (name === \"COUNTIFS\") return keep.length;\n            const s = n.args[0]; if (s?.k !== \"range\") return err(ERR.value);\n            const vals = rangeCells(s.a, s.b).flat(); if (vals.length !== size) return err(ERR.value);\n            const x = nums(keep.map((k) => vals[k] as Value));\n            if (name === \"SUMIFS\") return x.reduce((a, b) => a + b, 0);\n            return x.length ? x.reduce((a, b) => a + b, 0) / x.length : err(ERR.div0);\n          }\n          case \"XLOOKUP\": {\n            const la = n.args[1], ra = n.args[2];\n            if (la?.k !== \"range\" || ra?.k !== \"range\") return err(ERR.value);\n            const keys = rangeCells(la.a, la.b).flat(), vals = rangeCells(ra.a, ra.b).flat();\n            if (keys.length !== vals.length) return err(ERR.value);\n            const key = arg(0); if (isErr(key)) return key;\n            const k = keys.findIndex((v) => typeof key === \"number\" ? v === key : toStr(v).toLowerCase() === toStr(key).toLowerCase());\n            if (k >= 0) return vals[k] ?? \"\";\n            return n.args.length > 3 ? arg(3) : err(ERR.na);\n          }\n          case \"MATCH\": {\n            const la = n.args[1]; if (la?.k !== \"range\") return err(ERR.value);\n            const keys = rangeCells(la.a, la.b).flat();\n            const key = arg(0); if (isErr(key)) return key;\n            const type = n.args.length > 2 ? toNum(arg(2)) : 1; if (isErr(type)) return type;\n            if (type === 0) {\n              const k = keys.findIndex((v) => typeof key === \"number\" ? v === key : toStr(v).toLowerCase() === toStr(key).toLowerCase());\n              return k >= 0 ? k + 1 : err(ERR.na);\n            }\n            if (typeof key !== \"number\") return err(ERR.na);\n            let best = -1;\n            keys.forEach((v, i) => { if (typeof v === \"number\" && (type > 0 ? v <= key : v >= key)) best = i; });\n            return best >= 0 ? best + 1 : err(ERR.na);\n          }\n          case \"INDEX\": {\n            const t = n.args[0]; if (t?.k !== \"range\") return err(ERR.value);\n            const rows = rangeCells(t.a, t.b);\n            let r = toNum(arg(1)); if (isErr(r)) return r;\n            let c = n.args.length > 2 ? toNum(arg(2)) : 1; if (isErr(c)) return c;\n            if (rows.length === 1 && n.args.length === 2) { c = r; r = 1; }\n            const v = rows[Math.trunc(r) - 1]?.[Math.trunc(c) - 1];\n            return v === undefined ? err(ERR.ref) : v;\n          }\n          case \"PMT\": {\n            const r = toNum(arg(0)), np = toNum(arg(1)), pv = toNum(arg(2));\n            const fv = n.args.length > 3 ? toNum(arg(3)) : 0, ty = n.args.length > 4 ? toNum(arg(4)) : 0;\n            const e = [r, np, pv, fv, ty].find(isErr); if (e) return e;\n            const R = r as number, N = np as number, P = pv as number, F = fv as number, T = ty as number;\n            if (N === 0) return err(ERR.div0);\n            if (R === 0) return -(P + F) / N;\n            const g = (1 + R) ** N;\n            return -(R * (F + P * g)) / ((1 + R * T) * (g - 1));\n          }\n          case \"ROUNDUP\": case \"ROUNDDOWN\": {\n            const x = toNum(arg(0)), d = n.args.length > 1 ? toNum(arg(1)) : 0;\n            if (isErr(x)) return x; if (isErr(d)) return d;\n            const f = 10 ** Math.trunc(d), y = Math.abs(x) * f;\n            const m = name === \"ROUNDUP\" ? Math.ceil(y - 1e-9) : Math.floor(y + 1e-9);\n            return Math.sign(x) * m / f;\n          }\n          case \"INT\": { const x = toNum(arg(0)); return isErr(x) ? x : Math.floor(x); }\n          case \"PRODUCT\": { const v = flat(n.args); return firstErr(v) ?? nums(v).reduce((s, x) => s * x, 1); }\n          case \"COUNTBLANK\": return flat(n.args).filter((v) => v === \"\").length;\n          case \"PROPER\": { const s = arg(0); return isErr(s) ? s : toStr(s).toLowerCase().replace(/(^|[^a-zà-ÿ])([a-zà-ÿ])/g, (_m, a: string, b: string) => a + b.toUpperCase()); }\n          case \"VLOOKUP\": {"],["client/src/data/courses/mosp.ts","import type { CourseModule, LmsCourse, Lesson } from \"../../lms/types\";","import type { CourseModule, LmsCourse } from \"../../lms/types\";\nimport { m3 } from \"./mosp/m3\";\nimport { m4 } from \"./mosp/m4\";\nimport { m5 } from \"./mosp/m5\";\nimport { m6 } from \"./mosp/m6\";\nimport { m7 } from \"./mosp/m7\";\nimport { m8 } from \"./mosp/m8\";"],["client/src/data/courses/mosp.ts","const outline = (id: string, titles: string[]): Lesson[] =>\n  titles.map((title, i) => ({ id: `${id}-l${i + 1}`, title, minutes: 20, objectives: [], blocks: [] }));\n\n",""],["client/src/data/courses/mosp.ts","// ─────────────────────────── MODULES 3–8 (outline) ───────────────────────────\n\nconst coming = (n: number, title: string, summary: string, hours: number, lessons: string[]): CourseModule => ({\n  id: `mosp-m${n}`, number: n, title, summary, hours, lessons: outline(`mosp-m${n}`, lessons), comingSoon: true,\n});\n\n",""],["client/src/data/courses/mosp.ts","    coming(3, \"Microsoft Word — Advanced Document Production\", \"Tables, mail merge, Track Changes, tables of contents and templates.\", 10, [\n      \"Tables that organise data\", \"Mail merge for letters and labels\", \"Reviewing with comments and Track Changes\", \"Tables of contents, captions and templates\"]),\n    coming(4, \"Microsoft Excel — Spreadsheet Fundamentals\", \"Workbooks, formulas, cell references, sorting, filtering and charts.\", 12, [\n      \"Your first workbook\", \"Formulas and cell references\", \"Sort, filter and format data\", \"Charts and printing\"]),\n    coming(5, \"Microsoft Excel — Advanced Data Analysis\", \"Logical and lookup functions, PivotTables, dashboards and What-If analysis.\", 12, [\n      \"IF, AND, OR and IFS\", \"XLOOKUP, VLOOKUP and INDEX-MATCH\", \"PivotTables and PivotCharts\", \"What-If analysis and protection\"]),\n    coming(6, \"Microsoft PowerPoint — Professional Presentations\", \"Design, Slide Master, visuals, animation and delivery.\", 10, [\n      \"Designing clear slides\", \"Slide Master and branding\", \"Charts, SmartArt and media\", \"Rehearsing and delivering\"]),\n    coming(7, \"Microsoft Outlook — Professional Communication & Organization\", \"E-mail, calendar, contacts, tasks and inbox management.\", 8, [\n      \"Professional e-mail\", \"Inbox rules and folders\", \"Calendar and meetings\", \"Tasks and contacts\"]),\n    coming(8, \"Integrated Office Skills & Capstone Project\", \"Combine Word, Excel, PowerPoint and Outlook in one professional deliverable.\", 10, [\n      \"Linking Excel data into Word and PowerPoint\", \"Collaboration in OneDrive and SharePoint\", \"Capstone: the business deliverable package\"]),\n","    m3,\n    m4,\n    m5,\n    m6,\n    m7,\n    m8,\n"]];
const FR = {"Create a table from scratch or by converting existing text":"Créer un tableau de zéro ou en convertissant un texte existant","Format, sort and total a table, and repeat its header row on every page":"Mettre en forme, trier et totaliser un tableau, et répéter sa ligne d'en-tête sur chaque page","Decide when a Word table is enough and when the data belongs in Excel":"Décider quand un tableau Word suffit et quand les données doivent aller dans Excel","Price lists, staff rosters, training schedules and budget summaries all read better in a table than in paragraphs separated by tabs and spaces. A Word table keeps columns aligned whatever the font, grows with its content and can be sorted and totalled without retyping anything.":"Les listes de prix, les plannings du personnel, les calendriers de formation et les résumés budgétaires se lisent mieux dans un tableau que dans des paragraphes séparés par des tabulations et des espaces. Un tableau Word garde les colonnes alignées quelle que soit la police, s'agrandit avec son contenu et peut être trié et totalisé sans rien ressaisir.","Three ways to create a table":"Trois façons de créer un tableau","Method":"Méthode","How":"Comment","Best for":"Idéal pour","Quick grid":"Grille rapide","Insert › Table, then drag over the grid":"Insertion › Tableau, puis faites glisser la souris sur la grille","Small tables up to 10 columns and 8 rows":"Les petits tableaux, jusqu'à 10 colonnes et 8 lignes","Insert Table dialog":"Boîte de dialogue Insérer un tableau","Insert › Table › Insert Table, then type the number of columns and rows":"Insertion › Tableau › Insérer un tableau, puis saisissez le nombre de colonnes et de lignes","Larger tables, or when you want a fixed column width from the start":"Les grands tableaux, ou quand vous voulez une largeur de colonne fixe dès le départ","Convert Text to Table":"Convertir le texte en tableau","Select text separated by tabs, commas or paragraphs, then Insert › Table › Convert Text to Table":"Sélectionnez un texte séparé par des tabulations, des points-virgules ou des paragraphes, puis Insertion › Tableau › Convertir le texte en tableau","Lists copied from an e-mail, a website or an old document":"Les listes copiées d'un e-mail, d'un site web ou d'un ancien document","Table":"Tableau","Word guesses the separator. Check the number of columns before clicking OK.":"Word devine le séparateur. Vérifiez le nombre de colonnes avant de cliquer sur OK.","Convert a tabbed list into a table":"Convertir une liste tabulée en tableau","Turn on Show/Hide ¶ to check that each line uses the same separator, for example one tab between columns.":"Activez Afficher tout ¶ pour vérifier que chaque ligne utilise le même séparateur, par exemple une tabulation entre les colonnes.","Select all the lines, including the header line.":"Sélectionnez toutes les lignes, y compris la ligne d'en-tête.","Insert › Table › Convert Text to Table":"Insertion › Tableau › Convertir le texte en tableau","Under Separate text at, choose":"Sous Séparer le texte au niveau des, choisissez","Tabs":"Tabulations","(or Commas), check the number of columns and click OK.":"(ou Points-virgules), vérifiez le nombre de colonnes et cliquez sur OK.","Make it readable with Table Design":"Rendre le tableau lisible avec Création de tableau","Table Styles":"Les styles de tableau","apply borders, shading and header formatting in one click. Choose a light style for documents that will be printed in black and white.":"appliquent bordures, trames et mise en forme de l'en-tête en un clic. Choisissez un style clair pour les documents imprimés en noir et blanc.","Table Style Options":"Les options de style de tableau","switch parts of the style on or off: Header Row, Total Row, Banded Rows, First Column.":"activent ou désactivent des parties du style : Ligne d'en-tête, Ligne Total, Lignes à bandes, Première colonne.","Borders":"Bordures","Shading":"Trame de fond","adjust individual cells when a style is not enough.":"ajustent des cellules précises quand un style ne suffit pas.","Headers that repeat on every page":"Des en-têtes qui se répètent sur chaque page","When a table runs over several pages, readers of page 3 no longer know what each column means. Word can repeat the header row automatically at the top of every page.":"Quand un tableau s'étend sur plusieurs pages, le lecteur de la page 3 ne sait plus à quoi correspond chaque colonne. Word peut répéter automatiquement la ligne d'en-tête en haut de chaque page.","Table Layout":"Disposition","Data":"Données","Repeat Header Rows":"Répéter les lignes d'en-tête","Click in the first row (or select the first rows) before clicking. The same option is in Table Properties › Row.":"Cliquez dans la première ligne (ou sélectionnez les premières lignes) avant de cliquer. La même option se trouve dans Propriétés du tableau › Ligne.","Never retype the header":"Ne ressaisissez jamais l'en-tête","A header typed again by hand at the top of page 2 moves to the middle of a page as soon as rows are added or deleted. Repeat Header Rows follows the page breaks for you.":"Un en-tête retapé à la main en haut de la page 2 se retrouve au milieu d'une page dès que des lignes sont ajoutées ou supprimées. Répéter les lignes d'en-tête suit les sauts de page à votre place.","Merge, split, sort and total":"Fusionner, fractionner, trier et totaliser","Command":"Commande","Where":"Emplacement","Use it to":"Utilisez-la pour","Merge Cells":"Fusionner les cellules","Table Layout › Merge":"Disposition › Fusionner","Join cells into one, for example a title across the whole table":"Réunir plusieurs cellules en une, par exemple un titre sur toute la largeur du tableau","Split Cells":"Fractionner les cellules","Divide one cell into several columns or rows":"Diviser une cellule en plusieurs colonnes ou lignes","Sort":"Trier","Table Layout › Data":"Disposition › Données","Order rows by name, amount or date. Tick \"My list has a header row\" so the header stays on top":"Classer les lignes par nom, montant ou date. Cochez « Ma liste a une ligne d'en-tête » pour que l'en-tête reste en haut","Formula":"Formule","Add a total with a formula field such as =SUM(ABOVE) or =SUM(LEFT)":"Ajouter un total avec un champ formule comme =SUM(ABOVE) ou =SUM(LEFT)","Convert to Text":"Convertir en texte","Turn a table back into tabbed or comma-separated text":"Retransformer un tableau en texte séparé par des tabulations ou des points-virgules","Total a column with a formula":"Totaliser une colonne avec une formule","Click in the empty cell at the bottom of the amount column.":"Cliquez dans la cellule vide en bas de la colonne des montants.","Table Layout › Data › Formula":"Disposition › Données › Formule","Word proposes =SUM(ABOVE). Keep it, choose a number format if you want one, and click OK.":"Word propose =SUM(ABOVE). Gardez-la, choisissez un format de nombre si vous le souhaitez, puis cliquez sur OK.","If you change an amount later, click the total and press F9 to update it.":"Si vous modifiez un montant plus tard, cliquez sur le total et appuyez sur F9 pour le mettre à jour.","Word formulas do not recalculate by themselves":"Les formules Word ne se recalculent pas toutes seules","A Word formula is a field: it calculates once and then waits. After any change, select the table and press F9. If you need many formulas, percentages or frequent updates, keep the data in Excel.":"Une formule Word est un champ : elle calcule une fois, puis attend. Après toute modification, sélectionnez le tableau et appuyez sur F9. Si vous avez besoin de nombreuses formules, de pourcentages ou de mises à jour fréquentes, gardez les données dans Excel.","AutoFit and alignment":"Ajustement automatique et alignement","AutoFit Contents":"Ajuster au contenu","makes each column as wide as its longest entry.":"donne à chaque colonne la largeur de sa plus longue entrée.","AutoFit Window":"Ajuster à la fenêtre","stretches the table to the margins. Both are under Table Layout › Cell Size › AutoFit.":"étire le tableau jusqu'aux marges. Les deux se trouvent dans Disposition › Taille de la cellule › Ajustement automatique.","Distribute Columns":"Distribuer les colonnes","gives selected columns the same width, which looks tidy for dates or amounts.":"donne la même largeur aux colonnes sélectionnées, ce qui est net pour des dates ou des montants.","Use the nine buttons in Table Layout › Alignment: left-align text, right-align amounts so the units line up, and centre short codes.":"Utilisez les neuf boutons de Disposition › Alignement : alignez le texte à gauche, les montants à droite pour que les unités soient alignées, et centrez les codes courts.","Word table or Excel?":"Tableau Word ou Excel ?","Situation":"Situation","Best tool":"Meilleur outil","A schedule, a contact list or a price list inside a letter or report":"Un planning, une liste de contacts ou une liste de prix dans une lettre ou un rapport","Word table":"Tableau Word","One or two totals that rarely change":"Un ou deux totaux qui changent rarement","Word table with =SUM(ABOVE)":"Tableau Word avec =SUM(ABOVE)","Many calculations, percentages, filters or a chart":"Beaucoup de calculs, des pourcentages, des filtres ou un graphique","Excel, then paste or link the result into Word (Module 8)":"Excel, puis collez ou liez le résultat dans Word (module 8)","A list that will be reused for a mail merge":"Une liste qui servira pour un publipostage","Excel, one row per person (Lesson 2)":"Excel, une ligne par personne (leçon 2)","A hardware shop in Bafoussam sends its monthly price list to 40 building contractors. With the list in a Word table sorted by product, right-aligned prices and a header row that repeats on every page, the three-page document is easy to read on paper and on a phone.":"Une quincaillerie de Bafoussam envoie chaque mois sa liste de prix à 40 entrepreneurs du bâtiment. Avec la liste dans un tableau Word trié par produit, des prix alignés à droite et une ligne d'en-tête répétée sur chaque page, le document de trois pages se lit facilement sur papier comme sur téléphone.","Choose the right table command":"Choisir la bonne commande de tableau","A training centre in Yaoundé keeps its course timetable in a Word table. Choose the right command for each request, then type the formulas.":"Un centre de formation de Yaoundé tient son emploi du temps des cours dans un tableau Word. Choisissez la bonne commande pour chaque demande, puis saisissez les formules.","Almost every table command is on the Table Layout tab. Formulas are fields: SUM with ABOVE adds the column above, SUM with LEFT adds the row to the left.":"Presque toutes les commandes de tableau se trouvent dans l'onglet Disposition. Les formules sont des champs : SUM avec ABOVE additionne la colonne au-dessus, SUM avec LEFT additionne la ligne à gauche.","The timetable runs over three pages and the column titles must appear at the top of each page.":"L'emploi du temps occupe trois pages et les titres des colonnes doivent apparaître en haut de chaque page.","Repeat Header Rows follows the page breaks. The Header Row option in Table Design only changes the formatting of the first row.":"Répéter les lignes d'en-tête suit les sauts de page. L'option Ligne d'en-tête de Création de tableau ne change que la mise en forme de la première ligne.","Insert › Header":"Insertion › En-tête","Table Layout › Data › Repeat Header Rows":"Disposition › Données › Répéter les lignes d'en-tête","Table Design › Header Row":"Création de tableau › Ligne d'en-tête","Layout › Breaks › Page":"Mise en page › Sauts de page › Page","The title \"Timetable, October 2026\" must run across all five columns of the first row.":"Le titre « Emploi du temps, octobre 2026 » doit s'étendre sur les cinq colonnes de la première ligne.","The courses must appear in alphabetical order, with the header row staying on top.":"Les cours doivent apparaître par ordre alphabétique, la ligne d'en-tête restant en haut.","Table Layout › Data › Sort, with \"My list has a header row\" ticked":"Disposition › Données › Trier, avec « Ma liste a une ligne d'en-tête » coché","Home › Paragraph › Sort, with no options":"Accueil › Paragraphe › Trier, sans aucune option","Cut and paste the rows one by one":"Couper et coller les lignes une par une","Table Design › Banded Rows":"Création de tableau › Lignes à bandes","Type the formula that adds the fees in the cells above the last cell of the Fee column.":"Saisissez la formule qui additionne les frais des cellules au-dessus de la dernière cellule de la colonne Frais.","SUM(ABOVE) adds the numbers above the cell in the same column.":"SUM(ABOVE) additionne les nombres situés au-dessus de la cellule, dans la même colonne.","Type the formula that adds the numbers to the left of the last cell of a row.":"Saisissez la formule qui additionne les nombres à gauche de la dernière cellule d'une ligne.","You changed one fee, but the total did not change. What do you do?":"Vous avez modifié un montant, mais le total n'a pas changé. Que faites-vous ?","F9 updates the selected fields. Word formulas never recalculate on their own.":"F9 met à jour les champs sélectionnés. Les formules Word ne se recalculent jamais toutes seules.","Retype the formula":"Ressaisir la formule","Select the total and press F9":"Sélectionner le total et appuyer sur F9","Save and close the document":"Enregistrer et fermer le document","Press Ctrl + Z":"Appuyer sur Ctrl + Z","An NGO wants to analyse 600 survey answers by region, with percentages and a chart. Where should the data be kept?":"Une ONG veut analyser 600 réponses d'enquête par région, avec des pourcentages et un graphique. Où les données doivent-elles être conservées ?","In a Word table with =SUM formulas":"Dans un tableau Word avec des formules =SUM","In Excel, with only the summary brought into the Word report":"Dans Excel, en ne reprenant que la synthèse dans le rapport Word","In a Word table sorted by region":"Dans un tableau Word trié par région","In tabbed text in Word":"Dans un texte tabulé dans Word","Word tables are for presenting data. Calculations, percentages and charts on hundreds of rows belong in Excel; the report then shows the summary.":"Les tableaux Word servent à présenter des données. Les calculs, pourcentages et graphiques sur des centaines de lignes relèvent d'Excel ; le rapport en montre ensuite la synthèse.","Type a list of 10 staff members with name, department and phone number separated by tabs, then convert it to a table":"Saisissez une liste de 10 employés avec le nom, le service et le téléphone séparés par des tabulations, puis convertissez-la en tableau","Apply a light table style and turn on Banded Rows":"Appliquez un style de tableau clair et activez Lignes à bandes","Sort the table by department, then by name":"Triez le tableau par service, puis par nom","Add enough rows to reach a second page and make the header row repeat":"Ajoutez assez de lignes pour atteindre une deuxième page et faites répéter la ligne d'en-tête","Add a Budget column and total it with =SUM(ABOVE), then change a number and update the total with F9":"Ajoutez une colonne Budget et totalisez-la avec =SUM(ABOVE), puis modifiez un nombre et mettez à jour le total avec F9","Insert a table":"Insérer un tableau","Exam MO-110: Microsoft Word (Microsoft 365 Apps)":"Examen MO-110 : Microsoft Word (Microsoft 365 Apps)","Prepare a clean Excel recipient list for a mail merge":"Préparer dans Excel une liste de destinataires propre pour un publipostage","Run the Mailings workflow from Start Mail Merge to Finish & Merge":"Dérouler le processus de l'onglet Publipostage, de Démarrer la fusion et le publipostage à Terminer et fusionner","Personalise letters with merge fields and rules, and print labels and envelopes":"Personnaliser des lettres avec des champs de fusion et des règles, et imprimer des étiquettes et des enveloppes","Mail merge produces hundreds of personalised letters, labels, envelopes or e-mails from one document and one list. You write the letter once, Word fills in each person's name, address and amount, and you check the result before printing. It saves hours and avoids the copy-and-paste mistakes that send one member's amount to another.":"Le publipostage produit des centaines de lettres, étiquettes, enveloppes ou e-mails personnalisés à partir d'un seul document et d'une seule liste. Vous rédigez la lettre une fois, Word insère le nom, l'adresse et le montant de chaque personne, et vous vérifiez le résultat avant d'imprimer. Vous gagnez des heures et évitez les erreurs de copier-coller qui envoient le montant d'un membre à un autre.","The three parts of a mail merge":"Les trois éléments d'un publipostage","Part":"Élément","What it is":"Ce que c'est","Main document":"Document principal","The letter, label or e-mail with the text that is the same for everyone, plus merge fields":"La lettre, l'étiquette ou l'e-mail avec le texte commun à tous, plus les champs de fusion","An invitation to the general assembly":"Une invitation à l'assemblée générale","Data source":"Source de données","The list with one row per recipient and one column per piece of information":"La liste avec une ligne par destinataire et une colonne par information","An Excel workbook of 200 association members":"Un classeur Excel de 200 membres d'une association","Merged result":"Résultat de la fusion","One personalised copy per recipient":"Un exemplaire personnalisé par destinataire","200 letters in a new document, or sent straight to the printer":"200 lettres dans un nouveau document, ou envoyées directement à l'imprimante","Prepare a clean recipient list in Excel":"Préparer une liste de destinataires propre dans Excel","Put":"Placez","one header row":"une seule ligne d'en-tête","in row 1, with short names without spaces such as Title, FirstName, LastName, City, Email, Amount.":"en ligne 1, avec des noms courts sans espaces comme Title, FirstName, LastName, City, Email, Amount.","No merged cells, no title above the headers and no empty rows inside the list.":"Aucune cellule fusionnée, aucun titre au-dessus des en-têtes et aucune ligne vide dans la liste.","One piece of information per column: split \"M. Paul NDZANA\" into Title, FirstName and LastName.":"Une seule information par colonne : séparez « M. Paul NDZANA » en Title, FirstName et LastName.","No totals or notes below the list: Word would treat them as recipients.":"Aucun total ni aucune note sous la liste : Word les traiterait comme des destinataires.","Save and close the workbook before you connect it to Word.":"Enregistrez et fermez le classeur avant de le connecter à Word.","Numbers, phone numbers and dates":"Nombres, numéros de téléphone et dates","Word reads the value stored in the cell, not the way Excel displays it. An amount may lose its thousands separator and a phone number may lose its leading zero or + sign. Store phone numbers as text, and for amounts add a column in Excel that already contains the amount written as text, such as 25 000.":"Word lit la valeur enregistrée dans la cellule, pas la façon dont Excel l'affiche. Un montant peut perdre son séparateur de milliers et un numéro de téléphone son zéro initial ou son signe +. Enregistrez les numéros de téléphone en texte et, pour les montants, ajoutez dans Excel une colonne qui contient déjà le montant écrit en texte, par exemple 25 000.","The Mailings workflow":"Le processus de l'onglet Publipostage","Mailings":"Publipostage","Start Mail Merge":"Démarrer la fusion et le publipostage","Letters":"Lettres","Merge letters from an Excel list":"Fusionner des lettres à partir d'une liste Excel","Open or write the letter, then go to":"Ouvrez ou rédigez la lettre, puis allez dans","Mailings › Start Mail Merge › Letters":"Publipostage › Démarrer la fusion et le publipostage › Lettres","Select Recipients › Use an Existing List":"Sélection des destinataires › Utiliser une liste existante",", choose the workbook and the sheet, and keep \"First row of data contains column headers\" ticked.":", choisissez le classeur et la feuille, et laissez cochée l'option « La première ligne de données contient les en-têtes de colonnes ».","Edit Recipient List":"Modifier la liste de destinataires","to sort, filter or untick people who should not receive the letter.":"pour trier, filtrer ou décocher les personnes qui ne doivent pas recevoir la lettre.","Place the cursor where each detail belongs and use":"Placez le curseur à l'endroit de chaque information et utilisez","Insert Merge Field":"Insérer un champ de fusion","to add fields such as «Title», «FirstName» and «LastName».":"pour ajouter des champs comme «Title», «FirstName» et «LastName».","Preview Results":"Aperçu des résultats","and use the arrows to check several recipients, especially long names and empty cells.":"et utilisez les flèches pour vérifier plusieurs destinataires, en particulier les noms longs et les cellules vides.","Finish & Merge":"Terminer et fusionner","and choose Edit Individual Documents, Print Documents or Send Email Messages.":"et choisissez Modifier des documents individuels, Imprimer les documents ou Envoyer des messages électroniques.","Button":"Bouton","What it inserts or does":"Ce qu'il insère ou fait","Address Block":"Bloc d'adresse","A complete address built from several columns, in a layout you choose":"Une adresse complète construite à partir de plusieurs colonnes, dans la présentation de votre choix","Greeting Line":"Formule d'appel","A salutation such as \"Dear Mr Ndzana,\" with a fallback for missing names":"Une formule de politesse comme « Cher Monsieur Ndzana, » avec une solution de repli si le nom manque","One column of the list, shown between « » chevrons":"Une colonne de la liste, affichée entre chevrons « »","Rules":"Règles","Conditions such as If…Then…Else, or Skip Record If to leave some people out":"Des conditions comme Si…Alors…Sinon, ou Ignorer l'enregistrement si pour exclure certaines personnes","Replaces the fields with real data, one recipient at a time":"Remplace les champs par les vraies données, un destinataire à la fois","Check for Errors":"Vérification automatique des erreurs","Simulates the merge and reports problems before you print":"Simule la fusion et signale les problèmes avant l'impression","Personalise with a rule":"Personnaliser avec une règle","Rules let the text change from one recipient to another. With If…Then…Else you can write \"Madame\" when the Gender column contains F and \"Monsieur\" otherwise, or add a reminder paragraph only for members whose dues are unpaid.":"Les règles permettent au texte de changer d'un destinataire à l'autre. Avec Si…Alors…Sinon, vous pouvez écrire « Madame » quand la colonne Gender contient F et « Monsieur » sinon, ou ajouter un paragraphe de rappel uniquement pour les membres dont la cotisation n'est pas payée.","Write & Insert Fields":"Champs d'écriture et d'insertion","If…Then…Else":"Si…Alors…Sinon","Choose the field, the comparison and the value, then type the text to insert in each case.":"Choisissez le champ, la comparaison et la valeur, puis saisissez le texte à insérer dans chaque cas.","Finish the merge":"Terminer la fusion","Finish & Merge option":"Option de Terminer et fusionner","Result":"Résultat","Edit Individual Documents":"Modifier des documents individuels","A new document with one letter per recipient":"Un nouveau document avec une lettre par destinataire","You want to check or save the letters before printing. This is the safest choice":"Vous voulez vérifier ou enregistrer les lettres avant de les imprimer. C'est le choix le plus sûr","Print Documents":"Imprimer les documents","Sends all letters to the printer":"Envoie toutes les lettres à l'imprimante","You have already checked the preview carefully":"Vous avez déjà vérifié l'aperçu avec soin","Send Email Messages":"Envoyer des messages électroniques","One e-mail per recipient through Outlook, using the Email column":"Un e-mail par destinataire via Outlook, à partir de la colonne Email","The letter goes by e-mail. Outlook for Windows must be installed and set up":"La lettre part par e-mail. Outlook pour Windows doit être installé et configuré","Labels and envelopes":"Étiquettes et enveloppes","Print address labels":"Imprimer des étiquettes d'adresse","Start a new blank document and go to":"Créez un nouveau document vierge et allez dans","Mailings › Start Mail Merge › Labels":"Publipostage › Démarrer la fusion et le publipostage › Étiquettes","Choose the label vendor and product number printed on the box, for example an A4 sheet of 21 labels.":"Choisissez le fournisseur et la référence des étiquettes indiqués sur la boîte, par exemple une feuille A4 de 21 étiquettes.","Select the same recipient list, then insert an":"Sélectionnez la même liste de destinataires, puis insérez un","or merge fields in the first label only.":"ou des champs de fusion dans la première étiquette seulement.","Update Labels":"Mettre à jour les étiquettes","to copy the layout to every label on the sheet.":"pour copier la présentation sur toutes les étiquettes de la feuille.","Preview, then print one test sheet on plain paper and hold it against a label sheet before using the real labels.":"Affichez l'aperçu, puis imprimez une feuille de test sur papier ordinaire et superposez-la à une planche d'étiquettes avant d'utiliser les vraies étiquettes.","Envelopes work the same way: Mailings › Start Mail Merge › Envelopes, choose the size (DL is common for A4 letters folded in three), then place the address fields in the address box.":"Les enveloppes fonctionnent de la même façon : Publipostage › Démarrer la fusion et le publipostage › Enveloppes, choisissez le format (DL est courant pour une lettre A4 pliée en trois), puis placez les champs d'adresse dans la zone d'adresse.","The secretary of a teachers' association in Bafoussam must invite 200 members to the annual general meeting. With the member list cleaned in Excel, one letter written in Word and a rule that adds a reminder for unpaid dues, the 200 letters and the envelope labels are ready in under an hour.":"La secrétaire d'une association d'enseignants de Bafoussam doit inviter 200 membres à l'assemblée générale annuelle. Avec la liste des membres nettoyée dans Excel, une seule lettre rédigée dans Word et une règle qui ajoute un rappel pour les cotisations impayées, les 200 lettres et les étiquettes des enveloppes sont prêtes en moins d'une heure.","Run a mail merge in the right order":"Réaliser un publipostage dans le bon ordre","You prepare invitation letters for the members of a savings cooperative in Douala. The Excel list has the columns Title, FirstName, LastName, City and Email. Answer each question.":"Vous préparez des lettres d'invitation pour les membres d'une coopérative d'épargne de Douala. La liste Excel contient les colonnes Title, FirstName, LastName, City et Email. Répondez à chaque question.","The workflow goes from left to right on the Mailings tab: Start Mail Merge, Select Recipients, insert fields, Preview Results, Finish & Merge. Merge fields appear between « » chevrons.":"Le processus va de gauche à droite dans l'onglet Publipostage : Démarrer la fusion et le publipostage, Sélection des destinataires, insertion des champs, Aperçu des résultats, Terminer et fusionner. Les champs de fusion apparaissent entre chevrons « ».","Step 1: what do you click first on the Mailings tab?":"Étape 1 : sur quoi cliquez-vous d'abord dans l'onglet Publipostage ?","Start Mail Merge › Letters":"Démarrer la fusion et le publipostage › Lettres","Step 2: how do you connect the Excel member list?":"Étape 2 : comment connectez-vous la liste Excel des membres ?","Insert › Object":"Insertion › Objet","File › Open":"Fichier › Ouvrir","Select Recipients › Type a New List":"Sélection des destinataires › Entrer une nouvelle liste","Type the merge field that inserts the member's first name, as Word shows it in the letter.":"Saisissez le champ de fusion qui insère le prénom du membre, tel que Word l'affiche dans la lettre.","Word shows a merge field as the column name between chevrons.":"Word affiche un champ de fusion sous la forme du nom de la colonne entre chevrons.","Type the merge field for the family name column.":"Saisissez le champ de fusion de la colonne du nom de famille.","Only members from Douala should receive this letter. Where do you filter the list?":"Seuls les membres de Douala doivent recevoir cette lettre. Où filtrez-vous la liste ?","Edit Recipient List lets you filter, sort or untick recipients without changing the Excel file.":"Modifier la liste de destinataires permet de filtrer, trier ou décocher des destinataires sans modifier le fichier Excel.","Delete the other rows in the merged letters":"Supprimer les autres lignes dans les lettres fusionnées","Edit Recipient List › Filter":"Modifier la liste de destinataires › Filtrer","Rules › Next Record":"Règles › Enregistrement suivant","Which Finish & Merge option lets you check every letter before printing?":"Quelle option de Terminer et fusionner permet de vérifier chaque lettre avant l'impression ?","Format a merge letter":"Mettre en forme une lettre de publipostage","This payslip notice already contains merge fields. Format it: the first line in Heading 1 and centred, the place and date right-aligned, the words «NetPay» FCFA in bold, and the three deductions as a bulleted list.":"Cet avis de paiement contient déjà des champs de fusion. Mettez-le en forme : la première ligne en Titre 1 et centrée, le lieu et la date alignés à droite, les mots «NetPay» FCFA en gras, et les trois retenues en liste à puces.","Formatting applied to a merge field is kept in every merged letter. Select «NetPay» FCFA together before clicking Bold, and select the three deduction lines before clicking Bullets.":"La mise en forme appliquée à un champ de fusion est conservée dans chaque lettre fusionnée. Sélectionnez ensemble «NetPay» FCFA avant de cliquer sur Gras, et sélectionnez les trois lignes de retenues avant de cliquer sur Puces.","Your merged letters show some members twice and one letter addressed to \"TOTAL\". What is the most likely cause?":"Vos lettres fusionnées montrent certains membres deux fois et une lettre adressée à « TOTAL ». Quelle est la cause la plus probable ?","The letter uses the wrong font":"La lettre utilise la mauvaise police","The Excel list has duplicate rows and a totals row below the data":"La liste Excel contient des lignes en double et une ligne de total sous les données","Preview Results was switched on":"L'aperçu des résultats était activé","The labels were not updated":"Les étiquettes n'ont pas été mises à jour","Word creates one letter for every row of the data source. Clean the list in Excel first: one header row, one row per person, nothing below the data.":"Word crée une lettre pour chaque ligne de la source de données. Nettoyez d'abord la liste dans Excel : une ligne d'en-tête, une ligne par personne, rien sous les données.","Create an Excel list of 8 people with the columns Title, FirstName, LastName, City and Email":"Créez une liste Excel de 8 personnes avec les colonnes Title, FirstName, LastName, City et Email","Write a short invitation letter and connect it to the list with Select Recipients":"Rédigez une courte lettre d'invitation et connectez-la à la liste avec Sélection des destinataires","Insert a Greeting Line and the City field, and preview at least three recipients":"Insérez une formule d'appel et le champ City, puis affichez l'aperçu d'au moins trois destinataires","Add an If…Then…Else rule that prints a different sentence for people in Yaoundé":"Ajoutez une règle Si…Alors…Sinon qui imprime une phrase différente pour les personnes de Yaoundé","Finish with Edit Individual Documents, then create a sheet of address labels from the same list":"Terminez avec Modifier des documents individuels, puis créez une planche d'étiquettes d'adresse à partir de la même liste","Use mail merge for bulk email, letters, labels, and envelopes":"Utiliser le publipostage pour des e-mails, lettres, étiquettes et enveloppes en nombre","Add, answer and resolve comments during a review":"Ajouter, répondre à et résoudre des commentaires pendant une relecture","Record, display, accept and reject changes with Track Changes":"Enregistrer, afficher, accepter et refuser des modifications avec le Suivi des modifications","Compare two versions, restrict editing and proofread a bilingual document":"Comparer deux versions, restreindre la modification et relire un document bilingue","Reports, contracts and project proposals are rarely written by one person. Comments and Track Changes let several reviewers work on the same document while the author keeps full control: every suggestion is visible, attributed to its author and can be accepted or rejected one by one.":"Les rapports, contrats et propositions de projet sont rarement rédigés par une seule personne. Les commentaires et le Suivi des modifications permettent à plusieurs relecteurs de travailler sur le même document tandis que l'auteur garde le contrôle : chaque proposition est visible, attribuée à son auteur et peut être acceptée ou refusée une par une.","Comments: discuss without changing the text":"Commentaires : discuter sans modifier le texte","Comments":"Commentaires","New Comment":"Nouveau commentaire","Shortcut: Ctrl + Alt + M.":"Raccourci : Ctrl + Alt + M.","Work with comments":"Travailler avec les commentaires","Select the words the comment is about, then press":"Sélectionnez les mots concernés par le commentaire, puis appuyez sur","Type your remark and post it. Type @ followed by a colleague's name to mention them: they receive an e-mail notification.":"Tapez votre remarque et publiez-la. Tapez @ suivi du nom d'un collègue pour le mentionner : il reçoit une notification par e-mail.","To answer, click":"Pour répondre, cliquez sur","Reply":"Répondre","in the comment instead of starting a new one, so the whole discussion stays together.":"dans le commentaire au lieu d'en créer un nouveau, afin que toute la discussion reste regroupée.","When the point is settled, choose":"Quand le point est réglé, choisissez","Resolve":"Résoudre","from the comment's menu. It stays in the document, greyed out, and can be reopened.":"dans le menu du commentaire. Il reste dans le document, grisé, et peut être rouvert.","Before sending the final version, delete all comments: Review › Comments › Delete › Delete All Comments in Document.":"Avant d'envoyer la version finale, supprimez tous les commentaires : Révision › Commentaires › Supprimer › Supprimer tous les commentaires du document.","Track Changes: every edit recorded":"Suivi des modifications : chaque correction enregistrée","Tracking":"Suivi","Shortcut: Ctrl + Shift + E. The button stays highlighted while tracking is on.":"Raccourci : Ctrl + Maj + E. Le bouton reste en surbrillance tant que le suivi est activé.","While tracking is on, inserted text is underlined in colour, deleted text is struck through or moved to a balloon, and a line in the margin marks each changed line. Each reviewer gets a different colour.":"Quand le suivi est activé, le texte inséré est souligné en couleur, le texte supprimé est barré ou déplacé dans une bulle, et un trait dans la marge signale chaque ligne modifiée. Chaque relecteur reçoit une couleur différente.","Display for Review":"Affichage pour la révision","What you see":"Ce que vous voyez","Simple Markup":"Marques simples","The edited text, with a red line in the margin where something changed":"Le texte modifié, avec un trait rouge dans la marge là où quelque chose a changé","Read the new version comfortably":"Lire confortablement la nouvelle version","All Markup":"Toutes les marques","Every insertion, deletion and formatting change, with the reviewer's name":"Chaque insertion, suppression et modification de mise en forme, avec le nom du relecteur","Check each change before accepting it":"Vérifier chaque modification avant de l'accepter","No Markup":"Aucune marque","The document as it would look if all changes were accepted":"Le document tel qu'il serait si toutes les modifications étaient acceptées","Proofread the final result":"Relire le résultat final","Original":"Original","The document before any tracked change":"Le document avant toute modification suivie","Compare with what you first wrote":"Comparer avec ce que vous aviez écrit au départ","Accept or reject changes":"Accepter ou refuser les modifications","and switch to":"et passez en","Review › Changes › Next":"Révision › Modifications › Suivant","to jump to the first change.":"pour aller à la première modification.","Accept":"Accepter","or":"ou","Reject":"Refuser",". Word moves to the next change automatically.":". Word passe automatiquement à la modification suivante.","When you trust all the remaining changes, use the arrow under Accept and choose":"Quand vous faites confiance à toutes les modifications restantes, utilisez la flèche sous Accepter et choisissez","Accept All Changes":"Accepter toutes les modifications","Hiding changes is not removing them":"Masquer les modifications ne les supprime pas","Switching to No Markup or turning Track Changes off does not delete the recorded changes. A client who opens the file can still see every deletion and comment. Accept or reject all changes, delete the comments, then run File › Info › Check for Issues › Inspect Document before sending.":"Passer en Aucune marque ou désactiver le Suivi des modifications ne supprime pas les modifications enregistrées. Un client qui ouvre le fichier peut encore voir chaque suppression et chaque commentaire. Acceptez ou refusez toutes les modifications, supprimez les commentaires, puis lancez Fichier › Informations › Vérifier la présence de problèmes › Inspecter le document avant l'envoi.","Review shortcuts":"Raccourcis de révision","Insert a comment":"Insérer un commentaire","Turn Track Changes on or off":"Activer ou désactiver le Suivi des modifications","Check spelling and grammar (opens the Editor pane)":"Vérifier l'orthographe et la grammaire (ouvre le volet Éditeur)","Thesaurus":"Dictionnaire des synonymes","Practise the review shortcuts":"Entraînez-vous aux raccourcis de révision","Check spelling and grammar":"Vérifier l'orthographe et la grammaire","Compare two versions":"Comparer deux versions","A partner sometimes sends back an edited copy without Track Changes. Compare shows every difference between the two files as tracked changes in a new document, so you can review them normally.":"Un partenaire renvoie parfois une copie corrigée sans Suivi des modifications. Comparer affiche chaque différence entre les deux fichiers sous forme de modifications suivies dans un nouveau document, que vous relisez ensuite normalement.","Compare":"Comparer","Choose the original document and the revised document. Combine merges the copies of several reviewers into one.":"Choisissez le document original et le document révisé. Combiner fusionne en un seul les exemplaires de plusieurs relecteurs.","Restrict Editing":"Restreindre la modification","Force reviewers to track their changes":"Obliger les relecteurs à suivre leurs modifications","Review › Protect › Restrict Editing":"Révision › Protéger › Restreindre la modification","Under Editing restrictions, tick the box and choose":"Sous Restrictions de modifications, cochez la case et choisissez","Tracked changes":"Modifications","(or Comments, Filling in forms, No changes).":"(ou Commentaires, Remplissage de formulaires, Aucune modification).","Yes, Start Enforcing Protection":"Oui, activer la protection","and enter a password if you want one.":"et saisissez un mot de passe si vous le souhaitez.","Reviewers can now edit, but every change is recorded and they cannot switch tracking off.":"Les relecteurs peuvent maintenant modifier le texte, mais chaque modification est enregistrée et ils ne peuvent pas désactiver le suivi.","Spelling, grammar and the proofing language":"Orthographe, grammaire et langue de vérification","Press F7 to open the":"Appuyez sur F7 pour ouvrir le volet","Editor":"Éditeur","pane, which lists spelling, grammar and clarity suggestions one by one.":", qui présente une par une les suggestions d'orthographe, de grammaire et de clarté.","Word checks each passage in its proofing language. Select a French passage and choose Review › Language › Set Proofing Language › French.":"Word vérifie chaque passage dans sa langue de vérification. Sélectionnez un passage en français et choisissez Révision › Langue › Définir la langue de vérification › Français.","Tick":"Cochez","Do not check spelling or grammar":"Ne pas vérifier l'orthographe ou la grammaire","for codes, product references or long lists of names.":"pour les codes, les références de produits ou les longues listes de noms.","Right-click a correct name such as Nkongsamba and choose":"Faites un clic droit sur un nom correct comme Nkongsamba et choisissez","Add to Dictionary":"Ajouter au dictionnaire","so Word stops flagging it.":"pour que Word cesse de le signaler.","A consultancy in Yaoundé writes a bilingual project proposal for a ministry. The English team and the French team review with Track Changes on, the project manager accepts or rejects each change, and the French sections are set to the French proofing language so F7 checks both parts correctly.":"Un cabinet de conseil de Yaoundé rédige une proposition de projet bilingue pour un ministère. L'équipe anglophone et l'équipe francophone relisent avec le Suivi des modifications activé, le chef de projet accepte ou refuse chaque modification, et les parties en français sont réglées sur la langue de vérification française pour que F7 vérifie correctement les deux parties.","Make the right review decision":"Prendre la bonne décision de relecture","You coordinate the review of a funding proposal for an NGO in Garoua. Choose the right feature for each situation.":"Vous coordonnez la relecture d'une demande de financement pour une ONG de Garoua. Choisissez la bonne fonctionnalité pour chaque situation.","Think about what each person needs to see or be prevented from doing. Restrict Editing controls what reviewers may do; the display options only change what you see.":"Demandez-vous ce que chaque personne doit voir ou ne doit pas pouvoir faire. Restreindre la modification contrôle ce que les relecteurs peuvent faire ; les options d'affichage ne changent que ce que vous voyez.","The director wants to read the edited text without coloured marks, but still see where something changed.":"Le directeur veut lire le texte modifié sans marques de couleur, tout en voyant où quelque chose a changé.","Turn Track Changes off":"Désactiver le Suivi des modifications","A reviewer must be unable to make changes that are not tracked.":"Un relecteur ne doit pas pouvoir faire de modifications non suivies.","Restrict Editing with Tracked changes keeps tracking on for everyone until the password is entered.":"Restreindre la modification avec l'option Modifications garde le suivi activé pour tous jusqu'à la saisie du mot de passe.","Review › Protect › Restrict Editing › Tracked changes":"Révision › Protéger › Restreindre la modification › Modifications","Mark as Final":"Marquer comme final","Save as PDF":"Enregistrer en PDF","A partner returns an edited copy without Track Changes. How do you see what changed?":"Un partenaire renvoie une copie corrigée sans Suivi des modifications. Comment voyez-vous ce qui a changé ?","Read both files side by side":"Lire les deux fichiers côte à côte","Review › Compare › Compare":"Révision › Comparer › Comparer","Undo history":"L'historique d'annulation","Review › Track Changes":"Révision › Suivi des modifications","A colleague answered your comment by creating a new comment further down. What should she have done?":"Une collègue a répondu à votre commentaire en créant un nouveau commentaire plus bas. Qu'aurait-elle dû faire ?","Used Reply in the original comment":"Utiliser Répondre dans le commentaire d'origine","Used Track Changes":"Utiliser le Suivi des modifications","Deleted your comment":"Supprimer votre commentaire","Written her answer in the text":"Écrire sa réponse dans le texte","Which key opens the Editor pane to check spelling and grammar?":"Quelle touche ouvre le volet Éditeur pour vérifier l'orthographe et la grammaire ?","The final version goes to the donor tomorrow. What must you do with the tracked changes and comments?":"La version finale part chez le bailleur demain. Que devez-vous faire des modifications suivies et des commentaires ?","Changes and comments stay in the file until they are accepted, rejected or deleted, whatever the display.":"Les modifications et les commentaires restent dans le fichier tant qu'ils ne sont pas acceptés, refusés ou supprimés, quel que soit l'affichage.","Switch to No Markup":"Passer en Aucune marque","Accept or reject all changes and delete all comments":"Accepter ou refuser toutes les modifications et supprimer tous les commentaires","Nothing, the donor cannot see them":"Rien, le bailleur ne peut pas les voir","You turned Track Changes off and chose No Markup. The coloured changes disappeared. What happens when the client opens the file?":"Vous avez désactivé le Suivi des modifications et choisi Aucune marque. Les modifications en couleur ont disparu. Que se passe-t-il quand le client ouvre le fichier ?","Nothing: the changes are deleted":"Rien : les modifications sont supprimées","The client can still display every tracked change and comment":"Le client peut encore afficher chaque modification suivie et chaque commentaire","The document is locked":"Le document est verrouillé","The changes are accepted automatically":"Les modifications sont acceptées automatiquement","Display options only change what you see on your screen. The changes remain in the file until they are accepted or rejected.":"Les options d'affichage ne changent que ce que vous voyez à l'écran. Les modifications restent dans le fichier jusqu'à ce qu'elles soient acceptées ou refusées.","Turn on Track Changes with Ctrl + Shift + E and edit three sentences of an existing document":"Activez le Suivi des modifications avec Ctrl + Maj + E et modifiez trois phrases d'un document existant","Add two comments with Ctrl + Alt + M, reply to one and resolve it":"Ajoutez deux commentaires avec Ctrl + Alt + M, répondez à l'un et résolvez-le","Switch between Simple Markup and All Markup, then accept one change and reject another":"Passez de Marques simples à Toutes les marques, puis acceptez une modification et refusez-en une autre","Compare your edited file with the original copy":"Comparez votre fichier modifié avec la copie d'origine","Set one paragraph to French proofing and run F7":"Réglez un paragraphe sur la langue de vérification française et lancez F7","Track changes in Word":"Suivre les modifications dans Word","Keyboard shortcuts in Word":"Raccourcis clavier dans Word","Build and update an automatic table of contents from heading styles":"Créer et mettre à jour une table des matières automatique à partir des styles de titre","Number figures and tables with captions, cross-references and footnotes":"Numéroter les figures et les tableaux avec des légendes, des renvois et des notes de bas de page","Save a company letterhead as a .dotx template and create documents from it":"Enregistrer le papier à en-tête de l'entreprise comme modèle .dotx et créer des documents à partir de celui-ci","Long documents such as annual reports, procedure manuals and theses need a table of contents, numbered figures and consistent layout. Word builds all of this automatically, as long as the document is structured with styles.":"Les documents longs comme les rapports annuels, les manuels de procédures et les mémoires ont besoin d'une table des matières, de figures numérotées et d'une présentation cohérente. Word construit tout cela automatiquement, à condition que le document soit structuré avec des styles.","Headings are the foundation":"Les titres sont la base","The table of contents lists every paragraph formatted with Heading 1, Heading 2 or Heading 3. Titles made bold by hand are invisible to it. Before inserting a table of contents, open the Navigation Pane (View › Navigation Pane): what you see there is exactly what the table of contents will show.":"La table des matières reprend chaque paragraphe mis en forme avec Titre 1, Titre 2 ou Titre 3. Les titres simplement mis en gras à la main lui sont invisibles. Avant d'insérer une table des matières, ouvrez le volet de navigation (Affichage › Volet de navigation) : ce que vous y voyez est exactement ce que la table des matières affichera.","Apply Heading 3":"Appliquer Titre 3","Practise the heading shortcuts":"Entraînez-vous aux raccourcis des titres","Prepare a report for its table of contents":"Préparer un rapport pour sa table des matières","Apply Heading 1 to the three chapter titles (Introduction to the programme, Results of the year, Outlook for 2027) and Heading 2 to the two section titles (Vaccination campaigns, Community health training). Then justify the introduction paragraph.":"Appliquez Titre 1 aux trois titres de chapitre (Introduction to the programme, Results of the year, Outlook for 2027) et Titre 2 aux deux titres de section (Vaccination campaigns, Community health training). Justifiez ensuite le paragraphe d'introduction.","Click in each title and choose the style; you do not need to select the whole line. Chapters are Heading 1, the sections inside a chapter are Heading 2.":"Cliquez dans chaque titre et choisissez le style ; inutile de sélectionner toute la ligne. Les chapitres sont en Titre 1, les sections à l'intérieur d'un chapitre en Titre 2.","Insert and update the table of contents":"Insérer et mettre à jour la table des matières","Table of Contents":"Table des matières","Automatic Table 1":"Table automatique 1","Custom Table of Contents lets you choose how many heading levels to show and the style of the dotted leaders.":"Table des matières personnalisée permet de choisir le nombre de niveaux de titres affichés et le style des points de suite.","Insert a table of contents":"Insérer une table des matières","Put the cursor on the blank page after the cover page.":"Placez le curseur sur la page vierge qui suit la page de garde.","References › Table of Contents":"Références › Table des matières","and choose an automatic table.":"et choisissez une table automatique.","Hold Ctrl and click an entry to check that it jumps to the right heading.":"Maintenez Ctrl et cliquez sur une entrée pour vérifier qu'elle mène au bon titre.","After editing the report, click":"Après avoir modifié le rapport, cliquez sur","References › Update Table":"Références › Mettre à jour la table","Page numbers only, or entire table?":"Numéros de page seulement, ou toute la table ?","Update Table asks what to update. Choose":"Mettre à jour la table vous demande quoi mettre à jour. Choisissez","Update page numbers only":"Mettre à jour les numéros de page uniquement","when only the length of the text changed. Choose":"quand seule la longueur du texte a changé. Choisissez","Update entire table":"Mettre à jour toute la table","when you added, deleted or renamed headings.":"quand vous avez ajouté, supprimé ou renommé des titres.","Captions and cross-references":"Légendes et renvois","Number a figure or a table":"Numéroter une figure ou un tableau","Select the picture, chart or table.":"Sélectionnez l'image, le graphique ou le tableau.","References › Captions › Insert Caption":"Références › Légendes › Insérer une légende","Choose the label Figure or Table, type a short description after the number, and choose the position: usually above a table and below a figure.":"Choisissez l'étiquette Figure ou Tableau, tapez une courte description après le numéro, et choisissez la position : en général au-dessus d'un tableau et sous une figure.","Word numbers the captions in order and renumbers them when you insert a new one in between.":"Word numérote les légendes dans l'ordre et les renumérote quand vous en insérez une nouvelle entre deux.","Captions":"Légendes","Cross-reference":"Renvoi","Choose the reference type (Figure, Table, Heading), then \"Only label and number\" to write \"see Figure 3\" in the text.":"Choisissez la catégorie (Figure, Tableau, Titre), puis « Étiquette et numéro seulement » pour écrire « voir Figure 3 » dans le texte.","Insert Table of Figures":"Insérer une table des illustrations","Lists every caption with its page number, like a table of contents for figures or tables.":"Liste chaque légende avec son numéro de page, comme une table des matières pour les figures ou les tableaux.","Cross-references, captions and tables of figures are fields, like the table of contents. Before printing, press Ctrl + A and then F9 to update all of them at once.":"Les renvois, les légendes et les tables des illustrations sont des champs, comme la table des matières. Avant d'imprimer, appuyez sur Ctrl + A puis sur F9 pour tous les mettre à jour en une fois.","Footnotes":"Notes de bas de page","A footnote adds a source or an explanation at the bottom of the page without breaking the flow of the text. Use References › Footnotes › Insert Footnote (Ctrl + Alt + F). Word numbers the notes and keeps each one on the same page as its reference number.":"Une note de bas de page ajoute une source ou une explication en bas de la page sans couper le fil du texte. Utilisez Références › Notes de bas de page › Insérer une note de bas de page (Ctrl + Alt + F). Word numérote les notes et garde chacune sur la même page que son appel de note.","A letterhead template (.dotx)":"Un modèle de papier à en-tête (.dotx)","Create and use a letterhead template":"Créer et utiliser un modèle de papier à en-tête","In a new document, put the logo, company name, address, taxpayer number (NIU) and phone numbers in the header and footer.":"Dans un nouveau document, placez le logo, le nom de l'entreprise, l'adresse, le numéro d'identifiant unique (NIU) et les numéros de téléphone dans l'en-tête et le pied de page.","Set A4, the margins and the styles your company uses, and leave the body empty.":"Réglez le format A4, les marges et les styles de votre entreprise, et laissez le corps du document vide.","Go to File › Save As and choose Word Template (*.dotx) as the file type. Word proposes the Custom Office Templates folder: keep it.":"Allez dans Fichier › Enregistrer sous et choisissez Modèle Word (*.dotx) comme type de fichier. Word propose le dossier Modèles Office personnalisés : gardez-le.","To write a letter, go to":"Pour écrire une lettre, allez dans","File › New › Personal":"Fichier › Nouveau › Personnel","and click the template. Word opens a new untitled document, so the template itself stays clean.":"et cliquez sur le modèle. Word ouvre un nouveau document sans titre : le modèle lui-même reste intact.","To change the template later, open the .dotx file itself (File › Open), edit it and save it.":"Pour modifier le modèle plus tard, ouvrez le fichier .dotx lui-même (Fichier › Ouvrir), modifiez-le et enregistrez-le.","A logistics SME in Douala found five different letterheads in use, some with an old phone number. The office manager built one .dotx template with the current details and shared it in the team's OneDrive. Every new letter now starts from the same, correct letterhead.":"Une PME de logistique de Douala a découvert cinq papiers à en-tête différents en circulation, dont certains avec un ancien numéro de téléphone. La responsable administrative a créé un seul modèle .dotx avec les coordonnées à jour et l'a partagé dans le OneDrive de l'équipe. Chaque nouvelle lettre part désormais du même papier à en-tête, correct.","You added two new chapters to a report, but they do not appear in the table of contents. What do you do?":"Vous avez ajouté deux nouveaux chapitres à un rapport, mais ils n'apparaissent pas dans la table des matières. Que faites-vous ?","Type them into the table of contents by hand":"Les saisir à la main dans la table des matières","References › Update Table › Update page numbers only":"Références › Mettre à jour la table › Mettre à jour les numéros de page uniquement","Check that they use Heading 1, then References › Update Table › Update entire table":"Vérifier qu'ils utilisent Titre 1, puis Références › Mettre à jour la table › Mettre à jour toute la table","Delete the table of contents and retype it":"Supprimer la table des matières et la retaper","New headings appear only if they use a Heading style, and only after an update of the entire table. Page numbers only would not add them.":"Les nouveaux titres n'apparaissent que s'ils utilisent un style de titre, et seulement après une mise à jour de toute la table. Les numéros de page seuls ne les ajouteraient pas.","Apply Heading 1 and Heading 2 to a report of at least five pages and check the Navigation Pane":"Appliquez Titre 1 et Titre 2 à un rapport d'au moins cinq pages et vérifiez le volet de navigation","Insert an automatic table of contents after the cover page":"Insérez une table des matières automatique après la page de garde","Add captions to two tables and one picture, then refer to the picture with a cross-reference":"Ajoutez des légendes à deux tableaux et à une image, puis faites référence à l'image avec un renvoi","Insert a table of figures and a footnote that gives a source":"Insérez une table des illustrations et une note de bas de page qui indique une source","Save your organisation's letterhead as a .dotx template and create a new letter from it":"Enregistrez le papier à en-tête de votre organisation comme modèle .dotx et créez une nouvelle lettre à partir de celui-ci","Create a template":"Créer un modèle","Practice lab: advanced Word documents":"Atelier pratique : documents Word avancés","Choose the right table command for a real document":"Choisir la bonne commande de tableau pour un vrai document","Check a recipient list before a mail merge":"Vérifier une liste de destinataires avant un publipostage","Structure and format a long document for its table of contents":"Structurer et mettre en forme un long document pour sa table des matières","Plan a complete merge, review and publication workflow":"Planifier un processus complet de publipostage, de relecture et de diffusion","Exercise 1: A price list table":"Exercice 1 : un tableau de prix","Build a supplier price list":"Construire la liste de prix d'un fournisseur","A pharmacy in Garoua receives a supplier price list as plain text, with a tab between the product, the pack size and the price. Choose the right command for each step.":"Une pharmacie de Garoua reçoit la liste de prix d'un fournisseur en texte brut, avec une tabulation entre le produit, le conditionnement et le prix. Choisissez la bonne commande pour chaque étape.","Creating a table from existing text is on the Insert tab. Everything you do once the table exists is on Table Design (appearance) or Table Layout (structure, sorting and formulas).":"La création d'un tableau à partir d'un texte existant se trouve dans l'onglet Insertion. Tout ce que vous faites une fois le tableau créé se trouve dans Création de tableau (apparence) ou Disposition (structure, tri et formules).","Turn the tabbed lines into a table.":"Transformez les lignes tabulées en tableau.","Home › Paragraph › Tabs":"Accueil › Paragraphe › Tabulations","Insert › Table › Draw Table":"Insertion › Tableau › Dessiner un tableau","Table Layout › Convert to Text":"Disposition › Convertir en texte","Give the table shaded header formatting and banded rows in one click.":"Donnez au tableau un en-tête ombré et des lignes à bandes en un clic.","Home › Styles › Heading 1":"Accueil › Styles › Titre 1","Table Design › Table Styles":"Création de tableau › Styles de tableau","Table Layout › Alignment":"Disposition › Alignement","Layout › Page Color":"Mise en page › Couleur de page","The prices must line up on the units. How do you align the price column?":"Les prix doivent être alignés sur les unités. Comment alignez-vous la colonne des prix ?","Right-aligned amounts put units under units and thousands under thousands, which makes them easy to compare.":"Des montants alignés à droite placent les unités sous les unités et les milliers sous les milliers, ce qui facilite la comparaison.","Centre":"Centré","Left":"Gauche","Right":"Droite","Put the products in alphabetical order without moving the header.":"Classez les produits par ordre alphabétique sans déplacer l'en-tête.","Table Layout › Data › Sort, with a header row":"Disposition › Données › Trier, avec une ligne d'en-tête","Table Design › First Column":"Création de tableau › Première colonne","Cut and paste the rows":"Couper et coller les lignes","Home › Find › Replace":"Accueil › Rechercher › Remplacer","Make every column exactly as wide as its content.":"Donnez à chaque colonne exactement la largeur de son contenu.","Fixed Column Width":"Largeur de colonne fixe","Exercise 2: Check a mailing list":"Exercice 2 : vérifier une liste de diffusion","Is the list ready for the merge?":"La liste est-elle prête pour la fusion ?","A farmers' cooperative in Garoua will send its members a dues reminder by mail merge. Before merging, fill H2:H7: the number of members, the number of missing e-mail addresses, the number of members in Garoua, the dues collected, the Garoua members who paid at least 10 000 FCFA and the members with no payment recorded.":"Une coopérative agricole de Garoua va envoyer à ses membres un rappel de cotisation par publipostage. Avant la fusion, remplissez H2:H7 : le nombre de membres, le nombre d'adresses e-mail manquantes, le nombre de membres à Garoua, les cotisations encaissées, les membres de Garoua qui ont payé au moins 10 000 FCFA et les membres sans aucun paiement enregistré.","COUNTA counts filled cells and COUNTBLANK counts empty ones. COUNTIF(C2:C9,\"Garoua\") counts one city. For two conditions use COUNTIFS(C2:C9,\"Garoua\",E2:E9,\">=10000\").":"COUNTA (NBVAL) compte les cellules remplies et COUNTBLANK (NB.VIDE) les cellules vides. COUNTIF(C2:C9,\"Garoua\") compte une ville. Pour deux conditions, utilisez COUNTIFS (NB.SI.ENS) : COUNTIFS(C2:C9,\"Garoua\",E2:E9,\">=10000\").","Exercise 3: A procedures manual":"Exercice 3 : un manuel de procédures","Structure a procedures manual":"Structurer un manuel de procédures","Prepare this extract of a ministry procedures manual for its table of contents and for printing: the two chapter titles in Heading 1, the two section titles in Heading 2, the purpose paragraph justified, the deadline in bold and the four steps as a numbered list.":"Préparez cet extrait d'un manuel de procédures ministériel pour sa table des matières et pour l'impression : les deux titres de chapitre en Titre 1, les deux titres de section en Titre 2, le paragraphe d'objet justifié, le délai en gras et les quatre étapes en liste numérotée.","Chapters: \"Mission expenses\" and \"Supporting documents\". Sections: \"Before the mission\" and \"After the mission\". Select the four steps together before clicking Numbering. Bold only the words \"within 15 days\".":"Chapitres : « Mission expenses » et « Supporting documents ». Sections : « Before the mission » et « After the mission ». Sélectionnez ensemble les quatre étapes avant de cliquer sur Numérotation. Mettez en gras uniquement les mots « within 15 days ».","Exercise 4: Payslip notices from start to finish":"Exercice 4 : des avis de paie de A à Z","Plan the whole production":"Planifier toute la production","An SME in Yaoundé sends a monthly pay notice to 45 employees, on its letterhead, reviewed by the finance manager before it goes out. Answer each question about the complete workflow. Type shortcuts as keys joined with +, for example Ctrl + B.":"Une PME de Yaoundé envoie chaque mois un avis de paie à 45 employés, sur son papier à en-tête, relu par le responsable financier avant l'envoi. Répondez à chaque question sur l'ensemble du processus. Tapez les raccourcis sous forme de touches reliées par +, par exemple Ctrl + B.","Think in order: the letterhead template, the Excel list, the merge fields and rules, the review with Track Changes, then the final merge. Each answer is in one of the four lessons of this module.":"Pensez dans l'ordre : le modèle de papier à en-tête, la liste Excel, les champs de fusion et les règles, la relecture avec le Suivi des modifications, puis la fusion finale. Chaque réponse se trouve dans l'une des quatre leçons de ce module.","The letterhead must be reused every month without anyone overwriting it. How is it saved?":"Le papier à en-tête doit être réutilisé chaque mois sans que personne ne l'écrase. Comment est-il enregistré ?","As a .docx in Documents":"En .docx dans Documents","As a Word Template (.dotx)":"En Modèle Word (.dotx)","As a PDF":"En PDF","As a .txt file":"En fichier .txt","The Excel payroll list has a merged title in row 1 and the column names in row 3. What do you do before merging?":"La liste de paie Excel a un titre fusionné en ligne 1 et les noms de colonnes en ligne 3. Que faites-vous avant la fusion ?","Word reads the first row as the field names. A merged title in row 1 gives fields with meaningless names.":"Word lit la première ligne comme noms de champs. Un titre fusionné en ligne 1 donne des champs aux noms sans signification.","Nothing, Word skips the title":"Rien, Word ignore le titre","Delete the title rows so the column names are in row 1, with no merged cells":"Supprimer les lignes de titre pour que les noms de colonnes soient en ligne 1, sans cellules fusionnées","Merge the header cells too":"Fusionner aussi les cellules d'en-tête","Save the list as a PDF":"Enregistrer la liste en PDF","Type the merge field for the Excel column named NetPay.":"Saisissez le champ de fusion de la colonne Excel nommée NetPay.","Employees with a salary advance must see an extra sentence about the repayment. Which rule do you use?":"Les employés qui ont une avance sur salaire doivent voir une phrase supplémentaire sur le remboursement. Quelle règle utilisez-vous ?","If…Then…Else inserts one text when a condition is true (for example Advance greater than 0) and another text, or nothing, otherwise.":"Si…Alors…Sinon insère un texte quand une condition est vraie (par exemple Advance supérieur à 0) et un autre texte, ou rien, dans le cas contraire.","Skip Record If":"Ignorer l'enregistrement si","Next Record":"Enregistrement suivant","Merge Record #":"N° d'enregistrement de fusion","The finance manager reviews the letter template. Which shortcut turns Track Changes on?":"Le responsable financier relit le modèle de lettre. Quel raccourci active le Suivi des modifications ?","Which shortcut inserts a comment on the selected text?":"Quel raccourci insère un commentaire sur le texte sélectionné ?","The finance manager must not be able to switch tracking off. Which setting do you apply?":"Le responsable financier ne doit pas pouvoir désactiver le suivi. Quel réglage appliquez-vous ?","Restrict Editing with Tracked changes":"Restreindre la modification avec l'option Modifications","Lock the Excel file":"Verrouiller le fichier Excel","All changes are accepted. What is the safest way to finish, so you can check the 45 notices before they are printed?":"Toutes les modifications sont acceptées. Quelle est la façon la plus sûre de terminer, pour vérifier les 45 avis avant leur impression ?","Preview Results only":"Aperçu des résultats seulement","Module 3 Quiz":"Quiz du module 3","A table runs over four pages. How do you make its column titles appear at the top of each page?":"Un tableau s'étend sur quatre pages. Comment faire apparaître les titres de ses colonnes en haut de chaque page ?","Copy the first row at the top of each page":"Copier la première ligne en haut de chaque page","Insert a page break before each page":"Insérer un saut de page avant chaque page","Repeat Header Rows follows the page breaks automatically. The Header Row option only changes formatting.":"Répéter les lignes d'en-tête suit automatiquement les sauts de page. L'option Ligne d'en-tête ne change que la mise en forme.","In a mail merge, what is the Excel list of recipients called?":"Dans un publipostage, comment appelle-t-on la liste Excel des destinataires ?","The data source":"La source de données","The main document":"Le document principal","The template":"Le modèle","The merged result":"Le résultat de la fusion","The data source holds one row per recipient. The main document holds the text that is the same for everyone.":"La source de données contient une ligne par destinataire. Le document principal contient le texte commun à tous.","What does Ctrl + Shift + E do in Word?":"Que fait Ctrl + Maj + E dans Word ?","Centres the paragraph":"Centre le paragraphe","Inserts a comment":"Insère un commentaire","Opens the Editor pane":"Ouvre le volet Éditeur","Turns Track Changes on or off":"Active ou désactive le Suivi des modifications","Ctrl + Shift + E switches tracking on or off. Ctrl + Alt + M inserts a comment and F7 opens the Editor.":"Ctrl + Maj + E active ou désactive le suivi. Ctrl + Alt + M insère un commentaire et F7 ouvre l'Éditeur.","Which Display for Review option shows the edited text with only a red line in the margin where changes were made?":"Quelle option d'Affichage pour la révision montre le texte modifié avec seulement un trait rouge dans la marge là où des modifications ont été faites ?","Simple Markup is comfortable for reading. Switch to All Markup to see each change in detail.":"Marques simples est confortable pour la lecture. Passez en Toutes les marques pour voir chaque modification en détail.","You renamed several headings. What must you do so the table of contents shows the new names?":"Vous avez renommé plusieurs titres. Que devez-vous faire pour que la table des matières affiche les nouveaux noms ?","Press Ctrl + S":"Appuyer sur Ctrl + S","References › Update Table › Update entire table":"Références › Mettre à jour la table › Mettre à jour toute la table","Insert a new table of contents below the old one":"Insérer une nouvelle table des matières sous l'ancienne","Update page numbers only keeps the old text. Update entire table rebuilds the list from the current headings.":"Mettre à jour les numéros de page uniquement garde l'ancien texte. Mettre à jour toute la table reconstruit la liste à partir des titres actuels.","Which file type should you use for a company letterhead that everyone reuses?":"Quel type de fichier utiliser pour un papier à en-tête d'entreprise que tout le monde réutilise ?",".dotx":".dotx",".docx":".docx",".pdf":".pdf",".xlsx":".xlsx","A .dotx template opens as a new untitled document each time, so the original letterhead is never overwritten.":"Un modèle .dotx s'ouvre à chaque fois comme un nouveau document sans titre : le papier à en-tête d'origine n'est jamais écrasé.","You changed a number in a Word table, but the =SUM(ABOVE) total did not change. What do you do?":"Vous avez modifié un nombre dans un tableau Word, mais le total =SUM(ABOVE) n'a pas changé. Que faites-vous ?","Retype the total":"Ressaisir le total","Save the document":"Enregistrer le document","Convert the table to text":"Convertir le tableau en texte","Word formulas are fields that do not recalculate by themselves. F9 updates the selected fields.":"Les formules Word sont des champs qui ne se recalculent pas tout seuls. F9 met à jour les champs sélectionnés.","Which recipient list will work best for a mail merge?":"Quelle liste de destinataires fonctionnera le mieux pour un publipostage ?","A list with a merged title in row 1 and totals at the bottom":"Une liste avec un titre fusionné en ligne 1 et des totaux en bas","One header row in row 1, one row per person, no merged cells and no totals":"Une ligne d'en-tête en ligne 1, une ligne par personne, sans cellules fusionnées ni totaux","A Word table with one person per paragraph":"Un tableau Word avec une personne par paragraphe","A list with names and addresses in one column":"Une liste avec les noms et les adresses dans une seule colonne","Word reads the first row as field names and creates one letter per row, so the list must be clean and rectangular.":"Word lit la première ligne comme noms de champs et crée une lettre par ligne : la liste doit donc être propre et rectangulaire.","Your first workbook: entering and organising data":"Votre premier classeur : saisir et organiser les données","Enter text, numbers and dates so that Excel recognises their type":"Saisir du texte, des nombres et des dates pour qu'Excel reconnaisse leur type","Fill series and patterns quickly with AutoFill and Flash Fill":"Remplir rapidement des séries et des modèles avec la recopie incrémentée et le Remplissage instantané","Organise sheets and save a workbook as .xlsx, .csv or PDF":"Organiser les feuilles et enregistrer un classeur au format .xlsx, .csv ou PDF","Excel is where most offices keep their numbers: daily sales, school fees, fuel purchases, staff hours, stock. A spreadsheet is only as reliable as the data typed into it, so this lesson is about entering data correctly and moving around a workbook quickly before we start calculating.":"C'est dans Excel que la plupart des bureaux tiennent leurs chiffres : ventes du jour, frais de scolarité, achats de carburant, heures du personnel, stock. Une feuille de calcul n'est fiable que si les données saisies le sont. Cette leçon porte donc sur la saisie correcte des données et sur les déplacements rapides dans un classeur, avant de commencer à calculer.","Workbook, worksheet, cell and range":"Classeur, feuille de calcul, cellule et plage","Term":"Terme","Workbook":"Classeur","The Excel file itself":"Le fichier Excel lui-même","2026_Ventes-Boutique.xlsx":"2026_Ventes-Boutique.xlsx","Worksheet (sheet)":"Feuille de calcul (feuille)","One page of the workbook, shown as a tab at the bottom":"Une page du classeur, affichée sous forme d'onglet en bas de l'écran","A sheet per month: Jan, Feb, Mar":"Une feuille par mois : Janv, Févr, Mars","The box where a column and a row meet, named by its column letter and row number":"La case où se croisent une colonne et une ligne, désignée par la lettre de sa colonne et le numéro de sa ligne","C4 is column C, row 4":"C4 correspond à la colonne C, ligne 4","Range":"Plage","A rectangle of cells, written as first cell:last cell":"Un rectangle de cellules, noté première cellule:dernière cellule","B2:B31 holds one month of daily sales":"B2:B31 contient un mois de ventes journalières","Text, numbers and dates":"Texte, nombres et dates","(names, products, references) is aligned to the left by default.":"(noms, produits, références) : aligné à gauche par défaut.","Numbers":"Nombres","are aligned to the right. Type them without units or spaces, for example 350000, and let the number format add the separator and FCFA later.":": alignés à droite. Tapez-les sans unité ni espace, par exemple 350000, et laissez le format de nombre ajouter ensuite le séparateur et FCFA.","Dates":"Dates","are stored as numbers too, so Excel can sort them and count the days between two dates. Press":": elles aussi enregistrées comme des nombres, ce qui permet à Excel de les trier et de compter les jours entre deux dates. Appuyez sur","to type today's date.":"pour saisir la date du jour.","to confirm and move down,":"pour valider et descendre,","to confirm and move right, and":"pour valider et passer à droite, et","to edit the active cell without retyping it.":"pour modifier la cellule active sans tout retaper.","Numbers stored as text break your totals":"Les nombres stockés sous forme de texte faussent vos totaux","An amount typed as 12 500 FCFA, or pasted from a bank or mobile money statement, is often stored as text. It sits on the left of the cell, shows a small green triangle, and SUM simply ignores it. Your total is wrong without any error message. Retype the number, or select the cells and choose":"Un montant saisi sous la forme 12 500 FCFA, ou collé depuis un relevé bancaire ou de mobile money, est souvent stocké sous forme de texte. Il se place à gauche de la cellule, affiche un petit triangle vert, et SUM (SOMME) l'ignore tout simplement. Votre total est faux sans aucun message d'erreur. Retapez le nombre, ou sélectionnez les cellules et choisissez","Convert to Number":"Convertir en nombre","from the warning icon.":"dans l'icône d'avertissement.","Fix the amounts stored as text":"Corrigez les montants stockés sous forme de texte","The total in":"Le total en","is too low because two amounts were typed with \"FCFA\" and are stored as text. Retype":"est trop faible, car deux montants ont été saisis avec « FCFA » et sont stockés sous forme de texte. Retapez","as plain numbers. The total and the count below it will correct themselves.":"comme de simples nombres. Le total et le décompte situé en dessous se corrigeront d'eux-mêmes.","Type only the digits: 7200 in D3 and 13000 in D5, with no spaces or letters. COUNT counts only real numbers, so it shows 5 when every amount is a number.":"Tapez uniquement les chiffres : 7200 en D3 et 13000 en D5, sans espace ni lettre. COUNT (NB) ne compte que les vrais nombres : il affiche 5 lorsque tous les montants sont des nombres.","Dates and regional settings":"Dates et paramètres régionaux","On a computer set to French (Cameroon), Excel reads 03/04/2026 as 3 April; on one set to English (United States) it reads 4 March. When files travel between colleagues, type dates as 2026-04-03 (year-month-day): Excel understands this form on every computer, and it matches the file naming rule from Module 1.":"Sur un ordinateur réglé en français (Cameroun), Excel lit 03/04/2026 comme le 3 avril ; sur un ordinateur réglé en anglais (États-Unis), il lit le 4 mars. Lorsque des fichiers circulent entre collègues, saisissez les dates sous la forme 2026-04-03 (année-mois-jour) : Excel comprend cette forme sur tous les ordinateurs, et elle respecte la règle de nommage des fichiers du Module 1.","Fill handle, AutoFill and Flash Fill":"Poignée de recopie, recopie incrémentée et Remplissage instantané","Fill a series with the fill handle":"Remplir une série avec la poignée de recopie","Type the first value, for example":"Tapez la première valeur, par exemple","Jan":"janv.","Monday":"lundi",". For a number series, type the first two values (1 and 2) and select both.":". Pour une série de nombres, tapez les deux premières valeurs (1 et 2) et sélectionnez-les toutes les deux.","Point at the small square in the bottom-right corner of the selection. The pointer becomes a thin black cross: this is the":"Pointez le petit carré situé dans le coin inférieur droit de la sélection. Le pointeur devient une fine croix noire : c'est la","fill handle":"poignée de recopie","Drag down or right. Excel continues the series: Feb, Mar, Apr… or 3, 4, 5…":"Faites glisser vers le bas ou vers la droite. Excel prolonge la série : févr., mars, avr.… ou 3, 4, 5…","Double-click the fill handle instead of dragging to fill down to the last row of the neighbouring column.":"Double-cliquez sur la poignée de recopie au lieu de la faire glisser pour remplir jusqu'à la dernière ligne de la colonne voisine.","Use the":"Utilisez le bouton","Auto Fill Options":"Options de recopie incrémentée","button that appears to switch between Copy Cells and Fill Series.":"qui apparaît pour choisir entre Copier les cellules et Incrémenter une série.","Flash Fill":"Remplissage instantané","learns a pattern from an example. If column A holds invoice references such as DLA-2026-014, type DLA in the first cell of column B, then press":"apprend un modèle à partir d'un exemple. Si la colonne A contient des références de facture comme DLA-2026-014, tapez DLA dans la première cellule de la colonne B, puis appuyez sur",": Excel fills the city code for every row. It works just as well to join first names and surnames or to change their capitals.":" : Excel remplit le code de la ville pour chaque ligne. Cela fonctionne tout aussi bien pour réunir prénoms et noms ou pour modifier leurs majuscules.","Data Tools":"Outils de données","Also on Home › Editing › Fill › Flash Fill. Check the result: Flash Fill guesses, and does not update when the source changes.":"Également dans Accueil › Édition › Remplissage › Remplissage instantané. Vérifiez le résultat : le Remplissage instantané devine, et il ne se met pas à jour quand la source change.","Move around and organise sheets":"Se déplacer et organiser les feuilles","Jump to the edge of the data in that direction":"Aller au bord des données dans cette direction","Go to cell A1":"Aller à la cellule A1","Go to the last used cell":"Aller à la dernière cellule utilisée","Next sheet (Ctrl + Page Up for the previous one)":"Feuille suivante (Ctrl + Pg préc pour la précédente)","Insert a new sheet":"Insérer une nouvelle feuille","Enter today's date":"Saisir la date du jour","Enter the current time":"Saisir l'heure actuelle","Practise the data-entry shortcuts":"Entraînez-vous aux raccourcis de saisie","Edit the active cell":"Modifier la cellule active","Name and colour sheet tabs":"Nommer et colorer les onglets de feuille","Double-click a sheet tab (or right-click it and choose":"Double-cliquez sur un onglet de feuille (ou faites un clic droit et choisissez","Rename":"Renommer",") and type a short name such as":") et tapez un nom court comme","Jan-2026":"Janv-2026","Douala":"Douala","Right-click the tab and choose":"Faites un clic droit sur l'onglet et choisissez","Tab Color":"Couleur d'onglet","to group related sheets, for example green for sales and orange for expenses.":"pour regrouper les feuilles liées, par exemple en vert pour les ventes et en orange pour les dépenses.","Drag a tab left or right to change the order. Hold":"Faites glisser un onglet vers la gauche ou la droite pour changer l'ordre. Maintenez","while dragging to make a copy of the sheet.":"enfoncée pendant le glissement pour faire une copie de la feuille.","Save in the right format":"Enregistrer dans le bon format","Format":"Format","What it keeps":"Ce qu'il conserve","Everything: all sheets, formulas, formatting and charts":"Tout : toutes les feuilles, les formules, la mise en forme et les graphiques","The normal working format":"Le format de travail habituel",".csv":".csv","Only the values of the active sheet, as plain text":"Uniquement les valeurs de la feuille active, en texte brut","Another system (accounting software, a database, a mobile money platform) must import the data":"Un autre système (logiciel de comptabilité, base de données, plateforme de mobile money) doit importer les données","A fixed picture of the printed pages":"Une image figée des pages imprimées","The figures are final and must be read, not changed":"Les chiffres sont définitifs et doivent être lus, pas modifiés","Save as type":"Type","Choose Excel Workbook (*.xlsx), CSV UTF-8 (Comma delimited) (*.csv) or PDF (*.pdf).":"Choisissez Classeur Excel (*.xlsx), CSV UTF-8 (délimité par des virgules) (*.csv) ou PDF (*.pdf).","You paste a column of amounts from a mobile money statement. They sit on the left of the cells and SUM returns a total that is far too low. What is the most likely cause?":"Vous collez une colonne de montants depuis un relevé de mobile money. Ils se placent à gauche des cellules et SUM (SOMME) renvoie un total bien trop faible. Quelle est la cause la plus probable ?","The column is too narrow":"La colonne est trop étroite","The amounts are stored as text":"Les montants sont stockés sous forme de texte","The sheet is protected":"La feuille est protégée","SUM only works on the first ten rows":"SUM (SOMME) ne fonctionne que sur les dix premières lignes","Left alignment and a green triangle are the signs of numbers stored as text. SUM skips text, so those amounts are left out of the total without any error.":"L'alignement à gauche et le triangle vert sont les signes de nombres stockés sous forme de texte. SUM (SOMME) ignore le texte : ces montants sont donc exclus du total sans aucune erreur.","Create a workbook with three sheets named Jan, Feb and Mar, each with a different tab colour":"Créez un classeur de trois feuilles nommées Janv, Févr et Mars, chacune avec une couleur d'onglet différente","On Jan, type a date in A2 as 2026-01-05 and fill the next 10 days with the fill handle":"Sur Janv, tapez une date en A2 sous la forme 2026-01-05 et remplissez les 10 jours suivants avec la poignée de recopie","Type five invoice references like DLA-2026-014 and extract the city codes with Ctrl + E":"Tapez cinq références de facture comme DLA-2026-014 et extrayez les codes de ville avec Ctrl + E","Type one amount as \"5 000 FCFA\", watch SUM ignore it, then convert it to a number":"Tapez un montant sous la forme « 5 000 FCFA », constatez que SUM (SOMME) l'ignore, puis convertissez-le en nombre","Save the workbook as .xlsx, then save the Jan sheet as a CSV copy":"Enregistrez le classeur au format .xlsx, puis enregistrez une copie de la feuille Janv au format CSV","Keyboard shortcuts in Excel":"Raccourcis clavier dans Excel","Exam MO-210: Microsoft Excel (Microsoft 365 Apps)":"Examen MO-210 : Microsoft Excel (Microsoft 365 Apps)","Write formulas with operators and the everyday functions SUM, AVERAGE, MIN, MAX, COUNT and COUNTA":"Écrire des formules avec les opérateurs et les fonctions courantes SUM, AVERAGE, MIN, MAX, COUNT et COUNTA (SOMME, MOYENNE, MIN, MAX, NB et NBVAL)","Choose between relative, absolute and mixed references and toggle them with F4":"Choisir entre références relatives, absolues et mixtes, et passer de l'une à l'autre avec F4","Calculate percentages and growth, and fix the most common formula errors":"Calculer des pourcentages et des taux de croissance, et corriger les erreurs de formule les plus courantes","A formula turns a sheet of numbers into a tool that answers questions: how much did we collect, what is the average, which branch sold most? Because formulas point to cells instead of fixed numbers, the answers update by themselves when the data changes.":"Une formule transforme une feuille de chiffres en un outil qui répond aux questions : combien avons-nous encaissé, quelle est la moyenne, quelle agence a le plus vendu ? Comme les formules renvoient à des cellules et non à des nombres fixes, les réponses se mettent à jour d'elles-mêmes lorsque les données changent.","Anatomy of a formula":"Anatomie d'une formule","Every formula starts with an equals sign.":"Toute formule commence par le signe égal.","multiplies the value in B2 by the value in C2. Click a cell instead of typing its address to avoid typing mistakes, and press":"multiplie la valeur de B2 par la valeur de C2. Cliquez sur une cellule plutôt que de taper son adresse pour éviter les fautes de frappe, et appuyez sur","to confirm.":"pour valider.","Operator":"Opérateur","Meaning":"Signification","Add, subtract":"Additionner, soustraire","Multiply, divide":"Multiplier, diviser","Power":"Puissance","=1.05^3 (three years of 5% growth)":"=1,05^3 (trois ans de croissance à 5 %)","Per cent":"Pour cent","Join text":"Assembler du texte","Order of operations":"Ordre des opérations","Excel calculates brackets first, then powers, then multiplication and division, then addition and subtraction. So =10+20/2 gives 20, not 15. To average two cells write =(B2+C2)/2, with the brackets.":"Excel calcule d'abord les parenthèses, puis les puissances, puis les multiplications et divisions, et enfin les additions et soustractions. Ainsi, =10+20/2 donne 20, et non 15. Pour la moyenne de deux cellules, écrivez =(B2+C2)/2, avec les parenthèses.","The functions you will use every day":"Les fonctions que vous utiliserez tous les jours","Function":"Fonction","What it returns":"Ce qu'elle renvoie","SUM":"SUM (SOMME)","The total of the numbers":"Le total des nombres","=SUM(C2:C31)":"=SUM(C2:C31)","AVERAGE":"AVERAGE (MOYENNE)","The mean of the numbers (empty cells are ignored)":"La moyenne des nombres (les cellules vides sont ignorées)","=AVERAGE(C2:C31)":"=AVERAGE(C2:C31)","MIN / MAX":"MIN / MAX","The smallest / largest number":"Le plus petit / le plus grand nombre","=MAX(C2:C31)":"=MAX(C2:C31)","COUNT":"COUNT (NB)","How many cells contain numbers":"Le nombre de cellules qui contiennent des nombres","=COUNT(C2:C31)":"=COUNT(C2:C31)","COUNTA":"COUNTA (NBVAL)","How many cells are not empty (text or numbers)":"Le nombre de cellules non vides (texte ou nombres)","=COUNTA(A2:A31)":"=COUNTA(A2:A31)","Editing":"Édition","AutoSum":"Somme automatique","Or press Alt + =. Excel proposes a range: check it before pressing Enter. The arrow next to AutoSum offers Average, Count Numbers, Max and Min.":"Ou appuyez sur Alt + =. Excel propose une plage : vérifiez-la avant d'appuyer sur Entrée. La flèche à côté de Somme automatique propose Moyenne, Nombres, Max et Min.","School fees: the first instalment":"Frais de scolarité : la première tranche","Pupils with an empty cell in column C have not paid yet. Fill":"Les élèves dont la cellule de la colonne C est vide n'ont pas encore payé. Remplissez","with the total collected, the average payment, the smallest and largest payments, the number of pupils who paid, the number of pupils on the list and the number who have not paid.":"avec le total encaissé, le paiement moyen, le plus petit et le plus grand paiement, le nombre d'élèves qui ont payé, le nombre d'élèves de la liste et le nombre de ceux qui n'ont pas payé.","Use SUM, AVERAGE, MIN and MAX on C2:C8. COUNT(C2:C8) counts only the payments; COUNTA(A2:A8) counts every name. Pupils not paid is one count minus the other: =F7-F6.":"Utilisez SUM, AVERAGE, MIN et MAX (SOMME, MOYENNE, MIN, MAX) sur C2:C8. COUNT(C2:C8) ne compte que les paiements ; COUNTA(A2:A8) compte tous les noms. Les élèves qui n'ont pas payé, c'est un décompte moins l'autre : =F7-F6.","Relative, absolute and mixed references":"Références relatives, absolues et mixtes","When you copy a formula, Excel adjusts its cell references.":"Lorsque vous copiez une formule, Excel ajuste ses références de cellule.","copied one row down becomes":"copiée une ligne plus bas devient",". That is right for C, but wrong for B1 if B1 holds a single rate that every row needs. A dollar sign locks the part of the reference that must not move.":". C'est juste pour C, mais faux pour B1 si B1 contient un taux unique dont toutes les lignes ont besoin. Le signe dollar verrouille la partie de la référence qui ne doit pas bouger.","Reference":"Référence","Written":"Écriture","When copied":"Une fois copiée","Relative":"Relative","Column and row both change":"La colonne et la ligne changent toutes les deux","Absolute":"Absolue","Always points to B1":"Renvoie toujours à B1","Mixed (row locked)":"Mixte (ligne verrouillée)","The column changes, the row stays 1":"La colonne change, la ligne reste 1","Mixed (column locked)":"Mixte (colonne verrouillée)","The column stays B, the row changes":"La colonne reste B, la ligne change","Lock a reference with F4":"Verrouiller une référence avec F4","Type the formula, for example =C4*B1, and leave the cursor on or just after B1.":"Tapez la formule, par exemple =C4*B1, et laissez le curseur sur B1 ou juste après.","once to get $B$1. Press again for B$1, again for $B1, and once more to return to B1.":"une fois pour obtenir $B$1. Appuyez encore pour B$1, encore pour $B1, et une dernière fois pour revenir à B1.",", then copy the formula down with the fill handle.":", puis recopiez la formule vers le bas avec la poignée de recopie.","Click a copied cell and check the formula bar: the locked reference has not moved.":"Cliquez sur une cellule copiée et regardez la barre de formule : la référence verrouillée n'a pas bougé.","Fuel costs with one price cell":"Coût du carburant avec une seule cellule de prix","The fuel price is in":"Le prix du carburant se trouve en",". Fill":". Remplissez","with each vehicle's cost (litres × price),":"avec le coût de chaque véhicule (litres × prix),","with the total cost, and":"avec le coût total, et","with each vehicle's share of the total. Use absolute references so the formulas can be copied down.":"avec la part de chaque véhicule dans le total. Utilisez des références absolues pour pouvoir recopier les formules vers le bas.","D4 is =C4*$B$1 and E4 is =D4/$D$8. Without the dollar signs, the copy in D5 would multiply by B2, which is empty, and give 0.":"D4 vaut =C4*$B$1 et E4 vaut =D4/$D$8. Sans les signes dollar, la copie en D5 multiplierait par B2, qui est vide, et donnerait 0.","Put every rate in its own cell":"Placez chaque taux dans sa propre cellule","VAT at 19.25%, the pump price of fuel, a per diem or an exchange rate change during the year. Type each one once in a clearly labelled cell and refer to it with an absolute reference. When the rate changes, you update one cell instead of hunting through hundreds of formulas.":"La TVA à 19,25 %, le prix du carburant à la pompe, un per diem ou un taux de change évoluent au cours de l'année. Saisissez chacun une seule fois dans une cellule clairement libellée et faites-y référence avec une référence absolue. Quand le taux change, vous modifiez une cellule au lieu de fouiller des centaines de formules.","Percentages and growth":"Pourcentages et croissance","Share of a total:":"Part d'un total :",", then apply the Percent Style.":", puis appliquez le Style de pourcentage.","Growth from last year to this year:":"Croissance de l'an dernier à cette année :",", or":", ou",". From 800 000 to 920 000 FCFA is 15% growth.":". Passer de 800 000 à 920 000 FCFA représente une croissance de 15 %.","Add a percentage:":"Ajouter un pourcentage :",". Remove a discount:":". Déduire une remise :","A percentage is a share: 15% is stored as 0.15. Type 15% with the sign, or 0.15, never 15.":"Un pourcentage est une part : 15 % est enregistré comme 0,15. Tapez 15 % avec le signe, ou 0,15, jamais 15.","When a formula shows an error":"Quand une formule affiche une erreur","Error":"Erreur","Usual cause":"Cause habituelle","Fix":"Solution","#DIV/0!":"#DIV/0!","Division by an empty cell or by zero":"Division par une cellule vide ou par zéro","Check the divisor; for a new branch with no sales last year, growth cannot be calculated":"Vérifiez le diviseur ; pour une nouvelle agence sans ventes l'an dernier, la croissance ne peut pas être calculée","#VALUE!":"#VALEUR!","Arithmetic on text, for example a number stored as text with FCFA":"Un calcul sur du texte, par exemple un nombre stocké sous forme de texte avec FCFA","Convert the text to a number":"Convertissez le texte en nombre","#NAME?":"#NOM?","A misspelled function (=SUMM) or text typed without quotes":"Une fonction mal orthographiée (=SUMM) ou du texte saisi sans guillemets","Correct the spelling; use the function list that appears as you type":"Corrigez l'orthographe ; utilisez la liste de fonctions qui s'affiche pendant la saisie","#REF!":"#REF!","A cell the formula pointed to was deleted":"Une cellule à laquelle la formule renvoyait a été supprimée","Undo the deletion or rewrite the reference":"Annulez la suppression ou réécrivez la référence","Not an error: the column is too narrow for the number":"Pas une erreur : la colonne est trop étroite pour le nombre","Double-click the column's right border to widen it":"Double-cliquez sur la bordure droite de la colonne pour l'élargir","Practise the formula shortcuts":"Entraînez-vous aux raccourcis des formules","Toggle absolute and relative references":"Basculer entre références absolues et relatives","Enter the same formula in every selected cell":"Saisir la même formule dans toutes les cellules sélectionnées","E4 contains =D4/D8, where D8 is the total. You copy it down to E5 and get #DIV/0!. How should E4 be written?":"E4 contient =D4/D8, où D8 est le total. Vous la recopiez en E5 et obtenez #DIV/0!. Comment faut-il écrire E4 ?","=SUM(D4/D8)":"=SUM(D4/D8)","Copying moves D8 to D9, which is empty, so Excel divides by zero. $D$8 keeps the total fixed while D4 moves down with each row.":"La copie déplace D8 vers D9, qui est vide : Excel divise donc par zéro. $D$8 garde le total fixe tandis que D4 descend avec chaque ligne.","A shop sold 800 000 FCFA in March and 920 000 FCFA in April (B2 and C2). Which formula gives the growth?":"Une boutique a vendu pour 800 000 FCFA en mars et 920 000 FCFA en avril (B2 et C2). Quelle formule donne la croissance ?","Growth is the change divided by the starting value: 120 000 / 800 000 = 0.15, or 15%. Without brackets, Excel divides B2 by B2 first.":"La croissance est la variation divisée par la valeur de départ : 120 000 / 800 000 = 0,15, soit 15 %. Sans parenthèses, Excel divise d'abord B2 par B2.","List ten expenses in column B and total them with Alt + =":"Listez dix dépenses dans la colonne B et faites-en le total avec Alt + =","Add the average, the smallest and the largest expense with AVERAGE, MIN and MAX":"Ajoutez la dépense moyenne, la plus petite et la plus grande avec AVERAGE (MOYENNE), MIN et MAX","Put a VAT rate of 19.25% in one cell and calculate VAT for each expense with an absolute reference":"Placez un taux de TVA de 19,25 % dans une cellule et calculez la TVA de chaque dépense avec une référence absolue","Calculate each expense's share of the total and apply the Percent Style":"Calculez la part de chaque dépense dans le total et appliquez le Style de pourcentage","Create a #DIV/0! and a #NAME? error on purpose, then fix them":"Provoquez volontairement une erreur #DIV/0! et une erreur #NOM?, puis corrigez-les","Switch between relative, absolute, and mixed references":"Basculer entre les références relatives, absolues et mixtes","Overview of formulas in Excel":"Vue d'ensemble des formules dans Excel","Sort a list on one or several levels and filter it to show only the rows you need":"Trier une liste sur un ou plusieurs niveaux et la filtrer pour n'afficher que les lignes utiles","Format a list as a table and apply number formats for FCFA, percentages and thousands":"Mettre une liste sous forme de tableau et appliquer des formats de nombre pour les FCFA, les pourcentages et les milliers","Highlight key values with conditional formatting and clean data with Freeze Panes, Remove Duplicates and Find & Replace":"Faire ressortir les valeurs clés avec la mise en forme conditionnelle et nettoyer les données avec Figer les volets, Supprimer les doublons et Rechercher et remplacer","A list of 500 transactions is hard to read. Sorting puts it in a useful order, filtering hides what you do not need, and formatting makes the important figures stand out. None of these tools changes your data: they change how you see it.":"Une liste de 500 transactions est difficile à lire. Le tri la met dans un ordre utile, le filtre masque ce dont vous n'avez pas besoin, et la mise en forme fait ressortir les chiffres importants. Aucun de ces outils ne modifie vos données : ils changent la façon dont vous les voyez.","Prepare the list first":"Préparez d'abord la liste","One header row with a clear, unique name in every column.":"Une seule ligne d'en-tête, avec un nom clair et unique dans chaque colonne.","No completely blank rows or columns inside the list: Excel treats them as the end of the data.":"Aucune ligne ou colonne entièrement vide dans la liste : Excel les considère comme la fin des données.","One type of data per column: only dates in the date column, only numbers in the amount column.":"Un seul type de données par colonne : uniquement des dates dans la colonne des dates, uniquement des nombres dans la colonne des montants.","No merged cells inside the list. Merged cells block sorting.":"Aucune cellule fusionnée dans la liste. Les cellules fusionnées bloquent le tri.","Sort on one or several levels":"Trier sur un ou plusieurs niveaux","To sort on one column, click any cell in it and use":"Pour trier sur une colonne, cliquez sur n'importe quelle cellule de celle-ci et utilisez","Sort A to Z":"Trier de A à Z","Sort Z to A":"Trier de Z à A",". Excel sorts the whole list and keeps each row together. For more than one criterion, use the Sort dialog.":". Excel trie toute la liste et garde chaque ligne entière. Pour plus d'un critère, utilisez la boîte de dialogue Trier.","Sort & Filter":"Trier et filtrer","Also Home › Editing › Sort & Filter › Custom Sort.":"Également dans Accueil › Édition › Trier et filtrer › Tri personnalisé.","Sort by region, then by amount":"Trier par région, puis par montant","Click any cell inside the list, then open":"Cliquez sur n'importe quelle cellule de la liste, puis ouvrez","Data › Sort":"Données › Trier","Check that":"Vérifiez que la case","My data has headers":"Mes données ont des en-têtes","is ticked.":"est cochée.","In":"Dans","Sort by":"Trier par",", choose Region, order A to Z.":", choisissez Région, ordre de A à Z.","Add Level":"Ajouter un niveau",". In":". Dans","Then by":"Puis par",", choose Amount, order Largest to Smallest.":", choisissez Montant, ordre Du plus grand au plus petit.","Click OK. Rows are grouped by region and, inside each region, the largest amounts come first.":"Cliquez sur OK. Les lignes sont regroupées par région et, dans chaque région, les montants les plus élevés viennent en premier.","Never sort a single selected column":"Ne triez jamais une seule colonne sélectionnée","If you select only one column and sort it, Excel warns you. Always choose":"Si vous sélectionnez une seule colonne et la triez, Excel vous avertit. Choisissez toujours","Expand the selection":"Étendre la sélection",". Otherwise that column moves on its own and every amount ends up next to the wrong name.":". Sinon, cette colonne bouge seule et chaque montant se retrouve à côté du mauvais nom.","Subtotals after sorting":"Sous-totaux après un tri","The deposits list has been sorted by region, then by amount. Because each region is now a block of rows, a simple SUM gives each regional total. Fill":"La liste des dépôts a été triée par région, puis par montant. Comme chaque région forme maintenant un bloc de lignes, une simple SUM (SOMME) donne chaque total régional. Remplissez","with the three regional totals,":"avec les trois totaux régionaux,","with the total of all regions and":"avec le total de toutes les régions et","with Littoral's share of that total.":"avec la part du Littoral dans ce total.","Centre is rows 2 to 4, Littoral rows 5 to 8, Ouest rows 9 and 10: =SUM(C2:C4), =SUM(C5:C8), =SUM(C9:C10). The share is =F3/F5.":"Le Centre occupe les lignes 2 à 4, le Littoral les lignes 5 à 8, l'Ouest les lignes 9 et 10 : =SUM(C2:C4), =SUM(C5:C8), =SUM(C9:C10). La part vaut =F3/F5.","Filter to show only what you need":"Filtrer pour n'afficher que l'utile","Filter":"Filtrer","Or Ctrl + Shift + L. An arrow appears in every header cell.":"Ou Ctrl + Maj + L. Une flèche apparaît dans chaque cellule d'en-tête.","Click a header arrow and tick only the values to show, for example Littoral and Ouest.":"Cliquez sur la flèche d'un en-tête et cochez uniquement les valeurs à afficher, par exemple Littoral et Ouest.","Use":"Utilisez","Number Filters › Greater Than":"Filtres numériques › Supérieur à","for amounts,":"pour les montants,","Text Filters › Contains":"Filtres textuels › Contient","for part of a name, and":"pour une partie d'un nom, et","Date Filters":"Filtres chronologiques","for a month or a quarter.":"pour un mois ou un trimestre.","Filters on several columns combine: Region = Littoral AND Amount greater than 500 000.":"Les filtres sur plusieurs colonnes se combinent : Région = Littoral ET Montant supérieur à 500 000.","Hidden rows are not deleted. The row numbers turn blue, and the status bar shows how many records were found.":"Les lignes masquées ne sont pas supprimées. Les numéros de ligne deviennent bleus, et la barre d'état indique le nombre d'enregistrements trouvés.","Clear a filter with the header arrow ›":"Effacez un filtre avec la flèche de l'en-tête ›","Clear Filter From":"Effacer le filtre de",", or remove all filters with":", ou retirez tous les filtres avec","Format as Table and number formats":"Mettre sous forme de tableau et formats de nombre","Turn a list into an Excel table":"Transformer une liste en tableau Excel","Click inside the list and choose":"Cliquez dans la liste et choisissez","Home › Format as Table":"Accueil › Mettre sous forme de tableau","(or press":"(ou appuyez sur","), then pick a style.":"), puis choisissez un style.","Confirm the range and that":"Confirmez la plage et vérifiez que la case","My table has headers":"Mon tableau comporte des en-têtes","Table Design":"Création de tableau","Total Row":"Ligne Total","Type a new row under the table: the table grows and the formatting, filters and formulas follow.":"Tapez une nouvelle ligne sous le tableau : le tableau s'agrandit et la mise en forme, les filtres et les formules suivent.","You want to show":"Vous voulez afficher","Number format":"Format de nombre","Number with thousands separator, 0 decimals":"Nombre avec séparateur de milliers, 0 décimale","Home › Number › Comma Style, then Decrease Decimal":"Accueil › Nombre › Séparateur de milliers, puis Réduire les décimales","1 250 000 FCFA":"1 250 000 FCFA","Custom: #,##0 \"FCFA\"":"Personnalisé : # ##0 \"FCFA\" (#,##0 \"FCFA\" dans Excel en anglais)","Format Cells (Ctrl + 1) › Number › Custom":"Format de cellule (Ctrl + 1) › Nombre › Personnalisée","Percentage":"Pourcentage","Home › Number › Percent Style (Ctrl + Shift + %)":"Accueil › Nombre › Style de pourcentage (Ctrl + Maj + %)","Custom date: yyyy-mm-dd":"Date personnalisée : aaaa-mm-jj","Format Cells › Number › Custom":"Format de cellule › Nombre › Personnalisée","FCFA has no decimals":"Le FCFA n'a pas de décimales","The CFA franc is used without cents, so show amounts with 0 decimals and a thousands separator. The separator shown (a space or a comma) depends on the computer's regional settings; the number stored in the cell stays the same. Keep the custom format in one cell style so every report from the finance team looks alike.":"Le franc CFA s'utilise sans centimes : affichez donc les montants avec 0 décimale et un séparateur de milliers. Le séparateur affiché (une espace ou une virgule) dépend des paramètres régionaux de l'ordinateur ; le nombre enregistré dans la cellule reste le même. Enregistrez le format personnalisé dans un style de cellule pour que tous les rapports du service financier se ressemblent.","Conditional formatting, Freeze Panes and clean-up tools":"Mise en forme conditionnelle, Figer les volets et outils de nettoyage","Styles":"Styles","Conditional Formatting":"Mise en forme conditionnelle","Highlight Cells Rules":"Règles de mise en surbrillance des cellules","Greater Than":"Supérieur à","For example, fill in red every invoice above 500 000 FCFA. Data Bars, in the same menu, draw a bar in each cell proportional to its value.":"Par exemple, colorez en rouge toute facture supérieure à 500 000 FCFA. Les Barres de données, dans le même menu, tracent dans chaque cellule une barre proportionnelle à sa valeur.","Window":"Fenêtre","Freeze Panes":"Figer les volets","Freeze Top Row":"Figer la ligne supérieure","The header row stays visible while you scroll down a long list.":"La ligne d'en-tête reste visible pendant que vous faites défiler une longue liste.","Remove Duplicates":"Supprimer les doublons","Tick only the columns that define a duplicate, such as the invoice number. Work on a copy: removed rows are deleted.":"Cochez uniquement les colonnes qui définissent un doublon, comme le numéro de facture. Travaillez sur une copie : les lignes retirées sont supprimées.","Turn filters on or off":"Activer ou désactiver les filtres","Format as Table":"Mettre sous forme de tableau","Find":"Rechercher","Find and Replace":"Rechercher et remplacer","Practise the list shortcuts":"Entraînez-vous aux raccourcis des listes","Choose the right tool for the list":"Choisissez le bon outil pour la liste","A logistics company in Douala keeps 600 deliveries in one sheet. Choose the tool or setting for each request. Type shortcuts as keys joined with +, for example Ctrl + B.":"Une entreprise de logistique de Douala enregistre 600 livraisons dans une feuille. Choisissez l'outil ou le réglage adapté à chaque demande. Tapez les raccourcis sous forme de touches reliées par +, par exemple Ctrl + B.","Sort changes the order, Filter hides rows, conditional formatting colours cells by rule, Freeze Panes keeps headers visible, and Remove Duplicates deletes repeated rows.":"Le tri change l'ordre, le filtre masque des lignes, la mise en forme conditionnelle colore les cellules selon une règle, Figer les volets garde les en-têtes visibles, et Supprimer les doublons efface les lignes répétées.","Order the list by driver A to Z and, for each driver, by delivery fee from highest to lowest.":"Classez la liste par chauffeur de A à Z et, pour chaque chauffeur, par frais de livraison du plus élevé au plus faible.","Two criteria need two levels in the Sort dialog, the main one first.":"Deux critères demandent deux niveaux dans la boîte de dialogue Trier, le principal en premier.","Sort A to Z on the Driver column":"Trier de A à Z sur la colonne Chauffeur","Data › Sort with two levels: Driver A to Z, then Fee Largest to Smallest":"Données › Trier avec deux niveaux : Chauffeur de A à Z, puis Frais du plus grand au plus petit","Filter on the Driver column":"Filtrer sur la colonne Chauffeur","Which shortcut turns the filter arrows on and off?":"Quel raccourci active et désactive les flèches de filtre ?","You filter to show only Bonabéri deliveries. What happens to the other rows?":"Vous filtrez pour n'afficher que les livraisons de Bonabéri. Que deviennent les autres lignes ?","A filter only hides rows. The blue row numbers show that some rows are hidden.":"Un filtre ne fait que masquer des lignes. Les numéros de ligne en bleu indiquent que certaines lignes sont masquées.","They are deleted":"Elles sont supprimées","They are hidden and come back when the filter is cleared":"Elles sont masquées et réapparaissent quand le filtre est effacé","They move to a new sheet":"Elles passent dans une nouvelle feuille","They move to the bottom of the list":"Elles passent en bas de la liste","Every fee above 25 000 FCFA must turn red automatically, even when fees change.":"Tous les frais supérieurs à 25 000 FCFA doivent passer en rouge automatiquement, même quand les frais changent.","Conditional formatting re-checks its rule every time the value changes. Manual colouring does not.":"La mise en forme conditionnelle revérifie sa règle chaque fois que la valeur change. Une couleur appliquée à la main, non.","Home › Font Color":"Accueil › Couleur de police","Home › Conditional Formatting › Highlight Cells Rules › Greater Than":"Accueil › Mise en forme conditionnelle › Règles de mise en surbrillance des cellules › Supérieur à","Data › Filter":"Données › Filtrer","Review › New Comment":"Révision › Nouveau commentaire","The column headings disappear when you scroll to row 400.":"Les en-têtes de colonne disparaissent quand vous faites défiler jusqu'à la ligne 400.","Print Titles repeats headings on printed pages; Freeze Panes keeps them visible on screen.":"Imprimer les titres répète les en-têtes sur les pages imprimées ; Figer les volets les garde visibles à l'écran.","View › Freeze Panes › Freeze Top Row":"Affichage › Figer les volets › Figer la ligne supérieure","Page Layout › Print Titles":"Mise en page › Imprimer les titres","Home › Wrap Text":"Accueil › Renvoyer à la ligne automatiquement","Some deliveries were imported twice with the same delivery number.":"Certaines livraisons ont été importées deux fois avec le même numéro de livraison.","Tick only the column that identifies a delivery. If you tick every column, rows that differ in one detail are kept.":"Cochez uniquement la colonne qui identifie une livraison. Si vous cochez toutes les colonnes, les lignes qui diffèrent sur un détail sont conservées.","Data › Remove Duplicates, ticking only Delivery number":"Données › Supprimer les doublons, en cochant uniquement Numéro de livraison","Home › Clear › Clear Formats":"Accueil › Effacer › Effacer les formats","Data › Flash Fill":"Données › Remplissage instantané","The area \"Akwa Nord\" was renamed \"Akwa-Nord\". Which shortcut opens Find and Replace on the Replace tab?":"Le quartier « Akwa Nord » a été renommé « Akwa-Nord ». Quel raccourci ouvre Rechercher et remplacer sur l'onglet Remplacer ?","You select only the Amount column and sort it from largest to smallest, choosing \"Continue with the current selection\". What happens?":"Vous sélectionnez uniquement la colonne Montant et la triez du plus grand au plus petit en choisissant « Continuer avec la sélection en cours ». Que se passe-t-il ?","The whole list is sorted correctly":"Toute la liste est triée correctement","Only the amounts move, so they no longer match their names":"Seuls les montants bougent : ils ne correspondent plus à leurs noms","Excel refuses to sort":"Excel refuse de trier","The amounts are converted to text":"Les montants sont convertis en texte","Sorting a single column breaks the rows apart: the amounts are reordered but the names stay put. Choose Expand the selection, or click one cell and let Excel select the list.":"Trier une seule colonne casse les lignes : les montants sont réordonnés mais les noms restent en place. Choisissez Étendre la sélection, ou cliquez sur une seule cellule et laissez Excel sélectionner la liste.","Build a list of 20 sales with Date, Region, Salesperson and Amount columns":"Construisez une liste de 20 ventes avec les colonnes Date, Région, Vendeur et Montant","Sort it by Region A to Z, then by Amount Largest to Smallest":"Triez-la par Région de A à Z, puis par Montant du plus grand au plus petit","Filter it to show only one region with amounts above 100 000 FCFA, then clear the filter":"Filtrez-la pour n'afficher qu'une région avec des montants supérieurs à 100 000 FCFA, puis effacez le filtre","Format it as a table, add a Total Row, and apply the custom format #,##0 \"FCFA\" to the amounts":"Mettez-la sous forme de tableau, ajoutez une Ligne Total et appliquez le format personnalisé # ##0 \"FCFA\" aux montants","Add Data Bars to the Amount column and freeze the top row":"Ajoutez des Barres de données à la colonne Montant et figez la ligne supérieure","Sort data in a range or table in Excel":"Trier des données dans une plage ou un tableau dans Excel","Filter data in a range or table in Excel":"Filtrer des données dans une plage ou un tableau dans Excel","Choose the chart type that fits the message: comparison, trend or share":"Choisir le type de graphique adapté au message : comparaison, tendance ou répartition","Create a chart and give it a title that states the finding":"Créer un graphique et lui donner un titre qui énonce la conclusion","Set up a sheet to print on A4 with titles, headers and footers, and export it to PDF":"Préparer une feuille pour l'impression sur A4 avec titres, en-têtes et pieds de page, et l'exporter en PDF","A table gives the exact figures; a chart shows the pattern at a glance. Most managers will look at your chart for a few seconds, so choose the type that makes the point obvious and write that point in the title. Then make sure the sheet prints cleanly, because many reports still end up on paper or as PDF attachments.":"Un tableau donne les chiffres exacts ; un graphique montre la tendance d'un coup d'œil. La plupart des responsables regarderont votre graphique quelques secondes : choisissez donc le type qui rend le message évident et écrivez ce message dans le titre. Vérifiez ensuite que la feuille s'imprime proprement, car beaucoup de rapports finissent encore sur papier ou en pièce jointe PDF.","Choose the chart for the message":"Choisir le graphique selon le message","Your message":"Votre message","Compare categories: branches, products, regions":"Comparer des catégories : agences, produits, régions","Column chart, or bar chart when labels are long":"Histogramme, ou graphique à barres quand les étiquettes sont longues","Pie with many slices":"Secteurs avec de nombreuses parts","Show a trend over time: months, quarters, years":"Montrer une évolution dans le temps : mois, trimestres, années","Line chart":"Graphique en courbes","Pie, which has no time axis":"Secteurs, qui n'ont pas d'axe du temps","Show parts of one whole, with 2 to 4 parts":"Montrer les parts d'un tout, avec 2 à 4 parts","Pie or doughnut chart":"Graphique en secteurs ou en anneau","Pie with 5 or more slices or with values that do not add up to a whole":"Secteurs avec 5 parts ou plus, ou avec des valeurs qui ne forment pas un tout","Fuel spending, January to June":"Dépenses de carburant, janvier à juin","The logistics manager wants to show the director that fuel spending has been rising since March. Which chart makes it clearest?":"Le responsable logistique veut montrer au directeur que les dépenses de carburant augmentent depuis mars. Quel graphique le montre le plus clairement ?","A line chart joins the months in order, so the rise from March to June is visible at once. A pie would hide the time order completely.":"Un graphique en courbes relie les mois dans l'ordre : la hausse de mars à juin se voit immédiatement. Un graphique en secteurs masquerait complètement l'ordre chronologique.","Feb":"févr.","Mar":"mars","Apr":"avr.","May":"mai","Jun":"juin","Sales by branch, first quarter":"Ventes par agence, premier trimestre","You must compare the seven branches and show clearly which ones sell the least. Which chart is best?":"Vous devez comparer les sept agences et montrer clairement celles qui vendent le moins. Quel graphique est le meilleur ?","Bars share one baseline, so the eye compares their lengths precisely. Seven pie slices of similar size are hard to rank, and a line suggests a sequence that branches do not have.":"Les barres partent d'une même ligne de base : l'œil compare précisément leurs longueurs. Sept parts de secteur de taille voisine sont difficiles à classer, et une courbe suggère une suite que les agences n'ont pas.","Yaoundé":"Yaoundé","Bafoussam":"Bafoussam","Garoua":"Garoua","Bamenda":"Bamenda","Kribi":"Kribi","Ngaoundéré":"Ngaoundéré","A title that states the finding":"Un titre qui énonce la conclusion","\"Fuel spending\" only names the data. \"Fuel spending up 54% since February\" tells the reader what to see. Write the conclusion in the title and keep the details, such as the unit and the period, in a subtitle or an axis title.":"« Dépenses de carburant » ne fait que nommer les données. « Dépenses de carburant en hausse de 54 % depuis février » dit au lecteur quoi regarder. Écrivez la conclusion dans le titre et gardez les détails, comme l'unité et la période, pour un sous-titre ou un titre d'axe.","Create and format a chart":"Créer et mettre en forme un graphique","From data to finished chart":"Des données au graphique terminé","Select the labels and the values, including the header row, for example A1:B7.":"Sélectionnez les étiquettes et les valeurs, ligne d'en-tête comprise, par exemple A1:B7.","Insert › Recommended Charts":"Insertion › Graphiques recommandés","and pick the type that fits your message, or press":"et choisissez le type adapté à votre message, ou appuyez sur","for a quick column chart.":"pour un histogramme rapide.","Click the chart title and type the finding.":"Cliquez sur le titre du graphique et tapez la conclusion.","button beside the chart (Chart Elements) to add or remove axis titles, data labels and the legend.":"à côté du graphique (Éléments de graphique) pour ajouter ou retirer les titres des axes, les étiquettes de données et la légende.","Drag the chart next to the table and resize it from a corner so it does not stretch.":"Faites glisser le graphique à côté du tableau et redimensionnez-le par un coin pour qu'il ne se déforme pas.","Charts":"Graphiques","Recommended Charts":"Graphiques recommandés","Chart Design":"Création de graphique","Add Chart Element":"Ajouter un élément de graphique","Chart Design also has Switch Row/Column, Select Data, Change Chart Type and Move Chart.":"L'onglet Création de graphique propose aussi Intervertir les lignes/colonnes, Sélectionner des données, Modifier le type de graphique et Déplacer le graphique.","Remove what does not help: gridlines that are too heavy, a legend when there is only one series, 3-D effects.":"Retirez ce qui n'aide pas : quadrillage trop marqué, légende quand il n'y a qu'une série, effets 3D.","Sort bars from largest to smallest so the ranking is easy to read.":"Triez les barres de la plus grande à la plus petite pour que le classement se lise facilement.","Use one colour for all bars and a contrasting colour for the bar you want to discuss.":"Utilisez une seule couleur pour toutes les barres et une couleur contrastée pour la barre dont vous voulez parler.","Start the value axis at zero for column and bar charts; otherwise small differences look huge.":"Faites partir l'axe des valeurs de zéro pour les histogrammes et les graphiques à barres ; sinon, de petites différences paraissent énormes.","Set up the page for printing":"Préparer la page pour l'impression","Page Layout":"Mise en page","Page Setup":"Mise en page","Orientation":"Orientation","Landscape":"Paysage","Wide tables usually fit better in landscape. Check that Size is A4.":"Les tableaux larges tiennent généralement mieux en paysage. Vérifiez que la Taille est A4.","Scale to Fit":"Mise à l'échelle","Width: 1 page":"Largeur : 1 page","Leave Height on Automatic: all columns fit across the page and long lists continue on the next pages.":"Laissez Hauteur sur Automatique : toutes les colonnes tiennent sur la largeur de la page et les longues listes continuent sur les pages suivantes.","Print Titles":"Imprimer les titres","In Rows to repeat at top, select the header row (for example $1:$1) so it prints on every page.":"Dans Lignes à répéter en haut, sélectionnez la ligne d'en-tête (par exemple $1:$1) pour qu'elle s'imprime sur chaque page.","Add a header and footer":"Ajouter un en-tête et un pied de page","Insert › Header & Footer":"Insertion › En-tête/Pied de page",". Excel switches to Page Layout view.":". Excel passe en mode Mise en page.","Click the left, centre or right box of the header and type, for example, the organisation name.":"Cliquez dans la zone gauche, centrale ou droite de l'en-tête et tapez, par exemple, le nom de l'organisation.","Scroll to the footer and use the":"Faites défiler jusqu'au pied de page et utilisez l'onglet","Header & Footer":"En-tête/Pied de page","tab to insert Page Number, Number of Pages and File Name.":"pour insérer Numéro de page, Nombre de pages et Nom du fichier.","Click any cell in the sheet, then return to":"Cliquez sur n'importe quelle cellule de la feuille, puis revenez à","View › Normal":"Affichage › Normal","Preview before you pay for printing":"Prévisualisez avant de payer l'impression","Printing a 12-page report at a cyber café in Yaoundé because one column spilled onto extra pages wastes paper and money. Press":"Imprimer un rapport de 12 pages dans un cybercafé de Yaoundé parce qu'une colonne a débordé sur des pages supplémentaires gaspille du papier et de l'argent. Appuyez sur","to see the print preview first, and when the report only needs to be read, send a PDF instead: it prints the same way on any computer.":"pour voir d'abord l'aperçu avant impression, et quand le rapport doit seulement être lu, envoyez plutôt un PDF : il s'imprime de la même façon sur n'importe quel ordinateur.","Preview and export to PDF":"Aperçu et export en PDF","Create PDF/XPS Document":"Créer un document PDF/XPS","Click Options to choose Active sheet(s), Entire workbook or only the Selection.":"Cliquez sur Options pour choisir Feuille(s) active(s), Classeur entier ou seulement la Sélection.","Print a staff hours report on A4":"Imprimer un rapport d'heures du personnel sur A4","The staff hours report of a Garoua health district has 10 columns and 180 rows. Choose the right setting for each problem. Type shortcuts as keys joined with +.":"Le rapport des heures du personnel d'un district de santé de Garoua compte 10 colonnes et 180 lignes. Choisissez le bon réglage pour chaque problème. Tapez les raccourcis sous forme de touches reliées par +.","Orientation and Print Titles are on Page Layout › Page Setup, fitting is in Page Layout › Scale to Fit, and the preview opens with Ctrl + P.":"Orientation et Imprimer les titres se trouvent dans Mise en page › Mise en page, l'ajustement dans Mise en page › Mise à l'échelle, et l'aperçu s'ouvre avec Ctrl + P.","The table is wider than it is tall. Which orientation?":"Le tableau est plus large que haut. Quelle orientation ?","Portrait":"Portrait","The last two columns still print on separate pages.":"Les deux dernières colonnes s'impriment encore sur des pages séparées.","Width: 1 page shrinks the sheet just enough to fit across, and leaves the height free.":"Largeur : 1 page réduit la feuille juste assez pour qu'elle tienne en largeur, et laisse la hauteur libre.","Reduce the font to 6 pt":"Réduire la police à 6 pt","Page Layout › Scale to Fit › Width: 1 page":"Mise en page › Mise à l'échelle › Largeur : 1 page","Delete the two columns":"Supprimer les deux colonnes","Page Layout › Breaks › Insert Page Break":"Mise en page › Sauts de page › Insérer un saut de page","Pages 2 to 5 have no column headings.":"Les pages 2 à 5 n'ont pas d'en-têtes de colonne.","Freeze Panes only works on screen. Print Titles repeats the header row on every printed page.":"Figer les volets n'agit qu'à l'écran. Imprimer les titres répète la ligne d'en-tête sur chaque page imprimée.","View › Freeze Panes":"Affichage › Figer les volets","Page Layout › Print Titles › Rows to repeat at top":"Mise en page › Imprimer les titres › Lignes à répéter en haut","Each page must show \"Page 3 of 5\" at the bottom.":"Chaque page doit afficher « Page 3 sur 5 » en bas.","Type it in the last row of the sheet":"Le taper dans la dernière ligne de la feuille","Insert › Header & Footer, then Page Number and Number of Pages in the footer":"Insertion › En-tête/Pied de page, puis Numéro de page et Nombre de pages dans le pied de page","Page Layout › Margins":"Mise en page › Marges","File › Info › Properties":"Fichier › Informations › Propriétés","Which shortcut opens the print preview?":"Quel raccourci ouvre l'aperçu avant impression ?","Only the Summary sheet must be sent as a PDF.":"Seule la feuille Synthèse doit être envoyée en PDF.","The Options button lets you export only the active sheet instead of the whole workbook.":"Le bouton Options permet d'exporter uniquement la feuille active au lieu du classeur entier.","File › Export › Create PDF/XPS Document, Options › Active sheet(s)":"Fichier › Exporter › Créer un document PDF/XPS, Options › Feuille(s) active(s)","File › Save As › CSV":"Fichier › Enregistrer sous › CSV","Take a screenshot":"Faire une capture d'écran","Print the whole workbook and scan it":"Imprimer tout le classeur et le scanner","Which chart title is best for a report to the management committee?":"Quel titre de graphique convient le mieux à un rapport pour le comité de direction ?","Chart 1":"Graphique 1","Sales":"Ventes","Sales by branch, Q1 2026 (FCFA)":"Ventes par agence, T1 2026 (FCFA)","Douala and Yaoundé make 57% of first-quarter sales":"Douala et Yaoundé réalisent 57 % des ventes du premier trimestre","A title that states the finding tells busy readers what to notice. The period and unit can go in a subtitle or axis title.":"Un titre qui énonce la conclusion indique aux lecteurs pressés ce qu'il faut remarquer. La période et l'unité peuvent aller dans un sous-titre ou un titre d'axe.","Enter monthly sales for six months and create a line chart with a title that states the trend":"Saisissez les ventes mensuelles de six mois et créez un graphique en courbes avec un titre qui énonce la tendance","Enter sales for five branches, create a bar chart and sort the bars from largest to smallest":"Saisissez les ventes de cinq agences, créez un graphique à barres et triez les barres de la plus grande à la plus petite","Set a long list to landscape, Width: 1 page, with the header row repeated on every page":"Réglez une longue liste en paysage, Largeur : 1 page, avec la ligne d'en-tête répétée sur chaque page","Add a footer with Page X of Y and the file name":"Ajoutez un pied de page avec Page X sur Y et le nom du fichier","Export only the active sheet to PDF and check it in the preview":"Exportez uniquement la feuille active en PDF et vérifiez-la dans l'aperçu","Create a chart from start to finish":"Créer un graphique du début à la fin","Print rows with column headers on top of every page":"Imprimer des lignes avec des en-têtes de colonne en haut de chaque page","Practice lab: Excel from data entry to report":"Atelier pratique : Excel, de la saisie au rapport","Total and average rows of data with the everyday functions":"Calculer totaux et moyennes de lignes de données avec les fonctions courantes","Build a two-way table with mixed references":"Construire un tableau à double entrée avec des références mixtes","Choose the right sort, filter, format, chart and formula for a report":"Choisir le bon tri, filtre, format, graphique et la bonne formule pour un rapport","Clean a report with missing values and numbers stored as text":"Nettoyer un rapport comportant des valeurs manquantes et des nombres stockés sous forme de texte","Exercise 1: Weekly hours at a clinic":"Exercice 1 : Heures de la semaine dans une clinique","Total the staff hours":"Totalisez les heures du personnel","A clinic in Bafoussam records the hours each staff member worked this week. Fill":"Une clinique de Bafoussam enregistre les heures travaillées cette semaine par chaque membre du personnel. Remplissez","with each person's weekly total,":"avec le total hebdomadaire de chaque personne,","with the total for the whole team and":"avec le total de toute l'équipe et","with the average per person.":"avec la moyenne par personne.","G2 is =SUM(B2:F2); copy it down to G5. The team total adds G2:G5, and the average per person is =AVERAGE(G2:G5).":"G2 vaut =SUM(B2:F2) ; recopiez-la jusqu'en G5. Le total de l'équipe additionne G2:G5, et la moyenne par personne est =AVERAGE(G2:G5).","Exercise 2: Mission allowance table":"Exercice 2 : Barème des frais de mission","One formula for a whole table":"Une seule formule pour tout un tableau","A ministry pays a daily mission allowance by staff category. Fill":"Un ministère verse des frais de mission journaliers selon la catégorie du personnel. Remplissez","with the allowance for 5, 10 and 22 days (daily rate × days) using":"avec l'indemnité pour 5, 10 et 22 jours (taux journalier × jours) en utilisant","one formula with mixed references":"une seule formule à références mixtes","copied across the table. Then fill":"recopiée dans tout le tableau. Remplissez ensuite","with Category A's new daily rate after the increase in":"avec le nouveau taux journalier de la catégorie A après la hausse indiquée en","In C3 type =$B3*C$2: the rate is always in column B ($B) and the days are always in row 2 (row $2). Copy it to the other eight cells. B8 is =B3*(1+B7).":"En C3, tapez =$B3*C$2 : le taux est toujours dans la colonne B ($B) et les jours toujours dans la ligne 2 (ligne $2). Recopiez-la dans les huit autres cellules. B8 vaut =B3*(1+B7).","Exercise 3: Preparing the regional sales report":"Exercice 3 : Préparer le rapport des ventes régionales","Formulas, formats and charts for a report":"Formules, formats et graphiques pour un rapport","A distributor in Garoua lists its 2025 sales in column B and its 2026 sales in column C, one row per region, with the grand total in B10 and C10. Answer each question. Type formulas exactly as you would in Excel, starting with =.":"Un distributeur de Garoua inscrit ses ventes 2025 dans la colonne B et ses ventes 2026 dans la colonne C, une ligne par région, avec le total général en B10 et C10. Répondez à chaque question. Tapez les formules exactement comme dans Excel, en commençant par =.","Growth is the change divided by the starting value. A reference that must not move when copied needs dollar signs. Think about what each tool does: sort orders, filter hides, conditional formatting colours by rule.":"La croissance est la variation divisée par la valeur de départ. Une référence qui ne doit pas bouger à la copie a besoin de signes dollar. Pensez à ce que fait chaque outil : le tri ordonne, le filtre masque, la mise en forme conditionnelle colore selon une règle.","Type the formula for D2: the growth from 2025 (B2) to 2026 (C2), as a share.":"Tapez la formule de D2 : la croissance de 2025 (B2) à 2026 (C2), sous forme de part.","=(C2-B2)/B2 and =C2/B2-1 give the same result. Without brackets, =C2-B2/B2 divides first and is wrong.":"=(C2-B2)/B2 et =C2/B2-1 donnent le même résultat. Sans parenthèses, =C2-B2/B2 divise d'abord et donne un résultat faux.","E2 shows each region's share of 2026 sales: =C2/C10. Rewrite it so that it can be copied down to E9.":"E2 affiche la part de chaque région dans les ventes 2026 : =C2/C10. Réécrivez-la pour pouvoir la recopier jusqu'en E9.","The total must stay in C10, so lock it: $C$10 (or at least the row: C$10).":"Le total doit rester en C10, verrouillez-le donc : $C$10 (ou au moins la ligne : C$10).","The growth for the new Kousséri region shows #DIV/0!. Why?":"La croissance de la nouvelle région de Kousséri affiche #DIV/0!. Pourquoi ?","Dividing by an empty cell counts as dividing by zero. Growth cannot be calculated for a region with no sales last year.":"Diviser par une cellule vide revient à diviser par zéro. La croissance ne peut pas être calculée pour une région sans ventes l'an dernier.","The 2026 figure is text":"Le chiffre 2026 est du texte","Its 2025 cell is empty because the region opened in 2026":"Sa cellule 2025 est vide, car la région a ouvert en 2026","The function name is misspelled":"Le nom de la fonction est mal orthographié","Growth shows as 0.12 instead of 12%.":"La croissance s'affiche 0,12 au lieu de 12 %.","0.12 is correct; it only needs the Percent Style. Multiplying by 100 and adding % would show 1200%.":"0,12 est correct ; il manque seulement le Style de pourcentage. Multiplier par 100 puis ajouter % afficherait 1200 %.","Multiply the formula by 100":"Multiplier la formule par 100","Apply the Percent Style (Ctrl + Shift + %)":"Appliquer le Style de pourcentage (Ctrl + Maj + %)","Type % after the formula":"Taper % après la formule","Change the column width":"Modifier la largeur de la colonne","Rank the regions by 2026 sales, largest first, while each row stays together.":"Classez les régions selon les ventes 2026, la plus forte en premier, en gardant chaque ligne entière.","Clicking one cell lets Excel select the whole list and keep each row together.":"Cliquer sur une seule cellule permet à Excel de sélectionner toute la liste et de garder chaque ligne entière.","Select column C only and click Sort Largest to Smallest, Continue with the current selection":"Sélectionner uniquement la colonne C et cliquer sur Trier du plus grand au plus petit, Continuer avec la sélection en cours","Click one cell in column C and choose Sort Largest to Smallest":"Cliquer sur une cellule de la colonne C et choisir Trier du plus grand au plus petit","Apply a filter and untick the small regions":"Appliquer un filtre et décocher les petites régions","Cut and paste the rows by hand":"Couper et coller les lignes à la main","Regions whose sales fell must stand out in red and update automatically.":"Les régions dont les ventes ont baissé doivent ressortir en rouge et se mettre à jour automatiquement.","A rule re-checks every time the figures change; a manual colour does not.":"Une règle se revérifie chaque fois que les chiffres changent ; une couleur manuelle, non.","Conditional Formatting › Highlight Cells Rules › Less Than 0 on the growth column":"Mise en forme conditionnelle › Règles de mise en surbrillance des cellules › Inférieur à 0 sur la colonne de croissance","Font Color red on today's falling regions":"Couleur de police rouge sur les régions en baisse aujourd'hui","Filter the growth column":"Filtrer la colonne de croissance","Which chart compares the nine regions' 2025 and 2026 sales side by side?":"Quel graphique compare côte à côte les ventes 2025 et 2026 des neuf régions ?","Clustered bars put the two years side by side for each region on a common baseline.":"Les barres groupées placent les deux années côte à côte pour chaque région, sur une ligne de base commune.","Pie chart":"Graphique en secteurs","Clustered bar or column chart":"Barres ou histogramme groupés","Line chart with one line per region":"Graphique en courbes avec une courbe par région","Doughnut chart":"Graphique en anneau","Exercise 4: Mosquito net distribution report":"Exercice 4 : Rapport de distribution de moustiquaires","Clean up a report with gaps and text":"Nettoyez un rapport lacunaire et mal saisi","An NGO's field report from the North region has problems: Pitoa has not reported households served yet, and some costs were typed with \"FCFA\". Fill":"Le rapport de terrain d'une ONG dans la région du Nord pose problème : Pitoa n'a pas encore déclaré les ménages servis, et certains coûts ont été saisis avec « FCFA ». Remplissez","with coverage (served ÷ targeted), showing":"avec la couverture (servis ÷ ciblés), en affichant","when Served is empty;":"lorsque Served est vide ;","with every cost as a real number; then the summary in":"avec chaque coût sous forme de vrai nombre ; puis la synthèse en","Coverage: =IF(C2=\"\",\"Not reported\",C2/B2). Cost: =VALUE(SUBSTITUTE(E2,\" FCFA\",\"\")) works for text and for real numbers alike; LEFT(E2,LEN(E2)-5) breaks on the rows that are already numbers. B9 is COUNT(C2:C6). For B10, divide households served by the targets of reporting districts only: =B8/SUMIF(C2:C6,\"<>\",B2:B6). B12 is =B11/B8.":"Couverture : =IF(C2=\"\",\"Not reported\",C2/B2) (SI). Coût : =VALUE(SUBSTITUTE(E2,\" FCFA\",\"\")) (CNUM, SUBSTITUE) fonctionne aussi bien pour le texte que pour les vrais nombres ; LEFT(E2,LEN(E2)-5) (GAUCHE, NBCAR) échoue sur les lignes qui sont déjà des nombres. B9 vaut COUNT(C2:C6) (NB). Pour B10, divisez les ménages servis par les cibles des seuls districts ayant déclaré : =B8/SUMIF(C2:C6,\"<>\",B2:B6) (SOMME.SI). B12 vaut =B11/B8.","Module 4 Quiz":"Quiz du module 4","Which shortcut fills a column by following the pattern of the example you typed, for example extracting DLA from DLA-2026-014?":"Quel raccourci remplit une colonne en suivant le modèle de l'exemple que vous avez tapé, par exemple pour extraire DLA de DLA-2026-014 ?","Ctrl + D":"Ctrl + D","Ctrl + E":"Ctrl + E","Ctrl + F":"Ctrl + F","Alt + =":"Alt + =","Ctrl + E runs Flash Fill, which copies the pattern of your example down the column. Ctrl + D copies the cell above.":"Ctrl + E lance le Remplissage instantané, qui reproduit le modèle de votre exemple dans toute la colonne. Ctrl + D recopie la cellule du dessus.","One cell in C2:C20 contains \"45 000 FCFA\" typed by hand. What does =SUM(C2:C20) do with it?":"Une cellule de C2:C20 contient « 45 000 FCFA » saisi à la main. Que fait =SUM(C2:C20) de cette cellule ?","Adds 45 000":"Elle ajoute 45 000","Shows #VALUE!":"Elle affiche #VALEUR!","Ignores it, because it is text":"Elle l'ignore, car c'est du texte","Converts it automatically":"Elle la convertit automatiquement","SUM skips text in a range, so the total is silently too low. Arithmetic with + on that cell would show #VALUE! instead.":"SUM (SOMME) ignore le texte d'une plage : le total est donc trop faible, sans avertissement. Un calcul avec + sur cette cellule afficherait plutôt #VALEUR!.","What does =10+20/2 return?":"Que renvoie =10+20/2 ?","Division comes before addition: 20/2 = 10, then 10 + 10 = 20. Write =(10+20)/2 to get 15.":"La division passe avant l'addition : 20/2 = 10, puis 10 + 10 = 20. Écrivez =(10+20)/2 pour obtenir 15.","You type =C4*B1 and press F4 once while the cursor is on B1. What does the reference become?":"Vous tapez =C4*B1 et appuyez une fois sur F4 alors que le curseur est sur B1. Que devient la référence ?","The first press of F4 locks both the column and the row. Further presses give B$1, then $B1, then back to B1.":"Le premier appui sur F4 verrouille à la fois la colonne et la ligne. Les appuis suivants donnent B$1, puis $B1, puis reviennent à B1.","Which function counts the cells that contain numbers only, ignoring names and empty cells?":"Quelle fonction compte uniquement les cellules qui contiennent des nombres, en ignorant les noms et les cellules vides ?","MAX":"MAX","COUNT counts numbers only. COUNTA counts every cell that is not empty, text included.":"COUNT (NB) ne compte que les nombres. COUNTA (NBVAL) compte toutes les cellules non vides, texte compris.","Which shortcut turns the filter arrows on or off?":"Quel raccourci active ou désactive les flèches de filtre ?","Ctrl + L":"Ctrl + L","Ctrl + Shift + L":"Ctrl + Maj + L","Ctrl + T":"Ctrl + T","Ctrl + H":"Ctrl + H","Ctrl + Shift + L toggles filters. Ctrl + T creates a table, which also has filter arrows.":"Ctrl + Maj + L active ou désactive les filtres. Ctrl + T crée un tableau, qui a lui aussi des flèches de filtre.","Which chart best shows how monthly sales changed over a year?":"Quel graphique montre le mieux l'évolution des ventes mensuelles sur une année ?","A table of 12 numbers":"Un tableau de 12 nombres","A line chart shows change over time in order. A pie shows parts of a whole and has no time axis.":"Un graphique en courbes montre l'évolution dans le temps, dans l'ordre. Un graphique en secteurs montre les parts d'un tout et n'a pas d'axe du temps.","A long list prints with the column headings only on page 1. Which setting fixes it?":"Une longue liste s'imprime avec les en-têtes de colonne uniquement sur la page 1. Quel réglage corrige cela ?","Page Layout › Orientation":"Mise en page › Orientation","Print Titles › Rows to repeat at top prints the header row on every page. Freeze Panes only affects the screen.":"Imprimer les titres › Lignes à répéter en haut imprime la ligne d'en-tête sur chaque page. Figer les volets n'agit que sur l'écran.","on the":"dans l'onglet","tab to add totals you can switch between Sum, Average and Count.":"pour ajouter des totaux que vous pouvez faire passer de Somme à Moyenne ou Nombre.","IF, AND, OR and IFS: formulas that make decisions":"SI, ET, OU et SI.CONDITIONS : des formules qui prennent des décisions","Write IF formulas that return different results depending on a logical test":"Écrire des formules SI qui renvoient des résultats différents selon un test logique","Combine several conditions with AND, OR and IFS, and hide errors with IFERROR":"Combiner plusieurs conditions avec ET, OU et SI.CONDITIONS, et masquer les erreurs avec SIERREUR","Calculate conditional totals and counts with COUNTIF, SUMIF, COUNTIFS and SUMIFS":"Calculer des totaux et des comptages conditionnels avec NB.SI, SOMME.SI, NB.SI.ENS et SOMME.SI.ENS","Until now your formulas always did the same calculation. Logical functions let a formula decide: pay a bonus only if the target is met, show \"Reorder\" only when stock is low, give a grade that depends on the score. These decisions are the heart of most real workplace spreadsheets.":"Jusqu'ici, vos formules faisaient toujours le même calcul. Les fonctions logiques permettent à une formule de décider : verser une prime seulement si l'objectif est atteint, afficher « Reorder » seulement quand le stock est bas, attribuer une mention selon la note. Ces décisions sont au cœur de la plupart des classeurs utilisés en entreprise.","A logical test is a comparison that is either TRUE or FALSE. Type":"Un test logique est une comparaison qui vaut VRAI ou FAUX (TRUE ou FALSE dans la version anglaise). Tapez","in a cell and Excel shows TRUE or FALSE. Every logical function is built on tests like this one.":"dans une cellule et Excel affiche VRAI ou FAUX. Toutes les fonctions logiques reposent sur des tests de ce type.","TRUE when…":"VRAI quand…","Equal to":"Égal à","=B2=\"Douala\"":"=B2=\"Douala\"","The city is Douala (not case-sensitive)":"La ville est Douala (majuscules et minuscules indifférentes)","Not equal to":"Différent de","=E2<>\"Paid\"":"=E2<>\"Paid\"","The status is anything except Paid":"Le statut est tout sauf Paid","Greater than, less than":"Supérieur à, inférieur à","The amount is above 500 000":"Le montant dépasse 500 000","Greater or equal, less or equal":"Supérieur ou égal, inférieur ou égal","Two absences or fewer":"Deux absences ou moins","IF: one test, two possible results":"SI : un test, deux résultats possibles","Text results go in double quotes: \"Yes\". Numbers and cell references do not.":"Les résultats en texte se mettent entre guillemets droits : \"Yes\". Les nombres et les références de cellules, non.","The result can be another formula, for example":"Le résultat peut être une autre formule, par exemple","In a French version of Excel, IF is SI and the separator is a semicolon:":"Dans la version française d'Excel, IF devient SI et le séparateur est le point-virgule :","AND, OR and NOT: several conditions at once":"ET, OU et NON : plusieurs conditions à la fois","Returns TRUE when…":"Renvoie VRAI quand…","AND":"AND (ET)","Every condition is true":"Toutes les conditions sont vraies","=AND(C2>=D2, E2<=2): target met and two absences or fewer":"=AND(C2>=D2, E2<=2) : objectif atteint et deux absences ou moins","OR":"OR (OU)","At least one condition is true":"Au moins une condition est vraie","=OR(B2=\"Douala\", B2=\"Yaoundé\"): works in one of the two big cities":"=OR(B2=\"Douala\", B2=\"Yaoundé\") : travaille dans l'une des deux grandes villes","NOT":"NOT (NON)","The condition is false":"La condition est fausse","=NOT(F2=\"Paid\")":"=NOT(F2=\"Paid\")","IF + AND":"IF + AND (SI + ET)","AND and OR are usually placed inside IF as its test":"ET et OU se placent généralement dans SI, comme test logique","=IF(AND(C2>=D2,E2<=2),C2*5%,0): bonus only when both hold":"=IF(AND(C2>=D2,E2<=2),C2*5%,0) : prime seulement si les deux conditions sont remplies","Sales bonus eligibility":"Droit à la prime sur ventes","A distributor in Douala pays a 5% bonus on sales to agents who meet their target and have no more than 2 days of absence. Fill F2:F5 with \"Yes\" or \"No\" (target met?) and G2:G5 with the bonus in FCFA (0 if not eligible).":"Un distributeur de Douala verse une prime de 5 % des ventes aux commerciaux qui atteignent leur objectif et n'ont pas plus de 2 jours d'absence. Remplissez F2:F5 avec \"Yes\" ou \"No\" (objectif atteint ?) et G2:G5 avec la prime en FCFA (0 si le commercial n'y a pas droit).","F2 is =IF(C2>=D2,\"Yes\",\"No\"). For G2 put AND inside IF: =IF(AND(C2>=D2,E2<=2),C2*5%,0). Abena met her target but was absent 4 days.":"F2 : =IF(C2>=D2,\"Yes\",\"No\"). Pour G2, placez ET dans SI : =IF(AND(C2>=D2,E2<=2),C2*5%,0). Abena a atteint son objectif mais a été absente 4 jours.","More than two results: nested IF or IFS":"Plus de deux résultats : SI imbriqués ou SI.CONDITIONS","To give a grade from a score you need more than two outcomes. The older way nests one IF inside another; IFS, available in Microsoft 365, lists test and result pairs and returns the result of the first test that is TRUE.":"Pour attribuer une mention à partir d'une note, il faut plus de deux résultats. L'ancienne méthode imbrique un SI dans un autre ; SI.CONDITIONS (IFS), disponible dans Microsoft 365, enchaîne des paires test/résultat et renvoie le résultat du premier test VRAI.","Order matters, and end with TRUE":"L'ordre compte, et terminez par VRAI","Excel stops at the first test that is TRUE, so test the highest band first. If B2>=10 came first, a score of 17 would get \"Pass\". The final pair TRUE,\"Fail\" catches everything else; without it IFS returns #N/A when no test is true.":"Excel s'arrête au premier test VRAI : testez donc la tranche la plus haute en premier. Si B2>=10 venait en premier, une note de 17 recevrait « Pass ». La dernière paire TRUE,\"Fail\" attrape tous les autres cas ; sans elle, SI.CONDITIONS renvoie #N/A quand aucun test n'est vrai.","IFERROR: a clean result instead of an error":"SIERREUR : un résultat propre au lieu d'une erreur","returns the formula's result, or your chosen value if the formula produces an error such as #DIV/0! or #N/A. For example":"renvoie le résultat de la formule, ou la valeur de votre choix si la formule produit une erreur comme #DIV/0! ou #N/A. Par exemple,","shows 0 instead of #DIV/0! when the target is empty. Use it for expected errors only; hiding every error can hide real mistakes.":"affiche 0 au lieu de #DIV/0! quand l'objectif est vide. Réservez-la aux erreurs attendues : masquer toutes les erreurs peut cacher de vraies fautes.","Conditional totals: COUNTIF, SUMIF, COUNTIFS, SUMIFS":"Totaux conditionnels : NB.SI, SOMME.SI, NB.SI.ENS, SOMME.SI.ENS","What it does":"Ce qu'elle fait","COUNTIF(range, criteria)":"COUNTIF(plage, critère) ; NB.SI en français","Counts cells that meet one condition":"Compte les cellules qui remplissent une condition","=COUNTIF(F2:F7,\"Reorder\")":"=COUNTIF(F2:F7,\"Reorder\")","SUMIF(range, criteria, sum_range)":"SUMIF(plage, critère, plage_somme) ; SOMME.SI","Adds values where one condition is met":"Additionne les valeurs là où une condition est remplie","=SUMIF(B2:B7,\"Douala\",C2:C7)":"=SUMIF(B2:B7,\"Douala\",C2:C7)","COUNTIFS(range1, crit1, range2, crit2…)":"COUNTIFS(plage1, critère1, plage2, critère2…) ; NB.SI.ENS","Counts rows that meet every condition":"Compte les lignes qui remplissent toutes les conditions","=COUNTIFS(B2:B7,\"Medicine\",F2:F7,\"<>OK\")":"=COUNTIFS(B2:B7,\"Medicine\",F2:F7,\"<>OK\")","SUMIFS(sum_range, range1, crit1…)":"SUMIFS(plage_somme, plage1, critère1…) ; SOMME.SI.ENS","Adds values where every condition is met. Note the sum range comes first":"Additionne les valeurs là où toutes les conditions sont remplies. Attention : la plage à additionner vient en premier","=SUMIFS(C2:C7,B2:B7,\"Medicine\")":"=SUMIFS(C2:C7,B2:B7,\"Medicine\")","Criteria with an operator go in quotes: \">100000\", \"<>OK\". To use a value from a cell, join the operator with &:":"Les critères avec un opérateur se mettent entre guillemets : \">100000\", \"<>OK\". Pour utiliser la valeur d'une cellule, reliez l'opérateur avec & :","Stock alerts in a health centre pharmacy":"Alertes de stock dans la pharmacie d'un centre de santé","Fill F2:F7 with an alert using IFS: \"Out\" when stock is 0, \"Reorder\" when stock is at or below the reorder level, otherwise \"OK\". Then fill F9 (number of Reorder alerts), F10 (Medicine items that are not OK) and F11 (total units in stock for Medicine).":"Remplissez F2:F7 avec une alerte grâce à SI.CONDITIONS : \"Out\" quand le stock est à 0, \"Reorder\" quand le stock est inférieur ou égal au seuil de réapprovisionnement, sinon \"OK\". Remplissez ensuite F9 (nombre d'alertes Reorder), F10 (articles de la catégorie Medicine qui ne sont pas OK) et F11 (total des unités en stock pour Medicine).","Test for 0 first: =IFS(C2=0,\"Out\",C2<=D2,\"Reorder\",TRUE,\"OK\"). F9 is a COUNTIF on F2:F7. F10 needs two conditions: COUNTIFS(B2:B7,\"Medicine\",F2:F7,\"<>OK\"). F11 is SUMIFS(C2:C7,B2:B7,\"Medicine\").":"Testez d'abord le 0 : =IFS(C2=0,\"Out\",C2<=D2,\"Reorder\",TRUE,\"OK\"). F9 est un NB.SI sur F2:F7. F10 demande deux conditions : COUNTIFS(B2:B7,\"Medicine\",F2:F7,\"<>OK\"). F11 est SUMIFS(C2:C7,B2:B7,\"Medicine\").","Formulas":"Formules","Formula Auditing":"Audit de formules","Evaluate Formula":"Évaluation de formule","Steps through a long formula one part at a time, so you can see which test is TRUE.":"Parcourt une longue formule étape par étape, pour voir quel test est VRAI.","A district health service in the Far North tracks essential drugs in 12 health centres. One IFS column flags \"Out\" and \"Reorder\", and a COUNTIFS per centre gives the district pharmacist the list to order before the rainy season cuts the roads. The same pattern works for any stock: cement in a hardware store, airtime scratch cards, school supplies.":"Un district de santé de l'Extrême-Nord suit les médicaments essentiels de 12 centres de santé. Une colonne SI.CONDITIONS signale « Out » et « Reorder », et un NB.SI.ENS par centre donne au pharmacien du district la liste à commander avant que la saison des pluies ne coupe les routes. Le même modèle fonctionne pour tout stock : ciment d'une quincaillerie, cartes de recharge, fournitures scolaires.","Which formula gives \"Pass\" for scores of 10 and above and \"Fail\" otherwise, where the score is in B2?":"Quelle formule renvoie \"Pass\" pour les notes de 10 et plus et \"Fail\" sinon, la note étant en B2 ?","=IF(B2>10,\"Pass\",\"Fail\")":"=IF(B2>10,\"Pass\",\"Fail\")","=IF(B2>=10,\"Pass\",\"Fail\")":"=IF(B2>=10,\"Pass\",\"Fail\")","=IF(B2>=10,Pass,Fail)":"=IF(B2>=10,Pass,Fail)","=IFS(B2>=10,\"Pass\")":"=IFS(B2>=10,\"Pass\")","B2>=10 includes exactly 10. Text must be in quotes, and IFS without a final TRUE pair returns #N/A for scores below 10.":"B2>=10 inclut exactement 10. Le texte doit être entre guillemets, et SI.CONDITIONS sans paire TRUE finale renvoie #N/A pour les notes inférieures à 10.","You want the total sales of agent Tchoumi in the Centre region only. Which function fits best?":"Vous voulez le total des ventes du commercial Tchoumi dans la seule région du Centre. Quelle fonction convient le mieux ?","SUMIF":"SUMIF (SOMME.SI)","COUNTIFS":"COUNTIFS (NB.SI.ENS)","SUMIFS":"SUMIFS (SOMME.SI.ENS)","IFERROR":"IFERROR (SIERREUR)","Two conditions (agent and region) and a total: SUMIFS. SUMIF accepts only one condition, and COUNTIFS counts rows instead of adding amounts.":"Deux conditions (commercial et région) et un total : SOMME.SI.ENS. SOMME.SI n'accepte qu'une condition, et NB.SI.ENS compte des lignes au lieu d'additionner des montants.","Build a list of 8 training participants with their final score out of 20":"Constituez une liste de 8 participants à une formation avec leur note finale sur 20","Add a Result column with IF: \"Certified\" from 12, otherwise \"Not certified\"":"Ajoutez une colonne Résultat avec SI : « Certifié » à partir de 12, sinon « Non certifié »","Add a Grade column with IFS: A from 16, B from 14, C from 12, otherwise D":"Ajoutez une colonne Mention avec SI.CONDITIONS : A à partir de 16, B à partir de 14, C à partir de 12, sinon D","Count the certified participants with COUNTIF and the average score of women with AVERAGEIFS":"Comptez les participants certifiés avec NB.SI et calculez la note moyenne des femmes avec MOYENNE.SI.ENS","Divide one score by an empty cell, then wrap the formula in IFERROR":"Divisez une note par une cellule vide, puis entourez la formule de SIERREUR","IFS function":"Fonction SI.CONDITIONS (IFS)","Microsoft Office Specialist: Excel Associate (Microsoft 365 Apps)":"Microsoft Office Specialist : Excel Associate (Microsoft 365 Apps)","XLOOKUP, VLOOKUP and INDEX-MATCH: finding data in tables":"RECHERCHEX, RECHERCHEV et INDEX-EQUIV : retrouver des données dans des tables","Look up prices, names and rates in a reference table with XLOOKUP and VLOOKUP":"Rechercher des prix, des noms et des taux dans une table de référence avec RECHERCHEX et RECHERCHEV","Explain the difference between exact and approximate match and use each correctly":"Expliquer la différence entre correspondance exacte et approximative, et utiliser chacune à bon escient","Combine INDEX and MATCH, and handle missing codes without errors":"Combiner INDEX et EQUIV, et gérer les codes absents sans erreur","Most workbooks have a reference table somewhere: a price list, a staff list, a table of tax or commission bands. Lookup functions fetch the right line from that table, so you type a product code once and Excel fills in the name and the price. When the price list changes, every invoice updates.":"La plupart des classeurs contiennent quelque part une table de référence : une liste de prix, une liste du personnel, un barème d'impôt ou de commission. Les fonctions de recherche vont chercher la bonne ligne dans cette table : vous tapez une seule fois le code produit et Excel remplit le nom et le prix. Quand la liste de prix change, toutes les factures se mettent à jour.","XLOOKUP: the modern lookup":"RECHERCHEX : la recherche moderne","lookup_value: what you are looking for, such as the product code in E2.":"lookup_value (valeur_cherchée) : ce que vous cherchez, par exemple le code produit en E2.","lookup_array: the column that contains the codes.":"lookup_array (tableau_recherche) : la colonne qui contient les codes.","return_array: the column that contains the answer, such as the price. It can be to the left or the right of the codes.":"return_array (tableau_renvoyé) : la colonne qui contient la réponse, par exemple le prix. Elle peut se trouver à gauche ou à droite des codes.","if_not_found: what to show when the code is missing, instead of #N/A.":"if_not_found (si_non_trouvé) : ce qu'il faut afficher quand le code est absent, au lieu de #N/A.","match_mode: leave it out for an exact match; -1 returns the next smaller value, which is what you need for bands.":"match_mode (mode_correspondance) : omettez-le pour une correspondance exacte ; -1 renvoie la valeur immédiatement inférieure, ce qu'il faut pour les tranches.","Lock the table with F4":"Verrouillez la table avec F4","When you copy a lookup down a column, the table must not move. Select the range in the formula and press F4 to add the dollar signs: $A$2:$A$6. The lookup value (E2) stays relative so it changes on each row.":"Quand vous recopiez une recherche vers le bas, la table ne doit pas bouger. Sélectionnez la plage dans la formule et appuyez sur F4 pour ajouter les dollars : $A$2:$A$6. La valeur cherchée (E2) reste relative pour changer à chaque ligne.","Price a hardware order":"Chiffrer une commande de quincaillerie","A hardware store in Bafoussam prices orders from its list. Fill G2:G5 with the item name using XLOOKUP (show \"Not found\" for unknown codes), H2:H5 with quantity × unit price (0 for unknown codes), and H6 with the order total.":"Une quincaillerie de Bafoussam chiffre les commandes à partir de sa liste. Remplissez G2:G5 avec le nom de l'article grâce à RECHERCHEX (affichez \"Not found\" pour les codes inconnus), H2:H5 avec quantité × prix unitaire (0 pour les codes inconnus), et H6 avec le total de la commande.","G2 is =XLOOKUP(E2,$A$2:$A$6,$B$2:$B$6,\"Not found\"). For H2 look up the price column with 0 as if_not_found and multiply by the quantity: =F2*XLOOKUP(E2,$A$2:$A$6,$C$2:$C$6,0). TOL-3 is not on the list.":"G2 : =XLOOKUP(E2,$A$2:$A$6,$B$2:$B$6,\"Not found\"). Pour H2, recherchez la colonne des prix avec 0 comme si_non_trouvé et multipliez par la quantité : =F2*XLOOKUP(E2,$A$2:$A$6,$C$2:$C$6,0). TOL-3 ne figure pas dans la liste.","VLOOKUP: still everywhere":"RECHERCHEV : encore partout","VLOOKUP is older but you will find it in thousands of existing workbooks, so you must be able to read it. It searches the first column of a table and returns the value from the column number you give.":"RECHERCHEV (VLOOKUP) est plus ancienne, mais vous la trouverez dans des milliers de classeurs existants : vous devez savoir la lire. Elle cherche dans la première colonne d'une table et renvoie la valeur de la colonne dont vous donnez le numéro.","Weakness of VLOOKUP":"Faiblesse de RECHERCHEV","What happens":"Ce qui se passe","XLOOKUP instead":"Avec RECHERCHEX","Column number typed as a fixed number":"Numéro de colonne tapé en dur","Insert a column inside the table and 3 now points at the wrong column: wrong prices, no error":"Insérez une colonne dans la table et le 3 pointe sur la mauvaise colonne : prix faux, sans aucune erreur","Points at the return column itself, so it follows the move":"Pointe directement sur la colonne renvoyée, donc suit le déplacement","Looks only to the right":"Ne regarde que vers la droite","Cannot return a value from a column to the left of the codes":"Impossible de renvoyer une valeur d'une colonne située à gauche des codes","The return column can be anywhere":"La colonne renvoyée peut être n'importe où","Approximate match by default":"Correspondance approximative par défaut","Forget FALSE and a missing code can return a neighbour's price":"Oubliez FALSE et un code absent peut renvoyer le prix d'un voisin","Exact match by default":"Correspondance exacte par défaut","No built-in missing-value text":"Pas de texte intégré pour les valeurs absentes","Shows #N/A, often wrapped in IFERROR":"Affiche #N/A, souvent entouré de SIERREUR","if_not_found argument":"Argument si_non_trouvé","Always type FALSE for codes":"Tapez toujours FALSE (FAUX) pour les codes","The last argument of VLOOKUP is TRUE (approximate) when you leave it out. For product codes, staff IDs or invoice numbers, always end with FALSE (or 0). Approximate match on unsorted codes gives wrong answers without any warning.":"Le dernier argument de RECHERCHEV vaut TRUE (approximatif) si vous l'omettez. Pour les codes produits, les matricules ou les numéros de facture, terminez toujours par FALSE (ou 0). Une correspondance approximative sur des codes non triés donne des réponses fausses sans le moindre avertissement.","INDEX and MATCH":"INDEX et EQUIV","Before XLOOKUP, professionals combined two functions. MATCH finds the position of a value in a column; INDEX returns the item at that position in another column. Together they do what XLOOKUP does, and they work in every version of Excel.":"Avant RECHERCHEX, les professionnels combinaient deux fonctions. EQUIV (MATCH) trouve la position d'une valeur dans une colonne ; INDEX renvoie l'élément situé à cette position dans une autre colonne. Ensemble, elles font ce que fait RECHERCHEX, et elles fonctionnent dans toutes les versions d'Excel.","Approximate match for bands":"Correspondance approximative pour les tranches","Commission, tax and discount scales are written as bands: from 0, from 1 000 000, from 3 000 000… Put the lower limit of each band in the first column, sorted smallest to largest. An approximate match returns the last band whose limit is less than or equal to the value.":"Les barèmes de commission, d'impôt et de remise s'écrivent en tranches : à partir de 0, à partir de 1 000 000, à partir de 3 000 000… Placez la limite inférieure de chaque tranche dans la première colonne, triée du plus petit au plus grand. Une correspondance approximative renvoie la dernière tranche dont la limite est inférieure ou égale à la valeur.","VLOOKUP with TRUE:":"RECHERCHEV avec TRUE :","MATCH with 1:":"EQUIV avec 1 :","XLOOKUP with match_mode -1:":"RECHERCHEX avec match_mode -1 :","Commission bands":"Tranches de commission","Agents are paid a commission that depends on their sales band (table in A8:C12). Fill C2:C5 with the band name using INDEX and MATCH, D2:D5 with the rate using VLOOKUP with approximate match, and E2:E5 with the commission (sales × rate).":"Les commerciaux touchent une commission qui dépend de leur tranche de ventes (table en A8:C12). Remplissez C2:C5 avec le nom de la tranche grâce à INDEX et EQUIV, D2:D5 avec le taux grâce à RECHERCHEV en correspondance approximative, et E2:E5 avec la commission (ventes × taux).","C2: =INDEX($B$9:$B$12,MATCH(B2,$A$9:$A$12,1)). D2: =VLOOKUP(B2,$A$9:$C$12,3,TRUE). E2: =B2*D2. Ewane's sales are exactly 3 000 000, so she is already in the Silver band.":"C2 : =INDEX($B$9:$B$12,MATCH(B2,$A$9:$A$12,1)). D2 : =VLOOKUP(B2,$A$9:$C$12,3,TRUE). E2 : =B2*D2. Les ventes d'Ewane valent exactement 3 000 000 : elle est donc déjà dans la tranche Silver.","Function Library":"Bibliothèque de fonctions","Lookup & Reference":"Recherche et référence","Lists XLOOKUP, VLOOKUP, INDEX and MATCH with a dialog box that explains each argument.":"Liste RECHERCHEX, RECHERCHEV, INDEX et EQUIV avec une boîte de dialogue qui explique chaque argument.","An NGO in Yaoundé pays mission allowances by staff grade. HR keeps one staff table (ID, name, grade) and one allowance table (grade, daily rate). Finance types only the staff ID and the number of nights; XLOOKUP fills in the name and rate. When the board raises the rates, HR changes one table and every claim sheet is correct.":"Une ONG de Yaoundé verse les indemnités de mission selon la catégorie du personnel. Les RH tiennent une table du personnel (matricule, nom, catégorie) et une table des indemnités (catégorie, taux journalier). La comptabilité ne tape que le matricule et le nombre de nuitées ; RECHERCHEX remplit le nom et le taux. Quand le conseil relève les taux, les RH modifient une seule table et toutes les fiches de remboursement sont justes.","A colleague's formula is =VLOOKUP(A2,Prices!A:D,4,FALSE). Someone inserts a new column B in the Prices sheet. What happens?":"La formule d'un collègue est =VLOOKUP(A2,Prices!A:D,4,FALSE). Quelqu'un insère une nouvelle colonne B dans la feuille Prices. Que se passe-t-il ?","Excel adjusts the 4 automatically":"Excel ajuste le 4 automatiquement","The formula now returns values from the wrong column":"La formule renvoie désormais les valeurs de la mauvaise colonne","The formula shows #REF!":"La formule affiche #REF!","Nothing, because FALSE protects it":"Rien, car FALSE la protège","The table range grows to A:E, but the column number stays 4, which now points at a different column. XLOOKUP or INDEX-MATCH avoid this because they reference the return column directly.":"La plage de la table s'étend à A:E, mais le numéro de colonne reste 4 et pointe maintenant sur une autre colonne. RECHERCHEX et INDEX-EQUIV évitent ce problème car elles font référence directement à la colonne renvoyée.","Which lookup should use an approximate match?":"Quelle recherche doit utiliser une correspondance approximative ?","Finding a price from a product code":"Trouver un prix à partir d'un code produit","Finding a staff name from an employee ID":"Trouver le nom d'un agent à partir de son matricule","Finding a tax rate from an income, using a table of lower band limits":"Trouver un taux d'imposition à partir d'un revenu, avec une table des limites inférieures des tranches","Finding a phone number from a customer name":"Trouver un numéro de téléphone à partir du nom d'un client","Bands need approximate match: the income falls between two limits and Excel returns the band below. Codes, IDs and names must always match exactly.":"Les tranches demandent une correspondance approximative : le revenu tombe entre deux limites et Excel renvoie la tranche inférieure. Les codes, matricules et noms doivent toujours correspondre exactement.","Create a price list of 8 products with codes, names and prices on a sheet named Prices":"Créez une liste de prix de 8 produits (codes, noms, prix) sur une feuille nommée Prix","On another sheet, build an order form where typing a code fills in the name and price with XLOOKUP":"Sur une autre feuille, construisez un bon de commande où la saisie d'un code remplit le nom et le prix avec RECHERCHEX","Rewrite one of the lookups with VLOOKUP and one with INDEX and MATCH":"Réécrivez l'une des recherches avec RECHERCHEV et une autre avec INDEX et EQUIV","Insert a column in the price list and see which formula breaks":"Insérez une colonne dans la liste de prix et observez quelle formule se casse","Add a discount table by order amount and look up the discount with approximate match":"Ajoutez une table de remises selon le montant de la commande et recherchez la remise en correspondance approximative","XLOOKUP function":"Fonction RECHERCHEX (XLOOKUP)","PivotTables and PivotCharts: summarise thousands of rows":"Tableaux et graphiques croisés dynamiques : résumer des milliers de lignes","Prepare a data list so a PivotTable can use it":"Préparer une liste de données utilisable par un tableau croisé dynamique","Build a PivotTable with the Rows, Columns, Values and Filters areas and change how values are summarised":"Construire un tableau croisé dynamique avec les zones Lignes, Colonnes, Valeurs et Filtres, et changer le mode de synthèse des valeurs","Add slicers and a PivotChart, refresh after changes, and rebuild a pivot summary with SUMIFS":"Ajouter des segments et un graphique croisé dynamique, actualiser après des modifications, et reproduire un résumé croisé avec SOMME.SI.ENS","A PivotTable turns a long list of transactions into a summary table in a few clicks: sales by region and product, expenses by month and budget line, beneficiaries by district and gender. You drag fields around instead of writing formulas, and you can change the question in seconds.":"Un tableau croisé dynamique transforme une longue liste de transactions en tableau de synthèse en quelques clics : ventes par région et par produit, dépenses par mois et par ligne budgétaire, bénéficiaires par district et par sexe. Vous faites glisser des champs au lieu d'écrire des formules, et vous changez de question en quelques secondes.","Step 1: prepare the data":"Étape 1 : préparer les données","One header row, with a short, unique name in every column.":"Une seule ligne d'en-têtes, avec un nom court et unique dans chaque colonne.","One record per row: one sale, one payment, one beneficiary.":"Un enregistrement par ligne : une vente, un paiement, un bénéficiaire.","No blank rows or columns inside the data, and no subtotal rows.":"Aucune ligne ni colonne vide au milieu des données, et aucune ligne de sous-total.","One type of data per column: amounts are numbers, not \"250 000 FCFA\" typed as text.":"Un seul type de donnée par colonne : les montants sont des nombres, pas « 250 000 FCFA » saisi comme du texte.","Turn the list into a table so new rows are included automatically.":"Transformez la liste en tableau pour que les nouvelles lignes soient incluses automatiquement.","Or press Ctrl + T. Give the table a name in Table Design › Table Name, for example tblSales.":"Ou appuyez sur Ctrl + T. Nommez le tableau dans Création de tableau › Nom du tableau, par exemple tblVentes.","Step 2: insert the PivotTable":"Étape 2 : insérer le tableau croisé dynamique","PivotTable":"Tableau croisé dynamique","From Table/Range":"À partir d'un tableau ou d'une plage","Create your first PivotTable":"Créer votre premier tableau croisé dynamique","Click any cell inside the table.":"Cliquez dans n'importe quelle cellule du tableau.","Go to Insert › PivotTable › From Table/Range. Excel suggests the table name as the range.":"Allez dans Insertion › Tableau croisé dynamique › À partir d'un tableau ou d'une plage. Excel propose le nom du tableau comme plage.","Keep New Worksheet and click OK.":"Gardez Nouvelle feuille de calcul et cliquez sur OK.","In the PivotTable Fields pane, drag Region to Rows, Product to Columns and Amount to Values.":"Dans le volet Champs de tableau croisé dynamique, faites glisser Region vers Lignes, Product vers Colonnes et Amount vers Valeurs.","Rename the new sheet, for example Summary.":"Renommez la nouvelle feuille, par exemple Synthèse.","Area":"Zone","Typical fields":"Champs habituels","Rows":"Lignes","One row in the summary for each distinct value":"Une ligne du résumé pour chaque valeur distincte","Region, agent, budget line, month":"Région, commercial, ligne budgétaire, mois","Columns":"Colonnes","One column for each distinct value; keep it to a few":"Une colonne pour chaque valeur distincte ; limitez-vous à quelques-unes","Product, year, gender":"Produit, année, sexe","Values":"Valeurs","The numbers that are calculated: Sum, Count, Average…":"Les nombres calculés : Somme, Nombre, Moyenne…","Amount, quantity, number of beneficiaries":"Montant, quantité, nombre de bénéficiaires","Filters":"Filtres","A drop-down above the table that limits the whole report":"Une liste déroulante au-dessus du tableau qui limite tout le rapport","Year, project, donor":"Année, projet, bailleur","Change how values are summarised":"Changer le mode de synthèse des valeurs","Numbers are added (Sum) by default; text fields dropped in Values are counted (Count).":"Par défaut, les nombres sont additionnés (Somme) ; les champs texte placés dans Valeurs sont comptés (Nombre).","To switch to Average or Count, right-click a value › Summarize Values By.":"Pour passer à Moyenne ou Nombre, clic droit sur une valeur › Synthèse des valeurs par.","To show shares, right-click › Show Values As › % of Grand Total (or % of Column Total).":"Pour afficher des parts, clic droit › Afficher les valeurs › % du total général (ou % du total de la colonne).","Format numbers once for the whole field: right-click › Number Format, instead of formatting cells.":"Formatez les nombres une fois pour tout le champ : clic droit › Format de nombre, plutôt que de formater les cellules.","Group dates by month or quarter, or amounts by ranges: right-click an item › Group.":"Regroupez les dates par mois ou trimestre, ou les montants par tranches : clic droit sur un élément › Grouper.","Which field goes where?":"Quel champ va où ?","The finance officer of a micro-credit network wants a report on loans disbursed. For each need, choose the PivotTable area, then answer the two questions about summarising.":"La responsable financière d'un réseau de microcrédit veut un rapport sur les prêts décaissés. Pour chaque besoin, choisissez la zone du tableau croisé dynamique, puis répondez aux deux questions sur la synthèse des valeurs.","Rows and Columns create the headings of the summary, Values holds the numbers that are calculated, and Filters limits the whole report to one choice.":"Lignes et Colonnes créent les intitulés du résumé, Valeurs contient les nombres calculés, et Filtres limite tout le rapport à un seul choix.","One line per branch (Douala, Yaoundé, Garoua…)":"Une ligne par agence (Douala, Yaoundé, Garoua…)","One column per loan type (Agriculture, Trade, School fees)":"Une colonne par type de prêt (Agriculture, Commerce, Frais de scolarité)","Loan type has only three values, so it fits across the columns.":"Le type de prêt n'a que trois valeurs : il tient bien en colonnes.","The total amount disbursed":"Le montant total décaissé","A drop-down to show only the year 2026":"Une liste déroulante pour n'afficher que l'année 2026","A filter limits the whole report without adding rows or columns.":"Un filtre limite tout le rapport sans ajouter de lignes ni de colonnes.","The manager wants the number of loans, not the amount. What do you change?":"La directrice veut le nombre de prêts, pas le montant. Que changez-vous ?","Count counts the loans in each cell. You can also drag the Loan ID field to Values, where text is counted automatically.":"Nombre compte les prêts de chaque cellule. Vous pouvez aussi faire glisser le champ Numéro de prêt dans Valeurs, où le texte est compté automatiquement.","Summarize Values By › Count":"Synthèse des valeurs par › Nombre","Show Values As › % of Grand Total":"Afficher les valeurs › % du total général","Group":"Grouper","Refresh":"Actualiser","She also wants each branch's share of the total. Which option gives it?":"Elle veut aussi la part de chaque agence dans le total. Quelle option la donne ?","Show Values As recalculates each cell as a share. Number Format would only display the amounts with a % sign.":"Afficher les valeurs recalcule chaque cellule comme une part. Format de nombre ne ferait qu'afficher les montants avec un signe %.","Summarize Values By › Average":"Synthèse des valeurs par › Moyenne","Number Format › Percentage":"Format de nombre › Pourcentage","Insert Slicer":"Insérer un segment","Slicers, refresh and PivotCharts":"Segments, actualisation et graphiques croisés dynamiques","PivotTable Analyze":"Analyse du tableau croisé dynamique","Buttons that filter the PivotTable with one click. Ideal for dashboards shown to managers.":"Des boutons qui filtrent le tableau croisé dynamique en un clic. Idéal pour les tableaux de bord présentés à la direction.","A PivotTable does not update itself":"Un tableau croisé dynamique ne se met pas à jour tout seul","When the source data changes, the PivotTable keeps the old figures until you refresh it. If you add rows to a plain range instead of a table, you must also change the source range.":"Quand les données sources changent, le tableau croisé dynamique garde les anciens chiffres jusqu'à ce que vous l'actualisiez. Si vous ajoutez des lignes à une plage simple au lieu d'un tableau, vous devez aussi modifier la plage source.","Format the list as a table":"Mettre la liste sous forme de tableau","Refresh the selected PivotTable":"Actualiser le tableau croisé dynamique sélectionné","Refresh all PivotTables and data connections in the workbook":"Actualiser tous les tableaux croisés dynamiques et connexions de données du classeur","PivotChart":"Graphique croisé dynamique","A chart linked to the PivotTable: filtering or pivoting one changes the other.":"Un graphique lié au tableau croisé dynamique : filtrer ou réorganiser l'un modifie l'autre.","The same summary with SUMIFS":"Le même résumé avec SOMME.SI.ENS","Each cell of a PivotTable is a SUMIFS (or COUNTIFS) with the row and column headings as criteria. Writing it yourself is useful when the layout of a report is fixed, when you need to mix sources, or to check a pivot. Mixed references let one formula fill the whole grid: $E2 keeps column E for the region, F$1 keeps row 1 for the product.":"Chaque cellule d'un tableau croisé dynamique est un SOMME.SI.ENS (ou NB.SI.ENS) qui prend les intitulés de ligne et de colonne comme critères. L'écrire vous-même est utile quand la présentation d'un rapport est imposée, quand vous devez combiner plusieurs sources, ou pour vérifier un tableau croisé. Les références mixtes permettent à une seule formule de remplir toute la grille : $E2 fige la colonne E pour la région, F$1 fige la ligne 1 pour le produit.","Build a pivot summary with SUMIFS":"Construire un résumé croisé avec SOMME.SI.ENS","A food wholesaler lists its sales in A1:C10. Fill the summary: F2:G4 with total sales by region and product, H2:H4 with the number of sales per region, and F5:H5 with the grand totals.":"Un grossiste en produits alimentaires liste ses ventes en A1:C10. Remplissez le résumé : F2:G4 avec le total des ventes par région et par produit, H2:H4 avec le nombre de ventes par région, et F5:H5 avec les totaux généraux.","Type =SUMIFS($C$2:$C$10,$A$2:$A$10,$E2,$B$2:$B$10,F$1) in F2, then copy it to G2 and down to row 4. H2 is =COUNTIF($A$2:$A$10,E2). Row 5 is SUM of each column.":"Tapez =SUMIFS($C$2:$C$10,$A$2:$A$10,$E2,$B$2:$B$10,F$1) en F2, puis recopiez-la en G2 et jusqu'à la ligne 4. H2 : =COUNTIF($A$2:$A$10,E2). La ligne 5 est la SOMME de chaque colonne.","The M&E officer of an NGO in Bamenda receives a monthly export of 3 000 beneficiary records. One PivotTable with District in Rows, Gender in Columns and a count of Beneficiary ID in Values answers the donor's standard table. A slicer for the month and a PivotChart turn it into a one-page dashboard for the coordination meeting.":"Le chargé de suivi-évaluation d'une ONG de Bamenda reçoit chaque mois un export de 3 000 fiches de bénéficiaires. Un seul tableau croisé dynamique avec District en Lignes, Sexe en Colonnes et le nombre d'identifiants de bénéficiaires en Valeurs répond au tableau type du bailleur. Un segment pour le mois et un graphique croisé dynamique en font un tableau de bord d'une page pour la réunion de coordination.","You added 40 new sales to the source table, but the PivotTable totals have not changed. What should you do?":"Vous avez ajouté 40 nouvelles ventes au tableau source, mais les totaux du tableau croisé dynamique n'ont pas changé. Que devez-vous faire ?","Delete the PivotTable and build it again":"Supprimer le tableau croisé dynamique et le reconstruire","Refresh the PivotTable":"Actualiser le tableau croisé dynamique","Press F9 to recalculate":"Appuyer sur F9 pour recalculer","Sort the source data":"Trier les données sources","A PivotTable reads its source only when it is refreshed: PivotTable Analyze › Refresh, or Alt + F5. Because the source is a table, the new rows are included.":"Un tableau croisé dynamique ne relit sa source que lorsqu'il est actualisé : Analyse du tableau croisé dynamique › Actualiser, ou Alt + F5. Comme la source est un tableau, les nouvelles lignes sont incluses.","Which data list is ready for a PivotTable?":"Quelle liste de données est prête pour un tableau croisé dynamique ?","A list with a subtotal row after each region":"Une liste avec une ligne de sous-total après chaque région","A list with two header rows merged across columns":"Une liste avec deux lignes d'en-têtes fusionnées sur plusieurs colonnes","A list with one header row, one record per row and no blank rows":"Une liste avec une seule ligne d'en-têtes, un enregistrement par ligne et aucune ligne vide","A list where amounts are typed as \"250 000 FCFA\"":"Une liste où les montants sont saisis sous la forme « 250 000 FCFA »","Subtotal rows would be counted twice, merged headers give fields no clear name, and amounts typed as text cannot be added.":"Les lignes de sous-total seraient comptées deux fois, les en-têtes fusionnés ne donnent pas de nom clair aux champs, et les montants saisis comme du texte ne peuvent pas être additionnés.","Format a sales or expense list of at least 30 rows as a table and name it":"Mettez sous forme de tableau une liste de ventes ou de dépenses d'au moins 30 lignes et nommez-la","Insert a PivotTable with a category in Rows, a period in Columns and an amount in Values":"Insérez un tableau croisé dynamique avec une catégorie en Lignes, une période en Colonnes et un montant en Valeurs","Show the values as % of Grand Total, then switch back to Sum":"Affichez les valeurs en % du total général, puis revenez à Somme","Add a slicer and a PivotChart, and place them next to the PivotTable":"Ajoutez un segment et un graphique croisé dynamique, et placez-les à côté du tableau croisé dynamique","Add five rows to the table, refresh, and check that the totals change":"Ajoutez cinq lignes au tableau, actualisez et vérifiez que les totaux changent","Overview of PivotTables and PivotCharts":"Vue d'ensemble des tableaux croisés dynamiques et des graphiques croisés dynamiques","What-If analysis, data validation and protection":"Analyse de scénarios, validation des données et protection","Calculate loan repayments with PMT and test options with Goal Seek, Scenario Manager and data tables":"Calculer des remboursements de prêt avec VPM et tester des options avec Valeur cible, le Gestionnaire de scénarios et les tables de données","Control what users can type with Data Validation lists, number limits and input messages":"Contrôler les saisies grâce aux listes de validation des données, aux limites numériques et aux messages de saisie","Lock formulas and protect sheets and workbooks before sharing a model":"Verrouiller les formules et protéger les feuilles et les classeurs avant de partager un modèle","What-If analysis answers questions such as \"What will I repay each month?\", \"How much can I borrow if I can pay 100 000 FCFA a month?\" or \"What happens to profit if prices rise by 10%?\". Once your model is right, validation and protection stop other people from breaking it.":"L'analyse de scénarios répond à des questions comme « Combien vais-je rembourser chaque mois ? », « Combien puis-je emprunter si je peux payer 100 000 FCFA par mois ? » ou « Que devient le bénéfice si les prix augmentent de 10 % ? ». Une fois votre modèle juste, la validation et la protection empêchent les autres de le casser.","PMT: the monthly repayment of a loan":"VPM : la mensualité d'un prêt","Argument":"Argument","rate":"rate (taux)","Interest rate per period":"Taux d'intérêt par période","Monthly payments: divide the annual rate by 12":"Paiements mensuels : divisez le taux annuel par 12","nper":"nper (npm)","Number of payments":"Nombre de paiements","Months, not years: 2 years = 24":"En mois, pas en années : 2 ans = 24","pv":"pv (va)","Amount borrowed today":"Montant emprunté aujourd'hui","Excel treats money you receive as positive and money you pay as negative":"Excel compte l'argent reçu en positif et l'argent payé en négatif","fv, type":"fv, type (vc, type)","Optional: balance left at the end, and 1 for payments at the start of each period":"Facultatifs : solde restant à la fin, et 1 pour des paiements en début de période","Leave them out for an ordinary loan":"Omettez-les pour un prêt ordinaire","Why PMT is negative":"Pourquoi VPM est négatif","PMT shows the payment as money going out, so the result is negative when the loan amount is positive. Put a minus sign before the loan amount (-B2) or before PMT to show a positive repayment.":"VPM présente le paiement comme une sortie d'argent : le résultat est donc négatif quand le montant du prêt est positif. Placez un signe moins devant le montant (-B2) ou devant VPM pour afficher une mensualité positive.","Compare three loan offers":"Comparer trois offres de prêt","A tailor in Yaoundé needs 1 500 000 FCFA to buy machines and compares three offers. Fill E2:E4 with the monthly repayment as a positive number, F2:F4 with the total repaid and G2:G4 with the total interest.":"Une couturière de Yaoundé a besoin de 1 500 000 FCFA pour acheter des machines et compare trois offres. Remplissez E2:E4 avec la mensualité en nombre positif, F2:F4 avec le total remboursé et G2:G4 avec le total des intérêts.","E2 is =PMT(C2/12,D2,-B2): monthly rate, number of months, and the amount with a minus sign. Total repaid is E2*D2, and interest is the total repaid minus the amount borrowed.":"E2 : =PMT(C2/12,D2,-B2) : taux mensuel, nombre de mois, et montant précédé d'un signe moins. Le total remboursé est E2*D2, et les intérêts sont le total remboursé moins le montant emprunté.","Bank B has the lowest monthly payment but costs the most in interest, because you pay for twice as long. Always compare the total cost, not only the monthly amount.":"La banque B a la mensualité la plus faible, mais elle coûte le plus en intérêts, car vous payez deux fois plus longtemps. Comparez toujours le coût total, pas seulement la mensualité.","Goal Seek: work backwards from the result":"Valeur cible : partir du résultat voulu","What-If Analysis":"Analyse de scénarios","Goal Seek":"Valeur cible","How much can I borrow for 100 000 FCFA a month?":"Combien puis-je emprunter pour 100 000 FCFA par mois ?","Click the cell with the PMT formula, for example E3.":"Cliquez sur la cellule qui contient la formule VPM, par exemple E3.","Open Data › What-If Analysis › Goal Seek. Set cell already shows E3.":"Ouvrez Données › Analyse de scénarios › Valeur cible. Cellule à définir affiche déjà E3.","In To value, type 100000.":"Dans Valeur à atteindre, tapez 100000.","In By changing cell, select the loan amount, B3. It must contain a number, not a formula.":"Dans Cellule à modifier, sélectionnez le montant du prêt, B3. Elle doit contenir un nombre, pas une formule.","Click OK. Excel tries values until the payment is 100 000, then click OK to keep the result or Cancel to undo it.":"Cliquez sur OK. Excel essaie des valeurs jusqu'à ce que la mensualité soit de 100 000, puis cliquez sur OK pour garder le résultat ou sur Annuler pour revenir en arrière.","Scenario Manager and data tables":"Gestionnaire de scénarios et tables de données","Scenario Manager (Data › What-If Analysis › Scenario Manager) saves named sets of input values, for example Pessimistic, Expected and Optimistic prices and volumes. Show each one in turn, or click Summary for a comparison report on a new sheet.":"Le Gestionnaire de scénarios (Données › Analyse de scénarios › Gestionnaire de scénarios) enregistre des jeux nommés de valeurs d'entrée, par exemple des prix et volumes Pessimiste, Attendu et Optimiste. Affichez-les tour à tour, ou cliquez sur Synthèse pour obtenir un rapport comparatif sur une nouvelle feuille.","A data table (Data › What-If Analysis › Data Table) calculates one formula for a whole list of inputs, such as the repayment for 12, 18, 24 and 36 months. You give the row or column input cell, and Excel fills the grid.":"Une table de données (Données › Analyse de scénarios › Table de données) calcule une formule pour toute une liste de valeurs d'entrée, par exemple la mensualité sur 12, 18, 24 et 36 mois. Vous indiquez la cellule d'entrée en ligne ou en colonne, et Excel remplit la grille.","Use Goal Seek for one target, Scenario Manager for a few named cases with several inputs, and a data table for one or two inputs across many values.":"Utilisez Valeur cible pour un seul objectif, le Gestionnaire de scénarios pour quelques cas nommés à plusieurs entrées, et une table de données pour une ou deux entrées sur de nombreuses valeurs.","Data Validation: control what people type":"Validation des données : contrôler les saisies","Data Validation":"Validation des données","Tab or setting":"Onglet ou option","Use it for":"Sert à","Settings › Allow: List":"Options › Autoriser : Liste","A drop-down of allowed values":"Une liste déroulante de valeurs autorisées","Source: Douala,Yaoundé,Garoua, or a range such as =$H$2:$H$10":"Source : Douala;Yaoundé;Garoua, ou une plage comme =$H$2:$H$10","Settings › Allow: Whole number":"Options › Autoriser : Nombre entier","Numbers between limits":"Des nombres compris entre deux limites","Quantity between 1 and 500; number of months between 6 and 36":"Quantité entre 1 et 500 ; nombre de mois entre 6 et 36","Settings › Allow: Decimal or Date":"Options › Autoriser : Décimal ou Date","Amounts, rates or dates within limits":"Montants, taux ou dates dans des limites","Interest rate between 0 and 0.4":"Taux d'intérêt entre 0 et 0,4","Input Message":"Message de saisie","A tip that appears when the cell is selected":"Une indication qui apparaît quand la cellule est sélectionnée","\"Type the amount in FCFA, without spaces\"":"« Tapez le montant en FCFA, sans espaces »","Error Alert":"Alerte d'erreur","What happens with a wrong entry: Stop blocks it, Warning and Information allow it after a message":"Ce qui se passe en cas de saisie incorrecte : Arrêt la bloque, Avertissement et Informations l'acceptent après un message","Stop: \"Choose a city from the list\"":"Arrêt : « Choisissez une ville dans la liste »","Lock cells and protect the sheet":"Verrouiller les cellules et protéger la feuille","Every cell is locked by default, but locking only works once the sheet is protected. So the method is: unlock the input cells, then protect the sheet. Users can type in the inputs, and the formulas are safe.":"Toutes les cellules sont verrouillées par défaut, mais le verrouillage n'agit qu'une fois la feuille protégée. La méthode est donc : déverrouiller les cellules de saisie, puis protéger la feuille. Les utilisateurs peuvent saisir les données, et les formules sont à l'abri.","Protect a loan calculator":"Protéger un simulateur de prêt","Select the input cells (amount, rate, months).":"Sélectionnez les cellules de saisie (montant, taux, mois).","Press Ctrl + 1 to open Format Cells, go to the Protection tab and untick Locked.":"Appuyez sur Ctrl + 1 pour ouvrir Format de cellule, allez dans l'onglet Protection et décochez Verrouillée.","Go to Review › Protect Sheet, choose what users may do, type a password if needed and click OK.":"Allez dans Révision › Protéger la feuille, choisissez ce que les utilisateurs peuvent faire, tapez un mot de passe si nécessaire et cliquez sur OK.","To stop people adding, deleting or renaming sheets, use Review › Protect Workbook (structure).":"Pour empêcher d'ajouter, de supprimer ou de renommer des feuilles, utilisez Révision › Protéger le classeur (structure).","To stop people opening the file at all, use File › Info › Protect Workbook › Encrypt with Password.":"Pour empêcher toute ouverture du fichier, utilisez Fichier › Informations › Protéger le classeur › Chiffrer avec mot de passe.","Sheet protection is not security":"Protéger une feuille n'est pas sécuriser","Protect Sheet prevents accidental changes; it does not hide confidential data from a determined person. For salaries or client data, encrypt the file with a password and control who can open it in OneDrive. Keep passwords somewhere safe: Microsoft cannot recover them.":"Protéger la feuille évite les modifications accidentelles ; cela ne cache pas des données confidentielles à une personne déterminée. Pour les salaires ou les données clients, chiffrez le fichier avec un mot de passe et contrôlez qui peut l'ouvrir dans OneDrive. Conservez les mots de passe en lieu sûr : Microsoft ne peut pas les récupérer.","Goal Seek, validation and protection":"Valeur cible, validation et protection","Your loan calculator has the amount in B2, the annual rate in C2, the months in D2 and the PMT formula in E2. Answer each question; type cell references like B2.":"Votre simulateur de prêt contient le montant en B2, le taux annuel en C2, le nombre de mois en D2 et la formule VPM en E2. Répondez à chaque question ; tapez les références de cellules sous la forme B2.","Goal Seek sets the formula cell to a value by changing an input cell. Protection needs two steps: unlock the inputs, then protect the sheet.":"Valeur cible amène la cellule de formule à une valeur en modifiant une cellule d'entrée. La protection se fait en deux temps : déverrouiller les entrées, puis protéger la feuille.","Goal Seek: what do you type in Set cell?":"Valeur cible : que tapez-vous dans Cellule à définir ?","Set cell is always the cell that contains the formula whose result you want to fix.":"La cellule à définir est toujours celle qui contient la formule dont vous voulez fixer le résultat.","Goal Seek: what do you type in To value, for a payment of 100 000 FCFA a month?":"Valeur cible : que tapez-vous dans Valeur à atteindre pour une mensualité de 100 000 FCFA ?","Goal Seek: what do you type in By changing cell, to find the amount you can borrow?":"Valeur cible : que tapez-vous dans Cellule à modifier pour trouver le montant que vous pouvez emprunter ?","By changing cell must be an input that the formula depends on, and it must contain a value, not a formula.":"La cellule à modifier doit être une entrée dont dépend la formule, et elle doit contenir une valeur, pas une formule.","The months in D2 must be a whole number from 6 to 36. Which setting do you use?":"Le nombre de mois en D2 doit être un nombre entier de 6 à 36. Quel réglage utilisez-vous ?","Data Validation › Allow: Whole number, between 6 and 36":"Validation des données › Autoriser : Nombre entier, compris entre 6 et 36","Data Validation › Allow: List":"Validation des données › Autoriser : Liste","Conditional Formatting › Highlight Cells Rules":"Mise en forme conditionnelle › Règles de mise en surbrillance des cellules","Review › Protect Sheet":"Révision › Protéger la feuille","You want a note to appear when someone selects B2, before they type. Which Data Validation tab do you use?":"Vous voulez qu'une note apparaisse quand quelqu'un sélectionne B2, avant la saisie. Quel onglet de Validation des données utilisez-vous ?","Protection":"Protection","Colleagues must be able to change B2:D2 but never the formula in E2. What do you do?":"Vos collègues doivent pouvoir modifier B2:D2 mais jamais la formule en E2. Que faites-vous ?","All cells are locked by default, so protecting the sheet alone would block the inputs too.":"Toutes les cellules sont verrouillées par défaut : protéger la feuille seule bloquerait aussi les entrées.","Protect the sheet only":"Protéger uniquement la feuille","Unlock B2:D2 in Format Cells › Protection, then protect the sheet":"Déverrouiller B2:D2 dans Format de cellule › Protection, puis protéger la feuille","Lock E2, then protect the workbook structure":"Verrouiller E2, puis protéger la structure du classeur","Hide column E":"Masquer la colonne E","You want to compare an Expected case and a Crisis case, each changing the amount, the rate and the months. Which tool fits?":"Vous voulez comparer un cas Attendu et un cas Crise, chacun modifiant le montant, le taux et le nombre de mois. Quel outil convient ?","Scenario Manager stores named sets of several inputs and can produce a summary report.":"Le Gestionnaire de scénarios enregistre des jeux nommés de plusieurs entrées et peut produire un rapport de synthèse.","Scenario Manager":"Gestionnaire de scénarios","Protect Workbook":"Protéger le classeur","A credit officer at a microfinance institution in Bafoussam visits clients with a laptop. Her loan simulator has drop-down lists for the loan product, whole-number limits for the duration, and a protected sheet so the PMT formulas and rates set by head office cannot be changed. The client sees the repayment immediately, and every officer uses the same rules.":"Une chargée de crédit d'une institution de microfinance de Bafoussam rend visite aux clients avec un ordinateur portable. Son simulateur de prêt a des listes déroulantes pour le produit de prêt, des limites en nombres entiers pour la durée, et une feuille protégée pour que les formules VPM et les taux fixés par le siège ne puissent pas être modifiés. Le client voit sa mensualité immédiatement, et tous les agents appliquent les mêmes règles.","A loan of 3 000 000 FCFA at 12% a year is repaid monthly over 3 years. Which formula gives the monthly payment as a positive number?":"Un prêt de 3 000 000 FCFA à 12 % par an est remboursé mensuellement sur 3 ans. Quelle formule donne la mensualité en nombre positif ?","=PMT(12%,3,3000000)":"=PMT(12%,3,3000000)","=PMT(12%/12,36,-3000000)":"=PMT(12%/12,36,-3000000)","=PMT(12%,36,-3000000)":"=PMT(12%,36,-3000000)","=PMT(1%,3,3000000)":"=PMT(1%,3,3000000)","Monthly payments need a monthly rate (12%/12) and the number of months (36). The minus sign before the amount makes the result positive.":"Des paiements mensuels demandent un taux mensuel (12%/12) et le nombre de mois (36). Le signe moins devant le montant rend le résultat positif.","You protected a sheet, and now nobody can type in the input cells either. What did you forget?":"Vous avez protégé une feuille, et maintenant plus personne ne peut saisir dans les cellules d'entrée non plus. Qu'avez-vous oublié ?","To protect the workbook structure":"De protéger la structure du classeur","To unlock the input cells before protecting the sheet":"De déverrouiller les cellules de saisie avant de protéger la feuille","To add Data Validation":"D'ajouter une validation des données","To save the file as .xlsm":"D'enregistrer le fichier au format .xlsm","Cells are locked by default. Untick Locked in Format Cells › Protection for the inputs, then protect the sheet again.":"Les cellules sont verrouillées par défaut. Décochez Verrouillée dans Format de cellule › Protection pour les entrées, puis protégez de nouveau la feuille.","Build a loan calculator with amount, annual rate and months as inputs and a PMT formula":"Construisez un simulateur de prêt avec le montant, le taux annuel et le nombre de mois en entrée, et une formule VPM","Use Goal Seek to find the amount you can borrow for 75 000 FCFA a month":"Utilisez Valeur cible pour trouver le montant que vous pouvez emprunter pour 75 000 FCFA par mois","Create three scenarios in Scenario Manager and produce a Summary report":"Créez trois scénarios dans le Gestionnaire de scénarios et produisez un rapport de synthèse","Add Data Validation: a list of loan products and whole numbers from 6 to 36 for the months, with an input message":"Ajoutez une validation des données : une liste de produits de prêt et des nombres entiers de 6 à 36 pour les mois, avec un message de saisie","Unlock the input cells, protect the sheet, and test that the formula cannot be changed":"Déverrouillez les cellules de saisie, protégez la feuille et vérifiez que la formule ne peut pas être modifiée","Use Goal Seek to find the result you want by adjusting an input value":"Utiliser Valeur cible pour trouver le résultat voulu en ajustant une valeur d'entrée","Protect a worksheet":"Protéger une feuille de calcul","Practice lab: decisions, lookups and analysis in Excel":"Atelier pratique : décisions, recherches et analyse dans Excel","Apply IF and COUNTIF to a simple follow-up list":"Appliquer SI et NB.SI à une liste de suivi simple","Combine lookups with IFERROR to handle missing codes":"Combiner des recherches avec SIERREUR pour gérer les codes absents","Choose the right analysis tool and write PMT and SUMIFS formulas":"Choisir le bon outil d'analyse et écrire des formules VPM et SOMME.SI.ENS","Build a complete invoice summary that combines XLOOKUP, SUMIFS and IF":"Construire un récapitulatif de factures complet qui combine RECHERCHEX, SOMME.SI.ENS et SI","Exercise 1: School fees follow-up":"Exercice 1 : suivi des frais de scolarité","Who still owes school fees?":"Qui doit encore des frais de scolarité ?","The bursar of a secondary school in Bamenda follows up fees. Fill E2:E5 with the balance (fees due minus paid), F2:F5 with \"Cleared\" when the balance is 0 or \"Owing\" otherwise, then F7 with the number of students owing and F8 with the total still to collect.":"L'économe d'un établissement secondaire de Bamenda suit le paiement des frais. Remplissez E2:E5 avec le solde (frais dus moins payés), F2:F5 avec \"Cleared\" quand le solde est à 0 ou \"Owing\" sinon, puis F7 avec le nombre d'élèves débiteurs et F8 avec le total restant à encaisser.","E2 is =C2-D2. F2 is =IF(E2=0,\"Cleared\",\"Owing\"). F7 counts \"Owing\" with COUNTIF, and F8 is the SUM of the balances.":"E2 : =C2-D2. F2 : =IF(E2=0,\"Cleared\",\"Owing\"). F7 compte les \"Owing\" avec NB.SI, et F8 est la SOMME des soldes.","Exercise 2: Mission allowances":"Exercice 2 : indemnités de mission","Look up staff and daily rates":"Rechercher le personnel et les taux journaliers","An NGO pays mission allowances by grade. For each mission in rows 9 to 12, fill C with the staff name (\"Unknown ID\" if the ID is not in the staff list), D with the grade (\"None\" if unknown) and E with nights × daily rate, showing 0 when the grade cannot be found.":"Une ONG verse des indemnités de mission selon la catégorie. Pour chaque mission des lignes 9 à 12, remplissez C avec le nom de l'agent (\"Unknown ID\" si le matricule ne figure pas dans la liste), D avec la catégorie (\"None\" si elle est inconnue) et E avec nuitées × taux journalier, en affichant 0 quand la catégorie est introuvable.","C9: =XLOOKUP(A9,$A$2:$A$6,$B$2:$B$6,\"Unknown ID\"). D9 is the same with the grade column and \"None\". For E9, find the rate with INDEX($F$2:$F$4,MATCH(D9,$E$2:$E$4,0)), multiply by B9, and wrap everything in IFERROR(…,0).":"C9 : =XLOOKUP(A9,$A$2:$A$6,$B$2:$B$6,\"Unknown ID\"). D9 est identique avec la colonne des catégories et \"None\". Pour E9, trouvez le taux avec INDEX($F$2:$F$4,MATCH(D9,$E$2:$E$4,0)), multipliez par B9, et entourez le tout de IFERROR(…,0).","Exercise 3: The right analysis tool":"Exercice 3 : le bon outil d'analyse","Choose the tool and write the formula":"Choisir l'outil et écrire la formule","A cooperative of coffee farmers in the West region asks you for help with its workbook. Answer each question. Type formulas in English with commas, starting with =.":"Une coopérative de caféiculteurs de la région de l'Ouest vous demande de l'aide pour son classeur. Répondez à chaque question. Tapez les formules en anglais avec des virgules, en commençant par =.","Goal Seek finds one input for a target result, Scenario Manager compares named cases, a PivotTable summarises long lists, and Data Validation controls entries. For PMT, the rate and the number of periods must both be monthly.":"Valeur cible trouve une entrée pour un résultat visé, le Gestionnaire de scénarios compare des cas nommés, un tableau croisé dynamique résume de longues listes, et la Validation des données contrôle les saisies. Pour VPM, le taux et le nombre de périodes doivent être tous deux mensuels.","The cooperative borrows the amount in B2 at the annual rate in B3 over the number of months in B4. Write the formula for the monthly payment as a positive number.":"La coopérative emprunte le montant en B2 au taux annuel en B3 sur le nombre de mois en B4. Écrivez la formule de la mensualité en nombre positif.","Divide the annual rate by 12, use the number of months, and put a minus sign before the amount (or before PMT).":"Divisez le taux annuel par 12, utilisez le nombre de mois, et placez un signe moins devant le montant (ou devant PMT).","Deliveries are listed with the farmer's village in A2:A200 and the kilograms in C2:C200. Write a formula for the total kilograms delivered from Dschang.":"Les livraisons sont listées avec le village du producteur en A2:A200 et les kilogrammes en C2:C200. Écrivez une formule qui donne le total des kilogrammes livrés depuis Dschang.","SUMIFS puts the range to add first; SUMIF puts it last. Both work for one condition.":"SUMIFS place la plage à additionner en premier ; SUMIF la place en dernier. Les deux conviennent pour une seule condition.","The board wants to know the price per kilogram that brings total income to exactly 45 000 000 FCFA. Which tool?":"Le conseil veut connaître le prix au kilogramme qui porte le revenu total à exactement 45 000 000 FCFA. Quel outil ?","One target result and one input to change: Goal Seek.":"Un résultat visé et une entrée à modifier : Valeur cible.","It also wants to compare a Good harvest, a Normal harvest and a Drought case, each with a different volume, price and transport cost.":"Il veut aussi comparer une Bonne récolte, une Récolte normale et un cas Sécheresse, chacun avec un volume, un prix et un coût de transport différents.","A list of 4 000 deliveries must be summarised by village and by month, with a count of farmers.":"Une liste de 4 000 livraisons doit être résumée par village et par mois, avec le nombre de producteurs.","A nested IF":"Des SI imbriqués","A PivotTable":"Un tableau croisé dynamique","Collectors keep typing the village name differently (Dschang, dschang, Dshang). How do you prevent this?":"Les collecteurs saisissent le nom du village de plusieurs façons (Dschang, dschang, Dshang). Comment l'éviter ?","A drop-down list only accepts the approved spellings, so SUMIFS and PivotTables group the data correctly.":"Une liste déroulante n'accepte que les orthographes approuvées : SOMME.SI.ENS et les tableaux croisés dynamiques regroupent alors correctement les données.","Protect the workbook":"Protéger le classeur","Data Validation with a List of villages":"Validation des données avec une Liste de villages","In a PivotTable of deliveries, where do you put the Month field to get one column per month?":"Dans un tableau croisé dynamique des livraisons, où placez-vous le champ Mois pour obtenir une colonne par mois ?","Exercise 4: Customer invoices and volume discount":"Exercice 4 : factures clients et remise sur volume","Invoice lines, customer totals and discount":"Lignes de facture, totaux clients et remise","A wholesaler in Douala prices orders from the list in A1:C5. Fill D8:D12 with quantity × unit price: a discontinued code or a cancelled line (no quantity) must give 0, not an error. Then fill G2:G3 with each customer's total, and H2:H3 with the amount to invoice after a 10% discount for customers whose total is at least 500 000 FCFA.":"Un grossiste de Douala chiffre les commandes à partir de la liste en A1:C5. Remplissez D8:D12 avec quantité × prix unitaire : un code abandonné ou une ligne annulée (sans quantité) doit donner 0, pas une erreur. Remplissez ensuite G2:G3 avec le total de chaque client, et H2:H3 avec le montant à facturer après une remise de 10 % pour les clients dont le total atteint au moins 500 000 FCFA.","D8: =C8*XLOOKUP(B8,$A$2:$A$5,$C$2:$C$5,0). SUC-10 is not on the list, so if_not_found must be 0. G2: =SUMIFS($D$8:$D$12,$A$8:$A$12,F2). H2: =IF(G2>=500000,G2*0.9,G2). Mbopi's total is exactly 500 000, so > instead of >= gives the wrong answer.":"D8 : =C8*XLOOKUP(B8,$A$2:$A$5,$C$2:$C$5,0). SUC-10 ne figure pas dans la liste : si_non_trouvé doit donc valoir 0. G2 : =SUMIFS($D$8:$D$12,$A$8:$A$12,F2). H2 : =IF(G2>=500000,G2*0.9,G2). Le total de Mbopi est exactement 500 000 : avec > au lieu de >=, la réponse est fausse.","Module 5 Quiz":"Quiz du module 5","What does =IF(AND(B2>=12,C2=\"Yes\"),\"Certified\",\"Not certified\") return when B2 is 14 and C2 is \"No\"?":"Que renvoie =IF(AND(B2>=12,C2=\"Yes\"),\"Certified\",\"Not certified\") quand B2 vaut 14 et C2 vaut \"No\" ?","Certified":"Certified","Not certified":"Not certified","TRUE":"TRUE (VRAI)","AND needs every condition to be true. The score is enough, but C2 is not \"Yes\", so IF returns the value_if_false.":"ET exige que toutes les conditions soient vraies. La note suffit, mais C2 ne vaut pas \"Yes\" : SI renvoie donc la valeur_si_faux.","Why do you end an IFS formula with TRUE,\"…\"?":"Pourquoi terminer une formule SI.CONDITIONS par TRUE,\"…\" ?","To make it faster":"Pour la rendre plus rapide","To give a result when none of the other tests is true":"Pour donner un résultat quand aucun des autres tests n'est vrai","To make the tests case-sensitive":"Pour que les tests tiennent compte des majuscules","To convert text to numbers":"Pour convertir du texte en nombres","TRUE is always true, so it catches every remaining case. Without it, IFS returns #N/A when no test matches.":"TRUE est toujours vrai : il attrape donc tous les cas restants. Sans lui, SI.CONDITIONS renvoie #N/A quand aucun test ne correspond.","Which formula adds the amounts in C2:C100 for the Littoral region (A2:A100) and the product Rice (B2:B100)?":"Quelle formule additionne les montants de C2:C100 pour la région Littoral (A2:A100) et le produit Rice (B2:B100) ?","=SUMIF(A2:A100,\"Littoral\",C2:C100)":"=SUMIF(A2:A100,\"Littoral\",C2:C100)","=COUNTIFS(A2:A100,\"Littoral\",B2:B100,\"Rice\")":"=COUNTIFS(A2:A100,\"Littoral\",B2:B100,\"Rice\")","=SUMIFS(A2:A100,\"Littoral\",B2:B100,\"Rice\")":"=SUMIFS(A2:A100,\"Littoral\",B2:B100,\"Rice\")","=SUMIFS(C2:C100,A2:A100,\"Littoral\",B2:B100,\"Rice\")":"=SUMIFS(C2:C100,A2:A100,\"Littoral\",B2:B100,\"Rice\")","SUMIFS starts with the range to add, followed by pairs of criteria range and criteria.":"SOMME.SI.ENS commence par la plage à additionner, suivie de paires plage de critères / critère.","What does the fourth argument of =XLOOKUP(E2,A2:A50,C2:C50,\"Not found\") do?":"Que fait le quatrième argument de =XLOOKUP(E2,A2:A50,C2:C50,\"Not found\") ?","Sets approximate match":"Il active la correspondance approximative","Returns \"Not found\" instead of #N/A when the code is missing":"Il renvoie \"Not found\" au lieu de #N/A quand le code est absent","Searches from the bottom":"Il cherche à partir du bas","Makes the lookup case-sensitive":"Il rend la recherche sensible à la casse","The optional if_not_found argument replaces the #N/A error with your own value.":"L'argument facultatif si_non_trouvé remplace l'erreur #N/A par votre propre valeur.","Which lookup is correct for finding a tax rate from a table of lower income limits sorted in ascending order?":"Quelle recherche est correcte pour trouver un taux d'imposition dans une table de limites inférieures de revenu triées par ordre croissant ?","=VLOOKUP(B2,$A$2:$B$6,2,TRUE)":"=VLOOKUP(B2,$A$2:$B$6,2,TRUE)","=VLOOKUP(B2,$A$2:$B$6,2,FALSE)":"=VLOOKUP(B2,$A$2:$B$6,2,FALSE)","=MATCH(B2,$A$2:$A$6,0)":"=MATCH(B2,$A$2:$A$6,0)","=XLOOKUP(B2,$A$2:$A$6,$B$2:$B$6)":"=XLOOKUP(B2,$A$2:$A$6,$B$2:$B$6)","Bands need approximate match. VLOOKUP with TRUE returns the band whose lower limit is the largest one not above the income.":"Les tranches demandent une correspondance approximative. RECHERCHEV avec TRUE renvoie la tranche dont la limite inférieure est la plus grande sans dépasser le revenu.","In a PivotTable, which area creates a drop-down that limits the whole report, for example to one year?":"Dans un tableau croisé dynamique, quelle zone crée une liste déroulante qui limite tout le rapport, par exemple à une année ?","Filters sit above the PivotTable and apply to all of it. Slicers do the same job with buttons.":"Les filtres se placent au-dessus du tableau croisé dynamique et s'appliquent à l'ensemble. Les segments font le même travail avec des boutons.","What does =PMT(15%/12,24,-1000000) calculate?":"Que calcule =PMT(15%/12,24,-1000000) ?","The total interest on the loan":"Le total des intérêts du prêt","The monthly repayment of 1 000 000 FCFA over 24 months at 15% a year":"La mensualité d'un prêt de 1 000 000 FCFA sur 24 mois à 15 % par an","The amount you can borrow":"Le montant que vous pouvez emprunter","The yearly repayment over 24 years":"L'annuité sur 24 ans","The rate is divided by 12 and nper is 24 months, so the result is the monthly payment. The minus sign makes it positive.":"Le taux est divisé par 12 et nper vaut 24 mois : le résultat est donc la mensualité. Le signe moins la rend positive.","Which tool finds the loan amount that gives a monthly payment of exactly 80 000 FCFA?":"Quel outil trouve le montant du prêt qui donne une mensualité d'exactement 80 000 FCFA ?","Protect Sheet":"Protéger la feuille","Goal Seek changes one input cell until a formula reaches the value you set.":"Valeur cible modifie une cellule d'entrée jusqu'à ce qu'une formule atteigne la valeur fixée.","Build each slide around one message with a title that states the point":"Construire chaque diapositive autour d'un seul message, avec un titre qui énonce l'idée","Use layouts, placeholders, Designer and the alignment tools to keep slides tidy":"Utiliser les dispositions, les espaces réservés, le Concepteur et les outils d'alignement pour garder des diapositives ordonnées","Make slides readable and accessible with contrast, font sizes and alt text":"Rendre les diapositives lisibles et accessibles grâce au contraste, à la taille des polices et au texte de remplacement","A slide is not a document. Your audience reads it in a few seconds while listening to you, often from the back of a hot meeting room with a tired projector. Clear slides carry one idea each, use few words and large text, and leave the details to you and to a handout.":"Une diapositive n'est pas un document. Votre public la lit en quelques secondes tout en vous écoutant, souvent depuis le fond d'une salle de réunion chaude, avec un vieux projecteur fatigué. Une diapositive claire porte une seule idée, utilise peu de mots et un texte de grande taille, et laisse les détails à votre discours et à un document distribué.","One slide, one message":"Une diapositive, un message","Decide the single point of the slide before you open PowerPoint. If you need two points, make two slides.":"Décidez de l'idée unique de la diapositive avant d'ouvrir PowerPoint. Si vous avez deux idées, faites deux diapositives.","Write the title as a short sentence that states that point. The audience should get the message from the title alone.":"Rédigez le titre sous la forme d'une phrase courte qui énonce cette idée. Le public doit comprendre le message rien qu'en lisant le titre.","Keep bullets short: three to five bullets, and no more than about ten words each. Write key words, not full paragraphs.":"Gardez des puces courtes : trois à cinq puces, d'une dizaine de mots au maximum chacune. Écrivez des mots clés, pas des paragraphes entiers.","Say the detail out loud and put it in the speaker notes or in a handout, not on the slide.":"Donnez les détails à l'oral et mettez-les dans les notes du présentateur ou dans un document distribué, pas sur la diapositive.","Use a picture, a chart or a diagram when it shows the point faster than words.":"Utilisez une image, un graphique ou un schéma lorsqu'il montre l'idée plus vite que des mots.","Topic title (weak)":"Titre de sujet (faible)","Message title (strong)":"Titre de message (fort)","Sales Q1 2026":"Ventes T1 2026","Q1 sales rose 12% thanks to the Bafoussam branch":"Les ventes du T1 ont augmenté de 12 % grâce à l'agence de Bafoussam","Training results":"Résultats de la formation","85% of staff passed the Excel test after two weeks":"85 % du personnel a réussi le test Excel après deux semaines","Budget":"Budget","Fuel costs take a third of the 2026 transport budget":"Le carburant absorbe un tiers du budget transport 2026","Survey":"Enquête","Most clients want to pay by mobile money":"La plupart des clients veulent payer par mobile money","Readable from the back of the room":"Lisible depuis le fond de la salle","Use at least 32 pt for titles and 24 pt for body text; never go below 18 pt. Choose dark text on a light background, or light text on a dark background, and avoid red on green or text over busy photos. A plain sans-serif font such as Calibri, Aptos or Arial reads best on a projector.":"Utilisez au moins 32 pt pour les titres et 24 pt pour le corps du texte ; ne descendez jamais sous 18 pt. Choisissez un texte foncé sur fond clair, ou un texte clair sur fond foncé, et évitez le rouge sur vert ou le texte posé sur une photo chargée. Une police simple sans empattement, comme Calibri, Aptos ou Arial, se lit le mieux au projecteur.","Layouts and placeholders":"Dispositions et espaces réservés","Each new slide uses a":"Chaque nouvelle diapositive utilise une","layout":"disposition",", such as Title and Content, Two Content or Section Header. A layout contains":", par exemple Titre et contenu, Deux contenus ou En-tête de section. Une disposition contient des","placeholders":"espaces réservés",", the dotted boxes that say \"Click to add title\" or \"Click to add text\". Typing in placeholders instead of drawing your own text boxes keeps fonts and positions consistent, lets the Outline view and screen readers find your titles, and allows the Slide Master to update every slide at once (Lesson 2).":", les cadres en pointillés qui affichent « Cliquez pour ajouter un titre » ou « Cliquez pour ajouter du texte ». Taper dans les espaces réservés plutôt que dessiner vos propres zones de texte garde des polices et des positions homogènes, permet au mode Plan et aux lecteurs d'écran de trouver vos titres, et permet au masque des diapositives de mettre à jour toutes les diapositives en une fois (leçon 2).","Slides":"Diapositives","Changes the layout of the selected slides without losing their content.":"Change la disposition des diapositives sélectionnées sans perdre leur contenu.","New Slide":"Nouvelle diapositive","Click the arrow under New Slide to choose the layout of the new slide.":"Cliquez sur la flèche sous Nouvelle diapositive pour choisir la disposition de la nouvelle diapositive.","Designer and the alignment tools":"Le Concepteur et les outils d'alignement","Design":"Création","Designer":"Concepteur","In recent versions Designer is also on the right end of the Home tab. It needs an internet connection.":"Dans les versions récentes, le Concepteur se trouve aussi à l'extrémité droite de l'onglet Accueil. Il nécessite une connexion Internet.","Designer suggests layouts for the pictures, icons and lists on the current slide. Pick a suggestion as a starting point, then check that the text is still large enough and that your title still states the point.":"Le Concepteur propose des mises en page pour les images, les icônes et les listes de la diapositive active. Prenez une suggestion comme point de départ, puis vérifiez que le texte reste assez grand et que votre titre énonce toujours l'idée.","Line objects up exactly":"Aligner les objets avec précision","Select the objects to line up: click the first, then hold":"Sélectionnez les objets à aligner : cliquez sur le premier, puis maintenez","and click the others.":"et cliquez sur les autres.","Shape Format › Arrange › Align":"Format de la forme › Organiser › Aligner","(or":"(ou","Picture Format":"Format de l'image","for pictures).":"pour les images).","Choose an edge, for example":"Choisissez un bord, par exemple","Align Top":"Aligner en haut","Align Middle":"Aligner au milieu","for a row of icons.":"pour une rangée d'icônes.","With three or more objects selected, choose":"Avec trois objets ou plus sélectionnés, choisissez","Distribute Horizontally":"Distribuer horizontalement","to make the gaps equal.":"pour obtenir des espacements égaux.","to group them so they move together.":"pour les grouper afin qu'ils se déplacent ensemble.","Smart guides":"Repères actifs","When you drag an object, red dotted lines appear when it lines up with another object or with the centre of the slide. Release the mouse on the guide for a perfect alignment.":"Quand vous faites glisser un objet, des lignes pointillées rouges apparaissent lorsqu'il s'aligne sur un autre objet ou sur le centre de la diapositive. Relâchez la souris sur le repère pour un alignement parfait.","Pictures, alt text and accessibility":"Images, texte de remplacement et accessibilité","Make the deck accessible":"Rendre la présentation accessible","Right-click each picture, chart or icon and choose":"Cliquez avec le bouton droit sur chaque image, graphique ou icône et choisissez","View Alt Text":"Afficher le texte de remplacement",". Describe what it shows in one sentence, or tick":". Décrivez en une phrase ce qu'il montre, ou cochez","Mark as decorative":"Marquer comme décoratif","for pure decoration.":"pour une simple décoration.","Give every slide a title, even if you hide it on a picture slide. Screen readers use titles to navigate.":"Donnez un titre à chaque diapositive, même si vous le masquez sur une diapositive d'image. Les lecteurs d'écran utilisent les titres pour naviguer.","Review › Check Accessibility":"Révision › Vérifier l'accessibilité","and fix each error and warning listed in the pane.":"et corrigez chaque erreur et chaque avertissement listés dans le volet.","Check the reading order of objects in the pane under":"Vérifiez l'ordre de lecture des objets dans le volet, sous","Reading Order":"Ordre de lecture","so a screen reader follows the logical order.":", afin qu'un lecteur d'écran suive l'ordre logique.","Accessibility":"Accessibilité","Check Accessibility":"Vérifier l'accessibilité","Rewrite a crowded health briefing slide":"Réécrire une diapositive surchargée sur la santé","This slide will be projected at the regional health delegation in Bafoussam. Rewrite it with a title that":"Cette diapositive sera projetée à la délégation régionale de la santé de Bafoussam. Réécrivez-la avec un titre qui","states the point":"énonce l'idée","no more than 4 bullets":"4 puces au maximum","of 10 words or fewer.":"de 10 mots au plus.","Try a title such as \"March campaign reached 92% of children under five\", then keep only coverage, the cold-chain problem and the funding request.":"Essayez un titre comme « La campagne de mars a touché 92 % des moins de cinq ans », puis gardez seulement la couverture, le problème de chaîne du froid et la demande de financement.","Editing shortcuts that save time":"Des raccourcis d'édition qui font gagner du temps","Insert a new slide":"Insérer une nouvelle diapositive","Duplicate the selected object or slide":"Dupliquer l'objet ou la diapositive sélectionnés","Group the selected objects":"Grouper les objets sélectionnés","Ungroup the selected group":"Dissocier le groupe sélectionné","Increase the font size":"Augmenter la taille de police","Decrease the font size":"Diminuer la taille de police","Centre the paragraph":"Centrer le paragraphe","Insert a hyperlink":"Insérer un lien hypertexte","Practise the PowerPoint editing shortcuts":"Entraînez-vous aux raccourcis d'édition de PowerPoint","Many meeting rooms in Yaoundé and Douala have bright windows and an old projector. Light grey text on white, or thin fonts, disappear on the wall. Before an important meeting, project one slide in the real room and read it from the last row.":"Beaucoup de salles de réunion à Yaoundé et à Douala ont de grandes fenêtres lumineuses et un vieux projecteur. Un texte gris clair sur fond blanc, ou une police fine, disparaît sur le mur. Avant une réunion importante, projetez une diapositive dans la vraie salle et lisez-la depuis le dernier rang.","Which title works best for a slide showing that complaints fell after a new call centre opened in Douala?":"Quel titre convient le mieux à une diapositive montrant que les réclamations ont baissé après l'ouverture d'un nouveau centre d'appels à Douala ?","Customer complaints":"Réclamations des clients","Complaints fell by 40% after the Douala call centre opened":"Les réclamations ont baissé de 40 % après l'ouverture du centre d'appels de Douala","Analysis of complaints data from January to June 2026 by region and type":"Analyse des données de réclamations de janvier à juin 2026 par région et par type","Slide 7":"Diapositive 7","A message title states the finding in a short sentence, so the audience knows what to look for before they read the chart. Topic titles and long descriptive titles leave the reader to guess.":"Un titre de message énonce le constat en une phrase courte : le public sait ce qu'il doit regarder avant de lire le graphique. Les titres de sujet et les longs titres descriptifs laissent le lecteur deviner.","Take a presentation you gave recently and rewrite every title as a sentence that states the point":"Reprenez une présentation que vous avez faite récemment et réécrivez chaque titre sous forme de phrase qui énonce l'idée","Split any slide that has more than five bullets into two slides":"Scindez en deux toute diapositive de plus de cinq puces","Set titles to at least 32 pt and body text to at least 24 pt":"Réglez les titres à 32 pt au moins et le corps du texte à 24 pt au moins","Align and group one row of icons with the Align and Distribute commands":"Alignez et groupez une rangée d'icônes avec les commandes Aligner et Distribuer","Add alt text to every picture and run Check Accessibility until it reports no errors":"Ajoutez un texte de remplacement à chaque image et lancez Vérifier l'accessibilité jusqu'à ce qu'il ne signale plus aucune erreur","Make your PowerPoint presentations accessible to people with disabilities":"Rendre vos présentations PowerPoint accessibles aux personnes en situation de handicap","Use keyboard shortcuts to create PowerPoint presentations":"Utiliser des raccourcis clavier pour créer des présentations PowerPoint","Edit the Slide Master and its layouts to change every slide at once":"Modifier le masque des diapositives et ses dispositions pour changer toutes les diapositives en une fois","Add a logo, footer and slide numbers once and apply theme colours and fonts":"Ajouter une seule fois le logo, le pied de page et les numéros de diapositive, et appliquer les couleurs et polices du thème","Save and apply a corporate template (.potx) and reset slides that ignore the master":"Enregistrer et appliquer un modèle d'entreprise (.potx) et rétablir les diapositives qui ignorent le masque","If you add your logo to 30 slides one by one, you will have 30 logos in slightly different places, and changing them later takes an afternoon. The":"Si vous ajoutez votre logo à 30 diapositives une par une, vous aurez 30 logos à des positions légèrement différentes, et les modifier plus tard vous prendra un après-midi. Le","Slide Master":"Masque des diapositives","holds the design of the whole presentation: fonts, colours, background, logo, footer and the position of every placeholder. Change it once and every slide follows.":"contient la conception de toute la présentation : polices, couleurs, arrière-plan, logo, pied de page et position de chaque espace réservé. Modifiez-le une fois et toutes les diapositives suivent.","What the Slide Master controls":"Ce que contrôle le masque des diapositives","Where you see it":"Où le voir","What a change affects":"Ce qu'une modification affecte","The large thumbnail at the top of the left pane in Slide Master view":"La grande miniature en haut du volet gauche, en mode Masque des diapositives","Every layout and every slide: fonts, colours, background, logo":"Toutes les dispositions et toutes les diapositives : polices, couleurs, arrière-plan, logo","The smaller thumbnails under the master":"Les miniatures plus petites sous le masque","Only the slides that use that layout, for example Title Slide or Two Content":"Seulement les diapositives qui utilisent cette disposition, par exemple Diapositive de titre ou Deux contenus","Slide":"Diapositive","Normal view":"Mode Normal","That slide only. Use it for content, not for design":"Cette diapositive uniquement. À utiliser pour le contenu, pas pour la conception","Master Views":"Modes Masque","Click Close Master View on the Slide Master tab to return to Normal view.":"Cliquez sur Désactiver le mode Masque, dans l'onglet Masque des diapositives, pour revenir au mode Normal.","Add the logo and footer once":"Ajouter le logo et le pied de page une seule fois","Put the logo on every slide":"Placer le logo sur toutes les diapositives","Open":"Ouvrez","View › Slide Master":"Affichage › Masque des diapositives","and click the large master thumbnail at the top.":"et cliquez sur la grande miniature du masque, tout en haut.","Insert › Pictures › This Device":"Insertion › Images › Cet appareil","and choose the logo file, ideally a PNG with a transparent background.":"et choisissez le fichier du logo, idéalement un PNG à fond transparent.","Resize it and move it to a corner, for example top right. It now appears on every layout.":"Redimensionnez-le et placez-le dans un coin, par exemple en haut à droite. Il apparaît maintenant sur toutes les dispositions.","If the logo must not appear on the title slide, click the":"Si le logo ne doit pas apparaître sur la diapositive de titre, cliquez sur la disposition","Title Slide":"Diapositive de titre","layout and tick":"et cochez","Hide Background Graphics":"Masquer les graphiques d'arrière-plan","on the Slide Master tab. (This also hides any other graphics from the master on that layout.)":"dans l'onglet Masque des diapositives. (Cela masque aussi les autres graphiques du masque sur cette disposition.)","Close Master View":"Désactiver le mode Masque","Tick Slide number and Footer, type the footer text, tick Don't show on title slide, then click Apply to All.":"Cochez Numéro de diapositive et Pied de page, tapez le texte du pied de page, cochez Ne pas afficher sur la diapositive de titre, puis cliquez sur Appliquer partout.","Footer text lives on the master":"Le texte du pied de page vit sur le masque","The Header & Footer box switches the footer on; the Slide Master decides where it sits and how it looks. To change the footer font or position, edit the footer placeholder on the master, not on individual slides.":"La boîte En-tête/Pied active le pied de page ; le masque des diapositives décide de sa position et de son apparence. Pour changer la police ou la position du pied de page, modifiez l'espace réservé du pied de page sur le masque, pas sur chaque diapositive.","Themes: colours and fonts":"Thèmes : couleurs et polices","theme":"thème","is a set of colours, fonts and effects. When you use theme colours (the top rows of any colour menu) instead of \"More Colors\", a change of theme recolours the whole deck, including charts and SmartArt.":"est un ensemble de couleurs, de polices et d'effets. Si vous utilisez les couleurs du thème (les premières lignes de tout menu de couleurs) au lieu de « Autres couleurs », un changement de thème recolore toute la présentation, y compris les graphiques et les SmartArt.","Variants":"Variantes","More":"Autres","Colors":"Couleurs","Customize Colors":"Personnaliser les couleurs","Enter your organisation's brand colours, for example from the logo, and give the set a name.":"Saisissez les couleurs de la charte de votre organisation, par exemple celles du logo, et donnez un nom à cet ensemble.","Fonts":"Polices","Customize Fonts":"Personnaliser les polices","Choose one heading font and one body font.":"Choisissez une police pour les titres et une police pour le corps du texte.","Use a corporate template (.potx)":"Utiliser un modèle d'entreprise (.potx)","Create the template once":"Créer le modèle une fois pour toutes","Build the master: logo, colours, fonts, footer and the layouts your organisation needs.":"Construisez le masque : logo, couleurs, polices, pied de page et dispositions dont votre organisation a besoin.","Delete the example slides, or keep one example slide per layout as a guide.":"Supprimez les diapositives d'exemple, ou gardez-en une par disposition comme guide.","File › Save As":"Fichier › Enregistrer sous","and choose PowerPoint Template (*.potx) as the file type.":"et choisissez Modèle PowerPoint (*.potx) comme type de fichier.","Share the .potx file with colleagues, for example in a shared OneDrive or SharePoint folder.":"Partagez le fichier .potx avec vos collègues, par exemple dans un dossier OneDrive ou SharePoint partagé.","Themes":"Thèmes","Browse for Themes":"Rechercher les thèmes","Choose the .potx file to apply its master to an existing presentation.":"Choisissez le fichier .potx pour appliquer son masque à une présentation existante.","Fix slides that ignore the master":"Corriger les diapositives qui ignorent le masque","Old slides often keep manual formatting: a title moved by hand, a different font typed over, or text in a text box instead of a placeholder. These slides do not follow the master.":"Les anciennes diapositives gardent souvent une mise en forme manuelle : un titre déplacé à la main, une autre police appliquée par-dessus, ou du texte dans une zone de texte au lieu d'un espace réservé. Ces diapositives ne suivent pas le masque.","Bring a slide back in line":"Remettre une diapositive en conformité","Select the slides in the thumbnail pane (":"Sélectionnez les diapositives dans le volet des miniatures (","in the pane selects them all).":"dans le volet les sélectionne toutes).","Home › Slides › Reset":"Accueil › Diapositives › Rétablir",". Placeholders return to the position and formatting of their layout; your text stays.":". Les espaces réservés reprennent la position et la mise en forme de leur disposition ; votre texte reste.","If a title is in a separate text box, cut the text, delete the box and paste the text into the title placeholder.":"Si un titre se trouve dans une zone de texte séparée, coupez le texte, supprimez la zone et collez le texte dans l'espace réservé du titre.","Check the layout with":"Vérifiez la disposition avec","Home › Slides › Layout":"Accueil › Diapositives › Disposition","and choose the right one if needed.":"et choisissez la bonne si nécessaire.","An NGO in Yaoundé receives slides from five project officers for its annual review with donors. The communications officer builds one .potx template with the NGO logo, colours and a bilingual footer (\"Rapport annuel 2026 / Annual Report 2026\"), applies it to every file with Browse for Themes, then runs Reset on the old slides. The final deck looks like one team made it.":"Une ONG de Yaoundé reçoit les diapositives de cinq chargés de projet pour sa revue annuelle avec les bailleurs. Le chargé de communication crée un seul modèle .potx avec le logo de l'ONG, ses couleurs et un pied de page bilingue (« Rapport annuel 2026 / Annual Report 2026 »), l'applique à chaque fichier avec Rechercher les thèmes, puis utilise Rétablir sur les anciennes diapositives. La présentation finale semble réalisée par une seule équipe.","Slide Master decisions":"Décisions sur le masque des diapositives","A cooperative in Bafoussam is preparing a template for all its presentations. Choose the right action for each request.":"Une coopérative de Bafoussam prépare un modèle pour toutes ses présentations. Choisissez la bonne action pour chaque demande.","Design that must be the same on every slide belongs on the Slide Master; things that affect one kind of slide belong on a layout; old slides are brought back with Reset.":"Ce qui doit être identique sur toutes les diapositives va sur le masque ; ce qui concerne un seul type de diapositive va sur une disposition ; les anciennes diapositives se remettent en conformité avec Rétablir.","The logo must appear in the top-right corner of every slide.":"Le logo doit apparaître en haut à droite de chaque diapositive.","Objects on the master appear on every layout, and therefore on every slide.":"Les objets du masque apparaissent sur toutes les dispositions, donc sur toutes les diapositives.","Insert it on each slide":"L'insérer sur chaque diapositive","Insert it on the Slide Master (top thumbnail)":"L'insérer sur le masque des diapositives (miniature du haut)","Insert it in the speaker notes":"L'insérer dans les notes du présentateur","Paste it in the footer text":"Le coller dans le texte du pied de page","Only section header slides need a dark green background.":"Seules les diapositives d'en-tête de section doivent avoir un fond vert foncé.","A change on one layout affects only the slides that use that layout.":"Une modification sur une disposition n'affecte que les diapositives qui utilisent cette disposition.","Change the Slide Master background":"Changer l'arrière-plan du masque des diapositives","Change the background of the Section Header layout":"Changer l'arrière-plan de la disposition En-tête de section","Apply a new theme":"Appliquer un nouveau thème","Change each slide in Normal view":"Modifier chaque diapositive en mode Normal","Slide numbers must appear on every slide except the title slide.":"Les numéros de diapositive doivent apparaître sur toutes les diapositives sauf la diapositive de titre.","Insert › Header & Footer, tick Slide number and Don't show on title slide, Apply to All":"Insertion › En-tête/Pied, cocher Numéro de diapositive et Ne pas afficher sur la diapositive de titre, Appliquer partout","Type the number in a text box on each slide":"Taper le numéro dans une zone de texte sur chaque diapositive","Home › Numbering":"Accueil › Numérotation","View › Notes Page":"Affichage › Page de notes","Colleagues must start every new presentation with this design.":"Les collègues doivent commencer chaque nouvelle présentation avec cette conception.","A .potx template opens as a new, untitled presentation, so nobody overwrites the original.":"Un modèle .potx s'ouvre comme une nouvelle présentation sans titre, donc personne n'écrase l'original.","Save as .pptx and ask them to copy slides":"Enregistrer en .pptx et leur demander de copier les diapositives","Save as PowerPoint Template (.potx) and share it":"Enregistrer comme Modèle PowerPoint (.potx) et le partager","Export as PDF":"Exporter en PDF","Save as PowerPoint Show (.ppsx)":"Enregistrer comme Diaporama PowerPoint (.ppsx)","Three old slides have titles in the wrong place and the wrong font.":"Trois anciennes diapositives ont des titres mal placés et dans la mauvaise police.","Reset returns placeholders to the layout's position and formatting without deleting the text.":"Rétablir remet les espaces réservés à la position et à la mise en forme de la disposition, sans supprimer le texte.","Delete and retype them":"Les supprimer et les retaper","Select them and use Home › Slides › Reset":"Les sélectionner et utiliser Accueil › Diapositives › Rétablir","Change the theme":"Changer le thème","Use Format Painter on each letter":"Utiliser Reproduire la mise en forme sur chaque lettre","What is the file extension of a PowerPoint template?":"Quelle est l'extension de fichier d'un modèle PowerPoint ?","You changed the title font on the Slide Master, but slide 4 still shows the old font. What is the most likely cause?":"Vous avez changé la police des titres sur le masque des diapositives, mais la diapositive 4 affiche encore l'ancienne police. Quelle est la cause la plus probable ?","The Slide Master only works after you save":"Le masque ne fonctionne qu'après l'enregistrement","Slide 4 has manual formatting that overrides the master":"La diapositive 4 a une mise en forme manuelle qui l'emporte sur le masque","The font is not installed on the projector":"La police n'est pas installée sur le projecteur","Slide Master changes apply only to new slides":"Les modifications du masque ne s'appliquent qu'aux nouvelles diapositives","Manual formatting on a slide wins over the master. Select the slide and use Home › Slides › Reset to remove it.":"La mise en forme manuelle d'une diapositive l'emporte sur le masque. Sélectionnez la diapositive et utilisez Accueil › Diapositives › Rétablir pour la supprimer.","Open View › Slide Master and add a logo to the master":"Ouvrez Affichage › Masque des diapositives et ajoutez un logo sur le masque","Hide the logo on the Title Slide layout with Hide Background Graphics":"Masquez le logo sur la disposition Diapositive de titre avec Masquer les graphiques d'arrière-plan","Create a custom colour set from your organisation's brand colours":"Créez un jeu de couleurs personnalisé à partir des couleurs de votre organisation","Add a footer and slide numbers that do not show on the title slide":"Ajoutez un pied de page et des numéros de diapositive qui ne s'affichent pas sur la diapositive de titre","Save the result as a .potx template and apply it to an older presentation, then Reset the slides":"Enregistrez le résultat comme modèle .potx, appliquez-le à une ancienne présentation, puis rétablissez les diapositives","What is a slide master?":"Qu'est-ce qu'un masque des diapositives ?","Exam MO-300: Microsoft PowerPoint":"Examen MO-300 : Microsoft PowerPoint","Choose, insert and edit the chart that matches the message":"Choisir, insérer et modifier le graphique qui correspond au message","Turn bullet lists into SmartArt and add icons, video and audio":"Transformer des listes à puces en SmartArt et ajouter des icônes, de la vidéo et de l'audio","Compress media and use animations and transitions sparingly":"Compresser les médias et utiliser les animations et transitions avec modération","Numbers and processes are easier to understand as pictures. A good chart shows one comparison; a SmartArt diagram shows steps or structure; a short video can replace a long explanation. Used badly, the same tools produce cluttered slides and heavy files that will not open on a colleague's laptop.":"Les chiffres et les processus se comprennent mieux en images. Un bon graphique montre une seule comparaison ; un diagramme SmartArt montre des étapes ou une structure ; une courte vidéo peut remplacer une longue explication. Mal utilisés, ces mêmes outils produisent des diapositives encombrées et des fichiers lourds qui ne s'ouvriront pas sur l'ordinateur d'un collègue.","Choose the chart from the message":"Choisir le graphique à partir du message","Chart to use":"Graphique à utiliser","Compare items":"Comparer des éléments","Bar or column chart":"Graphique à barres ou histogramme","Sales by branch: Douala, Yaoundé, Garoua":"Ventes par agence : Douala, Yaoundé, Garoua","Show change over time":"Montrer une évolution dans le temps","Monthly cocoa deliveries over 12 months":"Livraisons mensuelles de cacao sur 12 mois","Show parts of a whole (few parts)":"Montrer les parts d'un tout (peu de parts)","Share of the budget by item, 3 to 5 items":"Part du budget par poste, 3 à 5 postes","Show a relationship between two numbers":"Montrer une relation entre deux nombres","Scatter chart":"Nuage de points","Training hours and test scores":"Heures de formation et notes au test","Cocoa delivered to the cooperative, January to June 2026":"Cacao livré à la coopérative, de janvier à juin 2026","The manager wants to show whether deliveries are growing month after month. Which chart shows that best?":"Le gérant veut montrer si les livraisons augmentent d'un mois à l'autre. Quel graphique le montre le mieux ?","A line joins the months in order, so the rise and the dip in April are visible at once. A pie treats the months as parts of a whole and hides the order of time.":"Une courbe relie les mois dans l'ordre : la hausse et le creux d'avril se voient d'un coup d'œil. Un secteur traite les mois comme les parts d'un tout et cache l'ordre du temps.","Insert and edit a chart":"Insérer et modifier un graphique","Illustrations":"Illustrations","Chart":"Graphique","Or click the chart icon in a content placeholder.":"Ou cliquez sur l'icône de graphique dans un espace réservé de contenu.","From data to a clean chart":"Des données à un graphique épuré","Choose the chart type and click OK. A small Excel sheet opens with example data.":"Choisissez le type de graphique et cliquez sur OK. Une petite feuille Excel s'ouvre avec des données d'exemple.","Type or paste your data over the example. Drag the blue border so it covers only your rows and columns.":"Tapez ou collez vos données à la place de l'exemple. Faites glisser la bordure bleue pour qu'elle couvre uniquement vos lignes et colonnes.","Close the sheet. To change the numbers later, select the chart and go to":"Fermez la feuille. Pour changer les chiffres plus tard, sélectionnez le graphique et allez dans","Chart Design › Data › Edit Data":"Création de graphique › Données › Modifier les données","Chart Elements":"Éléments de graphique","(the + button next to the chart) to add data labels and remove what you do not need, such as gridlines.":"(le bouton + à côté du graphique) pour ajouter des étiquettes de données et retirer ce qui est inutile, comme le quadrillage.","Write the finding in the slide title, for example \"Deliveries rose 50% since January\".":"Écrivez le constat dans le titre de la diapositive, par exemple « Les livraisons ont augmenté de 50 % depuis janvier ».","Charts from Excel":"Graphiques venant d'Excel","If the chart already exists in Excel, copy it and paste it into PowerPoint. Use the paste options to choose whether it takes the presentation's theme and whether it stays linked to the workbook. Module 8 covers linking in detail.":"Si le graphique existe déjà dans Excel, copiez-le et collez-le dans PowerPoint. Les options de collage vous permettent de choisir s'il prend le thème de la présentation et s'il reste lié au classeur. Le module 8 traite les liaisons en détail.","Turn bullets into SmartArt":"Transformer des puces en SmartArt","Convert to SmartArt":"Convertir en graphique SmartArt","Select the text placeholder first. More SmartArt Graphics shows every type.":"Sélectionnez d'abord l'espace réservé du texte. Autres graphiques SmartArt affiche tous les types.","SmartArt type":"Type de SmartArt","Process":"Processus","Steps in order":"Des étapes dans l'ordre","Loan application: request, visit, committee, payment":"Demande de prêt : dépôt, visite, comité, décaissement","Cycle":"Cycle","Steps that repeat":"Des étapes qui se répètent","Plan, do, check, act":"Planifier, réaliser, vérifier, agir","Hierarchy":"Hiérarchie","Reporting lines":"Des liens hiérarchiques","Organisation chart of a directorate":"Organigramme d'une direction","List":"Liste","Items of equal weight":"Des éléments de même importance","Three services of an SME":"Trois services d'une PME","Overlap or balance":"Chevauchement ou équilibre","Where two programmes share beneficiaries":"Là où deux programmes partagent des bénéficiaires","Icons, video and audio":"Icônes, vidéo et audio","Icons":"Icônes","Icons are vector images: they stay sharp at any size and you can recolour them with theme colours.":"Les icônes sont des images vectorielles : elles restent nettes à toutes les tailles et vous pouvez les recolorer avec les couleurs du thème.","Media":"Média","Video":"Vidéo","This Device":"Cet appareil","Audio is on the same Media group: Insert › Media › Audio.":"L'audio se trouve dans le même groupe Média : Insertion › Média › Audio.","Keep the file light":"Garder un fichier léger","For pictures: select one, go to":"Pour les images : sélectionnez-en une, allez dans","Picture Format › Adjust › Compress Pictures":"Format de l'image › Ajuster › Compresser les images",", untick \"Apply only to this picture\" and choose a lower resolution, for example 150 ppi.":", décochez « Appliquer uniquement à cette image » et choisissez une résolution plus faible, par exemple 150 ppp.","For video and audio: go to":"Pour la vidéo et l'audio : allez dans","File › Info › Compress Media":"Fichier › Informations › Compresser le média","Standard (480p)":"Standard (480p)","for sharing or":"pour le partage ou","HD (720p)":"HD (720p)","for projecting.":"pour la projection.","Save, then check the new file size in File Explorer.":"Enregistrez, puis vérifiez la nouvelle taille du fichier dans l'Explorateur de fichiers.","Keep the original video files in a folder next to the presentation in case you need the full quality later.":"Conservez les vidéos d'origine dans un dossier à côté de la présentation, au cas où vous auriez besoin plus tard de la pleine qualité.","Animations and transitions, used sparingly":"Des animations et transitions avec modération","Effect":"Effet","Where to find it":"Où le trouver","Good use":"Bon usage","Appear or Fade (entrance)":"Apparaître ou Fondu (ouverture)","Animations › Animation":"Animations › Animation","Show bullets or chart parts one at a time as you talk about them":"Afficher les puces ou les parties d'un graphique une à une, au fil de votre discours","Fade (transition)":"Fondu (transition)","Transitions › Transition to This Slide":"Transitions › Accès à cette diapositive","A calm, consistent change between slides":"Un passage calme et homogène d'une diapositive à l'autre","Morph (transition)":"Morphose (transition)","Move or zoom an object smoothly from one slide to the next":"Déplacer ou agrandir un objet en douceur d'une diapositive à la suivante","Spin, Bounce, Flip":"Rotation, Rebondir, Retourner","Animations and Transitions":"Animations et Transitions","Rarely at work: they distract from the message":"Rarement au travail : ces effets détournent l'attention du message","Create a Morph effect":"Créer un effet Morphose","Build the first slide, for example a map of Cameroon with a small label.":"Construisez la première diapositive, par exemple une carte du Cameroun avec une petite étiquette.","Duplicate the slide with":"Dupliquez la diapositive avec","in the thumbnail pane.":"dans le volet des miniatures.","On the second slide, move, resize or recolour the same objects, for example enlarge the Littoral region.":"Sur la deuxième diapositive, déplacez, redimensionnez ou recolorez les mêmes objets, par exemple agrandissez la région du Littoral.","Select the second slide and choose":"Sélectionnez la deuxième diapositive et choisissez","Transitions › Morph":"Transitions › Morphose",". Play it with":". Visionnez l'effet avec","A 40 MB deck full of phone videos will not go through a ministry e-mail server and will stall on a slow connection in Garoua. Compress media before you send, share a OneDrive link instead of an attachment, and keep animations to Appear or Fade so the deck runs smoothly on an older laptop.":"Une présentation de 40 Mo pleine de vidéos de téléphone ne passera pas par le serveur de messagerie d'un ministère et bloquera sur une connexion lente à Garoua. Compressez les médias avant l'envoi, partagez un lien OneDrive plutôt qu'une pièce jointe, et limitez les animations à Apparaître ou Fondu pour que la présentation tourne sans à-coups sur un ordinateur ancien.","Choose the right visual and effect":"Choisir le bon visuel et le bon effet","You are preparing a presentation for a microfinance institution in Douala. Choose the best option for each slide.":"Vous préparez une présentation pour un établissement de microfinance à Douala. Choisissez la meilleure option pour chaque diapositive.","Match the visual to the message: comparison, time, parts of a whole, or steps. For effects, prefer the simplest one that helps the audience follow.":"Associez le visuel au message : comparaison, temps, parts d'un tout ou étapes. Pour les effets, préférez le plus simple qui aide le public à suivre.","Number of new accounts in each of four branches in 2026":"Nombre de nouveaux comptes dans chacune des quatre agences en 2026","Comparing separate items is a job for bars: they share one baseline.":"Comparer des éléments distincts, c'est le rôle des barres : elles partagent une même ligne de base.","Bar chart":"Graphique à barres","SmartArt Cycle":"SmartArt Cycle","The five steps of a loan application, from request to payment":"Les cinq étapes d'une demande de prêt, du dépôt au décaissement","A Process diagram shows steps in order with arrows.":"Un diagramme Processus montre des étapes dans l'ordre, avec des flèches.","SmartArt Process":"SmartArt Processus","SmartArt Hierarchy":"SmartArt Hiérarchie","A table of 5 columns":"Un tableau de 5 colonnes","You want the three bullet points to show one at a time as you speak.":"Vous voulez que les trois puces apparaissent une à une pendant que vous parlez.","Appear or Fade reveals each point without distracting from it.":"Apparaître ou Fondu révèle chaque point sans en détourner l'attention.","Bounce entrance animation":"Animation d'ouverture Rebondir","Appear or Fade entrance animation, On Click":"Animation d'ouverture Apparaître ou Fondu, Au clic","Vortex transition":"Transition Vortex","Rehearse Timings":"Vérification du minutage","The file is 65 MB because of two phone videos and must be e-mailed.":"Le fichier fait 65 Mo à cause de deux vidéos de téléphone et doit être envoyé par e-mail.","Compress Media re-encodes the videos at a lower quality and makes the file much smaller.":"Compresser le média réencode les vidéos à une qualité plus faible et rend le fichier beaucoup plus léger.","Save as .potx":"Enregistrer en .potx","Delete the Slide Master":"Supprimer le masque des diapositives","Home › Reset":"Accueil › Rétablir","A map should zoom smoothly into the Littoral region on the next slide.":"Une carte doit zoomer en douceur sur la région du Littoral à la diapositive suivante.","Morph animates the difference between two slides that share the same objects.":"Morphose anime la différence entre deux diapositives qui partagent les mêmes objets.","Morph transition":"Transition Morphose","Fly In animation on every region":"Animation Entrée brusque sur chaque région","Push transition":"Transition Pousser","Insert a video of a map":"Insérer une vidéo d'une carte","The share of a 12 000 000 FCFA budget spent on salaries, rent and equipment":"La part d'un budget de 12 000 000 FCFA consacrée aux salaires, au loyer et au matériel","Three parts of one whole is a good use of a pie or doughnut chart.":"Trois parts d'un même tout : c'est un bon usage du graphique en secteurs ou en anneau.","What must you do for the Morph transition to move a logo from the left of slide 5 to the right of slide 6?":"Que faut-il faire pour que la transition Morphose déplace un logo de la gauche de la diapositive 5 vers la droite de la diapositive 6 ?","Apply Morph to slide 5 and draw a motion path":"Appliquer Morphose à la diapositive 5 et tracer une trajectoire","Have the same logo on both slides, placed differently, and apply Morph to slide 6":"Avoir le même logo sur les deux diapositives, placé différemment, et appliquer Morphose à la diapositive 6","Insert the logo as a video":"Insérer le logo sous forme de vidéo","Apply the Fly In animation to both slides":"Appliquer l'animation Entrée brusque aux deux diapositives","Morph works on the slide you arrive on. It finds the objects shared by the two slides and animates their change of position, size or colour.":"Morphose s'applique à la diapositive d'arrivée. Elle repère les objets communs aux deux diapositives et anime leur changement de position, de taille ou de couleur.","Insert a column chart, replace the example data with sales for three branches and edit it with Edit Data":"Insérez un histogramme, remplacez les données d'exemple par les ventes de trois agences et modifiez-les avec Modifier les données","Change the slide title so it states what the chart shows":"Changez le titre de la diapositive pour qu'il énonce ce que montre le graphique","Convert a four-step bullet list into a SmartArt Process":"Convertissez une liste à puces de quatre étapes en SmartArt Processus","Insert an icon, recolour it with a theme colour and add alt text":"Insérez une icône, recolorez-la avec une couleur du thème et ajoutez un texte de remplacement","Insert a short video, compress the media and compare the file size before and after":"Insérez une courte vidéo, compressez le média et comparez la taille du fichier avant et après","Reduce the file size of a picture in Microsoft Office":"Réduire la taille d'une image dans Microsoft Office","Prepare speaker notes and rehearse with Presenter View and Rehearse Timings":"Préparer des notes du présentateur et répéter avec le mode Présentateur et la Vérification du minutage","Control a slide show with the keyboard and set up a projector correctly":"Piloter un diaporama au clavier et configurer correctement un projecteur","Export the presentation as PDF, video or handouts and share it for co-authoring":"Exporter la présentation en PDF, en vidéo ou en documents à distribuer, et la partager pour la coédition","Good slides do not save an unprepared speaker. Rehearsing with your notes, knowing the slide show keys, and arriving with a backup copy make the difference between a calm presentation and ten minutes lost to a cable, a frozen laptop or a power cut.":"De bonnes diapositives ne sauvent pas un orateur mal préparé. Répéter avec vos notes, connaître les touches du diaporama et arriver avec une copie de secours font la différence entre une présentation sereine et dix minutes perdues à cause d'un câble, d'un ordinateur bloqué ou d'une coupure de courant.","Speaker notes":"Notes du présentateur","Notes":"Notes","Or click Notes in the status bar. The notes pane opens under the slide.":"Ou cliquez sur Notes dans la barre d'état (Commentaires dans les anciennes versions). Le volet des notes s'ouvre sous la diapositive.","Write the details, figures and transitions you will say in the notes, not on the slide. Keep them short enough to read at a glance: key words and numbers, not a full speech.":"Écrivez dans les notes les détails, les chiffres et les enchaînements que vous direz, pas sur la diapositive. Gardez-les assez courtes pour être lues d'un coup d'œil : des mots clés et des chiffres, pas un discours complet.","Presenter View and the projector":"Le mode Présentateur et le projecteur","Presenter View shows you the current slide, the next slide, your notes and a timer on the laptop screen, while the audience sees only the slide on the projector. It needs two screens set to":"Le mode Présentateur vous montre, sur l'écran de l'ordinateur, la diapositive en cours, la suivante, vos notes et un chronomètre, tandis que le public ne voit que la diapositive au projecteur. Il faut deux écrans réglés sur","Extend":"Étendre",", not Duplicate.":", et non Dupliquer.","Connect a laptop to a projector":"Brancher un ordinateur portable à un projecteur","Connect the HDMI or VGA cable and switch on the projector before you start the slide show.":"Branchez le câble HDMI ou VGA et allumez le projecteur avant de lancer le diaporama.","In PowerPoint, go to":"Dans PowerPoint, allez dans","Slide Show › Monitors":"Diaporama › Moniteurs",", tick":", cochez","Use Presenter View":"Utiliser le mode Présentateur","and set the Monitor to the projector (or leave Automatic).":"et réglez le moniteur sur le projecteur (ou laissez Automatique).","Start the show with":"Lancez le diaporama avec",". If the screens are swapped, click":". Si les écrans sont inversés, cliquez sur","Display Settings › Swap Presenter View and Slide Show":"Paramètres d'affichage › Permuter le mode Présentateur et le diaporama","at the top of Presenter View.":"en haut du mode Présentateur.","Slide Show":"Diaporama","Monitors":"Moniteurs","Set Up":"Configuration","A Recording toolbar shows the time on the current slide and the total.":"Une barre d'outils Enregistrement affiche le temps passé sur la diapositive en cours et le temps total.","Go through the presentation as if the audience were there. At the end, PowerPoint shows the total time and asks whether to keep the timings. Keep them if the slides must advance on their own, for example on a stand at a trade fair; otherwise note the times and untick":"Déroulez la présentation comme si le public était là. À la fin, PowerPoint affiche la durée totale et demande s'il faut conserver le minutage. Conservez-le si les diapositives doivent défiler seules, par exemple sur un stand de foire commerciale ; sinon, notez les durées et décochez","Use Timings":"Utiliser le minutage","in the Set Up group so you advance slides yourself.":"dans le groupe Configuration pour avancer vous-même les diapositives.","Slide Show keys":"Les touches du diaporama","The slide show keys are single keys or work only during a show, so the browser trainer cannot capture them. Learn them from this table and try them in PowerPoint.":"Les touches du diaporama sont des touches seules ou ne fonctionnent que pendant un diaporama : l'entraîneur du navigateur ne peut donc pas les capter. Apprenez-les avec ce tableau et essayez-les dans PowerPoint.","Key":"Touche","What it does during a slide show":"Ce qu'elle fait pendant un diaporama","Start from the first slide":"Démarrer à la première diapositive","Shift + F5":"Maj + F5","Start from the current slide":"Démarrer à la diapositive en cours","Alt + F5":"Alt + F5","Start in Presenter View":"Démarrer en mode Présentateur","N, Space, Right arrow or Page Down":"N, Espace, Flèche droite ou Pg suiv","Next slide or next animation":"Diapositive ou animation suivante","P, Backspace, Left arrow or Page Up":"P, Retour arrière, Flèche gauche ou Pg préc","Previous slide or animation":"Diapositive ou animation précédente","Slide number + Enter":"Numéro de diapositive + Entrée","Jump to that slide, for example 12 + Enter":"Aller à cette diapositive, par exemple 12 + Entrée","B or full stop (.)":"B ou point (.)","Black screen; press again to return":"Écran noir ; appuyez de nouveau pour revenir","W or comma (,)":"W ou virgule (,)","White screen; press again to return":"Écran blanc ; appuyez de nouveau pour revenir","Ctrl + S":"Ctrl + S","Show the list of all slides":"Afficher la liste de toutes les diapositives","Laser pointer":"Pointeur laser","Ctrl + P / E":"Ctrl + P / E","Pen for drawing on the slide / erase the drawings":"Stylet pour dessiner sur la diapositive / effacer les dessins","End the slide show":"Terminer le diaporama","Use the black screen":"Utilisez l'écran noir","When the discussion moves away from the slides, press":"Quand la discussion s'éloigne des diapositives, appuyez sur",". The audience looks at you instead of an old slide. Press":". Le public vous regarde au lieu d'une ancienne diapositive. Appuyez de nouveau sur","again to continue exactly where you were.":"pour reprendre exactement là où vous étiez.","Export, handouts and sharing":"Exporter, imprimer des documents et partager","PDF":"PDF","File › Export › Create PDF/XPS Document":"Fichier › Exporter › Créer un document PDF/XPS","Sending the final deck to participants, or as a backup to project from any computer":"Envoyer la présentation finale aux participants, ou garder une copie de secours à projeter depuis n'importe quel ordinateur","Video (.mp4)":"Vidéo (.mp4)","File › Export › Create a Video":"Fichier › Exporter › Créer une vidéo","Playing on a screen at a stand, or sharing on WhatsApp or a website":"Diffuser sur un écran de stand, ou partager sur WhatsApp ou un site web","Printed handouts":"Documents imprimés","File › Print › Full Page Slides › Handouts":"Fichier › Imprimer › Diapositives pleine page › Documents","Participants take notes; 3 slides per page leaves lines for writing":"Les participants prennent des notes ; 3 diapositives par page laissent des lignes pour écrire","Shared link":"Lien partagé","Share (top right)":"Partager (en haut à droite)","Colleagues edit the same deck at the same time (co-authoring)":"Des collègues modifient la même présentation en même temps (coédition)","Print":"Imprimer","Full Page Slides":"Diapositives pleine page","3 Slides":"3 diapositives","Choose Handouts, 3 Slides to print lines for notes beside each slide.":"Choisissez Documents, 3 diapositives pour imprimer des lignes de notes à côté de chaque diapositive.","To co-author, save the presentation to OneDrive or SharePoint, click":"Pour coéditer, enregistrez la présentation dans OneDrive ou SharePoint, cliquez sur","and invite colleagues with edit rights. Each person can work on different slides at the same time, and their initials appear on the slide they are editing.":"et invitez des collègues avec le droit de modifier. Chacun peut travailler sur des diapositives différentes en même temps, et ses initiales apparaissent sur la diapositive qu'il modifie.","Plan for a power cut":"Prévoir une coupure de courant","Power cuts and unfamiliar computers are part of presenting in Cameroon. Charge the laptop fully, bring your own HDMI adapter, and keep a PDF copy of the deck on a USB drive and in your e-mail. If the laptop fails, the PDF opens on any computer, and printed handouts let you continue even without a projector.":"Les coupures de courant et les ordinateurs inconnus font partie des présentations au Cameroun. Chargez complètement l'ordinateur, apportez votre propre adaptateur HDMI, et gardez une copie PDF de la présentation sur une clé USB et dans votre messagerie. Si l'ordinateur tombe en panne, le PDF s'ouvre sur n'importe quel ordinateur, et les documents imprimés vous permettent de continuer même sans projecteur.","Tighten a closing slide":"Resserrer une diapositive de conclusion","This is the last slide of a budget presentation to the municipal council in Garoua. Rewrite it with a title of 8 words or fewer that":"C'est la dernière diapositive d'une présentation du budget au conseil municipal de Garoua. Réécrivez-la avec un titre de 8 mots au plus qui","states the decision you ask for":"énonce la décision que vous demandez",", and":", et","of 8 words or fewer.":"de 8 mots au plus.","Start from the request: for example \"Please approve the 2027 budget in December\". Then keep the total, the main increase and the new revenue.":"Partez de la demande : par exemple « Merci d'adopter le budget 2027 en décembre ». Gardez ensuite le total, la principale hausse et la nouvelle recette.","Delivery decisions":"Décisions pour la présentation","You present a training report at a hotel in Yaoundé. Answer each question. Type keys as they appear on the keyboard, for example F5 or Shift + F5.":"Vous présentez un rapport de formation dans un hôtel de Yaoundé. Répondez à chaque question. Tapez les touches comme elles figurent sur le clavier, par exemple F5 ou Maj + F5.","Look again at the slide show keys table and at the export options.":"Revoyez le tableau des touches du diaporama et les options d'exportation.","Which key starts the slide show from the current slide?":"Quelle touche lance le diaporama à partir de la diapositive en cours ?","A participant asks a question and you want the screen to go black. Which key do you press?":"Un participant pose une question et vous voulez que l'écran devienne noir. Sur quelle touche appuyez-vous ?","You want to jump straight to slide 14. What do you type?":"Vous voulez aller directement à la diapositive 14. Que tapez-vous ?","The projector shows exactly what is on your laptop, including your notes. What must you change?":"Le projecteur montre exactement ce qu'il y a sur votre ordinateur, y compris vos notes. Que devez-vous changer ?","With Duplicate, both screens show the same image. Extend gives the projector its own screen, so Presenter View stays on the laptop.":"Avec Dupliquer, les deux écrans affichent la même image. Étendre donne au projecteur son propre écran, et le mode Présentateur reste sur l'ordinateur.","Win + P › Extend":"Win + P › Étendre","Win + P › Duplicate":"Win + P › Dupliquer","Turn off Presenter View":"Désactiver le mode Présentateur","Lower the screen resolution":"Baisser la résolution de l'écran","The organisers want a copy that anyone can open without PowerPoint and that will not change.":"Les organisateurs veulent une copie que tout le monde peut ouvrir sans PowerPoint et qui ne changera pas.","Send the .pptx":"Envoyer le .pptx","Share an editing link":"Partager un lien de modification","You want to know how long each slide takes before the real session.":"Vous voulez savoir combien de temps prend chaque diapositive avant la vraie séance.","Rehearse Timings records the time on each slide and the total.":"Vérification du minutage enregistre le temps passé sur chaque diapositive et le total.","Slide Show › Set Up › Rehearse Timings":"Diaporama › Configuration › Vérification du minutage","Transitions › Duration":"Transitions › Durée","The electricity goes off ten minutes before your presentation and the venue computer restarts without PowerPoint. What prepared backup lets you continue fastest?":"Le courant est coupé dix minutes avant votre présentation et l'ordinateur de la salle redémarre sans PowerPoint. Quelle copie de secours préparée vous permet de continuer le plus vite ?","The .potx template on your laptop":"Le modèle .potx sur votre ordinateur","A PDF copy of the deck on a USB drive":"Une copie PDF de la présentation sur une clé USB","The speaker notes in your head":"Les notes du présentateur dans votre tête","A link to the presentation on OneDrive with no internet":"Un lien vers la présentation sur OneDrive, sans Internet","A PDF opens on almost any computer, even without PowerPoint or an internet connection, and keeps the layout exactly.":"Un PDF s'ouvre sur presque tous les ordinateurs, même sans PowerPoint ni connexion Internet, et conserve exactement la mise en page.","Write speaker notes of key words for every slide of a five-slide presentation":"Rédigez des notes du présentateur en mots clés pour chaque diapositive d'une présentation de cinq diapositives","Run Rehearse Timings and note the total time":"Lancez la Vérification du minutage et notez la durée totale","Connect to a second screen or projector, choose Extend and present in Presenter View":"Branchez un second écran ou un projecteur, choisissez Étendre et présentez en mode Présentateur","During the show, use B, a slide number + Enter and Esc":"Pendant le diaporama, utilisez B, un numéro de diapositive + Entrée et Échap","Export a PDF copy to a USB drive and print handouts with 3 slides per page":"Exportez une copie PDF sur une clé USB et imprimez des documents à 3 diapositives par page","Use keyboard shortcuts to deliver PowerPoint presentations":"Utiliser des raccourcis clavier pour faire des présentations PowerPoint","Practice lab: professional presentations":"Atelier pratique : présentations professionnelles","Apply the rules of clear, accessible slides":"Appliquer les règles de diapositives claires et accessibles","Choose charts, SmartArt and media for a donor report":"Choisir graphiques, SmartArt et médias pour un rapport aux bailleurs","Fix branding and effects with the Slide Master, Reset and transitions":"Corriger l'identité visuelle et les effets avec le masque des diapositives, Rétablir et les transitions","Plan a conference talk from rehearsal timings":"Planifier une conférence à partir du minutage des répétitions","Exercise 1: A ministry briefing":"Exercice 1 : un exposé pour un ministère","Check the slides of a ministry briefing":"Vérifier les diapositives d'un exposé ministériel","A directorate of a ministry in Yaoundé prepares a 10-minute briefing for the Minister's cabinet. Choose the best answer for each question about slide design.":"Une direction d'un ministère à Yaoundé prépare un exposé de 10 minutes pour le cabinet du Ministre. Choisissez la meilleure réponse à chaque question sur la conception des diapositives.","One message per slide, a title that states the point, short bullets, large text, strong contrast and alt text on every picture.":"Un message par diapositive, un titre qui énonce l'idée, des puces courtes, un texte grand, un contraste fort et un texte de remplacement sur chaque image.","Which title is best for the slide on school enrolment?":"Quel titre convient le mieux à la diapositive sur la scolarisation ?","A message title states the finding in one short sentence.":"Un titre de message énonce le constat en une phrase courte.","Enrolment":"Scolarisation","Enrolment statistics 2021–2026 by region, gender and level":"Statistiques de scolarisation 2021–2026 par région, sexe et niveau","Girls' enrolment rose 9% in the Far North since 2021":"La scolarisation des filles a augmenté de 9 % dans l'Extrême-Nord depuis 2021","Slide 3: data":"Diapositive 3 : données","A slide has nine bullets of about twenty words each. What do you do?":"Une diapositive contient neuf puces d'une vingtaine de mots chacune. Que faites-vous ?","Reduce the font to 14 pt so it fits":"Réduire la police à 14 pt pour que tout tienne","Keep key words, move details to the notes and split it into two slides":"Garder les mots clés, déplacer les détails dans les notes et la scinder en deux diapositives","Add an animation to each bullet":"Ajouter une animation à chaque puce","Change the background to black":"Passer l'arrière-plan en noir","What is the smallest body text size you should use on a projected slide?":"Quelle est la plus petite taille de texte à utiliser sur une diapositive projetée ?","Aim for 24 pt or more; 18 pt is the minimum for text read from the back of the room.":"Visez 24 pt ou plus ; 18 pt est le minimum pour un texte lu depuis le fond de la salle.","10 pt":"10 pt","14 pt":"14 pt","18 pt":"18 pt","40 pt":"40 pt","Which colour combination reads best on an old projector?":"Quelle combinaison de couleurs se lit le mieux avec un vieux projecteur ?","Light grey text on white":"Texte gris clair sur blanc","Dark blue text on white":"Texte bleu foncé sur blanc","Red text on green":"Texte rouge sur vert","Yellow text on a photo":"Texte jaune sur une photo","A colleague who uses a screen reader will receive the deck. What must every photo have?":"Un collègue qui utilise un lecteur d'écran recevra la présentation. Que doit avoir chaque photo ?","Alt text lets the screen reader describe the picture. Use Review › Check Accessibility to find pictures without it.":"Le texte de remplacement permet au lecteur d'écran de décrire l'image. Utilisez Révision › Vérifier l'accessibilité pour trouver les images qui n'en ont pas.","A border":"Une bordure","Alt text":"Un texte de remplacement","An animation":"Une animation","A caption in bold":"Une légende en gras","Four logos of partner institutions are placed unevenly across the slide. Which tool fixes the gaps?":"Quatre logos d'institutions partenaires sont répartis de façon irrégulière sur la diapositive. Quel outil corrige les espacements ?","Arrange › Align › Distribute Horizontally":"Organiser › Aligner › Distribuer horizontalement","Designer only":"Le Concepteur seul","Crop":"Rogner","Exercise 2: An NGO donor report":"Exercice 2 : un rapport pour un bailleur d'ONG","Visuals for a donor report":"Des visuels pour un rapport aux bailleurs","An NGO working on clean water in the Adamaoua region reports to its donor. Choose the right visual or command for each slide, and type the menu paths where asked, with › or > between the parts.":"Une ONG qui travaille sur l'eau potable dans la région de l'Adamaoua rend compte à son bailleur. Choisissez le bon visuel ou la bonne commande pour chaque diapositive, et tapez les chemins de menu demandés, avec › ou > entre les parties.","Comparison: bars. Time: line. Parts of one whole: pie. Steps: SmartArt Process. Reporting lines: SmartArt Hierarchy. Heavy files: Compress Media.":"Comparaison : barres. Temps : courbe. Parts d'un tout : secteurs. Étapes : SmartArt Processus. Liens hiérarchiques : SmartArt Hiérarchie. Fichiers lourds : Compresser le média.","Boreholes drilled in each of five villages":"Forages réalisés dans chacun des cinq villages","Litres of water distributed per month over two years":"Litres d'eau distribués par mois sur deux ans","SmartArt List":"SmartArt Liste","How the 45 000 000 FCFA grant was split between drilling, training and monitoring":"La répartition de la subvention de 45 000 000 FCFA entre forage, formation et suivi","Three parts that add up to one grant: a pie or doughnut works well.":"Trois parts qui forment une seule subvention : un secteur ou un anneau convient bien.","The project team: coordinator, two engineers, four community officers":"L'équipe du projet : un coordonnateur, deux ingénieurs, quatre agents communautaires","A bulleted list of 7 items":"Une liste à puces de 7 éléments","Which menu path turns a selected bullet list into a SmartArt diagram? (tab › group › command)":"Quel chemin de menu transforme une liste à puces sélectionnée en diagramme SmartArt ? (onglet › groupe › commande)","Select the text placeholder first; the gallery previews each layout.":"Sélectionnez d'abord l'espace réservé du texte ; la galerie donne un aperçu de chaque disposition.","The deck with three field videos is 80 MB. Which menu path makes the videos smaller? (tab › section › command)":"La présentation avec trois vidéos de terrain fait 80 Mo. Quel chemin de menu réduit les vidéos ? (onglet › section › commande)","Choose Standard (480p) for sharing by e-mail, HD (720p) for projecting.":"Choisissez Standard (480p) pour l'envoi par e-mail, HD (720p) pour la projection.","After inserting a chart, the donor's figures change. Where do you update them?":"Après l'insertion d'un graphique, les chiffres du bailleur changent. Où les mettez-vous à jour ?","Delete and redraw the chart":"Supprimer et redessiner le graphique","Insert › Table":"Insertion › Tableau","Exercise 3: A sales pitch that must look on-brand":"Exercice 3 : un argumentaire commercial conforme à la charte","Fix the branding and effects of a sales pitch":"Corriger l'identité visuelle et les effets d'un argumentaire commercial","Kemba Solar SARL, an SME in Bafoussam that sells solar backup kits, merged slides from three salespeople into one pitch. Solve each problem with the most efficient method. Type shortcuts as keys joined with +.":"Kemba Solar SARL, une PME de Bafoussam qui vend des kits solaires de secours, a fusionné en un seul argumentaire les diapositives de trois commerciaux. Réglez chaque problème par la méthode la plus efficace. Tapez les raccourcis sous forme de touches reliées par +.","Think at the right level: master for every slide, layout for one kind of slide, Reset for slides with manual formatting. Keep effects simple, and remember that Morph goes on the second slide.":"Pensez au bon niveau : le masque pour toutes les diapositives, une disposition pour un type de diapositive, Rétablir pour les diapositives mises en forme à la main. Gardez des effets simples, et rappelez-vous que Morphose se place sur la deuxième diapositive.","The logo is on some slides only and in different positions.":"Le logo n'est que sur certaines diapositives, et à des positions différentes.","One logo on the master appears in the same place on every slide.":"Un seul logo sur le masque apparaît au même endroit sur toutes les diapositives.","Copy it to each slide and align it by eye":"Le copier sur chaque diapositive et l'aligner à l'œil","Delete the copies and put one logo on the Slide Master":"Supprimer les copies et placer un seul logo sur le masque des diapositives","Put it in the footer text":"Le mettre dans le texte du pied de page","Add it with Designer":"L'ajouter avec le Concepteur","After you apply the company template, six slides still show Times New Roman titles.":"Après l'application du modèle de l'entreprise, six diapositives affichent encore des titres en Times New Roman.","The titles carry manual formatting. Reset brings them back to the layout's font and position.":"Les titres portent une mise en forme manuelle. Rétablir leur rend la police et la position de la disposition.","Select those slides and click Home › Slides › Reset":"Sélectionner ces diapositives et cliquer sur Accueil › Diapositives › Rétablir","Change the theme again":"Changer encore de thème","Retype the titles":"Retaper les titres","One salesperson typed the titles in text boxes instead of title placeholders. What problem does that cause?":"Un commercial a tapé les titres dans des zones de texte au lieu des espaces réservés de titre. Quel problème cela pose-t-il ?","The titles do not follow the master and are missing for screen readers and the Outline view":"Les titres ne suivent pas le masque et sont absents pour les lecteurs d'écran et le mode Plan","The file cannot be saved":"Le fichier ne peut pas être enregistré","The slides cannot be printed":"Les diapositives ne peuvent pas être imprimées","Every slide flies in with a different transition: Vortex, Curtains, Origami.":"Chaque diapositive arrive avec une transition différente : Vortex, Rideaux, Origami.","One calm transition used everywhere looks professional and does not distract from the offer.":"Une seule transition calme, utilisée partout, fait professionnel et ne détourne pas l'attention de l'offre.","Keep them, they impress clients":"Les garder, elles impressionnent les clients","Select all slides and apply Fade, then Apply To All":"Sélectionner toutes les diapositives, appliquer Fondu, puis Appliquer partout","Remove the slides":"Supprimer les diapositives","Add sounds to them":"Leur ajouter des sons","You want the kit photo to grow and slide to the right between slides 4 and 5. Which slide gets the Morph transition?":"Vous voulez que la photo du kit grossisse et glisse vers la droite entre les diapositives 4 et 5. Quelle diapositive reçoit la transition Morphose ?","A transition belongs to the slide you arrive on.":"Une transition appartient à la diapositive d'arrivée.","Slide 4":"Diapositive 4","Slide 5":"Diapositive 5","Both":"Les deux","Neither: use a motion path":"Aucune : utiliser une trajectoire","Which shortcut duplicates the selected slide in the thumbnail pane, so you can build the Morph pair?":"Quel raccourci duplique la diapositive sélectionnée dans le volet des miniatures, pour construire la paire Morphose ?","Which shortcut groups the selected kit icons so they move together?":"Quel raccourci groupe les icônes de kits sélectionnées pour qu'elles se déplacent ensemble ?","Management wants every future pitch to start from this corrected design. How do you save it?":"La direction veut que chaque futur argumentaire parte de cette conception corrigée. Comment l'enregistrez-vous ?","PowerPoint Presentation (.pptx)":"Présentation PowerPoint (.pptx)","PowerPoint Template (.potx)":"Modèle PowerPoint (.potx)","PowerPoint Show (.ppsx)":"Diaporama PowerPoint (.ppsx)","Exercise 4: Timing a conference talk":"Exercice 4 : minuter une conférence","Plan a 25-minute conference talk from rehearsal timings":"Planifier une conférence de 25 minutes à partir du minutage des répétitions","You rehearsed a 25-minute talk for a business conference in Douala with Rehearse Timings. Column D holds the seconds recorded for each section; one section was not rehearsed yet. In":"Vous avez répété avec Vérification du minutage une intervention de 25 minutes pour une conférence d'affaires à Douala. La colonne D contient les secondes enregistrées pour chaque section ; une section n'a pas encore été répétée. En",", convert seconds to minutes rounded to 1 decimal, but show the text":", convertissez les secondes en minutes arrondies à 1 décimale, mais affichez le texte","when D is empty. In":"quand D est vide. En",", show":", affichez","if D is empty,":"si D est vide,","if the rehearsed minutes are more than the planned minutes (column C), otherwise":"si les minutes répétées dépassent les minutes prévues (colonne C), sinon",", total the rehearsed minutes. In":", totalisez les minutes répétées. En",", count the sections marked":", comptez les sections marquées",", estimate the length of the talk: rehearsed minutes plus the planned minutes of sections marked":", estimez la durée de l'intervention : minutes répétées plus minutes prévues des sections marquées","if B11 is greater than the slot in B9, otherwise":"si B11 est supérieur au créneau en B9, sinon","E2: =IF(D2=\"\",\"Not rehearsed\",ROUND(D2/60,1)). G2 tests the empty cell first, then compares E2 with C2. SUM ignores text, so E8 is a plain SUM. B11 adds a SUMIF on column G.":"E2 : =IF(D2=\"\",\"Not rehearsed\",ROUND(D2/60,1)) (SI et ARRONDI en français). G2 teste d'abord la cellule vide, puis compare E2 à C2. SUM (SOMME) ignore le texte, donc E8 est une simple somme. B11 ajoute un SUMIF (SOMME.SI) sur la colonne G.","Module 6 Quiz":"Quiz du module 6","Which slide title follows the \"one message\" rule?":"Quel titre de diapositive respecte la règle « un seul message » ?","Quarterly results":"Résultats trimestriels","Q3 revenue beat the target by 8%":"Le chiffre d'affaires du T3 a dépassé l'objectif de 8 %","Results, analysis, comments and next steps":"Résultats, analyse, commentaires et prochaines étapes","A message title states the point in a short sentence. The others only name a topic.":"Un titre de message énonce l'idée en une phrase courte. Les autres ne font que nommer un sujet.","Where do you add a logo so that it appears on every slide?":"Où ajouter un logo pour qu'il apparaisse sur toutes les diapositives ?","Design › Designer":"Création › Concepteur","On each slide in Normal view":"Sur chaque diapositive en mode Normal","On the Slide Master in View › Slide Master":"Sur le masque, dans Affichage › Masque des diapositives","Objects placed on the master appear on every layout, so on every slide.":"Les objets placés sur le masque apparaissent sur toutes les dispositions, donc sur toutes les diapositives.","Which command brings a slide's placeholders back to the position and formatting of its layout?":"Quelle commande remet les espaces réservés d'une diapositive à la position et à la mise en forme de sa disposition ?","Design › Format Background":"Création › Mettre en forme l'arrière-plan","Review › Compare":"Révision › Comparer","Reset removes manual formatting from placeholders but keeps your text.":"Rétablir supprime la mise en forme manuelle des espaces réservés mais garde votre texte.","Which file type is a PowerPoint template?":"Quel type de fichier est un modèle PowerPoint ?",".pptx":".pptx",".ppsx":".ppsx",".potx":".potx","A .potx opens as a new untitled presentation built on the template's master.":"Un .potx s'ouvre comme une nouvelle présentation sans titre, construite sur le masque du modèle.","Which chart best shows monthly sales over a year?":"Quel graphique montre le mieux les ventes mensuelles sur une année ?","A line shows the order of time and the trend between months.":"Une courbe montre l'ordre du temps et la tendance d'un mois à l'autre.","During a slide show, what does pressing B do?":"Pendant un diaporama, que fait la touche B ?","Shows a black screen until you press B again":"Elle affiche un écran noir jusqu'à ce que vous appuyiez de nouveau sur B","Goes back one slide":"Elle revient d'une diapositive","Makes the text bold":"Elle met le texte en gras","Opens the list of slides":"Elle ouvre la liste des diapositives","B (or the full stop) blacks out the screen so the audience focuses on you; press it again to return.":"B (ou le point) noircit l'écran pour que le public se concentre sur vous ; appuyez de nouveau pour revenir.","Presenter View is not showing on your laptop: the projector shows the same image. What is the fix?":"Le mode Présentateur ne s'affiche pas sur votre ordinateur : le projecteur montre la même image. Quelle est la solution ?","Press Ctrl + M":"Appuyer sur Ctrl + M","Choose Duplicate with Win + P":"Choisir Dupliquer avec Win + P","Choose Extend with Win + P":"Choisir Étendre avec Win + P","Presenter View needs two separate screens, which is what Extend provides.":"Le mode Présentateur a besoin de deux écrans distincts, ce que fournit Étendre.","Which is the best backup against a power cut or a venue computer without PowerPoint?":"Quelle est la meilleure copie de secours contre une coupure de courant ou un ordinateur de salle sans PowerPoint ?","A .potx template":"Un modèle .potx","A PDF copy on a USB drive":"Une copie PDF sur une clé USB","The Rehearse Timings file":"Le fichier de Vérification du minutage","A higher-resolution video":"Une vidéo en plus haute résolution","A PDF opens on almost any computer and keeps the exact layout of your slides.":"Un PDF s'ouvre sur presque tous les ordinateurs et conserve exactement la mise en page de vos diapositives.","Professional e-mail: write, address and send with care":"E-mail professionnel : rédiger, adresser et envoyer avec soin","Address messages correctly with To, Cc and Bcc, and protect recipients' privacy":"Adresser correctement les messages avec À, Cc et Cci, et protéger la confidentialité des destinataires","Structure an e-mail so the reader sees the purpose, the action and the deadline at once":"Structurer un e-mail pour que le lecteur voie d'emblée l'objet, l'action attendue et l'échéance","Use replies, forwarding, signatures, delayed delivery and recall with their limits in mind":"Utiliser les réponses, le transfert, les signatures, la remise différée et le rappel en connaissant leurs limites","E-mail is still the official channel of most offices: requests, approvals, invoices and invitations travel through it, and messages are kept as records. A clear, well-addressed e-mail gets a faster answer and protects you if a decision is questioned later.":"L'e-mail reste le canal officiel de la plupart des bureaux : demandes, validations, factures et invitations y circulent, et les messages sont conservés comme pièces. Un e-mail clair et bien adressé obtient une réponse plus rapide et vous protège si une décision est contestée plus tard.","Classic Outlook and new Outlook":"Outlook classique et nouvel Outlook","Microsoft is moving Windows users from classic Outlook to new Outlook, which looks like Outlook on the web. The features in this module exist in both, but some menu names and positions differ. The paths shown here are for classic Outlook; if you see a Settings gear instead of a File tab, you are in new Outlook.":"Microsoft fait passer les utilisateurs de Windows d'Outlook classique au nouvel Outlook, qui ressemble à Outlook sur le web. Les fonctionnalités de ce module existent dans les deux, mais certains noms et emplacements de menus diffèrent. Les chemins indiqués ici sont ceux d'Outlook classique ; si vous voyez une roue dentée Paramètres au lieu d'un onglet Fichier, vous êtes dans le nouvel Outlook.","To, Cc and Bcc":"À, Cc et Cci","Field":"Champ","Who goes there":"Qui y figure","What it tells the reader":"Ce que cela dit au lecteur","To":"À","The people who must act or answer":"Les personnes qui doivent agir ou répondre","\"This is for you, I am waiting for your reply.\"":"« C'est pour vous, j'attends votre réponse. »","Cc":"Cc","People who need to be informed, such as your manager":"Les personnes à informer, par exemple votre responsable","\"For information, no action expected.\"":"« Pour information, aucune action attendue. »","Bcc":"Cci","Recipients who must not see each other's addresses":"Les destinataires qui ne doivent pas voir les adresses des autres","Nobody sees the Bcc list. Use it for group mailings to people outside your organisation":"Personne ne voit la liste Cci. Utilisez-la pour les envois groupés à des personnes extérieures à votre organisation","Options":"Options","Show Fields":"Afficher les champs","In a new message window. The Bcc line then stays visible for future messages.":"Dans la fenêtre d'un nouveau message. La ligne Cci reste ensuite visible pour les messages suivants.","Group mails and privacy":"Envois groupés et confidentialité","Sending one message to 150 clients with all addresses in To or Cc exposes everyone's address to everyone, and invites endless Reply All chains. Put your own address in To and the recipients in Bcc, or use a mail merge. Bcc recipients are never included when someone clicks Reply All.":"Envoyer un message à 150 clients avec toutes les adresses dans À ou Cc expose l'adresse de chacun à tous et déclenche des chaînes interminables de « Répondre à tous ». Mettez votre propre adresse dans À et les destinataires dans Cci, ou utilisez un publipostage. Les destinataires en Cci ne sont jamais inclus quand quelqu'un clique sur Répondre à tous.","A structure the reader can scan":"Une structure que le lecteur peut parcourir","Subject line":"Objet",": topic, action and date, for example \"Q3 report Garoua branch: figures needed by Fri 16 Oct\".":": sujet, action et date, par exemple « Rapport T3 agence de Garoua : chiffres attendus pour le ven. 16 oct. ».","Greeting":"Formule d'appel",": \"Dear Mrs Mballa,\" for a first contact; \"Hello Paul,\" with colleagues you know.":": « Madame Mballa, » pour un premier contact ; « Bonjour Paul, » avec les collègues que vous connaissez.","Purpose first":"L'objet d'abord",": one sentence saying why you write.":": une phrase qui dit pourquoi vous écrivez.","Action and deadline":"Action et échéance",": what you need, from whom, by when. Bold the deadline.":": ce dont vous avez besoin, de qui, pour quand. Mettez l'échéance en gras.","Details":"Détails",": short paragraphs or a bulleted list. Attach or link the files you mention.":": paragraphes courts ou liste à puces. Joignez ou liez les fichiers que vous mentionnez.","Closing and signature":"Formule de politesse et signature",": name, title, organisation, phone number.":": nom, fonction, organisation, numéro de téléphone.","Weak subject":"Objet faible","Clear subject":"Objet clair","Urgent!!!":"Urgent !!!","Mission order Kribi: signature needed today before 15:00":"Ordre de mission Kribi : signature nécessaire aujourd'hui avant 15:00","Document":"Document","Draft MoU with CAMWATER, v2 for your comments by 20 Oct":"Projet de protocole d'accord avec la CAMWATER, v2 pour vos commentaires avant le 20 oct.","RE: RE: RE: question":"RE: RE: RE: question","Training room booking 5 Nov: confirmed":"Réservation de la salle de formation le 5 nov. : confirmée","(no subject)":"(sans objet)","Invoice AE-2026-118, 350 000 FCFA: payment reminder":"Facture AE-2026-118, 350 000 FCFA : relance de paiement","Format an e-mail body":"Mettre en forme le corps d'un e-mail","This e-mail asks four branch heads for their monthly figures. Make the deadline sentence":"Cet e-mail demande à quatre chefs d'agence leurs chiffres du mois. Mettez la phrase de l'échéance en",", turn the three items to send into a":", transformez les trois éléments à envoyer en",", and make the name of the shared folder":", et mettez le nom du dossier partagé en","Select the whole deadline sentence and click Bold. Select the three item lines together before clicking Bullets.":"Sélectionnez toute la phrase de l'échéance et cliquez sur Gras. Sélectionnez ensemble les trois lignes d'éléments avant de cliquer sur Puces.","Attachments or OneDrive links?":"Pièce jointe ou lien OneDrive ?","Send an attachment when…":"Envoyez une pièce jointe quand…","Share a OneDrive link when…":"Partagez un lien OneDrive quand…","The file is final, such as a signed PDF or an invoice":"Le fichier est définitif, par exemple un PDF signé ou une facture","Several people must edit the same file":"Plusieurs personnes doivent modifier le même fichier","The recipient is outside your organisation and may not open links":"Le destinataire est extérieur à votre organisation et risque de ne pas pouvoir ouvrir les liens","The file is large: mail servers often reject messages over 20–25 MB":"Le fichier est volumineux : les serveurs de messagerie refusent souvent les messages de plus de 20 à 25 Mo","You need a record of exactly what was sent":"Vous avez besoin d'une trace exacte de ce qui a été envoyé","You want to update the file after sending, or remove access later":"Vous voulez mettre le fichier à jour après l'envoi, ou retirer l'accès plus tard","Reply, Reply All and Forward":"Répondre, Répondre à tous et Transférer","Reply to the sender only":"Répondre à l'expéditeur seulement","Reply All":"Répondre à tous","Forward (in Outlook, not Find)":"Transférer (dans Outlook, pas Rechercher)","Send the message (classic Outlook asks to confirm the first time)":"Envoyer le message (Outlook classique demande confirmation la première fois)","Check names against the address book":"Vérifier les noms dans le carnet d'adresses","Practise the message shortcuts":"Entraînez-vous aux raccourcis des messages","Forward the message":"Transférer le message","Send the message":"Envoyer le message","Check names":"Vérifier les noms","Use Reply All only when every person on the list needs your answer. \"Thank you\" to 40 people is noise. When you forward a long thread, add two lines on top explaining what you want from the new reader.":"N'utilisez Répondre à tous que lorsque chaque personne de la liste a besoin de votre réponse. Un « Merci » à 40 personnes, c'est du bruit. Quand vous transférez un long échange, ajoutez deux lignes en haut pour expliquer ce que vous attendez du nouveau lecteur.","Signatures, delayed delivery and recall":"Signatures, remise différée et rappel","Mail":"Courrier","Signatures":"Signatures","In new Outlook: Settings › Accounts › Signatures. Create one full signature for new messages and a short one for replies.":"Dans le nouvel Outlook : Paramètres › Comptes › Signatures. Créez une signature complète pour les nouveaux messages et une courte pour les réponses.","Delay Delivery":"Différer la remise","In a message window. Set \"Do not deliver before\" a date and time. In new Outlook, use the arrow next to Send › Schedule send.":"Dans la fenêtre d'un message. Définissez « Ne pas remettre avant » une date et une heure. Dans le nouvel Outlook, utilisez la flèche à côté d'Envoyer › Planifier l'envoi.","Recall":"Le rappel","works only between Microsoft 365 work accounts in the same organisation, and only if the recipient has not opened the message. Never count on it.":"ne fonctionne qu'entre comptes professionnels Microsoft 365 de la même organisation, et seulement si le destinataire n'a pas ouvert le message. N'y comptez jamais.","A better safety net: in new Outlook, turn on":"Un meilleur filet de sécurité : dans le nouvel Outlook, activez","Undo send":"Annuler l'envoi","(Settings › Mail › Compose and reply) to get a few seconds to cancel.":"(Paramètres › Courrier › Composer et répondre) pour disposer de quelques secondes pour annuler.","Read the message aloud before sending anything sensitive, and add the recipients last so it cannot leave by accident.":"Relisez à voix haute tout message sensible avant de l'envoyer, et ajoutez les destinataires en dernier pour qu'il ne puisse pas partir par accident.","Bilingual e-mails":"E-mails bilingues","When writing to a ministry or partner that works in both official languages, put the French and English versions one after the other, separated by a line, rather than mixing sentences. Start with the language of the recipient. A subject line such as \"Invitation atelier / Workshop invitation: Bafoussam, 12 Nov\" shows both at once.":"Lorsque vous écrivez à un ministère ou à un partenaire qui travaille dans les deux langues officielles, placez les versions française et anglaise l'une après l'autre, séparées par une ligne, plutôt que de mélanger les phrases. Commencez par la langue du destinataire. Un objet comme « Invitation atelier / Workshop invitation : Bafoussam, 12 nov. » montre les deux à la fois.","Address and title the message":"Adresser le message et lui donner un objet","The Human Resources office of a Yaoundé SME is organising a first-aid training. Decide where each person goes, then choose and write clear subject lines.":"Le service des ressources humaines d'une PME de Yaoundé organise une formation aux premiers secours. Décidez où va chaque personne, puis choisissez et rédigez des objets clairs.","To = must act; Cc = informed; Bcc = must not see the other addresses. A good subject names the topic, the action and the date.":"À = doit agir ; Cc = informé ; Cci = ne doit pas voir les autres adresses. Un bon objet indique le sujet, l'action et la date.","The 12 staff members who must confirm attendance":"Les 12 membres du personnel qui doivent confirmer leur présence","Do not include":"Ne pas inclure","Your manager, who approved the budget and only needs to follow":"Votre responsable, qui a approuvé le budget et doit seulement suivre","The external trainer, who should not receive the staff members' addresses in a later reminder sent to the whole list":"Le formateur externe, qui ne doit pas recevoir les adresses du personnel dans un rappel envoyé plus tard à toute la liste","Bcc hides the addresses from each other. The trainer can still receive the reminder.":"Cci masque les adresses les unes des autres. Le formateur reçoit quand même le rappel.","A colleague on leave who has nothing to do with the training":"Un collègue en congé qui n'a rien à voir avec la formation","Which subject line is best?":"Quel objet est le meilleur ?","It gives the topic, the action expected and the deadline.":"Il indique le sujet, l'action attendue et l'échéance.","Training":"Formation","URGENT PLEASE READ":"URGENT À LIRE SVP","First-aid training 12 Nov: confirm attendance by 5 Nov":"Formation premiers secours 12 nov. : confirmez votre présence avant le 5 nov.","Hello everyone":"Bonjour à tous","Rewrite the subject \"Urgent!!!\" for this e-mail: you need the Q3 activity report of the Bafoussam branch by Friday 16 October.":"Réécrivez l'objet « Urgent!!! » pour cet e-mail : vous avez besoin du rapport d'activité du T3 de l'agence de Bafoussam pour le vendredi 16 octobre.","Name the document, the branch and the deadline. Exclamation marks do not make a message more urgent.":"Nommez le document, l'agence et l'échéance. Les points d'exclamation ne rendent pas un message plus urgent.","You send an invitation to 80 members of an association who do not know each other. Where do you put their addresses?":"Vous envoyez une invitation à 80 membres d'une association qui ne se connaissent pas. Où mettez-vous leurs adresses ?","In To, so everyone feels invited":"Dans À, pour que chacun se sente invité","In Cc":"Dans Cc","In Bcc, with your own address in To":"Dans Cci, avec votre propre adresse dans À","Half in To and half in Cc":"La moitié dans À et l'autre moitié dans Cc","Bcc keeps each member's address private and prevents Reply All chains to 80 people. Your own address in To gives the message a visible recipient.":"Cci garde l'adresse de chaque membre confidentielle et évite les chaînes de Répondre à tous vers 80 personnes. Votre propre adresse dans À donne au message un destinataire visible.","Create a full signature and a short reply signature in Outlook":"Créez dans Outlook une signature complète et une signature courte pour les réponses","Show the Bcc field in a new message window":"Affichez le champ Cci dans la fenêtre d'un nouveau message","Rewrite the subject lines of three e-mails you sent last week using topic, action and date":"Réécrivez l'objet de trois e-mails envoyés la semaine dernière avec sujet, action et date","Schedule a test message to yourself with Delay Delivery for 10 minutes later":"Programmez un message de test pour vous-même avec Différer la remise, 10 minutes plus tard","Send a large file as a OneDrive link instead of an attachment":"Envoyez un fichier volumineux sous forme de lien OneDrive plutôt qu'en pièce jointe","Keyboard shortcuts for Outlook":"Raccourcis clavier pour Outlook","How to recall an email in Outlook":"Comment rappeler un e-mail dans Outlook","Inbox rules and folders: keep 100+ e-mails a day under control":"Règles et dossiers de la boîte de réception : maîtriser plus de 100 e-mails par jour","Organise the mailbox with a simple folder structure, categories and flags":"Organiser la boîte aux lettres avec une structure de dossiers simple, des catégories et des indicateurs","Automate sorting with rules, Quick Steps and Focused Inbox":"Automatiser le tri avec les règles, les Actions rapides et la Boîte de réception Prioritaire","Find any message in seconds with search operators":"Retrouver n'importe quel message en quelques secondes avec les opérateurs de recherche","When 100 or more messages arrive every day, reading them in order no longer works. Professionals decide once what happens to each message, let Outlook sort the routine ones automatically, and use search instead of scrolling.":"Quand 100 messages ou plus arrivent chaque jour, les lire dans l'ordre ne fonctionne plus. Les professionnels décident une fois pour toutes du sort de chaque message, laissent Outlook trier automatiquement les messages de routine et utilisent la recherche au lieu de faire défiler.","Decide once: the four Ds":"Décider une fois : les quatre D","Decision":"Décision","When":"Quand","In Outlook":"Dans Outlook","No value, or already stored elsewhere":"Aucune valeur, ou déjà conservé ailleurs","Delete, or Archive if you may need it":"Supprimer, ou Archiver si vous risquez d'en avoir besoin","Do":"Faire","Takes less than two minutes":"Prend moins de deux minutes","Answer now, then file":"Répondre tout de suite, puis classer","Delegate":"Déléguer","Someone else should handle it":"Quelqu'un d'autre doit s'en occuper","Forward with a clear request":"Transférer avec une demande claire","Defer":"Différer","Takes longer and has a deadline":"Prend plus de temps et a une échéance","Flag with a date, or turn it into a task or calendar slot":"Marquer d'un indicateur avec une date, ou en faire une tâche ou un créneau dans le calendrier","A folder structure that stays small":"Une structure de dossiers qui reste petite","Create a few broad folders, not one per person. Outlook search is fast, so deep folder trees waste more time than they save. A good start: Inbox, Action, Waiting for, Reference, and one folder per major project or client.":"Créez quelques dossiers larges, pas un par personne. La recherche d'Outlook est rapide : des arborescences profondes font perdre plus de temps qu'elles n'en font gagner. Un bon départ : Boîte de réception, À traiter, En attente, Référence, et un dossier par grand projet ou client.","Create a new folder":"Créer un dossier","Move the selected message to a folder":"Déplacer le message sélectionné vers un dossier","Flag for follow-up with a custom date":"Marquer pour suivi avec une date personnalisée","Mark as unread":"Marquer comme non lu","Go to the search box":"Aller dans la zone de recherche","Delete the selected message":"Supprimer le message sélectionné","Focused Inbox, categories and flags":"Boîte de réception Prioritaire, catégories et indicateurs","Show Focused Inbox":"Afficher la boîte de réception Prioritaire","Outlook splits the Inbox into Focused and Other. Move a message to Focused once and future messages from that sender follow.":"Outlook divise la boîte de réception en Prioritaire et Autre. Déplacez une fois un message vers Prioritaire, et les messages suivants de cet expéditeur suivront.","Categories":"Les catégories","are coloured labels. A message can have several, for example \"Budget 2027\" and \"Waiting for\". Rename them in Home › Tags › Categorize › All Categories.":"sont des étiquettes de couleur. Un message peut en avoir plusieurs, par exemple « Budget 2027 » et « En attente ». Renommez-les dans Accueil › Indicateurs › Classer › Toutes les catégories.","Flags":"Les indicateurs","add a due date: Today, Tomorrow, This Week, Next Week or Custom. Flagged messages appear in your task list (Lesson 4).":"ajoutent une échéance : Aujourd'hui, Demain, Cette semaine, La semaine prochaine ou Personnalisé. Les messages marqués apparaissent dans votre liste de tâches (leçon 4).","Archive":"Archiver","moves a message out of the Inbox without deleting it. Use it for everything finished that you might need later.":"sort un message de la boîte de réception sans le supprimer. Utilisez-le pour tout ce qui est terminé mais dont vous pourriez avoir besoin plus tard.","Rules: let Outlook sort for you":"Les règles : laissez Outlook trier pour vous","A rule has three parts:":"Une règle comporte trois parties :","conditions":"des conditions","(which messages),":"(quels messages),","actions":"des actions","(what to do with them) and optional":"(que faire de ces messages) et, si besoin,","exceptions":"des exceptions","(which messages to leave alone). Most rules on messages you receive run on the server, so they work even when Outlook is closed on a Microsoft 365 account.":"(quels messages laisser de côté). La plupart des règles sur les messages reçus s'exécutent sur le serveur : elles fonctionnent même quand Outlook est fermé, avec un compte Microsoft 365.","Manage Rules & Alerts":"Gérer les règles et les alertes","New Rule":"Nouvelle règle","Faster: right-click a message › Rules › Create Rule. In new Outlook: Settings › Mail › Rules.":"Plus rapide : clic droit sur un message › Règles › Créer une règle. Dans le nouvel Outlook : Paramètres › Courrier › Règles.","Create a rule with the Rules Wizard":"Créer une règle avec l'Assistant Gestion des messages","Start from a blank rule:":"Partez d'une règle vide :","Apply rule on messages I receive":"Appliquer la règle aux messages que je reçois","Tick the conditions, for example":"Cochez les conditions, par exemple","from people or public group":"de personnes ou groupe public","with specific words in the subject":"avec des mots spécifiques dans l'objet",". Click each underlined value to fill it.":". Cliquez sur chaque valeur soulignée pour la renseigner.","Tick the actions, for example":"Cochez les actions, par exemple","move it to the specified folder":"la déplacer dans le dossier spécifié","assign it to the category":"la classer dans la catégorie","Add exceptions if needed, for example":"Ajoutez des exceptions si nécessaire, par exemple","except if it is marked as importance":"sauf si elle est marquée comme importance","High.":"Haute.","Name the rule, tick":"Nommez la règle, cochez","Run this rule now on messages already in Inbox":"Exécuter cette règle maintenant sur les messages qui se trouvent déjà dans « Boîte de réception »",", and click Finish.":", puis cliquez sur Terminer.","Quick Steps for one-click routines":"Les Actions rapides pour les routines en un clic","A Quick Step groups several actions into one button, for example \"mark as read, categorise Finance and move to Invoices\". Create them in Home › Quick Steps › Create New. Rules act on arrival; Quick Steps act when you click.":"Une Action rapide regroupe plusieurs actions dans un seul bouton, par exemple « marquer comme lu, classer Finance et déplacer vers Factures ». Créez-les dans Accueil › Actions rapides › Créer. Les règles agissent à l'arrivée ; les Actions rapides agissent quand vous cliquez.","Clean up and search":"Nettoyer et rechercher","Clean Up":"Nettoyer","Clean Up Conversation":"Nettoyer la conversation","Removes messages whose full text is already quoted in a later reply. New Outlook and Outlook on the web offer Sweep to delete or move everything from one sender.":"Supprime les messages dont le texte complet est déjà cité dans une réponse ultérieure. Le nouvel Outlook et Outlook sur le web proposent Balayer pour supprimer ou déplacer tous les messages d'un expéditeur.","Type in the search box":"Tapez dans la zone de recherche","Finds":"Trouve","Messages sent by anyone called Ngono":"Les messages envoyés par toute personne nommée Ngono","Messages with \"budget\" in the subject":"Les messages dont l'objet contient « budget »","Messages with attachments":"Les messages avec pièces jointes","Messages received yesterday (also: this week, last month)":"Les messages reçus hier (aussi : this week, last month)","The exact phrase, not the two words separately":"L'expression exacte, et non les deux mots séparément","Both conditions at once; use OR in capitals for either":"Les deux conditions à la fois ; utilisez OR en majuscules pour l'une ou l'autre","The Search tab that opens when you click the search box builds these operators for you, in the language of your Outlook. If your Outlook is in French, use its buttons once to see the exact words it expects.":"L'onglet Rechercher, qui s'ouvre quand vous cliquez dans la zone de recherche, construit ces opérateurs pour vous, dans la langue de votre Outlook. Si votre Outlook est en français, utilisez une fois ses boutons pour voir les mots exacts qu'il attend.","Build a rule and search the mailbox":"Créer une règle et rechercher dans la boîte aux lettres","Aïcha works at the Ministry of Trade in Yaoundé. Tax notices from the Direction Générale des Impôts (address avis@dgi.example.cm) arrive every day and bury her other mail. Build the rule, then write the searches she needs.":"Aïcha travaille au ministère du Commerce à Yaoundé. Les avis fiscaux de la Direction Générale des Impôts (adresse avis@dgi.example.cm) arrivent tous les jours et noient ses autres messages. Créez la règle, puis écrivez les recherches dont elle a besoin.","Conditions select the messages, actions do something to them, exceptions protect some of them. Search operators are written as name, colon, value, with no space after the colon.":"Les conditions sélectionnent les messages, les actions les traitent, les exceptions en protègent certains. Les opérateurs de recherche s'écrivent nom, deux-points, valeur, sans espace après les deux-points.","Condition that selects the tax notices":"Condition qui sélectionne les avis fiscaux","from people or public group: avis@dgi.example.cm":"de personnes ou groupe public : avis@dgi.example.cm","sent only to me":"envoyé uniquement à moi","marked as importance Low":"marqué comme importance Basse","with specific words in the body: Dear":"avec des mots spécifiques dans le corps : Dear","Action that gets them out of the Inbox without losing them":"Action qui les sort de la boîte de réception sans les perdre","delete it":"la supprimer","move it to the specified folder: Impôts":"la déplacer dans le dossier spécifié : Impôts","forward it to all staff":"la transférer à tout le personnel","print it":"l'imprimer","She still wants to see urgent notices in the Inbox. Which exception?":"Elle veut quand même voir les avis urgents dans la boîte de réception. Quelle exception ?","Messages marked High importance stay in the Inbox; all the others go to the folder.":"Les messages marqués d'une importance Haute restent dans la boîte de réception ; tous les autres vont dans le dossier.","except if it has an attachment":"sauf s'il comporte une pièce jointe","except if it is marked as importance High":"sauf si elle est marquée comme importance Haute","except if sent only to me":"sauf si envoyé uniquement à moi","No exception is possible":"Aucune exception n'est possible","The Inbox already holds 300 old notices. What should she tick on the last page of the wizard?":"La boîte de réception contient déjà 300 anciens avis. Que doit-elle cocher sur la dernière page de l'assistant ?","Turn on this rule":"Activer cette règle","Create this rule on all accounts":"Créer cette règle sur tous les comptes","Stop processing more rules":"Arrêter de traiter plus de règles","Search: every message sent by Mr Fouda":"Recherche : tous les messages envoyés par M. Fouda","Search: messages with \"tender\" in the subject":"Recherche : les messages dont l'objet contient « tender »","Search: messages from Fouda that have an attachment":"Recherche : les messages de Fouda qui ont une pièce jointe","Two operators separated by a space must both be true.":"Deux opérateurs séparés par une espace doivent être vrais tous les deux.","Practise the triage shortcuts":"Entraînez-vous aux raccourcis de tri","Move the message to a folder":"Déplacer le message vers un dossier","Flag for follow-up":"Marquer pour suivi","Mobile money and bank notifications":"Notifications de mobile money et de la banque","Automatic notifications from your bank, mobile money platform or ERP can reach hundreds a week. One rule that moves them to a \"Notifications\" folder, with an exception for messages containing \"failed\" or \"échec\", keeps the Inbox for people while still showing the alerts that matter.":"Les notifications automatiques de votre banque, de votre plateforme de mobile money ou de votre ERP peuvent atteindre des centaines par semaine. Une règle qui les déplace dans un dossier « Notifications », avec une exception pour les messages contenant « failed » ou « échec », réserve la boîte de réception aux personnes tout en affichant les alertes qui comptent.","You want every message from the finance team to be marked as read, categorised \"Finance\" and moved to a folder, but only when you decide. What should you create?":"Vous voulez que chaque message de l'équipe financière soit marqué comme lu, classé « Finance » et déplacé dans un dossier, mais seulement quand vous le décidez. Que devez-vous créer ?","A rule":"Une règle","A Quick Step":"Une Action rapide","A search folder":"Un dossier de recherche","A contact group":"Un groupe de contacts","A Quick Step runs several actions when you click it. A rule would act automatically on every message as it arrives.":"Une Action rapide exécute plusieurs actions quand vous cliquez dessus. Une règle agirait automatiquement sur chaque message à son arrivée.","Create four folders: Action, Waiting for, Reference and one project folder":"Créez quatre dossiers : À traiter, En attente, Référence et un dossier de projet","Rename three colour categories to match your work, such as Budget, Clients and Waiting for":"Renommez trois catégories de couleur selon votre travail, par exemple Budget, Clients et En attente","Create one rule for a newsletter or notification sender and run it on existing messages":"Créez une règle pour un expéditeur de lettre d'information ou de notifications et exécutez-la sur les messages existants","Create a Quick Step that marks a message as read and moves it to Reference":"Créez une Action rapide qui marque un message comme lu et le déplace vers Référence","Find last month's messages with attachments from one colleague using operators":"Retrouvez avec des opérateurs les messages du mois dernier avec pièces jointes d'un collègue","Manage email messages by using rules in Outlook":"Gérer les e-mails à l'aide de règles dans Outlook","Exam MO-400: Microsoft Outlook (Office 2019)":"Examen MO-400 : Microsoft Outlook (Office 2019)","Calendar and meetings across sites and time zones":"Calendrier et réunions entre sites et fuseaux horaires","Create appointments and meetings, including recurring and Teams meetings":"Créer des rendez-vous et des réunions, y compris périodiques et Teams","Find a time that suits every attendee with the Scheduling Assistant and time zones":"Trouver un horaire qui convient à chaque participant avec l'Assistant Planification et les fuseaux horaires","Track responses, share your calendar and book rooms":"Suivre les réponses, partager son calendrier et réserver des salles","The calendar is where your time is negotiated. A clear invitation, sent at a time that works for everyone and with an agenda, saves a round of e-mails and makes the meeting itself shorter.":"Le calendrier est l'endroit où votre temps se négocie. Une invitation claire, envoyée à une heure qui convient à tous et accompagnée d'un ordre du jour, évite un échange d'e-mails et raccourcit la réunion elle-même.","Appointment, meeting or event?":"Rendez-vous, réunion ou événement ?","Item":"Élément","Appointment":"Rendez-vous","Time blocked in your calendar only; nobody is invited":"Du temps bloqué uniquement dans votre calendrier ; personne n'est invité","Two hours to write the quarterly report":"Deux heures pour rédiger le rapport trimestriel","Meeting":"Réunion","An invitation sent to others, who accept or decline":"Une invitation envoyée à d'autres personnes, qui acceptent ou refusent","Weekly team meeting, client visit":"Réunion d'équipe hebdomadaire, visite d'un client","All-day event":"Événement d'une journée","A day marked without blocking hours":"Une journée marquée sans bloquer d'heures","Public holiday, colleague's leave":"Jour férié, congé d'un collègue","New Appointment":"Nouveau rendez-vous","Or Ctrl + Shift + A from anywhere in Outlook.":"Ou Ctrl + Maj + A depuis n'importe où dans Outlook.","New Meeting":"Nouvelle réunion","In the Calendar. Adding attendees to an appointment also turns it into a meeting.":"Dans le Calendrier. Ajouter des participants à un rendez-vous le transforme aussi en réunion.","Build a good invitation":"Rédiger une bonne invitation","Schedule a meeting":"Planifier une réunion","Add required attendees in":"Ajoutez les participants indispensables dans","Required":"Obligatoire","and people who may come in":"et les personnes qui peuvent venir dans","Optional":"Facultatif","Write a subject that says what will be decided, for example \"Validate the 2027 training plan\".":"Rédigez un objet qui dit ce qui sera décidé, par exemple « Valider le plan de formation 2027 ».","Open the":"Ouvrez l'outil","Scheduling Assistant":"Assistant Planification","to see everyone's free and busy times, and pick a slot where nobody is busy.":"pour voir les disponibilités de chacun, et choisissez un créneau où personne n'est occupé.","Room Finder":"Recherche de salle","or add a room from the list to book a meeting room at the same time.":"ou ajoutez une salle de la liste pour réserver une salle de réunion en même temps.","Teams Meeting":"Réunion Teams","to add an online link for people at other sites.":"pour ajouter un lien en ligne pour les personnes des autres sites.","Write the":"Rédigez","agenda":"l'ordre du jour","in the body: items, who presents, what decision is expected.":"dans le corps : points, qui présente, quelle décision est attendue.","Recurrence":"Périodicité","if the meeting repeats, then":"si la réunion se répète, puis sur","Send":"Envoyer","Response options":"Options de réponse","In the meeting window,":"Dans la fenêtre de la réunion,","Response Options":"Options de réponse","lets you turn off Request Responses for large information sessions, or stop attendees proposing new times. After sending, open the meeting and click":"permet de désactiver Demander des réponses pour les grandes séances d'information, ou d'empêcher les participants de proposer un nouvel horaire. Après l'envoi, ouvrez la réunion et cliquez sur","to see who accepted, declined or has not answered.":"pour voir qui a accepté, refusé ou n'a pas répondu.","Time zones":"Fuseaux horaires","Cameroon uses":"Le Cameroun utilise","West Africa Time (WAT), UTC+1":"l'heure d'Afrique de l'Ouest (WAT), UTC+1",", all year, with no summer time. Many partners change their clocks, so the difference with Douala changes during the year.":", toute l'année, sans heure d'été. Beaucoup de partenaires changent d'heure : l'écart avec Douala varie donc au cours de l'année.","City":"Ville","Offset":"Décalage","Difference with Douala":"Écart avec Douala","Abidjan, Dakar":"Abidjan, Dakar","UTC+0":"UTC+0","1 hour behind all year":"1 heure de moins toute l'année","Paris, Brussels":"Paris, Bruxelles","UTC+1 in winter, UTC+2 from late March to late October":"UTC+1 en hiver, UTC+2 de fin mars à fin octobre","Same time in winter, 1 hour ahead in summer":"Même heure en hiver, 1 heure de plus en été","Nairobi":"Nairobi","UTC+3":"UTC+3","2 hours ahead all year":"2 heures de plus toute l'année","Washington, Montréal":"Washington, Montréal","UTC−5 in winter, UTC−4 from March to early November":"UTC−5 en hiver, UTC−4 de mars à début novembre","6 hours behind in winter, 5 hours behind in summer":"6 heures de moins en hiver, 5 heures de moins en été","Calendar":"Calendrier","Tick Show a second time zone, for example Paris, to see both columns in the calendar.":"Cochez Afficher un deuxième fuseau horaire, par exemple Paris, pour voir les deux colonnes dans le calendrier.","In a meeting window, the":"Dans la fenêtre d'une réunion, le bouton","Time Zones":"Fuseaux horaires","button lets you set the start time in the time zone of the organiser. Outlook converts the time automatically for each attendee, so write the time zone in the body too: \"14:00 Douala (WAT) / 15:00 Paris\".":"permet de fixer l'heure de début dans le fuseau horaire de l'organisateur. Outlook convertit l'heure automatiquement pour chaque participant ; indiquez quand même le fuseau dans le corps : « 14:00 Douala (WAT) / 15:00 Paris ».","New appointment":"Nouveau rendez-vous","New meeting request":"Nouvelle demande de réunion","Go to a date in the Calendar":"Aller à une date dans le Calendrier","Practise the calendar shortcut":"Entraînez-vous au raccourci du calendrier","Share your calendar":"Partager votre calendrier","Share Calendar":"Partager le calendrier","In the Calendar. Choose what the person sees.":"Dans le Calendrier. Choisissez ce que la personne voit.","Can view when I'm busy":"Peut afficher quand je suis occupé",": colleagues see free and busy blocks only.":": les collègues ne voient que les plages libres et occupées.","Can view titles and locations":"Peut afficher les titres et les emplacements",": enough for an assistant planning your week.":": suffisant pour un assistant qui organise votre semaine.","Can view all details":"Peut afficher tous les détails","Can edit":"Peut modifier",": only for people you trust with your agenda.":": seulement pour les personnes à qui vous confiez votre agenda.","Mark personal appointments":"Marquez les rendez-vous personnels comme","Private":"Privé","so their details stay hidden even when the calendar is shared.":"pour que leurs détails restent masqués même lorsque le calendrier est partagé.","Meetings across Cameroonian sites":"Réunions entre sites camerounais","A regional NGO with offices in Douala, Garoua and Bertoua schedules its monthly meeting at 10:00 so the Garoua team, who may travel by road, can join. The invitation includes a Teams link and a phone dial-in for colleagues with weak connections, and the agenda is attached so people can read it offline during a power cut.":"Une ONG régionale avec des bureaux à Douala, Garoua et Bertoua fixe sa réunion mensuelle à 10:00 pour que l'équipe de Garoua, qui voyage parfois par la route, puisse y participer. L'invitation comprend un lien Teams et un accès téléphonique pour les collègues mal connectés, et l'ordre du jour est joint pour pouvoir être lu hors ligne pendant une coupure d'électricité.","Set up the meeting":"Paramétrer la réunion","Émile, a project officer in Yaoundé, organises a quarterly review with two colleagues in Douala, the partner's accountant in Abidjan and the country director. Choose the right settings.":"Émile, chargé de projet à Yaoundé, organise une revue trimestrielle avec deux collègues de Douala, la comptable du partenaire à Abidjan et la directrice pays. Choisissez les bons paramètres.","Meetings invite people, appointments do not. Abidjan is one hour behind Cameroon all year.":"Les réunions invitent des personnes, les rendez-vous non. Abidjan a une heure de moins que le Cameroun toute l'année.","What should he create?":"Que doit-il créer ?","An appointment":"Un rendez-vous","A meeting":"Une réunion","An all-day event":"Un événement d'une journée","A task":"Une tâche","The country director may join if her schedule allows. Where does she go?":"La directrice pays pourra se joindre si son emploi du temps le permet. Où la placer ?","Resources":"Ressources","Which tool shows everyone's free and busy times side by side?":"Quel outil affiche côte à côte les disponibilités de chacun ?","Categorize":"Classer","Colleagues in Douala and Abidjan will join online. What does he add?":"Les collègues de Douala et d'Abidjan participeront en ligne. Qu'ajoute-t-il ?","A OneDrive link":"Un lien OneDrive","A Teams meeting link":"Un lien de réunion Teams","A read receipt":"Un accusé de lecture","A second time zone":"Un deuxième fuseau horaire","The meeting starts at 10:00 in Yaoundé. What time is it in Abidjan? (hh:mm)":"La réunion commence à 10:00 à Yaoundé. Quelle heure est-il à Abidjan ? (hh:mm)","Abidjan is UTC+0 and Cameroon UTC+1, so Abidjan is one hour behind.":"Abidjan est en UTC+0 et le Cameroun en UTC+1 : Abidjan a donc une heure de moins.","The review repeats on the first Monday of every third month. Which button?":"La revue se répète le premier lundi tous les trois mois. Quel bouton ?","Forward":"Transférer","Two weeks later, where does he see who has not answered?":"Deux semaines plus tard, où voit-il qui n'a pas répondu ?","The Sent Items folder":"Le dossier Éléments envoyés","Tracking in the open meeting":"Suivi, dans la réunion ouverte","The Scheduling Assistant":"L'Assistant Planification","Focused Inbox":"Boîte de réception Prioritaire","On 20 October, a Douala manager sends an invitation for 15:00 Douala time to a partner in Paris. What time will the partner see in Outlook?":"Le 20 octobre, une responsable à Douala envoie une invitation pour 15:00, heure de Douala, à un partenaire à Paris. Quelle heure le partenaire verra-t-il dans Outlook ?","In October, Paris is still on summer time (UTC+2), one hour ahead of Cameroon (UTC+1). Outlook converts the time automatically.":"En octobre, Paris est encore à l'heure d'été (UTC+2), une heure de plus que le Cameroun (UTC+1). Outlook convertit l'heure automatiquement.","Block two hours of focused work as an appointment in your calendar":"Bloquez deux heures de travail concentré sous forme de rendez-vous dans votre calendrier","Add a second time zone for a city where you have partners":"Ajoutez un deuxième fuseau horaire pour une ville où vous avez des partenaires","Send a test meeting with a Teams link and an agenda to a colleague":"Envoyez à un collègue une réunion de test avec un lien Teams et un ordre du jour","Share your calendar with a colleague as \"Can view titles and locations\"":"Partagez votre calendrier avec un collègue en « Peut afficher les titres et les emplacements »","Open a meeting you organised and check the Tracking list":"Ouvrez une réunion que vous avez organisée et consultez la liste Suivi","Use the Scheduling Assistant and Room Finder for meetings in Outlook":"Utiliser l'Assistant Planification et la Recherche de salle pour les réunions dans Outlook","Tasks, contacts and automatic replies":"Tâches, contacts et réponses automatiques","Turn e-mails into tasks with due dates and reminders":"Transformer des e-mails en tâches avec échéances et rappels","Build contacts and contact groups, and import them from Excel or CSV":"Créer des contacts et des groupes de contacts, et les importer depuis Excel ou un fichier CSV","Set up Automatic Replies for internal and external senders":"Configurer les réponses automatiques pour les expéditeurs internes et externes","An inbox is a poor to-do list: important requests sink under new mail. Outlook can turn a message into a task with a date, keep your contacts in one place, and answer for you when you are away.":"Une boîte de réception fait une mauvaise liste de tâches : les demandes importantes coulent sous les nouveaux messages. Outlook peut transformer un message en tâche datée, garder vos contacts au même endroit et répondre à votre place quand vous êtes absent.","From e-mail to task":"De l'e-mail à la tâche","Flag":"Marquez d'un indicateur","a message (Home › Follow Up) and choose a date. It appears in your task list with a link back to the message.":"un message (Accueil › Assurer un suivi) et choisissez une date. Il apparaît dans votre liste de tâches avec un lien vers le message.","Follow Up › Add Reminder":"Assurer un suivi › Ajouter un rappel","to get a pop-up at a set time, for example the day before the deadline.":"pour recevoir une alerte à une heure donnée, par exemple la veille de l'échéance.","Create a task that is not linked to any e-mail with":"Créez une tâche qui n'est liée à aucun e-mail avec","Ctrl + Shift + K":"Ctrl + Maj + K",": subject, start date, due date, reminder.":": objet, date de début, échéance, rappel.","Your flagged messages and tasks also appear in":"Vos messages marqués et vos tâches apparaissent aussi dans","Microsoft To Do":"Microsoft To Do","on the web and on your phone, so you can tick them off anywhere.":"sur le web et sur votre téléphone : vous pouvez les cocher n'importe où.","Follow Up":"Assurer un suivi","Custom":"Personnalisé","Set a start date, due date and reminder. In new Outlook, you can also drag a message to My Day.":"Définissez une date de début, une échéance et un rappel. Dans le nouvel Outlook, vous pouvez aussi faire glisser un message vers Ma journée.","New task":"Nouvelle tâche","New contact":"Nouveau contact","New contact group":"Nouveau groupe de contacts","Practise the task and contact shortcuts":"Entraînez-vous aux raccourcis des tâches et des contacts","Contacts and contact groups":"Contacts et groupes de contacts","A complete contact card saves time later: full name, organisation, job title, e-mail, mobile number and city. A":"Une fiche de contact complète fait gagner du temps plus tard : nom complet, organisation, fonction, e-mail, numéro de mobile et ville. Un","contact group":"groupe de contacts","(called a contact list in new Outlook) puts several contacts behind one name, such as \"Branch heads\", so you type one name instead of twelve addresses.":"(appelé liste de contacts dans le nouvel Outlook) réunit plusieurs contacts sous un seul nom, par exemple « Chefs d'agence » : vous tapez un nom au lieu de douze adresses.","People":"Contacts","New Contact Group":"Nouveau groupe de contacts","Give it a name, click Add Members, choose From Outlook Contacts or From Address Book, then Save & Close.":"Donnez-lui un nom, cliquez sur Ajouter des membres, choisissez À partir des contacts Outlook ou À partir du carnet d'adresses, puis Enregistrer et fermer.","Contact groups and Bcc":"Groupes de contacts et Cci","When you put a contact group in To or Cc, recipients see all its members' addresses. For external groups, put the contact group in Bcc.":"Quand vous placez un groupe de contacts dans À ou Cc, les destinataires voient les adresses de tous ses membres. Pour les groupes externes, placez le groupe de contacts dans Cci.","Import contacts from Excel":"Importer des contacts depuis Excel","Import a list of partners":"Importer une liste de partenaires","In Excel, keep one row per person with clear headings such as First Name, Last Name, Company, E-mail, Mobile.":"Dans Excel, gardez une ligne par personne avec des en-têtes clairs comme Prénom, Nom, Société, E-mail, Mobile.","Save as":"Enregistrez au format","CSV UTF-8 (Comma delimited)":"CSV UTF-8 (délimité par des virgules)","so accented names such as Nkoué or Émilie import correctly.":"pour que les noms accentués comme Nkoué ou Émilie s'importent correctement.","In Outlook:":"Dans Outlook :","File › Open & Export › Import/Export":"Fichier › Ouvrir et exporter › Importer/Exporter",", then":", puis","Import from another program or file":"Importer à partir d'un autre programme ou fichier","Comma Separated Values":"Valeurs séparées par une virgule","Choose the file and whether to replace or allow duplicates, then select the Contacts folder.":"Choisissez le fichier et indiquez s'il faut remplacer ou autoriser les doublons, puis sélectionnez le dossier Contacts.","Map Custom Fields":"Mapper les champs personnalisés","and check that each Excel column is matched to the right Outlook field, then Finish.":"et vérifiez que chaque colonne Excel correspond au bon champ Outlook, puis cliquez sur Terminer.","Automatic Replies (Out of Office)":"Réponses automatiques (absence du bureau)","Automatic Replies":"Réponses automatiques","Work or school accounts. In new Outlook: Settings › Accounts › Automatic replies.":"Comptes professionnels ou scolaires. Dans le nouvel Outlook : Paramètres › Comptes › Réponses automatiques.","Only send during this time range":"N'envoyer que pendant cette période","so the reply stops by itself when you return.":"pour que la réponse s'arrête d'elle-même à votre retour.","Write a separate message for":"Rédigez un message distinct pour","Outside My Organization":"En dehors de mon organisation",": shorter, without internal details, and only to your contacts if you want to limit spam.":": plus court, sans détails internes, et uniquement à vos contacts si vous voulez limiter le spam.","Give the date of return and a colleague's name and address for urgent matters, but no personal details such as \"I am travelling abroad\".":"Indiquez la date de retour ainsi que le nom et l'adresse d'un collègue pour les urgences, mais aucun détail personnel comme « je suis en voyage à l'étranger ».","Organise tasks, contacts and leave":"Organiser tâches, contacts et congés","Serge, logistics officer of an SME in Douala, goes on leave from 2 to 13 November. Choose the right Outlook feature for each situation.":"Serge, responsable logistique d'une PME de Douala, part en congé du 2 au 13 novembre. Choisissez la bonne fonctionnalité d'Outlook pour chaque situation.","Flags and tasks carry dates; contact groups replace long lists of addresses; Automatic Replies handle absence.":"Les indicateurs et les tâches portent des dates ; les groupes de contacts remplacent de longues listes d'adresses ; les réponses automatiques gèrent les absences.","A supplier asks for a quotation by Friday. Serge wants a reminder on Thursday morning.":"Un fournisseur demande un devis pour vendredi. Serge veut un rappel jeudi matin.","Mark it as unread":"Le marquer comme non lu","Flag it with a custom date and add a reminder":"Le marquer d'un indicateur avec une date personnalisée et ajouter un rappel","Move it to Archive":"Le déplacer vers Archive","Forward it to himself":"Se le transférer à lui-même","He e-mails the same nine drivers every week.":"Il écrit chaque semaine aux neuf mêmes chauffeurs.","Create a contact group":"Créer un groupe de contacts","Create a rule":"Créer une règle","Share his calendar":"Partager son calendrier","Create a category":"Créer une catégorie","His 240 transport partners are in an Excel file. Which format should he save it in before importing?":"Ses 240 partenaires de transport sont dans un fichier Excel. Dans quel format doit-il l'enregistrer avant l'importation ?","CSV UTF-8 keeps accented characters such as é and è.":"Le CSV UTF-8 conserve les caractères accentués comme é et è.","Excel Macro-Enabled Workbook":"Classeur Excel (prenant en charge les macros)","Plain text with tabs":"Texte brut avec tabulations","During the import, the \"Mobile\" column lands in the \"Business Fax\" field. Where does he fix this?":"Pendant l'importation, la colonne « Mobile » arrive dans le champ « Télécopie (bureau) ». Où corrige-t-il cela ?","Which setting stops the out-of-office message automatically when he returns?":"Quel paramètre arrête automatiquement le message d'absence à son retour ?","Request Responses":"Demander des réponses","Which is the best external reply?":"Quelle est la meilleure réponse externe ?","Give the return date and an alternative contact, without personal details.":"Indiquez la date de retour et un autre contact, sans détails personnels.","\"I am in Dubai with my family until the 13th.\"":"« Je suis à Dubaï en famille jusqu'au 13. »","\"I am away until 13 November. For urgent logistics matters, please contact Mrs Ngo Biyong at logistique@example.cm.\"":"« Je suis absent jusqu'au 13 novembre. Pour toute urgence logistique, veuillez contacter Mme Ngo Biyong à logistique@example.cm. »","\"Out.\"":"« Absent. »","\"Call me on my personal number.\"":"« Appelez-moi sur mon numéro personnel. »","Before your leave":"Avant votre congé","Before a mission to the regions or annual leave, set Automatic Replies, delegate your open tasks by forwarding them with a short note, and share your calendar with the colleague covering for you. Your partners are not left waiting, and nobody has to call you in Kribi to ask where a file is.":"Avant une mission dans les régions ou un congé annuel, activez les réponses automatiques, déléguez vos tâches en cours en les transférant avec une courte note, et partagez votre calendrier avec le collègue qui vous remplace. Vos partenaires n'attendent pas, et personne n'a besoin de vous appeler à Kribi pour demander où se trouve un dossier.","You flag an e-mail with the date \"Next Week\". Where can you see it besides the Inbox?":"Vous marquez un e-mail avec l'échéance « La semaine prochaine ». Où le voyez-vous en dehors de la boîte de réception ?","Only in the Sent Items folder":"Seulement dans le dossier Éléments envoyés","In your task list and in Microsoft To Do":"Dans votre liste de tâches et dans Microsoft To Do","In the Calendar as a meeting":"Dans le Calendrier, sous forme de réunion","Nowhere else":"Nulle part ailleurs","Flagged messages appear in the To-Do List in Outlook and in the Flagged email list of Microsoft To Do.":"Les messages marqués apparaissent dans la liste des tâches d'Outlook et dans la liste Courrier marqué d'un indicateur de Microsoft To Do.","Flag three e-mails that need action with realistic dates, and add a reminder to one":"Marquez d'un indicateur trois e-mails qui demandent une action, avec des dates réalistes, et ajoutez un rappel à l'un d'eux","Create two tasks with Ctrl + Shift + K that are not linked to e-mails":"Créez avec Ctrl + Maj + K deux tâches non liées à des e-mails","Create a contact group for your team":"Créez un groupe de contacts pour votre équipe","Prepare a five-row contact list in Excel, save it as CSV UTF-8 and import it":"Préparez dans Excel une liste de cinq contacts, enregistrez-la en CSV UTF-8 et importez-la","Write internal and external Automatic Replies for your next leave (do not turn them on yet)":"Rédigez des réponses automatiques internes et externes pour votre prochain congé (ne les activez pas encore)","Set up out of office automatic replies in Outlook":"Configurer les réponses automatiques d'absence dans Outlook","Import or export contacts in Outlook using a .csv file":"Importer ou exporter des contacts dans Outlook à l'aide d'un fichier .csv","Practice lab: e-mail, rules and meetings":"Atelier pratique : e-mails, règles et réunions","Triage a busy inbox with clear decisions":"Trier une boîte de réception chargée avec des décisions claires","Design rules and searches for a real mailbox":"Concevoir des règles et des recherches pour une vraie boîte aux lettres","Plan a meeting across several time zones":"Planifier une réunion sur plusieurs fuseaux horaires","Send a sensitive group mailing without exposing anyone":"Faire un envoi groupé sensible sans exposer personne","Exercise 1: Monday morning in Bafoussam":"Exercice 1 : lundi matin à Bafoussam","Triage the inbox":"Trier la boîte de réception","Clarisse manages the Bafoussam branch of a microfinance institution. It is Monday 8:00 and she has 64 unread messages. Decide what to do with each one: delete, do it now, delegate, defer or file.":"Clarisse dirige l'agence de Bafoussam d'un établissement de microfinance. Il est 8:00 ce lundi et elle a 64 messages non lus. Décidez quoi faire de chacun : supprimer, faire tout de suite, déléguer, différer ou classer.","Two minutes or less: do it now. Someone else's job: delegate. Longer with a deadline: defer with a flag. Finished but worth keeping: file. No value: delete.":"Deux minutes ou moins : faites-le tout de suite. Le travail de quelqu'un d'autre : déléguez. Plus long avec une échéance : différez avec un indicateur. Terminé mais utile à garder : classez. Sans valeur : supprimez.","A promotional newsletter from a printer she has never used":"Une lettre d'information promotionnelle d'un imprimeur avec qui elle n'a jamais travaillé","Do it now":"Le faire tout de suite","Delegate (forward)":"Déléguer (transférer)","Defer (flag with a date)":"Différer (indicateur avec une date)","File (move to a folder)":"Classer (déplacer vers un dossier)","A colleague asks for the phone number of the Dschang agent. She knows it by heart.":"Un collègue demande le numéro de téléphone de l'agent de Dschang. Elle le connaît par cœur.","Answering takes less than two minutes.":"Répondre prend moins de deux minutes.","A client complains about a loan repayment schedule. The credit officer handles schedules.":"Un client se plaint de son échéancier de remboursement de prêt. C'est l'agent de crédit qui gère les échéanciers.","Head office asks for the branch budget proposal by Friday. It will take three hours.":"Le siège demande la proposition de budget de l'agence pour vendredi. Cela prendra trois heures.","The signed minutes of last month's credit committee, for her records":"Le procès-verbal signé du comité de crédit du mois dernier, pour ses archives","After triage, which shortcut moves a selected message to a folder?":"Après le tri, quel raccourci déplace un message sélectionné vers un dossier ?","Ctrl + Shift + V":"Ctrl + Maj + V","Ctrl + R":"Ctrl + R","Ctrl + Shift + A":"Ctrl + Maj + A","Exercise 2: Rules for an NGO programme officer":"Exercice 2 : des règles pour un chargé de programme d'ONG","Design rules and searches":"Concevoir des règles et des recherches","Olivier coordinates a health programme for an NGO in Garoua. He receives daily reports from 14 health centres (all from addresses ending in @centres.example.org, subject starting with \"Rapport journalier\"), plus alerts from the stock system (stock@example.org). Answer the questions to build his rules and searches.":"Olivier coordonne un programme de santé pour une ONG à Garoua. Il reçoit les rapports quotidiens de 14 centres de santé (tous depuis des adresses se terminant par @centres.example.org, avec un objet commençant par « Rapport journalier »), ainsi que les alertes du système de stock (stock@example.org). Répondez aux questions pour construire ses règles et ses recherches.","Pick the condition that matches all the messages you want and nothing else. Exceptions keep important messages in the Inbox. Operators: from:, subject:, hasattachments:, received:.":"Choisissez la condition qui correspond à tous les messages voulus et à rien d'autre. Les exceptions gardent les messages importants dans la boîte de réception. Opérateurs : from:, subject:, hasattachments:, received:.","Best condition for the daily reports":"Meilleure condition pour les rapports quotidiens","The subject words match all 14 centres with one condition.":"Les mots de l'objet couvrent les 14 centres avec une seule condition.","with specific words in the subject: Rapport journalier":"avec des mots spécifiques dans l'objet : Rapport journalier","with an attachment":"avec une pièce jointe","from people or public group: Olivier":"de personnes ou groupe public : Olivier","Best action for the daily reports":"Meilleure action pour les rapports quotidiens","move it to the specified folder: Rapports centres":"la déplacer dans le dossier spécifié : Rapports centres","forward it to the director":"la transférer au directeur","mark it as High importance":"la marquer avec l'importance Haute","Stock alerts must stay visible only when they mention a stock-out (\"rupture\"). How?":"Les alertes de stock ne doivent rester visibles que lorsqu'elles signalent une rupture de stock (« rupture »). Comment faire ?","The exception keeps the dangerous alerts in the Inbox while the routine ones are filed.":"L'exception garde les alertes dangereuses dans la boîte de réception pendant que les alertes de routine sont classées.","Rule moving stock@example.org to a folder, except if the subject contains \"rupture\"":"Une règle qui déplace stock@example.org vers un dossier, sauf si l'objet contient « rupture »","Rule deleting all stock alerts":"Une règle qui supprime toutes les alertes de stock","Flag every stock alert":"Marquer chaque alerte de stock d'un indicateur","No rule: read them all":"Aucune règle : tout lire","He wants one button to mark a report as read, categorise it \"Validé\" and move it to Archive. What does he create?":"Il veut un seul bouton pour marquer un rapport comme lu, le classer « Validé » et le déplacer vers Archive. Que crée-t-il ?","Search: daily reports that have an attachment":"Recherche : les rapports quotidiens qui ont une pièce jointe","Search: messages from the stock system received last week":"Recherche : les messages du système de stock reçus la semaine dernière","Combine from: with received: and a date word such as yesterday, this week or last week.":"Combinez from: avec received: et un mot de date comme yesterday, this week ou last week.","Exercise 3: A four-site meeting":"Exercice 3 : une réunion sur quatre sites","Plan across time zones":"Planifier entre fuseaux horaires","A Douala logistics company holds a one-hour steering meeting on Tuesday 13 October 2026 with its partners in Paris (UTC+2 on that date), Nairobi (UTC+3) and Washington (UTC−4 on that date). Douala is UTC+1. Everyone works from 8:00 to 17:00 local time. Answer in hh:mm.":"Une entreprise de logistique de Douala tient un comité de pilotage d'une heure le mardi 13 octobre 2026 avec ses partenaires à Paris (UTC+2 à cette date), Nairobi (UTC+3) et Washington (UTC−4 à cette date). Douala est en UTC+1. Tout le monde travaille de 8:00 à 17:00, heure locale. Répondez au format hh:mm.","Work out each difference with Douala first: Paris +1 h, Nairobi +2 h, Washington −5 h in October. Watch out: Paris and Washington change their clocks, Douala and Nairobi do not.":"Calculez d'abord chaque écart avec Douala : Paris +1 h, Nairobi +2 h, Washington −5 h en octobre. Attention : Paris et Washington changent d'heure, Douala et Nairobi non.","If the meeting starts at 14:00 in Douala, what time is it in Paris?":"Si la réunion commence à 14:00 à Douala, quelle heure est-il à Paris ?","At 14:00 in Douala, what time is it in Nairobi?":"À 14:00 à Douala, quelle heure est-il à Nairobi ?","At 14:00 in Douala, what time is it in Washington?":"À 14:00 à Douala, quelle heure est-il à Washington ?","Which Douala start time keeps the whole hour inside everyone's working day?":"Quelle heure de début à Douala garde toute l'heure de réunion dans la journée de travail de chacun ?","At 9:00 and 11:00 it is still night or early morning in Washington (3:00 and 5:00). At 16:00 the meeting ends at 19:00 in Nairobi. At 14:00 it runs 9:00–10:00 in Washington and 16:00–17:00 in Nairobi.":"À 9:00 et 11:00, il fait encore nuit ou c'est très tôt à Washington (3:00 et 5:00). À 16:00, la réunion se termine à 19:00 à Nairobi. À 14:00, elle a lieu de 9:00 à 10:00 à Washington et de 16:00 à 17:00 à Nairobi.","The same meeting is held on Tuesday 8 December 2026, when Paris is back to UTC+1. What time is it in Paris at 14:00 in Douala?":"La même réunion a lieu le mardi 8 décembre 2026, quand Paris est revenu à UTC+1. Quelle heure est-il à Paris à 14:00 à Douala ?","In winter Paris and Douala show the same time.":"En hiver, Paris et Douala ont la même heure.","On 8 December Washington is UTC−5. What time is it there at 14:00 in Douala?":"Le 8 décembre, Washington est en UTC−5. Quelle heure y est-il à 14:00 à Douala ?","What is the safest way to avoid confusion for the series?":"Quel est le moyen le plus sûr d'éviter toute confusion pour la série ?","Outlook converts the time for each attendee, and the body confirms it for anyone reading on another device.":"Outlook convertit l'heure pour chaque participant, et le corps du message la confirme pour quiconque lit sur un autre appareil.","Write only \"14:00\" in the invitation":"Écrire seulement « 14:00 » dans l'invitation","Set the time zone in the meeting and state the time for each city in the body":"Définir le fuseau horaire dans la réunion et indiquer l'heure de chaque ville dans le corps","Send four separate invitations":"Envoyer quatre invitations séparées","Ask everyone to convert the time themselves":"Demander à chacun de convertir l'heure lui-même","Exercise 4: A sensitive group mailing":"Exercice 4 : un envoi groupé sensible","Send confidential results to 60 candidates":"Envoyer des résultats confidentiels à 60 candidats","A training centre in Yaoundé must tell 60 external candidates that the results of a recruitment test are available, and send the results file to the jury. Candidates must not see each other's addresses or scores. Answer each question.":"Un centre de formation de Yaoundé doit informer 60 candidats externes que les résultats d'un test de recrutement sont disponibles, et envoyer le fichier des résultats au jury. Les candidats ne doivent voir ni les adresses ni les notes des autres. Répondez à chaque question.","Think of privacy first: who can see which addresses, who may use Reply All, and whether a file should travel as an attachment or a link with limited access.":"Pensez d'abord à la confidentialité : qui peut voir quelles adresses, qui peut utiliser Répondre à tous, et si un fichier doit voyager en pièce jointe ou par un lien à accès limité.","Where do the 60 candidates' addresses go?":"Où vont les adresses des 60 candidats ?","In the body of the message":"Dans le corps du message","What goes in the To field of that message?":"Que met-on dans le champ À de ce message ?","Your own address gives the message a visible recipient; some mail servers treat messages with an empty To field as spam.":"Votre propre adresse donne au message un destinataire visible ; certains serveurs de messagerie traitent comme spam les messages dont le champ À est vide.","Nothing, it can stay empty":"Rien, il peut rester vide","The centre's own address":"L'adresse du centre lui-même","The first candidate":"Le premier candidat","The whole jury":"Tout le jury","The candidates are in a contact group called \"Candidats 2026\". Where do you put the group?":"Les candidats sont dans un groupe de contacts appelé « Candidats 2026 ». Où placez-vous le groupe ?","A contact group in To or Cc reveals every member's address.":"Un groupe de contacts dans À ou Cc révèle l'adresse de chaque membre.","It cannot be used":"Il ne peut pas être utilisé","A candidate clicks Reply All to protest. Who receives the reply?":"Un candidat clique sur Répondre à tous pour protester. Qui reçoit la réponse ?","Bcc recipients are never included in Reply All.":"Les destinataires en Cci ne sont jamais inclus dans Répondre à tous.","All 60 candidates":"Les 60 candidats","Only the sender and the To and Cc recipients":"Seulement l'expéditeur et les destinataires en À et Cc","The jury":"Le jury","Nobody":"Personne","How should the jury receive the results file with scores?":"Comment le jury doit-il recevoir le fichier des résultats avec les notes ?","As an attachment to the candidates' message":"En pièce jointe du message aux candidats","As a OneDrive link shared with the jury members only, in a separate message":"Par un lien OneDrive partagé uniquement avec les membres du jury, dans un message séparé","Pasted in the body for all":"Collé dans le corps du message pour tous","Printed and scanned":"Imprimé puis scanné","You notice a spelling mistake in a candidate's name one minute after sending the jury message. What is realistic?":"Une minute après avoir envoyé le message au jury, vous remarquez une faute dans le nom d'un candidat. Qu'est-ce qui est réaliste ?","Recall always removes it":"Le rappel le supprime toujours","Recall may work only if the jury are in your organisation and have not opened it; otherwise send a short correction":"Le rappel ne peut fonctionner que si les membres du jury sont dans votre organisation et ne l'ont pas ouvert ; sinon, envoyez une courte correction","Delete it from Sent Items":"Le supprimer des Éléments envoyés","Ask everyone to ignore Outlook":"Demander à tout le monde d'ignorer Outlook","Write the subject line for the candidates: it must name the test and say the results are available (French or English).":"Rédigez l'objet pour les candidats : il doit nommer le test et annoncer que les résultats sont disponibles (en français ou en anglais).","Name the test and the news. Avoid \"Urgent\" and exclamation marks.":"Nommez le test et la nouvelle. Évitez « Urgent » et les points d'exclamation.","To avoid sending too early by mistake, which classic Outlook setting holds the message until 8:00 the next day?":"Pour éviter un envoi trop tôt par erreur, quel paramètre d'Outlook classique retient le message jusqu'à 8:00 le lendemain ?","Request a Read Receipt":"Demander un accusé de lecture","Module 7 Quiz":"Quiz du module 7","Which field hides the recipients' addresses from each other?":"Quel champ masque les adresses des destinataires les unes des autres ?","Subject":"Objet","Nobody sees the Bcc list, and Bcc recipients are not included when someone clicks Reply All.":"Personne ne voit la liste Cci, et les destinataires en Cci ne sont pas inclus quand quelqu'un clique sur Répondre à tous.","In Outlook, what does Ctrl + F do when a message is selected?":"Dans Outlook, que fait Ctrl + F lorsqu'un message est sélectionné ?","Opens the search box":"Ouvre la zone de recherche","Flags the message":"Marque le message d'un indicateur","Forwards the message":"Transfère le message","Opens the font settings":"Ouvre les paramètres de police","In Outlook, Ctrl + F forwards. Use Ctrl + E to search.":"Dans Outlook, Ctrl + F transfère. Utilisez Ctrl + E pour rechercher.","A rule has conditions, actions and…":"Une règle comporte des conditions, des actions et…","categories":"des catégories","folders":"des dossiers","signatures":"des signatures","Exceptions exclude some messages that match the conditions, for example those marked High importance.":"Les exceptions excluent certains messages qui remplissent les conditions, par exemple ceux marqués d'une importance Haute.","Which search finds messages with attachments sent by Ngono?":"Quelle recherche trouve les messages avec pièces jointes envoyés par Ngono ?","Ngono + attachment":"Ngono + pièce jointe","from:Ngono hasattachments:yes":"from:Ngono hasattachments:yes","subject:Ngono":"subject:Ngono","to:Ngono attach":"to:Ngono attach","from: filters the sender and hasattachments:yes keeps only messages with files.":"from: filtre l'expéditeur et hasattachments:yes ne garde que les messages avec des fichiers.","What is the time zone of Cameroon?":"Quel est le fuseau horaire du Cameroun ?","UTC+0 all year":"UTC+0 toute l'année","UTC+1 in winter and UTC+2 in summer":"UTC+1 en hiver et UTC+2 en été","UTC+1 all year (WAT)":"UTC+1 toute l'année (WAT)","UTC+3 all year":"UTC+3 toute l'année","Cameroon uses West Africa Time, UTC+1, with no summer time.":"Le Cameroun utilise l'heure d'Afrique de l'Ouest, UTC+1, sans heure d'été.","Where do you see who has accepted or declined a meeting you organised?":"Où voyez-vous qui a accepté ou refusé une réunion que vous avez organisée ?","Sent Items":"Éléments envoyés","The Tracking view lists each attendee's response.":"L'affichage Suivi liste la réponse de chaque participant.","Which shortcut creates a new task?":"Quel raccourci crée une nouvelle tâche ?","Ctrl + Shift + K creates a task. Ctrl + Shift + A is a new appointment and Ctrl + Shift + L a new contact group.":"Ctrl + Maj + K crée une tâche. Ctrl + Maj + A crée un nouveau rendez-vous et Ctrl + Maj + L un nouveau groupe de contacts.","When does message recall have a chance to work?":"Quand le rappel d'un message a-t-il une chance de fonctionner ?","Always, within one hour":"Toujours, dans l'heure qui suit","Only for Gmail recipients":"Seulement pour les destinataires Gmail","Only between work accounts in the same organisation, if the message is still unopened":"Seulement entre comptes professionnels de la même organisation, si le message n'a pas encore été ouvert","Only for messages with attachments":"Seulement pour les messages avec pièces jointes","Recall needs Microsoft 365 work accounts in the same organisation and an unopened message. Otherwise send a correction.":"Le rappel exige des comptes professionnels Microsoft 365 de la même organisation et un message non ouvert. Sinon, envoyez une correction.","Choose the right paste option when moving Excel tables and charts into Word or PowerPoint":"Choisir la bonne option de collage pour transférer des tableaux et graphiques Excel vers Word ou PowerPoint","Decide between linking, embedding and pasting a picture":"Choisir entre lier, incorporer et coller une image","Update, repair and break links before a document is shared":"Mettre à jour, réparer et rompre les liaisons avant de partager un document","Most professional reports repeat figures that already live in Excel. Typing them again wastes time and creates errors: the report says 45 million while the workbook says 45.15 million. When you link the data instead, Word and PowerPoint show the figures from the workbook and can be refreshed when the workbook changes.":"La plupart des rapports professionnels reprennent des chiffres qui existent déjà dans Excel. Les ressaisir fait perdre du temps et crée des erreurs : le rapport annonce 45 millions alors que le classeur indique 45,15 millions. Si vous liez les données, Word et PowerPoint affichent les chiffres du classeur et peuvent être actualisés quand le classeur change.","The paste options for an Excel table":"Les options de collage d'un tableau Excel","Copy a range in Excel with":"Copiez une plage dans Excel avec",", click in Word or PowerPoint, then open Home › Paste (or the small Paste Options button that appears after pasting). Each icon gives a different result:":", cliquez dans Word ou PowerPoint, puis ouvrez Accueil › Coller (ou le petit bouton Options de collage qui apparaît après le collage). Chaque icône donne un résultat différent :","Paste option":"Option de collage","What you get":"Ce que vous obtenez","Keep Source Formatting":"Conserver la mise en forme source","A Word or PowerPoint table that looks like the Excel range":"Un tableau Word ou PowerPoint qui ressemble à la plage Excel","A one-off copy that must look exactly as in Excel":"Une copie ponctuelle qui doit être identique à Excel","Use Destination Styles":"Utiliser les styles de destination","A table that takes the fonts and colours of the report":"Un tableau qui prend les polices et les couleurs du rapport","A one-off copy that should match the report":"Une copie ponctuelle qui doit s'accorder avec le rapport","Link & Keep Source Formatting":"Lier et conserver la mise en forme source","A linked table with the Excel look":"Un tableau lié avec l'apparence d'Excel","Figures that change and must stay in the Excel look":"Des chiffres qui changent et doivent garder l'apparence d'Excel","Link & Use Destination Styles":"Lier et utiliser les styles de destination","A linked table with the report's look":"Un tableau lié avec l'apparence du rapport","Monthly or quarterly reports where the figures are refreshed":"Rapports mensuels ou trimestriels dont les chiffres sont actualisés","Picture":"Image","An image of the range":"Une image de la plage","Final documents and PDFs: nobody can change the figures":"Documents définitifs et PDF : personne ne peut modifier les chiffres","Keep Text Only":"Conserver uniquement le texte","Plain text, cells separated by tabs":"Du texte brut, les cellules séparées par des tabulations","You only need the numbers or words, without a table":"Vous n'avez besoin que des nombres ou des mots, sans tableau","Paste Special":"Collage spécial","In Word and PowerPoint, also Ctrl + Alt + V. Choose Paste link and Microsoft Excel Worksheet Object to create a link.":"Dans Word et PowerPoint, aussi Ctrl + Alt + V. Choisissez Coller avec liaison et Objet Feuille de calcul Microsoft Excel pour créer une liaison.","Link, embed or picture?":"Lier, incorporer ou coller une image ?","Where the data lives":"Où se trouvent les données","Advantage":"Avantage","Risk":"Risque","Link (Paste link)":"Liaison (Coller avec liaison)","In the Excel workbook; the document shows it":"Dans le classeur Excel ; le document les affiche","One update in Excel refreshes every report":"Une seule mise à jour dans Excel actualise tous les rapports","Breaks if the workbook is moved or renamed":"Se rompt si le classeur est déplacé ou renommé","Embed":"Incorporer","A full copy of the workbook inside the document":"Une copie complète du classeur à l'intérieur du document","Works without the original file":"Fonctionne sans le fichier d'origine","The whole workbook travels with the file, including hidden sheets; the file grows":"Le classeur entier voyage avec le fichier, feuilles masquées comprises ; le fichier grossit","Only an image in the document":"Seulement une image dans le document","Small, safe, looks the same everywhere":"Léger, sûr, identique partout","Cannot be edited or updated":"Impossible à modifier ou à mettre à jour","Embedding shares more than you think":"L'incorporation partage plus que vous ne le pensez","An embedded table or chart carries the entire workbook, not just the cells you copied. A slide sent to a partner can therefore contain the salaries sheet or the supplier prices. For files that leave your organisation, paste a picture or export a PDF.":"Un tableau ou un graphique incorporé contient le classeur entier, pas seulement les cellules copiées. Une diapositive envoyée à un partenaire peut donc contenir la feuille des salaires ou les prix des fournisseurs. Pour les fichiers qui quittent votre organisation, collez une image ou exportez un PDF.","Link a table step by step":"Lier un tableau étape par étape","Paste Link into a Word report":"Coller avec liaison dans un rapport Word","Save the Excel workbook first, in its final folder (ideally OneDrive or SharePoint), with its final name.":"Enregistrez d'abord le classeur Excel dans son dossier définitif (idéalement OneDrive ou SharePoint), sous son nom définitif.","Select the range, for example A1:F6, and press":"Sélectionnez la plage, par exemple A1:F6, et appuyez sur","In Word, click where the table should go and open":"Dans Word, cliquez à l'endroit où doit se trouver le tableau et ouvrez","Home › Paste › Paste Special":"Accueil › Coller › Collage spécial","Paste link":"Coller avec liaison","Microsoft Excel Worksheet Object":"Objet Feuille de calcul Microsoft Excel","(or HTML Format to get a Word table), and click OK.":"(ou Format HTML pour obtenir un tableau Word), puis cliquez sur OK.","Change a figure in Excel, save, then right-click the table in Word and choose":"Modifiez un chiffre dans Excel, enregistrez, puis cliquez avec le bouton droit sur le tableau dans Word et choisissez","Update Link":"Mettre à jour la liaison","Linked charts in PowerPoint":"Graphiques liés dans PowerPoint","Copy an Excel chart and paste it on a slide with":"Copiez un graphique Excel et collez-le sur une diapositive avec","Use Destination Theme & Link Data":"Utiliser le thème de destination et lier les données",": the chart takes the colours of the presentation but its data stays in Excel. To refresh it, select the chart and use Chart Design › Refresh Data. Chart Design › Edit Data opens the source workbook.":" : le graphique prend les couleurs de la présentation mais ses données restent dans Excel. Pour l'actualiser, sélectionnez le graphique et utilisez Création de graphique › Actualiser les données. Création de graphique › Modifier les données ouvre le classeur source.","Manage every link from one place":"Gérer toutes les liaisons au même endroit","Info":"Informations","Edit Links to Files":"Modifier les liens d'accès aux fichiers","Appears at the bottom right under Related Documents only when the file contains links. Works the same in Word and PowerPoint.":"Apparaît en bas à droite, sous Documents associés, uniquement quand le fichier contient des liaisons. Fonctionne de la même façon dans Word et PowerPoint.","Update Now":"Mettre à jour maintenant","refreshes the selected links.":"actualise les liaisons sélectionnées.","Change Source":"Changer de source","points a broken link to the workbook's new location or name.":"redirige une liaison rompue vers le nouvel emplacement ou le nouveau nom du classeur.","Break Link":"Rompre la liaison","turns the linked object into a fixed copy that no longer updates.":"transforme l'objet lié en copie fixe qui ne se met plus à jour.","Automatic update":"Mise à jour automatique","refreshes links when the file opens;":"actualise les liaisons à l'ouverture du fichier ;","Manual update":"Mise à jour manuelle","waits until you ask.":"attend que vous le demandiez.","Links in Word":"Les liaisons dans Word","Open Paste Special (Word and PowerPoint)":"Ouvrir le Collage spécial (Word et PowerPoint)","Update the selected linked table or field":"Mettre à jour le tableau lié ou le champ sélectionné","Select the whole document, then F9 updates every link":"Sélectionner tout le document ; F9 met ensuite à jour toutes les liaisons","Unlink: turn the selected linked table into fixed content":"Délier : transformer le tableau lié sélectionné en contenu fixe","Why links break in real offices":"Pourquoi les liaisons se rompent dans les vrais bureaux","An accountant in Douala links the monthly report to C:\\Users\\Nadine\\Desktop\\Ventes.xlsx, then moves the workbook to the team's SharePoint folder. The next month the report still shows March figures. Agree on the final folder and file name before you link, and never link to a file on a USB drive or the desktop.":"Une comptable à Douala lie le rapport mensuel à C:\\Users\\Nadine\\Desktop\\Ventes.xlsx, puis déplace le classeur dans le dossier SharePoint de l'équipe. Le mois suivant, le rapport affiche toujours les chiffres de mars. Mettez-vous d'accord sur le dossier et le nom de fichier définitifs avant de lier, et ne liez jamais un fichier situé sur une clé USB ou sur le bureau.","Choose the paste option":"Choisir l'option de collage","For each situation, choose the paste option you would use when copying an Excel range into Word or PowerPoint.":"Pour chaque situation, choisissez l'option de collage que vous utiliseriez pour copier une plage Excel dans Word ou PowerPoint.","Ask two questions: must the figures update later (link or not)? Must they look like Excel or like the report (source or destination)? Final PDFs and files for outsiders are usually a picture.":"Posez-vous deux questions : les chiffres doivent-ils se mettre à jour plus tard (liaison ou non) ? Doivent-ils ressembler à Excel ou au rapport (source ou destination) ? Les PDF définitifs et les fichiers destinés à l'extérieur reçoivent généralement une image.","The monthly sales table in the management report must use the report's fonts and be refreshed every month from the same workbook.":"Le tableau mensuel des ventes du rapport de gestion doit utiliser les polices du rapport et être actualisé chaque mois à partir du même classeur.","Link keeps the connection to the workbook; Destination Styles gives the report's look.":"La liaison garde le lien avec le classeur ; les styles de destination donnent l'apparence du rapport.","A final report will be exported to PDF for a donor. The figures must never change.":"Un rapport définitif sera exporté en PDF pour un bailleur. Les chiffres ne doivent jamais changer.","A picture cannot be edited or refreshed by mistake, and it shows the same way everywhere.":"Une image ne peut pas être modifiée ni actualisée par erreur, et elle s'affiche de la même façon partout.","You only need the three product names from a column to write them in a sentence.":"Vous n'avez besoin que des noms des trois produits d'une colonne pour les écrire dans une phrase.","Keep Text Only drops the table and keeps the words.":"Conserver uniquement le texte supprime le tableau et garde les mots.","A one-off price list must look exactly as the finance team formatted it in Excel, and you may adjust it in Word.":"Une liste de prix ponctuelle doit être exactement telle que l'équipe financière l'a mise en forme dans Excel, et vous pourrez l'ajuster dans Word.","No update needed, and the Excel look must be kept.":"Aucune mise à jour n'est nécessaire et l'apparence d'Excel doit être conservée.","The quarterly dashboard table must stay in the corporate Excel colours and be refreshed every quarter.":"Le tableau du tableau de bord trimestriel doit garder les couleurs Excel de l'entreprise et être actualisé chaque trimestre.","Linked, with the source formatting.":"Lié, avec la mise en forme source.","Link, embed or fix?":"Lier, incorporer ou réparer ?","Answer each question about linked and embedded data. Type keys joined with +, for example Ctrl + C.":"Répondez à chaque question sur les données liées et incorporées. Tapez les touches reliées par +, par exemple Ctrl + C.","Edit Links to Files is on File › Info. F9 updates a selected field in Word. Embedded objects carry the whole workbook.":"Modifier les liens d'accès aux fichiers se trouve dans Fichier › Informations. F9 met à jour un champ sélectionné dans Word. Les objets incorporés contiennent le classeur entier.","The workbook was renamed from Ventes.xlsx to 2026-04_Ventes.xlsx. The Word report now shows an error when you update the link. What do you do?":"Le classeur a été renommé de Ventes.xlsx en 2026-04_Ventes.xlsx. Le rapport Word affiche maintenant une erreur quand vous mettez à jour la liaison. Que faites-vous ?","Change Source points the link to the file's new name or location.":"Changer de source redirige la liaison vers le nouveau nom ou le nouvel emplacement du fichier.","Delete the table and retype the figures":"Supprimer le tableau et ressaisir les chiffres","File › Info › Edit Links to Files › Change Source":"Fichier › Informations › Modifier les liens d'accès aux fichiers › Changer de source","Save the report as PDF":"Enregistrer le rapport en PDF","Rename the Word document":"Renommer le document Word","In Word, which key updates the linked table you have selected?":"Dans Word, quelle touche met à jour le tableau lié que vous avez sélectionné ?","F9 updates the selected field. Select everything with Ctrl + A first to update all links.":"F9 met à jour le champ sélectionné. Sélectionnez d'abord tout avec Ctrl + A pour mettre à jour toutes les liaisons.","A slide sent to an external partner contains an embedded chart. The workbook also has a salaries sheet. What is the risk?":"Une diapositive envoyée à un partenaire externe contient un graphique incorporé. Le classeur contient aussi une feuille des salaires. Quel est le risque ?","Embedding places a full copy of the workbook in the presentation. Paste a picture instead.":"L'incorporation place une copie complète du classeur dans la présentation. Collez plutôt une image.","None: only the chart is sent":"Aucun : seul le graphique est envoyé","The chart colours may change":"Les couleurs du graphique peuvent changer","The partner can open the whole embedded workbook, including the salaries sheet":"Le partenaire peut ouvrir tout le classeur incorporé, feuille des salaires comprise","The file cannot be opened without the workbook":"Le fichier ne peut pas s'ouvrir sans le classeur","Which method keeps the file smallest and safe from changes?":"Quelle méthode garde le fichier le plus léger et à l'abri des modifications ?","Link":"Liaison","Which shortcut turns a selected linked table in Word into fixed content that no longer updates?":"Quel raccourci transforme un tableau lié sélectionné dans Word en contenu fixe qui ne se met plus à jour ?","Ctrl + Shift + F9 unlinks the field. You can also use Break Link in the Edit Links dialog.":"Ctrl + Maj + F9 délie le champ. Vous pouvez aussi utiliser Rompre la liaison dans la boîte de dialogue des liaisons.","You pasted a table with Paste link last month. This month the Excel file was moved to a new SharePoint folder. What happens when you update the link?":"Le mois dernier, vous avez collé un tableau avec Coller avec liaison. Ce mois-ci, le fichier Excel a été déplacé dans un nouveau dossier SharePoint. Que se passe-t-il quand vous mettez à jour la liaison ?","Word finds the file automatically":"Word retrouve le fichier automatiquement","The link cannot find the source until you use Change Source":"La liaison ne trouve pas la source tant que vous n'utilisez pas Changer de source","The table is deleted":"Le tableau est supprimé","Word converts the table to a picture":"Word convertit le tableau en image","A link stores the path to the workbook. When the file moves or is renamed, the path no longer works and you must point it to the new location with Change Source.":"Une liaison enregistre le chemin du classeur. Quand le fichier est déplacé ou renommé, ce chemin ne fonctionne plus et vous devez indiquer le nouvel emplacement avec Changer de source.","Create a small Excel table of monthly sales for four towns and save it to OneDrive":"Créez un petit tableau Excel des ventes mensuelles de quatre villes et enregistrez-le dans OneDrive","Paste it into Word three times: Use Destination Styles, Link & Use Destination Styles, and Picture":"Collez-le trois fois dans Word : Utiliser les styles de destination, Lier et utiliser les styles de destination, et Image","Change one figure in Excel, save, and update the linked table with a right-click › Update Link":"Modifiez un chiffre dans Excel, enregistrez, puis mettez à jour le tableau lié avec clic droit › Mettre à jour la liaison","Paste an Excel chart into PowerPoint with Use Destination Theme & Link Data and refresh it":"Collez un graphique Excel dans PowerPoint avec Utiliser le thème de destination et lier les données, puis actualisez-le","Open File › Info › Edit Links to Files and look at the source path of each link":"Ouvrez Fichier › Informations › Modifier les liens d'accès aux fichiers et regardez le chemin source de chaque liaison","Copy from Excel to another Office program":"Copier depuis Excel vers un autre programme Office","Insert and update Excel data in PowerPoint":"Insérer et mettre à jour des données Excel dans PowerPoint","Share files with the right people and the right permissions":"Partager des fichiers avec les bonnes personnes et les bonnes autorisations","Co-author documents, mention colleagues in comments and restore earlier versions":"Coéditer des documents, mentionner des collègues dans les commentaires et restaurer des versions antérieures","Keep working during internet cuts with Files On-Demand and clear team naming rules":"Continuer à travailler pendant les coupures d'internet grâce à Fichiers à la demande et à des règles de nommage claires pour l'équipe","When a report is written by four people who e-mail attachments to each other, nobody knows which copy is the right one. Storing the file once in the cloud and sharing a link means everyone works on the same file, Office saves every version, and you control exactly who can see or change it.":"Quand un rapport est écrit par quatre personnes qui s'envoient des pièces jointes, personne ne sait quelle copie est la bonne. Enregistrer le fichier une seule fois dans le cloud et partager un lien permet à tous de travailler sur le même fichier ; Office conserve chaque version et vous contrôlez exactement qui peut le voir ou le modifier.","OneDrive or SharePoint?":"OneDrive ou SharePoint ?","OneDrive for work or school":"OneDrive professionnel ou scolaire","SharePoint (and Teams files)":"SharePoint (et fichiers Teams)","Belongs to":"Appartient à","You":"Vous","The team or department":"L'équipe ou le service","Your drafts and files you share now and then":"Vos brouillons et les fichiers que vous partagez de temps en temps","Team files that must stay after someone leaves":"Les fichiers d'équipe qui doivent rester après le départ d'une personne","When someone leaves":"Quand quelqu'un part","Their OneDrive is removed after a delay":"Son OneDrive est supprimé après un délai","Files stay with the team site":"Les fichiers restent sur le site de l'équipe","Your draft of the monthly report":"Votre brouillon du rapport mensuel","The shared Finance folder with all quarterly packages":"Le dossier partagé Finances avec tous les dossiers trimestriels","OneDrive or Sites":"OneDrive ou Sites","Sites lists the SharePoint sites and Teams you belong to.":"Sites liste les sites SharePoint et les équipes Teams dont vous êtes membre.","Share with the right people":"Partager avec les bonnes personnes","at the top right of Word, Excel or PowerPoint (or right-click a file on onedrive.com). Open the link settings to choose who can use the link, then choose what they can do:":"en haut à droite de Word, Excel ou PowerPoint (ou cliquez avec le bouton droit sur un fichier dans onedrive.com). Ouvrez les paramètres du lien pour choisir qui peut l'utiliser, puis ce que ces personnes peuvent faire :","lets the person change the file,":"permet de modifier le fichier,","Can view":"Peut afficher","lets them read and download it only. To stop sharing later, open Manage access and remove the person or the link.":"permet seulement de le lire et de le télécharger. Pour arrêter le partage plus tard, ouvrez Gérer l'accès et retirez la personne ou le lien.","Link setting":"Paramètre du lien","Who can open it":"Qui peut l'ouvrir","Typical use":"Usage type","Specific people":"Personnes spécifiques","Only the people you name, signed in with that address":"Uniquement les personnes que vous nommez, connectées avec cette adresse","Most work files, auditors, partners":"La plupart des fichiers de travail, auditeurs, partenaires","People in your organisation":"Personnes de votre organisation","Any colleague who has the link":"Tout collègue qui dispose du lien","Internal procedures, staff notices":"Procédures internes, notes au personnel","People with existing access":"Personnes ayant un accès existant","Only people who already have access":"Uniquement les personnes qui ont déjà accès","Sending a reminder link without changing permissions":"Renvoyer un lien de rappel sans modifier les autorisations","Anyone with the link":"Tout le monde disposant du lien","Anyone, even if the link is forwarded":"N'importe qui, même si le lien est transféré","Public flyers or forms; avoid for confidential files":"Affiches ou formulaires publics ; à éviter pour les fichiers confidentiels","Set the right sharing permissions":"Définir les bonnes autorisations de partage","Choose the link setting and permission for each situation.":"Choisissez le paramètre du lien et l'autorisation pour chaque situation.","Start with the narrowest option that still works. Anyone with the link is only for truly public content.":"Commencez par l'option la plus restreinte qui fonctionne encore. Tout le monde disposant du lien est réservé aux contenus vraiment publics.","Your colleague Brice writes half of the NGO's annual report with you.":"Votre collègue Brice rédige avec vous la moitié du rapport annuel de l'ONG.","He needs to change the document, and only he should get the access.":"Il doit modifier le document, et lui seul doit recevoir l'accès.","Specific people, Can edit":"Personnes spécifiques, Peut modifier","Specific people, Can view":"Personnes spécifiques, Peut afficher","People in your organisation, Can view":"Personnes de votre organisation, Peut afficher","Anyone with the link, Can view":"Tout le monde disposant du lien, Peut afficher","An external auditor from a Yaoundé firm must read the final accounts.":"Un auditeur externe d'un cabinet de Yaoundé doit lire les comptes définitifs.","The auditor reads but must not change the accounts. Naming the person stops the link working for anyone else.":"L'auditeur lit mais ne doit pas modifier les comptes. Nommer la personne empêche le lien de fonctionner pour quelqu'un d'autre.","The HR procedures manual must be readable by every staff member.":"Le manuel des procédures RH doit pouvoir être lu par tout le personnel.","All colleagues can read it, nobody outside the organisation can.":"Tous les collègues peuvent le lire, personne en dehors de l'organisation.","A job advertisement will be posted on the company's Facebook page.":"Une offre d'emploi sera publiée sur la page Facebook de l'entreprise.","The content is public anyway, so a view-only Anyone link is acceptable.":"Le contenu est de toute façon public, donc un lien Tout le monde en lecture seule est acceptable.","The Director General must approve the budget but should not modify the workbook.":"La Directrice générale doit approuver le budget mais ne doit pas modifier le classeur.","View access for one named person.":"Un accès en lecture pour une seule personne nommée.","Co-authoring in real time":"La coédition en temps réel","When a Word, Excel or PowerPoint file is saved in OneDrive or SharePoint, several people can edit it at the same time. Their pictures or initials appear at the top of the window and coloured flags show where each person is working. AutoSave must be on, and the file must be in a modern format (.docx, .xlsx, .pptx), not an old .doc or .xls.":"Quand un fichier Word, Excel ou PowerPoint est enregistré dans OneDrive ou SharePoint, plusieurs personnes peuvent le modifier en même temps. Leurs photos ou initiales apparaissent en haut de la fenêtre et des repères de couleur montrent où chacun travaille. L'enregistrement automatique doit être activé et le fichier doit être dans un format moderne (.docx, .xlsx, .pptx), pas un ancien .doc ou .xls.","Mention a colleague in a comment":"Mentionner un collègue dans un commentaire","Select the text or cell concerned and choose":"Sélectionnez le texte ou la cellule concernés et choisissez","Type":"Tapez","followed by the first letters of your colleague's name and pick them from the list.":"suivi des premières lettres du nom de votre collègue, puis choisissez-le dans la liste.","Write the request, for example \"please confirm the Garoua figure\", and post the comment.":"Rédigez la demande, par exemple « merci de confirmer le chiffre de Garoua », et publiez le commentaire.","Your colleague receives an e-mail with a link that opens the file at your comment.":"Votre collègue reçoit un e-mail avec un lien qui ouvre le fichier à l'endroit de votre commentaire.","Version History":"Historique des versions","Or click the file name in the title bar. On onedrive.com, right-click the file › Version history.":"Ou cliquez sur le nom du fichier dans la barre de titre. Dans onedrive.com, clic droit sur le fichier › Historique des versions.","Restore an earlier version":"Restaurer une version antérieure","Open Version History and select a version by its date, time and author.":"Ouvrez l'historique des versions et sélectionnez une version d'après sa date, son heure et son auteur.","It opens as a read-only copy. Check that it contains what you need.":"Elle s'ouvre en lecture seule. Vérifiez qu'elle contient ce dont vous avez besoin.","Restore":"Restaurer",". The old version becomes the current one and the replaced version stays in the history.":". L'ancienne version devient la version actuelle et la version remplacée reste dans l'historique.","If you only need a paragraph, copy it from the old version instead of restoring the whole file.":"Si vous n'avez besoin que d'un paragraphe, copiez-le depuis l'ancienne version au lieu de restaurer tout le fichier.","Check out and check in":"Extraire et archiver","Some SharePoint libraries ask you to":"Certaines bibliothèques SharePoint vous obligent à","check out":"extraire","a file before editing. While it is checked out, only you can change it; the others can only read. When you finish,":"un fichier avant de le modifier. Tant qu'il est extrait, vous seul pouvez le modifier ; les autres peuvent seulement le lire. Quand vous avez terminé,","check in":"archivez-le","with a short comment describing your change. Check-out and co-authoring do not mix: use check-out only for files such as signed procedures that one person at a time should edit. In the library, select the file, then … › More › Check out; in the desktop apps, File › Info › Check Out appears when the library supports it.":"avec un court commentaire qui décrit votre modification. Extraction et coédition ne vont pas ensemble : réservez l'extraction aux fichiers, comme les procédures signées, qu'une seule personne à la fois doit modifier. Dans la bibliothèque, sélectionnez le fichier, puis … › Plus › Extraire ; dans les applications de bureau, Fichier › Informations › Extraire apparaît quand la bibliothèque le permet.","Working with an unstable connection":"Travailler avec une connexion instable","OneDrive icon":"Icône OneDrive","Blue cloud":"Nuage bleu","Online-only: the file needs the internet to open":"En ligne uniquement : le fichier a besoin d'internet pour s'ouvrir","Green tick in a white circle":"Coche verte dans un cercle blanc","Available on this device since you last opened it":"Disponible sur cet appareil depuis votre dernière ouverture","White tick in a green circle":"Coche blanche dans un cercle vert","Always kept on this device, even offline":"Toujours conservé sur cet appareil, même hors connexion","Two blue arrows":"Deux flèches bleues","Syncing in progress":"Synchronisation en cours","Before a field mission or a long power cut":"Avant une mission de terrain ou une longue coupure de courant","A programme officer leaving Yaoundé for three days of field visits around Garoua right-clicks the project folder in File Explorer and chooses":"Une chargée de programme qui quitte Yaoundé pour trois jours de visites de terrain autour de Garoua clique avec le bouton droit sur le dossier du projet dans l'Explorateur de fichiers et choisit","Always keep on this device":"Toujours conserver sur cet appareil",". She keeps working offline, and OneDrive uploads her changes as soon as the connection returns. On a mobile data bundle, pause syncing from the OneDrive icon to save credit.":". Elle continue à travailler hors connexion, et OneDrive envoie ses modifications dès que la connexion revient. Avec un forfait de données mobiles, suspendez la synchronisation depuis l'icône OneDrive pour économiser votre crédit.","Naming and folder conventions for teams":"Conventions de nommage et de dossiers pour les équipes","Folders: number them by stage, for example":"Dossiers : numérotez-les par étape, par exemple","Files:":"Fichiers :","without _v1, _v2 inside the cloud, because Version History keeps the versions for you.":"sans _v1, _v2 dans le cloud, car l'historique des versions conserve les versions pour vous.","Add a version number only to copies that leave the team, such as a PDF sent to a donor.":"Ajoutez un numéro de version uniquement aux copies qui quittent l'équipe, comme un PDF envoyé à un bailleur.","Never keep a personal copy named \"Rapport_final_Awa\": comment in the shared file instead.":"Ne gardez jamais une copie personnelle nommée « Rapport_final_Awa » : commentez plutôt dans le fichier partagé.","Recover and co-author":"Récupérer et coéditer","Answer each question about version history, comments, check-out and offline work.":"Répondez à chaque question sur l'historique des versions, les commentaires, l'extraction et le travail hors connexion.","Version History is on File › Info. Mentions start with a special character. Co-authoring needs a modern file format.":"L'historique des versions se trouve dans Fichier › Informations. Les mentions commencent par un caractère spécial. La coédition exige un format de fichier moderne.","Yesterday a colleague deleted the whole Recommendations section of a shared report. How do you get it back?":"Hier, un collègue a supprimé toute la section Recommandations d'un rapport partagé. Comment la récupérer ?","Undo only works in your own session. Version History keeps the earlier versions saved in the cloud.":"L'annulation ne fonctionne que dans votre propre session. L'historique des versions conserve les versions antérieures enregistrées dans le cloud.","Ctrl + Z":"Ctrl + Z","File › Info › Version History, then open an earlier version":"Fichier › Informations › Historique des versions, puis ouvrir une version antérieure","Ask IT to restore last month's backup":"Demander au service informatique de restaurer la sauvegarde du mois dernier","Rewrite the section":"Réécrire la section","Which character do you type in a comment to mention a colleague?":"Quel caractère tapez-vous dans un commentaire pour mentionner un collègue ?","Two colleagues cannot edit Budget.xls at the same time, although it is on SharePoint. Why?":"Deux collègues ne peuvent pas modifier Budget.xls en même temps, bien qu'il soit sur SharePoint. Pourquoi ?","Real-time co-authoring needs the modern formats: .docx, .xlsx and .pptx.":"La coédition en temps réel exige les formats modernes : .docx, .xlsx et .pptx.","The file is too large":"Le fichier est trop volumineux","The file uses the old .xls format; save it as .xlsx":"Le fichier utilise l'ancien format .xls ; enregistrez-le en .xlsx","SharePoint does not support Excel":"SharePoint ne prend pas en charge Excel","AutoSave only works on Fridays":"L'enregistrement automatique ne fonctionne que le vendredi","You travel to Garoua tomorrow with no reliable internet. What do you do with the project folder?":"Vous partez demain à Garoua sans connexion internet fiable. Que faites-vous du dossier du projet ?","The files are downloaded now and stay available offline. Changes sync when you are back online.":"Les fichiers sont téléchargés maintenant et restent disponibles hors connexion. Les modifications se synchronisent à votre retour en ligne.","Free up space":"Libérer de l'espace","Share it with Anyone":"Le partager avec Tout le monde","Compress it to ZIP and e-mail it to yourself":"Le compresser en ZIP et vous l'envoyer par e-mail","A procedure in a SharePoint library is checked out to a colleague who is on leave. What is the right action?":"Une procédure d'une bibliothèque SharePoint est extraite par un collègue en congé. Quelle est la bonne action ?","A site owner can release the check-out. Copies create two versions of the truth.":"Un propriétaire du site peut libérer l'extraction. Les copies créent deux versions de la vérité.","Save a copy with another name and edit that":"Enregistrer une copie sous un autre nom et modifier celle-ci","Ask the library owner to check it in or discard the check-out":"Demander au propriétaire de la bibliothèque de l'archiver ou d'ignorer l'extraction","Delete the file":"Supprimer le fichier","Wait until the colleague returns next month":"Attendre le retour du collègue le mois prochain","You want an external partner to read a confidential report without the link working for anyone else. Which link setting do you choose?":"Vous voulez qu'un partenaire externe lise un rapport confidentiel sans que le lien fonctionne pour quelqu'un d'autre. Quel paramètre de lien choisissez-vous ?","Anyone with the link, Can edit":"Tout le monde disposant du lien, Peut modifier","Specific people only works for the addresses you enter, so a forwarded link is useless to others. Can view prevents changes.":"Personnes spécifiques ne fonctionne que pour les adresses que vous saisissez : un lien transféré est inutile pour les autres. Peut afficher empêche les modifications.","Save a Word document to OneDrive and share it with one colleague as Can view":"Enregistrez un document Word dans OneDrive et partagez-le avec un collègue en Peut afficher","Ask a colleague to open the same file and edit it with you at the same time":"Demandez à un collègue d'ouvrir le même fichier et de le modifier avec vous en même temps","Add a comment with an @mention and check that the e-mail notification arrives":"Ajoutez un commentaire avec une @mention et vérifiez que la notification par e-mail arrive","Open Version History and restore a version from earlier in the day":"Ouvrez l'historique des versions et restaurez une version antérieure de la journée","Set one folder to Always keep on this device and check the icon changes":"Réglez un dossier sur Toujours conserver sur cet appareil et vérifiez que l'icône change","Share files and folders in Microsoft OneDrive":"Partager des fichiers et des dossiers dans Microsoft OneDrive","Restore a previous version of a file stored in OneDrive":"Restaurer une version précédente d'un fichier stocké dans OneDrive","Compute quarterly results in Excel and link them into a structured Word report":"Calculer les résultats trimestriels dans Excel et les lier dans un rapport Word structuré","Summarise the results on clear PowerPoint slides":"Résumer les résultats sur des diapositives PowerPoint claires","Send the package by Outlook to the right people with a secure OneDrive link and a final quality check":"Envoyer le dossier par Outlook aux bonnes personnes, avec un lien OneDrive sécurisé et un dernier contrôle qualité","This capstone brings the whole programme together. You play the role of a business analyst who must deliver the quarterly performance package to the Director General: one Excel workbook, one Word report, one short presentation and one e-mail. The labs below follow the same scenario from start to finish.":"Ce projet final rassemble tout le programme. Vous jouez le rôle d'un analyste qui doit remettre le dossier de performance trimestriel à la Directrice générale : un classeur Excel, un rapport Word, une courte présentation et un e-mail. Les exercices ci-dessous suivent le même scénario du début à la fin.","The brief":"Le cahier des charges","AgroNova Distribution SARL sells seeds, fertiliser and small equipment to retailers from its head office in Bafoussam and three branches in Douala, Yaoundé and Garoua. The Director General, Mrs Chantal Ebongue, wants the Q3 2026 performance package on her desk by Friday 9 October, before the board meeting. The Finance Manager, Mr Paul Nkeng, must be kept informed.":"AgroNova Distribution SARL vend des semences, des engrais et du petit matériel aux détaillants depuis son siège de Bafoussam et trois agences à Douala, Yaoundé et Garoua. La Directrice générale, Mme Chantal Ebongue, veut le dossier de performance du T3 2026 sur son bureau au plus tard le vendredi 9 octobre, avant le conseil d'administration. Le Directeur financier, M. Paul Nkeng, doit être tenu informé.","What the package contains":"Contenu du dossier","Content":"Contenu","Key skills":"Compétences clés","2026-Q3_Results.xlsx":"2026-Q3_Results.xlsx","Targets, actual sales, achievement rate and status per region":"Objectifs, ventes réelles, taux de réalisation et statut par région","Formulas, absolute references, IF":"Formules, références absolues, SI","2026-Q3_Performance-report.docx":"2026-Q3_Performance-report.docx","Heading styles, a table of contents, a linked results table, recommendations":"Styles de titre, table des matières, tableau de résultats lié, recommandations","Styles, TOC, Paste link, captions":"Styles, table des matières, Coller avec liaison, légendes","2026-Q3_Board-summary.pptx":"2026-Q3_Board-summary.pptx","Five slides that tell the story in one minute each":"Cinq diapositives qui racontent l'histoire, une minute chacune","Clear titles, few bullets, linked chart":"Titres clairs, peu de puces, graphique lié","E-mail in Outlook":"E-mail dans Outlook","A short message with one OneDrive link to the folder":"Un court message avec un seul lien OneDrive vers le dossier","Recipients, subject, sharing permissions":"Destinataires, objet, autorisations de partage","Step 1: compute the results in Excel":"Étape 1 : calculer les résultats dans Excel","Q3 results by region":"Résultats du T3 par région","with each region's achievement rate (actual divided by target),":"avec le taux de réalisation de chaque région (réel divisé par objectif),","with the variance (actual minus target),":"avec l'écart (réel moins objectif),","with the status \"Achieved\" when the rate is 100% or more and \"Below target\" otherwise, then":"avec le statut \"Achieved\" quand le taux atteint 100 % ou plus et \"Below target\" sinon, puis","with the totals and the overall rate.":"avec les totaux et le taux global.","D2 is =C2/B2 and E2 is =C2-B2. The status uses IF: =IF(D2>=1,\"Achieved\",\"Below target\"). The overall rate is the total actual divided by the total target, not the average of the four rates.":"D2 vaut =C2/B2 et E2 vaut =C2-B2. Le statut utilise SI (IF) : =IF(D2>=1,\"Achieved\",\"Below target\"). Le taux global est le total réel divisé par l'objectif total, pas la moyenne des quatre taux.","Step 2: build the Word report":"Étape 2 : construire le rapport Word","Report structure":"Structure du rapport","Apply":"Appliquez","to the report title and chapter titles, and":"au titre du rapport et aux titres des chapitres, et","to the sections inside them.":"aux sections qu'ils contiennent.","Insert a table of contents on page 2 with":"Insérez une table des matières en page 2 avec","and choose an automatic style.":"et choisissez un style automatique.","In Excel, copy A1:F6 and paste it into the Results section with":"Dans Excel, copiez A1:F6 et collez la plage dans la section Résultats avec","Add a caption under the table with":"Ajoutez une légende sous le tableau avec","References › Insert Caption":"Références › Insérer une légende",", for example \"Table 1: Q3 2026 sales by region\".":", par exemple « Tableau 1 : ventes du T3 2026 par région ».","When the figures change, update the links, then right-click the table of contents and choose":"Quand les chiffres changent, mettez à jour les liaisons, puis cliquez avec le bouton droit sur la table des matières et choisissez","Update Field › Update entire table":"Mettre à jour les champs › Mettre à jour toute la table","Format the report section":"Mettre en forme la section du rapport","Make the title a":"Appliquez au titre le style",", make \"Results by region\" and \"Recommendations\"":", appliquez à « Results by region » et « Recommendations » le style","justify":"justifiez","the results paragraph, make the total":"le paragraphe des résultats, mettez le total","121 660 000 FCFA bold":"121 660 000 FCFA en gras",", and turn the three recommendations into a":", et transformez les trois recommandations en","Use the Styles menu for headings. Click inside the results paragraph before choosing Justify. Select the three recommendation lines together before clicking Numbering.":"Utilisez le menu Styles pour les titres. Cliquez dans le paragraphe des résultats avant de choisir Justifier. Sélectionnez ensemble les trois lignes de recommandations avant de cliquer sur Numérotation.","Step 3: a five-slide summary":"Étape 3 : une synthèse en cinq diapositives","Title that states the message":"Titre qui énonce le message","Q3 2026 performance package":"Dossier de performance du T3 2026","Company name, date, presenter":"Nom de l'entreprise, date, présentateur","Sales reached 98.9% of target":"Les ventes ont atteint 98,9 % de l'objectif","Linked chart: target and actual by region":"Graphique lié : objectif et réel par région","Douala and Bafoussam beat their targets":"Douala et Bafoussam dépassent leurs objectifs","Two or three short bullets":"Deux ou trois puces courtes","Garoua and Yaoundé need action":"Garoua et Yaoundé doivent agir","Causes in a few words":"Les causes en quelques mots","Three decisions for the board":"Trois décisions pour le conseil","The recommendations from the report":"Les recommandations du rapport","Rewrite the key results slide":"Réécrire la diapositive des résultats clés","Rewrite slide 2 for the board: a title of":"Réécrivez la diapositive 2 pour le conseil : un titre de","8 words or fewer":"8 mots maximum","that states the result, and":"qui énonce le résultat, et","10 words or fewer":"10 mots maximum","Put the conclusion in the title, for example \"Q3 sales reached 98.9% of target\". Keep one idea per bullet and move details to the report.":"Mettez la conclusion dans le titre, par exemple « Ventes du T3 : 98,9 % de l'objectif ». Une idée par puce, et laissez les détails au rapport.","Step 4: send the package from Outlook":"Étape 4 : envoyer le dossier depuis Outlook",": the person who must act, here the Director General.":" : la personne qui doit agir, ici la Directrice générale.",": people who only need to know, here the Finance Manager.":" : les personnes qui ont seulement besoin d'être informées, ici le Directeur financier.",": specific and searchable, for example \"Q3 2026 performance package for approval\".":" : précis et facile à retrouver, par exemple « Dossier de performance T3 2026 pour approbation ».","Body":"Corps",": three to five lines: what is attached, the key result, what you expect and by when.":" : trois à cinq lignes : ce qui est joint, le résultat clé, ce que vous attendez et pour quand.","Files":"Fichiers",": one OneDrive or SharePoint link to the folder instead of three heavy attachments; check the link permissions before sending.":" : un seul lien OneDrive ou SharePoint vers le dossier au lieu de trois lourdes pièces jointes ; vérifiez les autorisations du lien avant l'envoi.","only for large external lists, never to hide a recipient from a colleague.":"uniquement pour de grandes listes externes, jamais pour cacher un destinataire à un collègue.","Prepare the e-mail to the Director General":"Préparer l'e-mail à la Directrice générale","Complete the e-mail that sends the Q3 package to Mrs Ebongue, with Mr Nkeng informed.":"Complétez l'e-mail qui envoie le dossier du T3 à Mme Ebongue, en tenant M. Nkeng informé.","The person who must approve goes in To, the person who only needs to know goes in Cc. The link should work only for the people who need it.":"La personne qui doit approuver va dans À, celle qui doit seulement être informée va dans Cc. Le lien ne doit fonctionner que pour les personnes qui en ont besoin.","Who goes in the To line?":"Qui mettez-vous dans la ligne À ?","She is the person who must read and approve the package.":"C'est elle qui doit lire et approuver le dossier.","Paul Nkeng, Finance Manager":"Paul Nkeng, Directeur financier","Chantal Ebongue, Director General":"Chantal Ebongue, Directrice générale","All staff":"Tout le personnel","Nobody: use Bcc only":"Personne : utiliser uniquement Cci","Who goes in the Cc line?":"Qui mettez-vous dans la ligne Cc ?","The Finance Manager is kept informed but is not asked to act.":"Le Directeur financier est tenu informé mais n'a pas d'action à mener.","The transport contractor":"Le transporteur","The board members' personal addresses":"Les adresses personnelles des administrateurs","Type a clear subject line that mentions the quarter and the year.":"Tapez un objet clair qui mentionne le trimestre et l'année.","A specific subject with the period makes the e-mail easy to find before the board meeting.":"Un objet précis qui indique la période rend l'e-mail facile à retrouver avant le conseil.","How do you give her the three files?":"Comment lui transmettez-vous les trois fichiers ?","One link keeps the package in one place, stays light on slow connections, and only she can open it.":"Un seul lien garde le dossier au même endroit, reste léger sur une connexion lente, et elle seule peut l'ouvrir.","Attach the three files (about 18 MB)":"Joindre les trois fichiers (environ 18 Mo)","A link to the OneDrive folder shared with Specific people, Can view":"Un lien vers le dossier OneDrive partagé avec Personnes spécifiques, Peut afficher","An Anyone link with Can edit":"Un lien Tout le monde avec Peut modifier","Copy them on a USB drive":"Les copier sur une clé USB","The report's table is linked to the workbook. What must you do before exporting the report to PDF?":"Le tableau du rapport est lié au classeur. Que devez-vous faire avant d'exporter le rapport en PDF ?","A PDF freezes whatever the report shows at export time, so refresh the links and the table of contents first.":"Un PDF fige ce que le rapport affiche au moment de l'export : actualisez d'abord les liaisons et la table des matières.","Nothing, PDFs update themselves":"Rien, les PDF se mettent à jour tout seuls","Update the links and the table of contents, then export":"Mettre à jour les liaisons et la table des matières, puis exporter","Delete the table":"Supprimer le tableau","Change the paste option to Keep Text Only":"Changer l'option de collage en Conserver uniquement le texte","Quality checklist before you press Send":"Liste de contrôle qualité avant d'appuyer sur Envoyer","The totals in Word and PowerPoint match the workbook exactly after updating the links.":"Les totaux dans Word et PowerPoint correspondent exactement au classeur après la mise à jour des liaisons.","The table of contents is updated and all headings use Heading styles.":"La table des matières est à jour et tous les titres utilisent les styles de titre.","Every slide title states a message; no slide has more than four or five bullets.":"Chaque titre de diapositive énonce un message ; aucune diapositive n'a plus de quatre ou cinq puces.","Spelling is checked in the right language for each passage (French and English).":"L'orthographe est vérifiée dans la bonne langue pour chaque passage (français et anglais).","File names follow the team convention and the files sit in the shared folder.":"Les noms de fichiers suivent la convention de l'équipe et les fichiers sont dans le dossier partagé.","The link permissions are Specific people and Can view for the Director General.":"Les autorisations du lien sont Personnes spécifiques et Peut afficher pour la Directrice générale.","Nothing confidential is embedded: no hidden sheets, comments or personal notes remain (File › Info › Check for Issues › Inspect Document).":"Rien de confidentiel n'est incorporé : il ne reste ni feuilles masquées, ni commentaires, ni notes personnelles (Fichier › Informations › Vérifier la présence de problèmes › Inspecter le document).","Check for Issues":"Vérifier la présence de problèmes","Inspect Document":"Inspecter le document","Finds comments, hidden text, document properties and embedded content before you share.":"Trouve les commentaires, le texte masqué, les propriétés du document et le contenu incorporé avant le partage.","The workbook shows a total of 121 660 000 FCFA but the Word report still shows 119 800 000 FCFA. What is the most likely cause?":"Le classeur affiche un total de 121 660 000 FCFA mais le rapport Word indique toujours 119 800 000 FCFA. Quelle est la cause la plus probable ?","The report was pasted as a picture or the linked table has not been updated":"Le tableau a été collé comme image ou le tableau lié n'a pas été mis à jour","Word rounds large numbers":"Word arrondit les grands nombres","Excel has a formula error":"Excel contient une erreur de formule","The PDF was exported too early":"Le PDF a été exporté trop tôt","A picture never changes, and a link shows new figures only after it is updated (right-click › Update Link, or F9). Always compare the totals before sending.":"Une image ne change jamais, et une liaison n'affiche les nouveaux chiffres qu'après sa mise à jour (clic droit › Mettre à jour la liaison, ou F9). Comparez toujours les totaux avant l'envoi.","Build the AgroNova results workbook and save it to a OneDrive folder named 2026-Q3_Package":"Construisez le classeur de résultats d'AgroNova et enregistrez-le dans un dossier OneDrive nommé 2026-Q3_Package","Write a two-page Word report with a table of contents, a linked results table and a caption":"Rédigez un rapport Word de deux pages avec une table des matières, un tableau de résultats lié et une légende","Create the five-slide summary with a linked chart on slide 2":"Créez la synthèse de cinq diapositives avec un graphique lié sur la diapositive 2","Draft the Outlook e-mail with the right To and Cc recipients and a view-only folder link":"Préparez l'e-mail Outlook avec les bons destinataires en À et en Cc et un lien vers le dossier en lecture seule","Go through the quality checklist and run Inspect Document on the report":"Parcourez la liste de contrôle qualité et lancez Inspecter le document sur le rapport","Exam MO-400: Microsoft Outlook":"Examen MO-400 : Microsoft Outlook","Practice lab: integrated Office deliverables":"Atelier pratique : livrables Office intégrés","Choose paste options for tables and charts moved between Office apps":"Choisir les options de collage pour les tableaux et graphiques transférés entre applications Office","Format a report section that presents linked figures":"Mettre en forme une section de rapport qui présente des chiffres liés","Clean and summarise exported data with Excel formulas":"Nettoyer et résumer des données exportées avec des formules Excel","Combine Excel, Word, PowerPoint, OneDrive and Outlook decisions in one deliverable":"Combiner des décisions Excel, Word, PowerPoint, OneDrive et Outlook dans un même livrable","Exercise 1: The school enrolment brief":"Exercice 1 : la note sur les effectifs scolaires","Paste the enrolment figures":"Coller les chiffres des effectifs","A regional education delegation in Bertoua keeps its school enrolment figures in Excel. Choose the paste option for each document.":"Une délégation régionale de l'éducation à Bertoua tient ses effectifs scolaires dans Excel. Choisissez l'option de collage pour chaque document.","Link when the figures will change and must be refreshed. Picture for final documents. Destination styles to match the document, source formatting to keep the Excel look.":"Liez quand les chiffres vont changer et doivent être actualisés. Image pour les documents définitifs. Styles de destination pour s'accorder avec le document, mise en forme source pour garder l'apparence d'Excel.","A weekly Word bulletin must show the latest enrolment table in the bulletin's own style.":"Un bulletin Word hebdomadaire doit afficher le dernier tableau des effectifs dans le style propre au bulletin.","The figures change every week and the table should look like the bulletin.":"Les chiffres changent chaque semaine et le tableau doit ressembler au bulletin.","The signed annual report sent to the ministry as a PDF.":"Le rapport annuel signé envoyé au ministère en PDF.","A picture keeps the figures exactly as approved.":"Une image garde les chiffres exactement tels qu'ils ont été approuvés.","You need only the list of school names to paste into an e-mail.":"Vous n'avez besoin que de la liste des noms d'écoles pour la coller dans un e-mail.","A one-time copy of the table for a Word memo, matching the memo's fonts.":"Une copie unique du tableau pour une note de service Word, avec les polices de la note.","No link is needed for a one-off copy, and the memo's style should win.":"Aucune liaison n'est nécessaire pour une copie ponctuelle, et le style de la note doit primer.","Exercise 2: The cooperative's monthly note":"Exercice 2 : la note mensuelle de la coopérative","Format a note with linked figures":"Mettre en forme une note avec des chiffres liés",", \"Deliveries in May\" and \"Next steps\"":", appliquez à « Deliveries in May » et « Next steps » le style","the paragraph about deliveries, make":"le paragraphe sur les livraisons, mettez","4 850 kg":"4 850 kg","bold, and turn the three next steps into a":"en gras, et transformez les trois prochaines étapes en","Headings come from the Styles menu. Select only 4 850 kg before clicking Bold. Select the three step lines together before clicking Bullets.":"Les titres viennent du menu Styles. Sélectionnez seulement 4 850 kg avant de cliquer sur Gras. Sélectionnez ensemble les trois lignes d'étapes avant de cliquer sur Puces.","Exercise 3: A messy mobile money export":"Exercice 3 : un export mobile money désordonné","Clean the collections before linking them":"Nettoyer les encaissements avant de les lier","A microfinance branch exported its collections with amounts stored as text, and one receipt is still pending. Fill":"Une agence de microfinance a exporté ses encaissements avec des montants stockés en texte, et un reçu est encore en attente. Remplissez","with each amount as a real number (0 for the pending receipt), then":"avec chaque montant en vrai nombre (0 pour le reçu en attente), puis",": the Douala MoMo total, the number of non-cash receipts of 100 000 FCFA or more, the number of pending receipts and the average confirmed amount.":" : le total MoMo de Douala, le nombre de reçus hors espèces de 100 000 FCFA ou plus, le nombre de reçus en attente et le montant moyen confirmé.","Remove \" FCFA\" and the spaces with SUBSTITUTE, convert with VALUE, and wrap everything in IFERROR(…,0) for the pending receipt. Then use SUMIFS with two criteria, COUNTIFS with \"<>Cash\" and \">=100000\", COUNTIF on the text column, and AVERAGEIF with \">0\".":"Retirez \" FCFA\" et les espaces avec SUBSTITUTE (SUBSTITUE), convertissez avec VALUE (CNUM) et entourez le tout de IFERROR(…,0) (SIERREUR) pour le reçu en attente. Utilisez ensuite SUMIFS (SOMME.SI.ENS) avec deux critères, COUNTIFS (NB.SI.ENS) avec \"<>Cash\" et \">=100000\", COUNTIF (NB.SI) sur la colonne texte, et AVERAGEIF (MOYENNE.SI) avec \">0\".","Exercise 4: The donor report package":"Exercice 4 : le dossier du rapport au bailleur","Deliver the half-year donor package":"Remettre le dossier semestriel au bailleur","The NGO Femmes Actives du Nord in Garoua must send its half-year report to a donor. Targets are in B2:B6 and women reached in C2:C6 of the Excel workbook. Answer each question across Excel, Word, PowerPoint, OneDrive and Outlook. Type formulas starting with =.":"L'ONG Femmes Actives du Nord, à Garoua, doit envoyer son rapport semestriel à un bailleur. Les objectifs sont en B2:B6 et les femmes atteintes en C2:C6 du classeur Excel. Répondez à chaque question en passant par Excel, Word, PowerPoint, OneDrive et Outlook. Tapez les formules en commençant par =.","Overall rate = total reached divided by total target. Words in the report should update from Excel; anything leaving the NGO should be fixed and view-only. The donor contact acts, the country director is informed.":"Taux global = total atteint divisé par l'objectif total. Les chiffres du rapport doivent se mettre à jour depuis Excel ; tout ce qui quitte l'ONG doit être figé et en lecture seule. Le contact du bailleur agit, la directrice pays est informée.","Excel: type the formula for the overall reach rate of the five activities.":"Excel : tapez la formule du taux global d'atteinte des cinq activités.","Divide the totals. An average of the five rates would give small activities the same weight as large ones.":"Divisez les totaux. Une moyenne des cinq taux donnerait aux petites activités le même poids qu'aux grandes. En français : =SOMME(C2:C6)/SOMME(B2:B6).","Word draft: the results table must match the report's styles and follow corrections made in Excel.":"Brouillon Word : le tableau des résultats doit suivre les styles du rapport et les corrections faites dans Excel.","Word draft: the field team corrected two figures in Excel. How do you refresh every link in the report at once?":"Brouillon Word : l'équipe de terrain a corrigé deux chiffres dans Excel. Comment actualiser toutes les liaisons du rapport en une fois ?","Select everything and press F9. Ctrl + Shift + F9 would unlink the tables instead.":"Sélectionnez tout et appuyez sur F9. Ctrl + Maj + F9 délierait au contraire les tableaux.","Ctrl + A, then F9":"Ctrl + A, puis F9","Ctrl + Shift + F9":"Ctrl + Maj + F9","Close and reopen Excel":"Fermer et rouvrir Excel","PowerPoint: the chart for the donor's slide deck, sent as a file outside the NGO.":"PowerPoint : le graphique de la présentation destinée au bailleur, envoyée en fichier hors de l'ONG.","The workbook holds beneficiaries' names. A picture shares only the chart.":"Le classeur contient les noms des bénéficiaires. Une image ne partage que le graphique.","Use Destination Theme & Embed Workbook":"Utiliser le thème de destination et incorporer le classeur","Keep Source Formatting & Embed Workbook":"Conserver la mise en forme source et incorporer le classeur","OneDrive: how do you share the final folder with the donor's programme officer?":"OneDrive : comment partagez-vous le dossier final avec le chargé de programme du bailleur ?","Only the named person can open it, and nobody outside the NGO can change the final files.":"Seule la personne nommée peut l'ouvrir, et personne en dehors de l'ONG ne peut modifier les fichiers définitifs.","Outlook: the donor's programme officer must acknowledge the report; the NGO's country director should see the message. Where does the country director go?":"Outlook : le chargé de programme du bailleur doit accuser réception du rapport ; la directrice pays de l'ONG doit voir le message. Où la placez-vous ?","Cc is for people kept informed who are not asked to act.":"Cc sert aux personnes tenues informées à qui l'on ne demande pas d'agir.","Nowhere: forward it later":"Nulle part : lui transférer plus tard","Name the PDF sent on 15 July 2026 with the date_subject_version pattern, first version.":"Nommez le PDF envoyé le 15 juillet 2026 selon le modèle date_sujet_version, première version.","Copies that leave the team carry a version number; files inside the shared folder rely on Version History.":"Les copies qui quittent l'équipe portent un numéro de version ; les fichiers du dossier partagé s'appuient sur l'historique des versions.","Before sending, which command finds hidden comments and personal information in the Word report?":"Avant l'envoi, quelle commande trouve les commentaires masqués et les informations personnelles dans le rapport Word ?","File › Info › Check for Issues › Inspect Document":"Fichier › Informations › Vérifier la présence de problèmes › Inspecter le document","Review › Spelling & Grammar":"Révision › Grammaire et orthographe","Home › Styles":"Accueil › Styles","Module 8 Quiz":"Quiz du module 8","What does Paste Special › Paste link create in Word?":"Que crée Collage spécial › Coller avec liaison dans Word ?","A picture of the Excel range":"Une image de la plage Excel","A table that shows the workbook's data and can be updated":"Un tableau qui affiche les données du classeur et peut être mis à jour","A hyperlink that opens a website":"Un lien hypertexte qui ouvre un site web","A linked object displays data stored in the Excel file and is refreshed with Update Link or F9.":"Un objet lié affiche des données stockées dans le fichier Excel et s'actualise avec Mettre à jour la liaison ou F9.","Which action most often breaks a link between Word and Excel?":"Quelle action rompt le plus souvent une liaison entre Word et Excel ?","Moving or renaming the Excel workbook":"Déplacer ou renommer le classeur Excel","Changing a figure in Excel":"Modifier un chiffre dans Excel","Printing the Word report":"Imprimer le rapport Word","Opening the report on another day":"Ouvrir le rapport un autre jour","The link stores the workbook's path. When the path changes, use Change Source to repair it.":"La liaison enregistre le chemin du classeur. Quand ce chemin change, utilisez Changer de source pour la réparer.","Where can you see, update and break all the links in a Word or PowerPoint file?":"Où pouvez-vous voir, mettre à jour et rompre toutes les liaisons d'un fichier Word ou PowerPoint ?","Home › Paste":"Accueil › Coller","Insert › Link":"Insertion › Lien","File › Info › Edit Links to Files":"Fichier › Informations › Modifier les liens d'accès aux fichiers","The Edit Links dialog lists each link with Update Now, Change Source and Break Link.":"La boîte de dialogue des liaisons liste chaque liaison avec Mettre à jour maintenant, Changer de source et Rompre la liaison.","Why can embedding an Excel chart in a presentation be risky?":"Pourquoi incorporer un graphique Excel dans une présentation peut-il être risqué ?","The chart cannot be resized":"Le graphique ne peut pas être redimensionné","The entire workbook, including other sheets, is stored in the presentation":"Le classeur entier, autres feuilles comprises, est stocké dans la présentation","The chart updates every time Excel opens":"Le graphique se met à jour chaque fois qu'Excel s'ouvre","Embedded charts cannot be printed":"Les graphiques incorporés ne peuvent pas être imprimés","An embedded object carries a full copy of the workbook, which anyone who receives the file can open.":"Un objet incorporé contient une copie complète du classeur, que toute personne qui reçoit le fichier peut ouvrir.","An external auditor must read your final accounts. Which sharing option fits best?":"Un auditeur externe doit lire vos comptes définitifs. Quelle option de partage convient le mieux ?","Only the named auditor can open the file, and view access prevents changes.":"Seul l'auditeur nommé peut ouvrir le fichier, et l'accès en lecture empêche les modifications.","A colleague overwrote your section of a shared report this morning. What is the quickest way to recover it?":"Ce matin, un collègue a écrasé votre section d'un rapport partagé. Quel est le moyen le plus rapide de la récupérer ?","Version History keeps earlier versions of cloud files; open the version from before the change and restore it or copy the section.":"L'historique des versions conserve les versions antérieures des fichiers du cloud ; ouvrez la version d'avant la modification et restaurez-la ou copiez la section.","In File Explorer, a OneDrive file shows a blue cloud icon. What does it mean?":"Dans l'Explorateur de fichiers, un fichier OneDrive affiche une icône de nuage bleu. Que signifie-t-elle ?","The file is syncing":"Le fichier est en cours de synchronisation","The file has an error":"Le fichier présente une erreur","The file is shared with Anyone":"Le fichier est partagé avec Tout le monde","The file is online-only and needs the internet to open":"Le fichier est en ligne uniquement et a besoin d'internet pour s'ouvrir","Choose Always keep on this device before travelling so the file stays available offline.":"Choisissez Toujours conserver sur cet appareil avant de voyager pour que le fichier reste disponible hors connexion.","You send an 18 MB package of three files to the Director General. What is the best practice?":"Vous envoyez à la Directrice générale un dossier de trois fichiers de 18 Mo. Quelle est la bonne pratique ?","Attach the three files and Cc everyone":"Joindre les trois fichiers et mettre tout le monde en Cc","Send one link to the shared folder with view permission for her":"Envoyer un seul lien vers le dossier partagé avec une autorisation de lecture pour elle","Send each file in a separate e-mail":"Envoyer chaque fichier dans un e-mail séparé","Put the files on a USB drive":"Mettre les fichiers sur une clé USB","One link is light on the network, keeps a single copy of each file, and lets you control access.":"Un seul lien ménage le réseau, garde une seule copie de chaque fichier et vous permet de contrôler l'accès.","Click the practice pad, then press the shortcut for each action.":"Cliquez sur la zone d'entraînement, puis appuyez sur le raccourci de chaque action.","Click each numbered point to find out what it is.":"Cliquez sur chaque point numéroté pour découvrir de quoi il s'agit.","Interactive picture":"Image interactive","Shortcut trainer":"Entraînement aux raccourcis","Keyboard shortcuts for OneDrive for work or school":"Raccourcis clavier de OneDrive professionnel ou scolaire"};
function applyPatches(read, patches = PATCHES) {
  const out = {}, problems = [];
  for (const [file, find, repl] of patches) {
    const src = out[file] ?? read(file);
    if (src == null) { problems.push(`${file}: file not found`); continue; }
    const n = src.split(find).length - 1;
    if (n !== 1) { problems.push(`${file}: expected 1 match, found ${n} for: ${find.split("\n")[0].slice(0, 70)}`); out[file] = src; continue; }
    out[file] = src.replace(find, () => repl);
  }
  return { out, problems };
}

const crlf = {};
const read = (f) => { if (!existsSync(f)) return null; const s = readFileSync(f, "utf-8"); crlf[f] = s.includes("\r\n"); return s.replace(/\r\n/g, "\n"); };
const { out, problems } = applyPatches(read, PATCHES);
if (problems.length) fail("these files are not in the expected state:\n  " + problems.join("\n  ") + "\nSend me this message.");
const frPath = "client/src/i18n/fr.ts";
let frSrc = null, added = 0;
if (existsSync(frPath)) {
  frSrc = read(frPath);
  const end = frSrc.lastIndexOf("};");
  if (end === -1) fail(frPath + ": could not find the end of the FR object");
  const nb = "\u00a0";
  const typo = (t) => t.replace(/ ([:;?!»])/g, nb + "$1").replace(/« /g, "«" + nb);
  const lines = [];
  for (const [k, v] of Object.entries(FR)) {
    if (k === v || frSrc.includes(JSON.stringify(k) + ":")) continue;
    lines.push("  " + JSON.stringify(k) + ": " + JSON.stringify(typo(v)) + ",");
    added++;
  }
  frSrc = frSrc.slice(0, end) + "  // ---- MOSP Modules 3-8 ----\n" + lines.join("\n") + "\n" + frSrc.slice(end);
}
const eol = (f, s) => (crlf[f] ? s.replace(/\n/g, "\r\n") : s);
for (const [f, c] of Object.entries(FILES)) { mkdirSync(dirname(f), { recursive: true }); writeFileSync(f, c, "utf-8"); }
for (const [f, c] of Object.entries(out)) writeFileSync(f, eol(f, c), "utf-8");
if (frSrc) writeFileSync(frPath, eol(frPath, frSrc), "utf-8");
console.log("OK MOSP Modules 3–8 opened: 23 lessons, 6 practice labs (24 exercises), 6 quizzes");
console.log("OK spreadsheet functions added: IFS SUMIFS COUNTIFS AVERAGEIFS XLOOKUP INDEX MATCH PMT ROUNDUP ROUNDDOWN INT PRODUCT COUNTBLANK PROPER");
console.log(frSrc ? "OK " + added + " French translations added" : "NOTE French not added (translation not installed)");
